function CooldownPanels:NormalizeCDMAuraAlwaysShowMode(value, fallback)
	local mode = type(value) == "string" and string.upper(value) or nil
	local values = self.CDM_AURA_ALWAYS_SHOW_MODE or {}
	if mode == values.SHOW or mode == values.DESATURATE or mode == values.DESATURATE_ACTIVE or mode == values.HIDE or mode == values.HIDE_DESATURATE_ACTIVE then return mode end
	return fallback or values.HIDE or "HIDE"
end

function CooldownPanels:IsCDMAuraAlwaysShowModeVisibleWhenInactive(value)
	local values = self.CDM_AURA_ALWAYS_SHOW_MODE or {}
	local mode = self:NormalizeCDMAuraAlwaysShowMode(value, values.HIDE or "HIDE")
	return mode ~= (values.HIDE or "HIDE") and mode ~= (values.HIDE_DESATURATE_ACTIVE or "HIDE_DESATURATE_ACTIVE")
end

function CooldownPanels:GetCDMAuraAlwaysShowOptions()
	local values = self.CDM_AURA_ALWAYS_SHOW_MODE or {}
	return {
		{
			value = values.HIDE or "HIDE",
			label = L["CooldownPanelCDMAuraAlwaysShowModeHide"] or "Only show when active",
		},
		{
			value = values.HIDE_DESATURATE_ACTIVE or "HIDE_DESATURATE_ACTIVE",
			label = L["CooldownPanelCDMAuraAlwaysShowModeHideDesaturateActive"] or "Only show when active (desaturated)",
		},
		{
			value = values.SHOW or "SHOW",
			label = L["Always show"] or (L["Always show"] or "Always show"),
		},
		{
			value = values.DESATURATE or "DESATURATE",
			label = L["CooldownPanelCDMAuraAlwaysShowModeDesaturate"] or "Always show (desaturate if inactive)",
		},
		{
			value = values.DESATURATE_ACTIVE or "DESATURATE_ACTIVE",
			label = L["CooldownPanelCDMAuraAlwaysShowModeDesaturateActive"] or "Always show (desaturate when active)",
		},
	}
end

local function normalizeId(value)
	local num = tonumber(value)
	if num then return num end
	return value
end

local function getClassInfoById(classId)
	if GetClassInfo then return GetClassInfo(classId) end
	if C_CreatureInfo and C_CreatureInfo.GetClassInfo then
		local info = C_CreatureInfo.GetClassInfo(classId)
		if info then return info.className, info.classFile, info.classID end
	end
	return nil
end

local function getClassSpecMenuData()
	local classes = {}
	local getSpecCount = C_SpecializationInfo and C_SpecializationInfo.GetNumSpecializationsForClassID
	if not getSpecCount or not GetSpecializationInfoForClassID or not GetNumClasses then return classes end
	local sex = UnitSex and UnitSex("player") or nil
	local numClasses = GetNumClasses() or 0
	for classIndex = 1, numClasses do
		local className, classTag, classID = getClassInfoById(classIndex)
		if classID then
			local specCount = getSpecCount(classID) or 0
			if specCount > 0 then
				local specs = {}
				for specIndex = 1, specCount do
					local specID, specName, _, _, role = GetSpecializationInfoForClassID(classID, specIndex, sex)
					if specID then
						local isMelee = CooldownPanels and CooldownPanels.IsSpecQuickFilterMelee and CooldownPanels:IsSpecQuickFilterMelee(specID) or false
						local isCaster = role == "DAMAGER" and isMelee ~= true and classTag ~= "HUNTER"
						specs[#specs + 1] = {
							id = specID,
							name = specName or ("Spec " .. tostring(specID)),
							role = role,
							classTag = classTag,
							isMelee = isMelee,
							isCaster = isCaster,
						}
					end
				end
				if #specs > 0 then classes[#classes + 1] = {
					id = classID,
					name = className or classTag or tostring(classID),
					classTag = classTag,
					specs = specs,
				} end
			end
		end
	end
	if #classes > 1 then
		table.sort(classes, function(a, b)
			local an = a and a.name or ""
			local bn = b and b.name or ""
			if strcmputf8i then return strcmputf8i(an, bn) < 0 end
			return tostring(an):lower() < tostring(bn):lower()
		end)
	end
	return classes
end

local function getSpecNameById(specId)
	if GetSpecializationInfoForSpecID then
		local _, specName = GetSpecializationInfoForSpecID(specId)
		if specName and specName ~= "" then return specName end
	end
	return tostring(specId or "")
end

function CooldownPanels:IsSpecQuickFilterMelee(specId)
	specId = tonumber(specId)
	if not specId then return false end
	if specId == 70 or specId == 71 or specId == 72 or specId == 103 or specId == 251 or specId == 252 or specId == 255 then return true end
	if specId == 259 or specId == 260 or specId == 261 or specId == 263 or specId == 269 or specId == 577 then return true end
	return false
end

function CooldownPanels:GetSpecQuickFilterDefinitions(classMenuData)
	local definitions = {
		{ id = "HEALER", label = L["CooldownPanelSpecAllHealers"] or "All healers", specIds = {} },
		{ id = "TANK", label = L["CooldownPanelSpecAllTanks"] or "All tanks", specIds = {} },
		{ id = "MELEE", label = L["CooldownPanelSpecAllMelee"] or "All melee", specIds = {} },
		{ id = "CASTER", label = L["CooldownPanelSpecAllCasters"] or "All casters", specIds = {} },
	}

	for _, classData in ipairs(classMenuData or getClassSpecMenuData()) do
		for _, specData in ipairs(classData.specs or {}) do
			local specId = tonumber(specData.id)
			if specId and specId > 0 then
				if specData.role == "HEALER" then definitions[1].specIds[#definitions[1].specIds + 1] = specId end
				if specData.role == "TANK" then definitions[2].specIds[#definitions[2].specIds + 1] = specId end
				if specData.role == "DAMAGER" and specData.isMelee == true then definitions[3].specIds[#definitions[3].specIds + 1] = specId end
				if specData.isCaster == true then definitions[4].specIds[#definitions[4].specIds + 1] = specId end
			end
		end
	end

	return definitions
end

function CooldownPanels:HasAllSpecFilterEntries(target, specIds)
	if not target or type(specIds) ~= "table" or #specIds == 0 then return false end
	local filter = target.specFilter
	if type(filter) ~= "table" then return false end
	for _, specId in ipairs(specIds) do
		if filter[specId] ~= true then return false end
	end
	return true
end

function CooldownPanels:HasAllPanelSpecFilterEntries(panel, specIds) return self:HasAllSpecFilterEntries(panel, specIds) end

function CooldownPanels:HasAllEntrySpecFilterEntries(entry, specIds) return self:HasAllSpecFilterEntries(entry, specIds) end

function CooldownPanels:SetSpecFilterEntries(target, specIds, enabled)
	if not target or type(specIds) ~= "table" then return false end
	target.specFilter = target.specFilter or {}
	local changed = false
	for _, specId in ipairs(specIds) do
		specId = tonumber(specId)
		if specId and specId > 0 then
			if enabled then
				if target.specFilter[specId] ~= true then
					target.specFilter[specId] = true
					changed = true
				end
			elseif target.specFilter[specId] ~= nil then
				target.specFilter[specId] = nil
				changed = true
			end
		end
	end
	if target.specFilter and not next(target.specFilter) then target.specFilter = nil end
	return changed
end

function CooldownPanels:SetPanelSpecFilterEntries(panel, specIds, enabled) return self:SetSpecFilterEntries(panel, specIds, enabled) end

function CooldownPanels:SetEntrySpecFilterEntries(entry, specIds, enabled) return self:SetSpecFilterEntries(entry, specIds, enabled) end

function CooldownPanels:CommitPanelSpecFilter(panelId)
	self:RebuildSpellIndex()
	self:RefreshPanel(panelId)
	self:RefreshEditor()
end

local function getEffectiveSpellId(spellId)
	return Helper.GetEffectiveSpellId(spellId)
end

local function getBaseSpellId(spellId)
	return Helper.GetBaseSpellId(spellId)
end

function CooldownPanels:GetReadySoundStateKey(spellId)
	local id = tonumber(spellId)
	if not id then return nil end
	local exactStateKeys = self.runtime and self.runtime.readySoundExactStateKeyBySpellId
	if exactStateKeys and exactStateKeys[id] then return exactStateKeys[id] end
	local effectiveId = getEffectiveSpellId(id) or id
	return self:GetCanonicalSpellVariantID(effectiveId) or getBaseSpellId(effectiveId) or effectiveId
end

function CooldownPanels:GetReadySoundQuerySpellId(spellId)
	local id = tonumber(spellId)
	if not id then return nil end
	return self:ResolveTrackedSpellID(id)
end

function CooldownPanels:SpellIndexHasSpell(index, spellId)
	local id = tonumber(spellId)
	if not (index and id) then return false end
	local canonicalId = self:GetReadySoundStateKey(id)
	local baseId = getBaseSpellId(id) or id
	local effectiveId = getEffectiveSpellId(id) or id
	return index[id] ~= nil or index[baseId] ~= nil or index[effectiveId] ~= nil or (canonicalId and index[canonicalId] ~= nil) or false
end

function CooldownPanels:GetTrustedReadyUnavailable(spellId)
	local querySpellId = self:GetReadySoundQuerySpellId(spellId)
	if not querySpellId then return false end
	local _, _, _, _, isOnGCD, isActive = self:GetCachedSpellCooldownInfo(querySpellId)
	return isActive == true and isOnGCD == false
end

function CooldownPanels:EnsureStaticSpellVariantGroupsLoaded()
	self.runtime = self.runtime or {}
	if self.runtime.staticSpellVariantGroupsLoaded == true then return end
	local groups = self.staticSpellVariantGroups
	for i = 1, #(groups or {}) do
		self:RegisterStaticSpellVariantGroup(groups[i], { mapBaseSpellIDs = true })
	end
	self.runtime.staticSpellVariantGroupsLoaded = true
end

local function queryPlayerSpecId()
	if not (C_SpecializationInfo and C_SpecializationInfo.GetSpecialization) then return nil end
	local specIndex = C_SpecializationInfo.GetSpecialization()
	if not specIndex then return nil end
	if C_SpecializationInfo and C_SpecializationInfo.GetSpecializationInfo then
		local specId = C_SpecializationInfo.GetSpecializationInfo(specIndex)
		if type(specId) == "number" and specId > 0 then return specId end
		if type(specId) == "table" and type(specId.specID) == "number" and specId.specID > 0 then return specId.specID end
	end
	return nil
end

function cdp.RUNTIME.GetTalentNodeActiveEntryID(nodeInfo)
	if type(nodeInfo) ~= "table" then return nil end
	local activeEntry = nodeInfo.activeEntry
	if type(activeEntry) == "table" then
		local entryID = tonumber(activeEntry.entryID or activeEntry.id)
		if entryID then return entryID end
	elseif type(activeEntry) == "number" then
		return activeEntry
	end
	local activeEntryID = tonumber(nodeInfo.activeEntryID)
	if activeEntryID then return activeEntryID end
	local committed = nodeInfo.entryIDsWithCommittedRanks
	if type(committed) == "table" then
		for i = 1, #committed do
			local entryID = tonumber(committed[i])
			if entryID then return entryID end
		end
		for entryID, rank in pairs(committed) do
			local numericEntryID = tonumber(entryID)
			local numericRank = tonumber(rank)
			if numericEntryID and numericRank and numericRank > 0 then return numericEntryID end
		end
	end
	return nil
end

function cdp.RUNTIME.IsTalentChoiceNodeActive(nodeInfo, activeEntryID)
	if type(nodeInfo) ~= "table" or not activeEntryID then return false end
	local hasRankField = false
	for _, field in ipairs({ "currentRank", "activeRank", "ranksPurchased", "rank" }) do
		local rank = tonumber(nodeInfo[field])
		if rank ~= nil then
			hasRankField = true
			if rank > 0 then return true end
		end
	end
	local committed = nodeInfo.entryIDsWithCommittedRanks
	if type(committed) == "table" then
		for i = 1, #committed do
			if tonumber(committed[i]) == activeEntryID then return true end
		end
		for entryID, rank in pairs(committed) do
			local numericEntryID = tonumber(entryID)
			local numericRank = tonumber(rank)
			if numericEntryID == activeEntryID and (numericRank == nil or numericRank > 0) then return true end
		end
	end
	if hasRankField then return false end
	return true
end

function cdp.RUNTIME.GetTalentEntrySpellID(configID, entryID)
	local entryInfo = Api.GetTraitEntryInfo and Api.GetTraitEntryInfo(configID, entryID) or nil
	local definitionID = entryInfo and tonumber(entryInfo.definitionID) or nil
	if not definitionID then return nil end
	local definitionInfo = Api.GetTraitDefinitionInfo and Api.GetTraitDefinitionInfo(definitionID) or nil
	local spellID = definitionInfo and tonumber(definitionInfo.spellID) or nil
	if not spellID or spellID <= 0 then return nil end
	if Api.IsSpellPassiveFn and Api.IsSpellPassiveFn(spellID) then return nil end
	return spellID
end

function cdp.RUNTIME.AddTalentChoiceGroupLookupID(ctx, group, spellID)
	local id = tonumber(spellID)
	if not id or group.lookupSeen[id] then return end
	group.lookupSeen[id] = true
	local list = ctx.byID[id]
	if type(list) ~= "table" then
		list = {}
		ctx.byID[id] = list
	end
	list[#list + 1] = group
end

function cdp.RUNTIME.RegisterTalentChoiceRuntimeGroup(ctx, treeID, nodeID, spellIDs, selectedSpellID, activeEntryID)
	local selectedID = tonumber(selectedSpellID)
	if type(ctx) ~= "table" or type(spellIDs) ~= "table" or #spellIDs < 2 or not selectedID then return nil end
	local group = {
		kind = "talentChoice",
		treeID = treeID,
		nodeID = nodeID,
		key = tostring(treeID or "?") .. ":" .. tostring(nodeID or "?"),
		ids = spellIDs,
		idSet = {},
		canonicalID = tonumber(spellIDs[1]) or selectedID,
		selectedSpellID = selectedID,
		activeEntryID = activeEntryID,
		lookupSeen = {},
	}
	ctx.groups[#ctx.groups + 1] = group
	for i = 1, #spellIDs do
		local spellID = tonumber(spellIDs[i])
		if spellID then
			group.idSet[spellID] = true
			cdp.RUNTIME.AddTalentChoiceGroupLookupID(ctx, group, spellID)
			cdp.RUNTIME.AddTalentChoiceGroupLookupID(ctx, group, getBaseSpellId(spellID))
			cdp.RUNTIME.AddTalentChoiceGroupLookupID(ctx, group, getEffectiveSpellId(spellID))
		end
	end
	cdp.RUNTIME.AddTalentChoiceGroupLookupID(ctx, group, selectedID)
	cdp.RUNTIME.AddTalentChoiceGroupLookupID(ctx, group, getBaseSpellId(selectedID))
	cdp.RUNTIME.AddTalentChoiceGroupLookupID(ctx, group, getEffectiveSpellId(selectedID))
	group.lookupSeen = nil
	return group
end

function cdp.RUNTIME.AreEquivalentSpellIDs(firstSpellId, secondSpellId)
	local firstID = tonumber(firstSpellId)
	local secondID = tonumber(secondSpellId)
	if not (firstID and secondID) then return false end
	if firstID == secondID then return true end

	local firstBaseID = getBaseSpellId(firstID) or firstID
	local secondBaseID = getBaseSpellId(secondID) or secondID
	if firstBaseID == secondBaseID then return true end

	local firstEffectiveID = getEffectiveSpellId(firstID)
	local secondEffectiveID = getEffectiveSpellId(secondID)
	if firstEffectiveID and firstEffectiveID == secondID then return true end
	if secondEffectiveID and secondEffectiveID == firstID then return true end
	if firstEffectiveID and secondEffectiveID and firstEffectiveID == secondEffectiveID then return true end

	local firstEffectiveBaseID = firstEffectiveID and (getBaseSpellId(firstEffectiveID) or firstEffectiveID) or nil
	local secondEffectiveBaseID = secondEffectiveID and (getBaseSpellId(secondEffectiveID) or secondEffectiveID) or nil
	if firstEffectiveBaseID and firstEffectiveBaseID == secondBaseID then return true end
	if secondEffectiveBaseID and secondEffectiveBaseID == firstBaseID then return true end

	return false
end

function cdp.RUNTIME.DoesSpellMatchTalentChoiceGroup(group, spellId)
	local numericID = tonumber(spellId)
	if not (group and numericID) then return false end
	if type(group.idSet) == "table" and group.idSet[numericID] == true then return true end
	local selectedID = tonumber(group.selectedSpellID)
	if selectedID and cdp.RUNTIME.AreEquivalentSpellIDs(selectedID, numericID) then return true end
	return false
end

function cdp.RUNTIME.IsDirectTalentChoiceGroupMember(group, spellId)
	local numericID = tonumber(spellId)
	return group and group.kind == "talentChoice" and numericID and type(group.idSet) == "table" and group.idSet[numericID] == true or false
end

function cdp.RUNTIME.EnsureTalentChoiceSpellVariantGroupsLoaded(owner)
	owner.runtime = owner.runtime or {}
	local runtime = owner.runtime
	runtime.talentChoiceSpellVariantGroupsLoadedByConfig = nil
	local specID = queryPlayerSpecId()
	local configID = Api.GetActiveTalentConfigID and Api.GetActiveTalentConfigID() or nil
	if not specID or not configID then
		runtime.talentChoiceVariantContext = nil
		return nil
	end
	local generation = runtime.talentChoiceVariantGeneration or 0
	local key = tostring(specID) .. ":" .. tostring(configID) .. ":" .. tostring(generation)
	local existing = runtime.talentChoiceVariantContext
	if existing and existing.key == key then return existing end

	local ctx = {
		key = key,
		specID = specID,
		configID = configID,
		generation = generation,
		groups = {},
		byID = {},
	}

	local configInfo = Api.GetTraitConfigInfo and Api.GetTraitConfigInfo(configID) or nil
	local treeIDs = configInfo and configInfo.treeIDs
	if type(treeIDs) ~= "table" then
		runtime.talentChoiceVariantContext = ctx
		return ctx
	end

	local selectionNodeType = Api.TraitNodeTypeSelection
	local subtreeSelectionNodeType = Api.TraitNodeTypeSubTreeSelection or (Enum and Enum.TraitNodeType and Enum.TraitNodeType.SubTreeSelection)
	for _, treeID in ipairs(treeIDs) do
		local nodeIDs = Api.GetTraitTreeNodes and Api.GetTraitTreeNodes(treeID) or nil
		if type(nodeIDs) == "table" then
			for _, nodeID in ipairs(nodeIDs) do
				local nodeInfo = Api.GetTraitNodeInfo and Api.GetTraitNodeInfo(configID, nodeID) or nil
				local entryIDs = nodeInfo and nodeInfo.entryIDs
				local nodeType = nodeInfo and nodeInfo.type
				local activeEntryID = cdp.RUNTIME.GetTalentNodeActiveEntryID(nodeInfo)
				local isChoiceNode = selectionNodeType == nil
					or nodeType == selectionNodeType
					or nodeType == subtreeSelectionNodeType
					or (nodeType == nil and activeEntryID ~= nil)
				if type(entryIDs) == "table" and #entryIDs > 1 and isChoiceNode then
					local spellIDs = {}
					local seenSpellIDs = {}
					local selectedSpellID = activeEntryID and cdp.RUNTIME.GetTalentEntrySpellID(configID, activeEntryID) or nil
					for _, entryID in ipairs(entryIDs) do
						local spellID = cdp.RUNTIME.GetTalentEntrySpellID(configID, entryID)
						if spellID and not seenSpellIDs[spellID] then
							seenSpellIDs[spellID] = true
							spellIDs[#spellIDs + 1] = spellID
						end
					end
					if #spellIDs >= 2 and selectedSpellID and cdp.RUNTIME.IsTalentChoiceNodeActive(nodeInfo, activeEntryID) then
						cdp.RUNTIME.RegisterTalentChoiceRuntimeGroup(ctx, treeID, nodeID, spellIDs, selectedSpellID, activeEntryID)
					end
				end
			end
		end
	end
	runtime.talentChoiceVariantContext = ctx
	return ctx
end

function CooldownPanels:InvalidateTalentChoiceSpellVariantGroups()
	self.runtime = self.runtime or {}
	local runtime = self.runtime
	runtime.talentChoiceVariantGeneration = (runtime.talentChoiceVariantGeneration or 0) + 1
	runtime.talentChoiceVariantContext = nil
	runtime.talentChoiceSpellVariantGroupsLoadedByConfig = nil
	runtime.activeTalentChoiceGroupsForSpellCache = nil
	runtime.spellAliasIDsCache = nil
	runtime.runtimeCanonicalSpellVariantCache = nil
	self.spellVariantGroupByID = self.staticSpellVariantGroupByID
end

function CooldownPanels:GetActiveTalentChoiceVariantContext()
	local ctx = cdp.RUNTIME.EnsureTalentChoiceSpellVariantGroupsLoaded(self)
	local runtime = self.runtime
	if not ctx then ctx = runtime and runtime.talentChoiceVariantContext or nil end
	if not ctx then return nil end
	local specID = queryPlayerSpecId()
	local configID = Api.GetActiveTalentConfigID and Api.GetActiveTalentConfigID() or nil
	if ctx.specID ~= specID or ctx.configID ~= configID then
		self:InvalidateTalentChoiceSpellVariantGroups()
		return nil
	end
	return ctx
end

function CooldownPanels:GetStaticSpellVariantGroupForSpell(spellId)
	self:EnsureStaticSpellVariantGroupsLoaded()
	local numericID = tonumber(spellId)
	if not numericID then return nil end
	local baseSpellID = getBaseSpellId(numericID) or numericID
	local groupMap = self.staticSpellVariantGroupByID
	return type(groupMap) == "table" and (groupMap[numericID] or groupMap[baseSpellID]) or nil
end

function CooldownPanels:GetActiveTalentChoiceGroupsForSpell(spellId)
	local numericID = tonumber(spellId)
	if not numericID then return nil end
	self.runtime = self.runtime or {}
	local runtime = self.runtime
	local generation = runtime.talentChoiceVariantGeneration or 0
	local cache = runtime.activeTalentChoiceGroupsForSpellCache
	if not cache or cache.generation ~= generation then
		cache = { generation = generation }
		runtime.activeTalentChoiceGroupsForSpellCache = cache
	end
	local cached = cache[numericID]
	if cached ~= nil then return cached ~= false and cached or nil end

	local ctx = self:GetActiveTalentChoiceVariantContext()
	if not ctx then ctx = cdp.RUNTIME.EnsureTalentChoiceSpellVariantGroupsLoaded(self) end
	if not (ctx and type(ctx.byID) == "table") then
		cache[numericID] = false
		return nil
	end
	local groups = ctx.byID[numericID]
	local baseSpellID = getBaseSpellId(numericID)
	local effectiveSpellID = getEffectiveSpellId(numericID)
	if not groups and baseSpellID and baseSpellID ~= numericID then groups = ctx.byID[baseSpellID] end
	if not groups and effectiveSpellID and effectiveSpellID ~= numericID and effectiveSpellID ~= baseSpellID then groups = ctx.byID[effectiveSpellID] end
	if type(groups) ~= "table" then
		cache[numericID] = false
		return nil
	end

	local filtered = nil
	for i = 1, #groups do
		local group = groups[i]
		if cdp.RUNTIME.DoesSpellMatchTalentChoiceGroup(group, numericID) then
			filtered = filtered or {}
			filtered[#filtered + 1] = group
		end
	end
	cache[numericID] = filtered or false
	return filtered
end

function cdp.RUNTIME.ResolveTrackedSpellID(owner, spellId, options)
	local numericID = tonumber(spellId)
	if not numericID then return nil, nil, nil end
	local storedBaseSpellID = getBaseSpellId(numericID) or numericID
	if type(options) == "table" and options.exactTalentChoice == true then
		local effectiveSpellID = getEffectiveSpellId(numericID) or numericID
		return effectiveSpellID, numericID, storedBaseSpellID, nil
	end
	local resolvedSpellID, _, variantGroup = owner:ResolveRuntimeSpellVariantID(numericID)
	resolvedSpellID = resolvedSpellID or storedBaseSpellID
	local effectiveSpellID = getEffectiveSpellId(resolvedSpellID) or resolvedSpellID
	return effectiveSpellID, resolvedSpellID, storedBaseSpellID, variantGroup
end

function cdp.RUNTIME.CollectSpellAliasIDs(owner, spellId, ids, seen, includeTalentChoice)
	local function addID(id)
		local numericID = tonumber(id)
		if not numericID or seen[numericID] then return end
		seen[numericID] = true
		ids[#ids + 1] = numericID
	end

	local function collectID(id)
		local numericID = tonumber(id)
		if not numericID then return end
		addID(numericID)
		local baseSpellID = getBaseSpellId(numericID)
		if baseSpellID and baseSpellID ~= numericID then addID(baseSpellID) end
		local effectiveSpellID = getEffectiveSpellId(numericID)
		if effectiveSpellID and effectiveSpellID ~= numericID and effectiveSpellID ~= baseSpellID then addID(effectiveSpellID) end
	end

	collectID(spellId)
	local staticGroup = owner:GetStaticSpellVariantGroupForSpell(spellId)
	if type(staticGroup) == "table" then
		for i = 1, #staticGroup do
			collectID(staticGroup[i])
		end
	end
	if includeTalentChoice then
		local dynamicGroups = owner:GetActiveTalentChoiceGroupsForSpell(spellId)
		if type(dynamicGroups) == "table" then
			for groupIndex = 1, #dynamicGroups do
				local group = dynamicGroups[groupIndex]
				local groupIDs = group and group.ids
				if type(groupIDs) == "table" then
					for i = 1, #groupIDs do
						collectID(groupIDs[i])
					end
				end
				if group and group.selectedSpellID then collectID(group.selectedSpellID) end
				if group and group.canonicalID then collectID(group.canonicalID) end
			end
		end
	end
	return ids, seen
end

function cdp.RUNTIME.BuildSpellAliasIDs(owner, spellId, includeTalentChoice)
	local ids, seen = {}, {}
	return cdp.RUNTIME.CollectSpellAliasIDs(owner, spellId, ids, seen, includeTalentChoice)
end

function cdp.RUNTIME.GetCachedSpellAliasIDs(owner, spellId, includeTalentChoice)
	local numericID = tonumber(spellId)
	if not numericID then
		owner._emptySpellAliasIDs = owner._emptySpellAliasIDs or {}
		return owner._emptySpellAliasIDs
	end
	owner.runtime = owner.runtime or {}
	local runtime = owner.runtime
	local cacheRoot = runtime.spellAliasIDsCache
	if not cacheRoot then
		cacheRoot = {}
		runtime.spellAliasIDsCache = cacheRoot
	end
	local cacheKey = includeTalentChoice ~= false and "dynamic" or "static"
	local generation = includeTalentChoice ~= false and (runtime.talentChoiceVariantGeneration or 0) or 0
	local cache = cacheRoot[cacheKey]
	if not cache or cache.generation ~= generation then
		cache = { generation = generation }
		cacheRoot[cacheKey] = cache
	end
	local cached = cache[numericID]
	if cached then return cached end
	cached = cdp.RUNTIME.BuildSpellAliasIDs(owner, numericID, includeTalentChoice)
	cache[numericID] = cached
	return cached
end

function cdp.RUNTIME.GetSpellAliasIDs(owner, spellId, outIds, seenIds, options)
	local includeTalentChoice = type(options) ~= "table" or options.includeTalentChoice ~= false
	if not outIds and not seenIds then return cdp.RUNTIME.GetCachedSpellAliasIDs(owner, spellId, includeTalentChoice) end
	return cdp.RUNTIME.CollectSpellAliasIDs(owner, spellId, outIds or {}, seenIds or {}, includeTalentChoice)
end

function cdp.RUNTIME.AreSpellVariantsEquivalent(owner, firstSpellId, secondSpellId)
	local firstID = tonumber(firstSpellId)
	local secondID = tonumber(secondSpellId)
	if not (firstID and secondID) then return false end
	if firstID == secondID then return true end
	local firstCanonicalID = owner:GetCanonicalSpellVariantID(firstID) or getBaseSpellId(firstID) or firstID
	local secondCanonicalID = owner:GetCanonicalSpellVariantID(secondID) or getBaseSpellId(secondID) or secondID
	if firstCanonicalID == secondCanonicalID then return true end
	local firstEffectiveID = getEffectiveSpellId(firstID)
	local secondEffectiveID = getEffectiveSpellId(secondID)
	return (firstEffectiveID and firstEffectiveID == secondID)
		or (secondEffectiveID and secondEffectiveID == firstID)
		or (firstEffectiveID and secondEffectiveID and firstEffectiveID == secondEffectiveID)
		or false
end

function CooldownPanels:EnsureTalentChoiceSpellVariantGroupsLoaded() return cdp.RUNTIME.EnsureTalentChoiceSpellVariantGroupsLoaded(self) end

function CooldownPanels:ResolveTrackedSpellID(spellId, options) return cdp.RUNTIME.ResolveTrackedSpellID(self, spellId, options) end

function CooldownPanels:GetSpellAliasIDs(spellId, outIds, seenIds, options) return cdp.RUNTIME.GetSpellAliasIDs(self, spellId, outIds, seenIds, options) end

function CooldownPanels:IsEntryTalentChoiceExact(entry) return type(entry) == "table" and entry.type == "SPELL" and entry.talentChoiceExact == true end

function CooldownPanels:ResolveEntryTrackedSpellID(entry, spellId)
	return self:ResolveTrackedSpellID(spellId, { exactTalentChoice = self:IsEntryTalentChoiceExact(entry) })
end

function CooldownPanels:GetEntrySpellAliasIDs(entry, spellId, outIds, seenIds)
	return self:GetSpellAliasIDs(spellId, outIds, seenIds, { includeTalentChoice = not self:IsEntryTalentChoiceExact(entry) })
end

function CooldownPanels:IsTalentChoiceSpellID(spellId)
	local groups = self:GetActiveTalentChoiceGroupsForSpell(spellId)
	return type(groups) == "table" and #groups > 0
end

function CooldownPanels:CanEntryTrackTalentChoiceSeparately(entry)
	if not (entry and entry.type == "SPELL" and entry.spellID) then return false end
	if self:IsEntryTalentChoiceExact(entry) then return true end
	return self:IsTalentChoiceSpellID(entry.spellID)
end

function CooldownPanels:GetEntryReadySoundStateKey(entry, spellId)
	if not self:IsEntryTalentChoiceExact(entry) then
		local id = tonumber(spellId)
		if not id then return nil end
		local effectiveId = getEffectiveSpellId(id) or id
		return self:GetCanonicalSpellVariantID(effectiveId) or getBaseSpellId(effectiveId) or effectiveId
	end
	local resolvedSpellID = self:ResolveEntryTrackedSpellID(entry, spellId)
	return tonumber(resolvedSpellID) or tonumber(spellId)
end

function CooldownPanels:GetEntryReadySoundQuerySpellId(entry, spellId)
	if not self:IsEntryTalentChoiceExact(entry) then return self:GetReadySoundQuerySpellId(spellId) end
	return self:ResolveEntryTrackedSpellID(entry, spellId)
end

function CooldownPanels:SetEntryTalentChoiceExact(panelId, entryId, enabled)
	panelId = normalizeId(panelId)
	entryId = normalizeId(entryId)
	local panel = panelId and self:GetPanel(panelId) or nil
	local entry = panel and panel.entries and panel.entries[entryId] or nil
	if not (entry and entry.type == "SPELL" and entry.spellID) then return false end
	enabled = enabled == true
	if self:IsEntryTalentChoiceExact(entry) == enabled then return false end

	local nextSpellID
	if enabled then
		local _, resolvedSpellID, _, group = self:ResolveTrackedSpellID(entry.spellID)
		if not (group and group.kind == "talentChoice") then return false end
		nextSpellID = tonumber(group.selectedSpellID) or tonumber(resolvedSpellID)
	else
		nextSpellID = self:NormalizePersistentSpellID(entry.spellID, { allowTalentChoiceCanonical = true }) or tonumber(entry.spellID)
	end
	if not nextSpellID then return false end

	local options = enabled and { talentChoiceExact = true } or nil
	local duplicateEntryId = self:FindEntryByValue(panelId, "SPELL", nextSpellID, options)
	if duplicateEntryId and normalizeId(duplicateEntryId) ~= entryId then
		local message = L["CooldownPanelEntry"] and (L["CooldownPanelEntry"] .. " already exists.") or "Entry already exists."
		if UIErrorsFrame and UIErrorsFrame.AddMessage then UIErrorsFrame:AddMessage(message, 1, 0.2, 0.2) end
		return false
	end

	entry.spellID = nextSpellID
	entry.talentChoiceExact = enabled and true or nil
	self:ClearEntryCustomCooldownDuration(panelId, entryId, true)
	self:RebuildSpellIndex()
	self:RefreshPanel(panelId)
	self:RefreshEditor()
	if self.BlizzardEditor and self.BlizzardEditor.RefreshPanel then self.BlizzardEditor:RefreshPanel(panelId) end
	return true
end

function CooldownPanels:AreSpellVariantsEquivalent(firstSpellId, secondSpellId) return cdp.RUNTIME.AreSpellVariantsEquivalent(self, firstSpellId, secondSpellId) end

function CooldownPanels:GetStaticCanonicalSpellVariantID(spellId)
	self:EnsureStaticSpellVariantGroupsLoaded()
	local numericID = tonumber(spellId)
	if not numericID then return nil, false, nil end
	local baseSpellID = getBaseSpellId(numericID) or numericID
	local group = self:GetStaticSpellVariantGroupForSpell(numericID)
	if not group or type(group) ~= "table" or #group == 0 then return baseSpellID, false, nil end
	local canonicalID = tonumber(group[1]) or baseSpellID
	return canonicalID, canonicalID ~= baseSpellID, group
end

function CooldownPanels:GetRuntimeCanonicalSpellVariantID(spellId)
	local numericID = tonumber(spellId)
	if not numericID then return nil, false, nil end
	self.runtime = self.runtime or {}
	local runtime = self.runtime
	local generation = runtime.talentChoiceVariantGeneration or 0
	local cache = runtime.runtimeCanonicalSpellVariantCache
	if not cache or cache.generation ~= generation then
		cache = { generation = generation }
		runtime.runtimeCanonicalSpellVariantCache = cache
	end
	local cached = cache[numericID]
	if cached ~= nil then
		if cached == false then return nil, false, nil end
		return cached.canonicalID, cached.changed, cached.group
	end
	local baseSpellID = getBaseSpellId(numericID) or numericID
	local dynamicGroups = self:GetActiveTalentChoiceGroupsForSpell(numericID)
	if type(dynamicGroups) == "table" then
		local group = dynamicGroups[1]
		if group then
			local canonicalID = tonumber(group.canonicalID) or baseSpellID
			cache[numericID] = { canonicalID = canonicalID, changed = canonicalID ~= baseSpellID, group = group }
			return canonicalID, canonicalID ~= baseSpellID, group
		end
	end
	local canonicalID, changed, group = self:GetStaticCanonicalSpellVariantID(numericID)
	cache[numericID] = canonicalID and { canonicalID = canonicalID, changed = changed, group = group } or false
	return canonicalID, changed, group
end

function CooldownPanels:GetCanonicalSpellVariantID(spellId, options)
	if type(options) == "table" and options.staticOnly == true then
		return self:GetStaticCanonicalSpellVariantID(spellId)
	end
	return self:GetRuntimeCanonicalSpellVariantID(spellId)
end

function CooldownPanels:ResolveStaticKnownSpellVariantID(spellId)
	self:EnsureStaticSpellVariantGroupsLoaded()
	local numericID = tonumber(spellId)
	if not numericID then return nil, false, nil end
	local baseSpellID = getBaseSpellId(numericID) or numericID
	local group = self:GetStaticSpellVariantGroupForSpell(numericID)
	if not group or type(group) ~= "table" or #group == 0 then return baseSpellID, false, nil end
	if self:IsRacialSpellID(numericID) and Api.IsSpellKnown and Api.IsSpellKnown(numericID, false) then return numericID, numericID ~= baseSpellID, group end
	if Api.IsSpellKnown and Api.IsSpellKnown(baseSpellID, false) then return baseSpellID, false, group end
	for i = 1, #group do
		local candidateID = tonumber(group[i])
		if candidateID and candidateID > 0 and Api.IsSpellKnown and Api.IsSpellKnown(candidateID, false) then return candidateID, candidateID ~= baseSpellID, group end
	end
	return baseSpellID, false, group
end

function CooldownPanels:ResolveActiveTalentChoiceVariantID(spellId)
	local numericID = tonumber(spellId)
	if not numericID then return nil, false, nil end
	local dynamicGroups = self:GetActiveTalentChoiceGroupsForSpell(numericID)
	if type(dynamicGroups) ~= "table" then return nil, false, nil end
	for i = 1, #dynamicGroups do
		local group = dynamicGroups[i]
		local selectedID = group and tonumber(group.selectedSpellID) or nil
		if selectedID and selectedID > 0 then return selectedID, selectedID ~= numericID, group end
	end
	return nil, false, nil
end

function CooldownPanels:ResolveRuntimeSpellVariantID(spellId)
	local dynamicID, dynamicChanged, dynamicGroup = self:ResolveActiveTalentChoiceVariantID(spellId)
	if dynamicID then return dynamicID, dynamicChanged, dynamicGroup end
	return self:ResolveStaticKnownSpellVariantID(spellId)
end

function CooldownPanels:ResolveKnownSpellVariantID(spellId, options)
	if type(options) == "table" and options.staticOnly == true then
		return self:ResolveStaticKnownSpellVariantID(spellId)
	end
	return self:ResolveRuntimeSpellVariantID(spellId)
end

function CooldownPanels:NormalizePersistentSpellID(spellId, options)
	local numericID = tonumber(spellId)
	if not numericID then return spellId end
	local allowTalentChoiceCanonical = type(options) == "table" and options.allowTalentChoiceCanonical == true
	if allowTalentChoiceCanonical then
		local dynamicGroups = self:GetActiveTalentChoiceGroupsForSpell(numericID)
		if type(dynamicGroups) == "table" then
			for i = 1, #dynamicGroups do
				local canonicalID = tonumber(dynamicGroups[i] and dynamicGroups[i].canonicalID)
				if canonicalID and canonicalID > 0 then return canonicalID end
			end
		end
	end
	if self:IsRacialSpellID(numericID) then return numericID end
	local canonicalID, _, staticGroup = self:GetStaticCanonicalSpellVariantID(numericID)
	if staticGroup then return canonicalID end
	return numericID
end

local function isSpellPassiveSafe(spellId, effectiveId)
	if not spellId or not Api.IsSpellPassiveFn then return false end
	local checkId = effectiveId or getEffectiveSpellId(spellId) or spellId
	if Api.IsSpellPassiveFn(checkId) then return true end
	if checkId ~= spellId and Api.IsSpellPassiveFn(spellId) then return true end
	return false
end

local function shouldTrackPassiveSpell(entry)
	return entry and entry.trackPassiveSpell == true
end

function cdp.ENTRY.ShouldTrackUnknownSpell(entry)
	return entry and entry.trackUnknownSpell == true
end

function cdp.ENTRY.AttachControlTooltip(control, tooltipText)
	if not control or not tooltipText or tooltipText == "" then return end
	control:SetScript("OnEnter", function(self)
		if not GameTooltip then return end
		GameTooltip:SetOwner(self, "ANCHOR_RIGHT", 6, 0)
		GameTooltip:ClearLines()
		GameTooltip:AddLine(tooltipText, 1, 1, 1, true)
		GameTooltip:Show()
	end)
	control:SetScript("OnLeave", function()
		if GameTooltip then GameTooltip:Hide() end
	end)
end

local function setPowerInsufficient(runtime, spellId, isUsable, insufficientPower)
	if not runtime or not spellId then return false end
	runtime.powerInsufficient = runtime.powerInsufficient or {}
	runtime.spellUnusable = runtime.spellUnusable or {}
	local usable = isUsable == true
	local powerValue = (insufficientPower == true) and true or nil
	local unusableValue = (not usable and insufficientPower ~= true) and true or nil
	local changed = false
	local aliasCache = runtime.powerAliasIdsBySpell
	local ids = aliasCache and aliasCache[spellId]
	if not ids then
		ids = CooldownPanels:GetSpellAliasIDs(spellId)
		if aliasCache then aliasCache[spellId] = ids end
	end
	for i = 1, #ids do
		local id = ids[i]
		if runtime.powerInsufficient[id] ~= powerValue then
			runtime.powerInsufficient[id] = powerValue
			changed = true
		end
		if runtime.spellUnusable[id] ~= unusableValue then
			runtime.spellUnusable[id] = unusableValue
			changed = true
		end
	end
	return changed
end

local function getSpellPowerCostNamesFromCosts(costs)
	if type(costs) ~= "table" then return nil end
	local names, seen = {}, {}
	for _, info in ipairs(costs) do
		local name = info and info.name
		if type(name) == "string" and name ~= "" then
			local upperName = string.upper(name)
			if upperName ~= "" and not seen[upperName] then
				seen[upperName] = true
				names[#names + 1] = upperName
			end
		end
		local powerType = info and tonumber(info.type)
		local token = powerType and CooldownPanels.POWER_TYPE_TOKEN_BY_ID and CooldownPanels.POWER_TYPE_TOKEN_BY_ID[powerType] or nil
		if token and token ~= "" and not seen[token] then
			seen[token] = true
			names[#names + 1] = token
		end
	end
	if #names == 0 then return nil end
	return names
end

local function getSpellPowerCostNames(spellId)
	if not spellId or not Api.GetSpellPowerCost then return nil end
	return getSpellPowerCostNamesFromCosts(Api.GetSpellPowerCost(spellId))
end

local function getRuntime(panelId)
	local runtime = CooldownPanels.runtime[panelId]
	if not runtime then
		runtime = {}
		CooldownPanels.runtime[panelId] = runtime
	end
	return runtime
end

function CooldownPanels:GetEntrySpecFilteredOrder(panelId, panel, sourceOrder, currentSpecId)
	local runtime = getRuntime(panelId)
	local generation = Helper.GetPanelEntrySpecFilterGeneration and Helper.GetPanelEntrySpecFilterGeneration(panel) or 0
	if
		runtime._eqolEntrySpecFilterOrder
		and runtime._eqolEntrySpecFilterSourceOrder == sourceOrder
		and runtime._eqolEntrySpecFilterEntries == panel.entries
		and runtime._eqolEntrySpecFilterGeneration == generation
		and runtime._eqolEntrySpecFilterSpecId == currentSpecId
	then
		return runtime._eqolEntrySpecFilterOrder
	end
	local filteredOrder = {}
	if currentSpecId then
		for _, entryId in ipairs(sourceOrder or {}) do
			local entry = panel.entries and panel.entries[entryId] or nil
			if entry and CooldownPanels.EntryAllowsSpec(entry, currentSpecId) then
				filteredOrder[#filteredOrder + 1] = entryId
			elseif entry then
				CooldownPanels.ClearReadyGlowEntryState(panelId, entryId, true)
			end
		end
	end
	runtime._eqolEntrySpecFilterOrder = filteredOrder
	runtime._eqolEntrySpecFilterSourceOrder = sourceOrder
	runtime._eqolEntrySpecFilterEntries = panel.entries
	runtime._eqolEntrySpecFilterGeneration = generation
	runtime._eqolEntrySpecFilterSpecId = currentSpecId
	return filteredOrder
end

local PanelVisibility = (function()
	local optionCache

	local function copySelectionMap(selection)
		if type(selection) ~= "table" then return nil end
		local out
		for key, value in pairs(selection) do
			if value == true then
				out = out or {}
				out[key] = true
			end
		end
		return out
	end

	local function normalizeConfig(config)
		local normalize = addon.functions and addon.functions.NormalizeActionbarVisibilityConfig
		if normalize then return normalize(config) end
		return nil
	end

	local function getRuleOptions()
		if optionCache then return optionCache end
		local getOptions = addon.functions and addon.functions.GetActionbarVisibilityRuleOptions
		optionCache = getOptions and getOptions() or {}
		return optionCache
	end

	local function shouldShow(config)
		local cfg = normalizeConfig(config)
		if not cfg then return true end
		local shouldShowConfig = addon.functions and addon.functions.ShouldShowVisibilityConfig
		if shouldShowConfig then
			return shouldShowConfig(cfg, {
				supportsPlayerTargetRule = true,
				supportsPlayerCastingRule = true,
				supportsPlayerMountedRule = true,
				supportsGroupRule = true,
			})
		end
		return true
	end

	return {
		CopySelectionMap = copySelectionMap,
		NormalizeConfig = normalizeConfig,
		GetRuleOptions = getRuleOptions,
		ShouldShow = shouldShow,
	}
end)()

local updatePowerEventRegistration
local updateRangeCheckSpells
local updateItemCountCacheForItem
local ensureRoot
local ensurePanelAnchor
local panelAllowsSpec
local ensureAssistedHighlightHook

local STRATA_INDEX = {}
for index, strata in ipairs(Helper.STRATA_ORDER or {}) do
	if type(strata) == "string" and strata ~= "" then STRATA_INDEX[strata] = index end
end

local function getLayoutEditPanelHandleStrata(strata)
	local targetStrata = Helper.NormalizeStrata(strata, Helper.PANEL_LAYOUT_DEFAULTS.strata)
	local overlayStrata = Helper.NormalizeStrata("TOOLTIP", targetStrata)
	local targetIndex = STRATA_INDEX[targetStrata] or 0
	local overlayIndex = STRATA_INDEX[overlayStrata] or targetIndex
	if overlayIndex > targetIndex then return overlayStrata end
	return targetStrata
end

local function syncLayoutSelectionStrata(frame)
	if not (frame and frame.GetFrameStrata) then return end
	local selection = frame.Selection
	local supportsSelectionStrata = selection and selection.SetFrameStrata
	if supportsSelectionStrata and not frame._eqolSelectionBaseStrata then
		local baseStrata = Helper.NormalizeStrata((selection.GetFrameStrata and selection:GetFrameStrata()) or "MEDIUM", "MEDIUM")
		frame._eqolSelectionBaseStrata = baseStrata
		frame._eqolSelectionBaseStrataIndex = STRATA_INDEX[baseStrata] or STRATA_INDEX.MEDIUM or 3
	end
	local baseStrata = frame._eqolSelectionBaseStrata
	local baseIndex = frame._eqolSelectionBaseStrataIndex
	if not (baseStrata and baseIndex) then
		baseStrata = Helper.NormalizeStrata(frame:GetFrameStrata(), Helper.PANEL_LAYOUT_DEFAULTS.strata)
		baseIndex = STRATA_INDEX[baseStrata] or STRATA_INDEX.MEDIUM or 3
	end
	local currentStrata = Helper.NormalizeStrata(frame:GetFrameStrata(), baseStrata)
	local currentIndex = STRATA_INDEX[currentStrata]
	local targetStrata = (currentIndex and currentIndex > baseIndex) and currentStrata or baseStrata
	local anchorLevel = (selection and selection.GetFrameLevel and selection:GetFrameLevel()) or frame:GetFrameLevel()
	if supportsSelectionStrata and selection.GetFrameStrata and selection:GetFrameStrata() ~= targetStrata then selection:SetFrameStrata(targetStrata) end
	if supportsSelectionStrata and frame.editMoveHandle then
		frame.editMoveHandle:SetFrameStrata(targetStrata)
		frame.editMoveHandle:SetFrameLevel(anchorLevel + 20)
	end
	if frame.editPanelHandle then
		frame.editPanelHandle:SetFrameStrata(getLayoutEditPanelHandleStrata(targetStrata))
		frame.editPanelHandle:SetFrameLevel(anchorLevel + 21)
	end
	if supportsSelectionStrata and frame.editDropZone then
		frame.editDropZone:SetFrameStrata(frame:GetFrameStrata())
		frame.editDropZone:SetFrameLevel(frame:GetFrameLevel())
	end
end

local function refreshLayoutPanelFrame(panelId)
	local runtime = panelId and getRuntime(panelId) or nil
	syncLayoutSelectionStrata(runtime and runtime.frame)
end

local function refreshStandaloneSettingValues()
	local internal = addon.EditModeLib and addon.EditModeLib.internal
	if not internal then return end
	if internal.RequestRefreshSettingValues then
		internal:RequestRefreshSettingValues()
	elseif internal.RefreshSettingValues then
		internal:RefreshSettingValues()
	end
end

local function refreshStandaloneSettings()
	local lib = addon.EditModeLib
	if not (lib and lib.internal) then return end
	if lib.internal.RequestRefreshSettings then
		lib.internal:RequestRefreshSettings()
	elseif lib.internal.RefreshSettings then
		lib.internal:RefreshSettings()
	end
	if lib.internal.RefreshSettingValues then lib.internal:RefreshSettingValues() end
end

CooldownPanels.MarkRelativeFrameEntriesDirty = function()
	CooldownPanels.runtime = CooldownPanels.runtime or {}
	local runtime = CooldownPanels.runtime
	runtime._eqolRelativeFrameEntriesVersion = (runtime._eqolRelativeFrameEntriesVersion or 0) + 1
end

local fakeCursorFrame
local fakeCursorResetOnShow = true
local cursorFollowRunner
local cursorSpecRetryPending

local function ensureFakeCursorFrame()
	if fakeCursorFrame then return fakeCursorFrame end
	local frame = CreateFrame("Frame", cdp.FAKE_CURSOR.FRAME_NAME, UIParent)
	frame:SetSize(cdp.FAKE_CURSOR.SIZE, cdp.FAKE_CURSOR.SIZE)
	frame:SetFrameStrata("TOOLTIP")
	frame:SetClampedToScreen(true)
	frame:EnableMouse(true)
	frame:SetMovable(true)
	frame:RegisterForDrag("LeftButton")
	frame:SetScript("OnDragStart", frame.StartMoving)
	frame:SetScript("OnDragStop", frame.StopMovingOrSizing)

	local tex = frame:CreateTexture(nil, "OVERLAY")
	tex:SetAtlas(cdp.FAKE_CURSOR.ATLAS, true)
	tex:ClearAllPoints()
	tex:SetSize(cdp.FAKE_CURSOR.SIZE, cdp.FAKE_CURSOR.SIZE)
	tex:SetPoint("CENTER", frame, "CENTER", (cdp.FAKE_CURSOR.SIZE * 0.5) - cdp.FAKE_CURSOR.HOTSPOT_X, cdp.FAKE_CURSOR.HOTSPOT_Y - (cdp.FAKE_CURSOR.SIZE * 0.5))
	frame.texture = tex

	frame:Hide()
	fakeCursorFrame = frame
	return frame
end

local function showFakeCursorFrame()
	local frame = ensureFakeCursorFrame()
	if fakeCursorResetOnShow or not frame._eqolHasPosition then
		frame:ClearAllPoints()
		frame:SetPoint("CENTER", UIParent, "CENTER", cdp.FAKE_CURSOR.DEFAULT_X, cdp.FAKE_CURSOR.DEFAULT_Y)
		frame._eqolHasPosition = true
		fakeCursorResetOnShow = false
	end
	frame:Show()
	return frame
end

local function hideFakeCursorFrame()
	if fakeCursorFrame then
		fakeCursorFrame:SetAlpha(0)
		if fakeCursorFrame.texture then fakeCursorFrame.texture:Hide() end
		fakeCursorFrame:EnableMouse(false)
		fakeCursorFrame:Hide()
	end
end

local function resetFakeCursorFrame()
	fakeCursorResetOnShow = true
	if fakeCursorFrame then fakeCursorFrame._eqolHasPosition = nil end
end

local function setFakeCursorMode(mode)
	-- Always re-apply the visual state because layout edit paths can manipulate
	-- the fake cursor frame directly between mode transitions.
	if mode ~= "edit" and mode ~= "follow" then mode = "hidden" end
	if mode == "hidden" then
		hideFakeCursorFrame()
		return
	end
	local frame = ensureFakeCursorFrame()
	if mode == "edit" then
		showFakeCursorFrame()
		frame:SetAlpha(1)
		if frame.texture then frame.texture:Show() end
		frame:EnableMouse(true)
		frame:Show()
	elseif mode == "follow" then
		fakeCursorResetOnShow = false
		frame:SetAlpha(0)
		if frame.texture then frame.texture:Hide() end
		frame:EnableMouse(false)
		frame:Show()
	end
end

local function updateFakeCursorToMouse()
	local frame = ensureFakeCursorFrame()
	local x, y = Api.GetCursorPosition()
	if not x or not y then return end
	local scale = UIParent:GetEffectiveScale()
	frame:ClearAllPoints()
	frame:SetPoint("CENTER", UIParent, "BOTTOMLEFT", x / scale, y / scale)
end

local function startCursorFollow()
	if cursorFollowRunner and cursorFollowRunner:GetScript("OnUpdate") then return end
	if CooldownPanels:IsAnyPanelLayoutEditActive() then return end
	local runner = cursorFollowRunner
	if not runner then
		runner = CreateFrame("Frame")
		cursorFollowRunner = runner
	end
	updateFakeCursorToMouse()
	runner:SetScript("OnUpdate", function(self)
		if CooldownPanels:IsAnyPanelLayoutEditActive() then return end
		updateFakeCursorToMouse()
	end)
end

local function stopCursorFollow()
	if cursorFollowRunner then cursorFollowRunner:SetScript("OnUpdate", nil) end
end

local function panelUsesFakeCursor(panel)
	local anchor = ensurePanelAnchor(panel)
	local rel = anchor and anchor.relativeFrame
	return rel == cdp.FAKE_CURSOR.FRAME_NAME
end

CooldownPanels.IsPanelRuntimeEnabled = function(panelId, panel, runtime)
	if not panel or panel.enabled == false then return false end
	local sharedRuntime = runtime or CooldownPanels.runtime
	local enabledPanels = sharedRuntime and sharedRuntime.enabledPanels
	if enabledPanels then return enabledPanels[panelId] == true end
	return panelAllowsSpec(panel)
end

local function hasSpecFilteredCursorPanels()
	local root = ensureRoot()
	if not root or not root.panels then return false end
	for _, panel in pairs(root.panels) do
		if panel and panelUsesFakeCursor(panel) and panel.enabled ~= false then
			local filter = panel.specFilter
			if type(filter) == "table" then
				for _, enabled in pairs(filter) do
					if enabled then return true end
				end
			end
		end
	end
	return false
end

local function scheduleCursorSpecRetry()
	if cursorSpecRetryPending then return end
	if not C_Timer or not C_Timer.After then return end
	cursorSpecRetryPending = true
	C_Timer.After(0.5, function()
		cursorSpecRetryPending = false
		if not hasSpecFilteredCursorPanels() then return end
		if queryPlayerSpecId() then
			CooldownPanels:UpdateCursorAnchorState()
			return
		end
		scheduleCursorSpecRetry()
	end)
end

local function hasFakeCursorPanels()
	local root = ensureRoot()
	if not root or not root.panels then return false end
	for _, panel in pairs(root.panels) do
		if panel and panelUsesFakeCursor(panel) then
			if panel.enabled ~= false and panelAllowsSpec(panel) then return true end
		end
	end
	return false
end

function CooldownPanels:GetLayoutEditFakeCursorPanel()
	local runtime = CooldownPanels.runtime
	local editor = runtime and runtime.editor or nil
	if not (editor and editor.frame and editor.frame:IsShown()) then return nil end
	if editor.layoutEditActive ~= true then return nil end
	local panelId = normalizeId(editor.selectedPanelId)
	if not panelId then return nil end
	local panel = CooldownPanels:GetPanel(panelId)
	if panel and panelUsesFakeCursor(panel) then return panelId, panel end
	return nil
end

function CooldownPanels:UpdateCursorAnchorState()
	local layoutEditCursorPanelId = self:GetLayoutEditFakeCursorPanel()
	local wantsCursor = layoutEditCursorPanelId ~= nil or hasFakeCursorPanels()
	if wantsCursor then
		if layoutEditCursorPanelId then
			stopCursorFollow()
			setFakeCursorMode("edit")
			local frame = showFakeCursorFrame()
			frame:SetAlpha(1)
			if frame.texture then frame.texture:Show() end
			frame:EnableMouse(false)
			frame:Show()
			local runtime = getRuntime(layoutEditCursorPanelId)
			CooldownPanels.ClearAppliedAnchorCache(runtime)
			self:ApplyPanelPosition(layoutEditCursorPanelId)
		else
			setFakeCursorMode("follow")
			startCursorFollow()
		end
		cursorSpecRetryPending = false
	else
		stopCursorFollow()
		setFakeCursorMode("hidden")
		if hasSpecFilteredCursorPanels() and not queryPlayerSpecId() then scheduleCursorSpecRetry() end
	end
end

function CooldownPanels:GetGlowStyleOptions(panelId, layout, excludeActionButtonProc)
	layout = layout or (panelId and self:GetPanel(panelId) and self:GetPanel(panelId).layout) or nil
	local shape = cdp.ENTRY.NormalizeIconShape(layout and layout.iconShape, Helper.PANEL_LAYOUT_DEFAULTS.iconShape)
	if not cdp.ENTRY.IsIconShapeBackdropBorderCompatible(shape) then
		for _, option in ipairs(Helper.GLOW_STYLE_OPTIONS or {}) do
			if option.value == "PULSING" then return { option } end
		end
	end
	local options = {}
	for _, option in ipairs(Helper.GLOW_STYLE_OPTIONS or {}) do
		local supportedByBorder = layout and layout.iconBorderEnabled == true or option.value ~= "TINT_BORDER"
		local supportedByAura = excludeActionButtonProc ~= true or option.value ~= "PROC"
		if supportedByBorder and supportedByAura then options[#options + 1] = option end
	end
	return options
end

function CooldownPanels:IsInterruptGlowSupported(entry)
	if not (entry and entry.type == "SPELL") then return false end
	local tracker = addon.Aura and addon.Aura.FocusInterruptTracker
	if not (tracker and tracker.IsInterruptSpell) then return false end
	return tracker:IsInterruptSpell(entry.spellID) == true
end

function CooldownPanels:GetInterruptGlowTargetCondition(spellId)
	local tracker = addon.Aura and addon.Aura.FocusInterruptTracker
	if not (tracker and tracker.IsInterruptSpellReady and tracker.GetTargetInterruptibleCast) then return false, nil end
	if not tracker:IsInterruptSpellReady(spellId) then return false, nil end
	local cast = tracker:GetTargetInterruptibleCast()
	if not cast then return false, nil end
	return true, cast.rawNotInterruptible
end

cdp.ICON_BORDER = cdp.ICON_BORDER or {
	DEFAULT = "DEFAULT",
	BLIZZARD = "BLIZZARD",
	BLIZZARD_ALIAS = "ORIGINAL_BLIZZARD",
	SHAPE_METAL_LIGHT = addon.IconShape and addon.IconShape.BORDER and addon.IconShape.BORDER.ROUND_METAL_LIGHT or "SHAPE_ATLAS_CHARACTERCREATE_RING_METALLIGHT",
	SHAPE_COMMUNITIES_BLUE = addon.IconShape and addon.IconShape.BORDER and addon.IconShape.BORDER.ROUND_COMMUNITIES_BLUE or "SHAPE_ATLAS_COMMUNITIES_RING_BLUE",
	SHAPE_HEXAGON_1PX = addon.IconShape and addon.IconShape.BORDER and addon.IconShape.BORDER.HEXAGON_1PX or "SHAPE_TEXTURE_HEXAGON_1PX",
	SHAPE_DIAMOND_1PX = addon.IconShape and addon.IconShape.BORDER and addon.IconShape.BORDER.DIAMOND_1PX or "SHAPE_TEXTURE_DIAMOND_1PX",
	OVERLAY_ATLAS = "UI-HUD-CoolDownManager-IconOverlay",
	MASK_ATLAS = "UI-HUD-CoolDownManager-Mask",
	DEFAULT_SWIPE_TEXTURE = "Interface\\Buttons\\WHITE8X8",
	SWIPE_TEXTURE = "Interface\\HUD\\UI-HUD-CoolDownManager-Icon-Swipe",
	OVERLAY_OFFSET_X_RATIO = 0.175,
	OVERLAY_OFFSET_Y_RATIO = 0.175,
	OVERLAY_OFFSET_X_NUDGE = 0,
	ICON_BOTTOM_INSET = 2,
}
cdp.ICON_SHAPE = cdp.ICON_SHAPE or addon.IconShape or { DEFAULT = "DEFAULT", SQUARE = "SQUARE", ROUND = "ROUND", ROUND_STAR = "ROUND_STAR", STAR = "STAR", HEXAGON = "HEXAGON", DIAMOND = "DIAMOND" }
cdp.ICON_BORDER.SHAPE_ATLASES = cdp.ICON_BORDER.SHAPE_ATLASES or (addon.IconShape and addon.IconShape.BORDER_DEFINITIONS) or {}
cdp.ICON_BORDER.SHAPE_ATLAS_ORDER = cdp.ICON_BORDER.SHAPE_ATLAS_ORDER or (addon.IconShape and addon.IconShape.BORDER_ORDER) or {}

function cdp.ENTRY.IsIconShapeBackdropBorderCompatible(shape)
	if addon.IconShape and addon.IconShape.IsBackdropBorderCompatible then return addon.IconShape.IsBackdropBorderCompatible(shape) end
	shape = cdp.ENTRY.NormalizeIconShape(shape, Helper.PANEL_LAYOUT_DEFAULTS.iconShape)
	return shape == cdp.ICON_SHAPE.DEFAULT or shape == cdp.ICON_SHAPE.SQUARE
end

function cdp.ENTRY.IsShapeIconBorderTexture(value)
	if addon.IconShape and addon.IconShape.IsShapeBorder then return addon.IconShape.IsShapeBorder(value) end
	return type(value) == "string" and cdp.ICON_BORDER.SHAPE_ATLASES[value] ~= nil
end

function cdp.ENTRY.IsShapeIconBorderCompatible(value, shape)
	if addon.IconShape and addon.IconShape.IsBorderCompatible then return addon.IconShape.IsBorderCompatible(value, shape) end
	local info = type(value) == "string" and cdp.ICON_BORDER.SHAPE_ATLASES[value] or nil
	if not info then return false end
	shape = cdp.ENTRY.NormalizeIconShape(shape, Helper.PANEL_LAYOUT_DEFAULTS.iconShape)
	return type(info.shapes) ~= "table" or info.shapes[shape] == true
end

local function iconBorderOptions(shape)
	if addon.IconShape and addon.IconShape.GetBorderOptions then
		return addon.IconShape.GetBorderOptions(L, shape, {
			defaultOptions = {
				{ value = cdp.ICON_BORDER.DEFAULT, label = _G.DEFAULT or (L and L["Default"]) or "Default" },
				{ value = cdp.ICON_BORDER.BLIZZARD, label = L["CooldownPanelIconBorderBlizzard"] or "Original Blizzard" },
			},
			includeLSM = true,
		})
	end
	local list = {}
	local seen = {}
	local function add(value, label)
		local lv = tostring(value or ""):lower()
		if lv == "" or seen[lv] then return end
		seen[lv] = true
		list[#list + 1] = { value = value, label = label or value }
	end
	if not cdp.ENTRY.IsIconShapeBackdropBorderCompatible(shape) then
		for _, value in ipairs(cdp.ICON_BORDER.SHAPE_ATLAS_ORDER) do
			local info = cdp.ICON_BORDER.SHAPE_ATLASES[value]
			if cdp.ENTRY.IsShapeIconBorderCompatible(value, shape) then add(value, L[info.labelKey] or info.label) end
		end
		return list
	end
	add(cdp.ICON_BORDER.DEFAULT, _G.DEFAULT or (L and L["Default"]) or "Default")
	add(cdp.ICON_BORDER.BLIZZARD, L["CooldownPanelIconBorderBlizzard"] or "Original Blizzard")
	local names = addon.functions and addon.functions.GetLSMMediaNames and addon.functions.GetLSMMediaNames("border") or {}
	local hash = addon.functions and addon.functions.GetLSMMediaHash and addon.functions.GetLSMMediaHash("border") or {}
	for i = 1, #names do
		local name = names[i]
		local path = hash[name]
		if type(path) == "string" and path ~= "" then add(name, tostring(name)) end
	end
	return list
end

local function normalizeIconBorderTexture(value, fallback, shape)
	if not cdp.ENTRY.IsIconShapeBackdropBorderCompatible(shape) then
		if addon.IconShape and addon.IconShape.NormalizeBorder then return addon.IconShape.NormalizeBorder(value, fallback, shape, { emptyValue = cdp.ICON_BORDER.DEFAULT }) end
		if cdp.ENTRY.IsShapeIconBorderCompatible(value, shape) then return value end
		if cdp.ENTRY.IsShapeIconBorderCompatible(fallback, shape) then return fallback end
		for _, shapeValue in ipairs(cdp.ICON_BORDER.SHAPE_ATLAS_ORDER) do
			if cdp.ENTRY.IsShapeIconBorderCompatible(shapeValue, shape) then return shapeValue end
		end
		return cdp.ICON_BORDER.DEFAULT
	end
	if cdp.ENTRY.IsShapeIconBorderTexture(value) then value = nil end
	if cdp.ENTRY.IsShapeIconBorderTexture(fallback) then fallback = nil end
	if type(value) == "string" and value ~= "" then
		local upperValue = strupper(value)
		if upperValue == cdp.ICON_BORDER.BLIZZARD or upperValue == cdp.ICON_BORDER.BLIZZARD_ALIAS then return cdp.ICON_BORDER.BLIZZARD end
		return value
	end
	if type(fallback) == "string" and fallback ~= "" then return fallback end
	return cdp.ICON_BORDER.DEFAULT
end

function cdp.ENTRY.SupportsIconBorderSize(value, shape)
	local textureKey = normalizeIconBorderTexture(value, Helper.PANEL_LAYOUT_DEFAULTS.iconBorderTexture, shape)
	if addon.IconShape and addon.IconShape.SupportsBorderSize and not cdp.ENTRY.IsIconShapeBackdropBorderCompatible(shape) then return addon.IconShape.SupportsBorderSize(textureKey, shape) == true end
	if cdp.ENTRY.IsIconShapeBackdropBorderCompatible(shape) then return not cdp.ENTRY.IsBlizzardIconBorderTexture(textureKey) end
	local info = cdp.ICON_BORDER.SHAPE_ATLASES[textureKey]
	return info and info.thicknessMode == "layers"
end

function cdp.ENTRY.NormalizeIconShape(value, fallback)
	if addon.IconShape and addon.IconShape.Normalize then return addon.IconShape.Normalize(value, fallback) end
	return Helper.NormalizeIconShape(value, fallback)
end

function cdp.ENTRY.NormalizeGlowStyleForIconShape(style, fallback, shape)
	local normalized = Helper.NormalizeGlowStyle(style, fallback)
	shape = cdp.ENTRY.NormalizeIconShape(shape, Helper.PANEL_LAYOUT_DEFAULTS.iconShape)
	if not cdp.ENTRY.IsIconShapeBackdropBorderCompatible(shape) then return "PULSING" end
	return normalized
end

function cdp.ENTRY.GetIconShapeOptions()
	if addon.IconShape and addon.IconShape.GetOptions then return addon.IconShape.GetOptions(L, { exclude = { STAR = true } }) end
	return {
		{ value = "DEFAULT", label = L["settingsIconShapeDefault"] or _G.DEFAULT or "Default" },
		{ value = "ROUND_STAR", label = L["settingsIconShapeRoundStar"] or "Round star" },
		{ value = "HEXAGON", label = L["settingsIconShapeHexagon"] or "Hexagon" },
	}
end

function cdp.ENTRY.IsBlizzardIconBorderTexture(value)
	return normalizeIconBorderTexture(value, cdp.ICON_BORDER.DEFAULT) == cdp.ICON_BORDER.BLIZZARD
end

local function resolveIconBorderTexture(value)
	local key = normalizeIconBorderTexture(value, cdp.ICON_BORDER.DEFAULT)
	local ufHelper = addon.Aura and addon.Aura.UFHelper
	if ufHelper and ufHelper.resolveBorderTexture then return ufHelper.resolveBorderTexture(key) end
	if not key or key == "" or key == cdp.ICON_BORDER.DEFAULT then return "Interface\\Buttons\\WHITE8x8" end
	if LSM and LSM.Fetch then
		local tex = LSM:Fetch("border", key)
		if type(tex) == "string" and tex ~= "" then return tex end
	end
	return key
end

