function CooldownPanels:SuppressBarNativeIconPresentation(icon, data)
	local entry = data and data.entry
	if not (icon and entry and entry.displayMode == "BAR") then return end
	if data.showGhostIcon == true then return end
	if icon.texture then
		icon.texture:SetShown(false)
		icon.texture:SetAlpha(0)
	end
	if icon.cooldown then
		if icon.cooldown.SetHideCountdownNumbers then icon.cooldown:SetHideCountdownNumbers(true) end
		if icon.cooldown.SetAlpha then icon.cooldown:SetAlpha(0) end
	end
	if icon.count then icon.count:Hide() end
	if icon.charges then icon.charges:Hide() end
	if icon.keybind then icon.keybind:Hide() end
	if icon.stateTexture then icon.stateTexture:Hide() end
	if icon.stateTextureSecond then icon.stateTextureSecond:Hide() end
	if icon.staticText then icon.staticText:Hide() end
	if icon.overlay then icon.overlay:Hide() end
	if icon.blizzardIconOverlay then icon.blizzardIconOverlay:Hide() end
	self.HidePreviewGlowBorder(icon)
	self.StopAllIconGlows(icon)
end

function CooldownPanels.FillCachedColor(cache, r, g, b, a)
	cache = cache or {}
	cache[1] = r or 1
	cache[2] = g or 1
	cache[3] = b or 1
	cache[4] = a or 1
	return cache
end

function CooldownPanels.ResolveCachedEntryColor(cacheRootName, entry, color, fallbackColor)
	if not entry then return fallbackColor or Helper.ACTIVATION_OVERLAY_COLOR_DEFAULT end
	local roots = CooldownPanels._styleCacheRoots
	local root = roots and roots[cacheRootName]
	if not root then return Helper.NormalizeColor(color, fallbackColor) end
	local cache = root[entry]
	local fallbackR = fallbackColor and fallbackColor[1] or nil
	local fallbackG = fallbackColor and fallbackColor[2] or nil
	local fallbackB = fallbackColor and fallbackColor[3] or nil
	local fallbackA = fallbackColor and fallbackColor[4] or nil
	if
		not cache
		or cache.srcColor ~= color
		or cache.fallbackR ~= fallbackR
		or cache.fallbackG ~= fallbackG
		or cache.fallbackB ~= fallbackB
		or cache.fallbackA ~= fallbackA
	then
		cache = cache or {}
		cache.srcColor = color
		cache.fallbackR = fallbackR
		cache.fallbackG = fallbackG
		cache.fallbackB = fallbackB
		cache.fallbackA = fallbackA
		local r, g, b, a = Helper.ResolveColor(color, fallbackColor)
		cache.color = CooldownPanels.FillCachedColor(cache.color, r, g, b, a)
		root[entry] = cache
	end
	return cache.color
end

