function cdp.ENTRY.IsStyleClipboardKeyAllowedForEntry(key, entry)
	local style = cdp.ENTRY.STYLE_CLIPBOARD
	if type(key) ~= "string" or key:match("^_") then return false end
	if key:match("^cdmAura") and not (style.CDM_AURA_ONLY_KEYS[key] or style.SPELL_CDM_AURA_OVERLAY_KEYS[key]) then return false end
	if style.SKIP_KEYS[key] then return false end
	local entryType = entry and entry.type
	if style.SPELL_ONLY_KEYS[key] and entryType ~= "SPELL" then return false end
	if style.SPELL_CDM_AURA_OVERLAY_KEYS[key] and entryType ~= "SPELL" then return false end
	if style.ITEM_ONLY_KEYS[key] and entryType ~= "ITEM" then return false end
	if style.SLOT_ONLY_KEYS[key] and entryType ~= "SLOT" then return false end
	if style.CDM_AURA_ONLY_KEYS[key] and not style.SPELL_CDM_AURA_OVERLAY_KEYS[key] and entryType ~= "CDM_AURA" then return false end
	if style.STATE_TEXTURE_KEYS[key] then return entryType == "SPELL" or entryType == "CDM_AURA" end
	if key == "showStacks" then
		if entryType == "SLOT" then
			local slotID = tonumber(entry and entry.slotID)
			return slotID == 13 or slotID == 14
		end
		return entryType == "SPELL" or entryType == "CDM_AURA"
	end
	if key == "showStacksUseGlobal" then
		if entryType == "SLOT" then
			local slotID = tonumber(entry and entry.slotID)
			return slotID == 13 or slotID == 14
		end
		return entryType == "SPELL" or entryType == "CDM_AURA"
	end
	if key == "activationOverlayBehaviorUseGlobal" or key == "activationOverlayOnly" or key == "activationOverlayGlow" or key == "activationOverlayGlowColor" or key == "activationOverlayReverse" or key == "activationOverlayColor" then
		return entryType == "SPELL" or entryType == "ITEM" or entryType == "MACRO"
	end
	if key == "autoCooldownDurationEnabled" then return entryType == "SPELL" or entryType == "SLOT" or entryType == "MACRO" end
	if key == "customCooldownDurationOnCooldownMultipleStacks" then return entryType == "SPELL" end
	if key == "customCooldownDurationEnabled" or key == "customCooldownDurationOnCooldownEnabled" or key == "customCooldownDuration" then return entryType == "SPELL" or entryType == "ITEM" or entryType == "SLOT" or entryType == "MACRO" end
	return true
end

function cdp.ENTRY.CopyStyleValue(value) return Helper.CopyTableDeep(value) end

local function getPlayerClassSpecMap()
	local classId = UnitClass and select(3, UnitClass("player")) or nil
	if not classId then return nil end
	local getSpecCount = C_SpecializationInfo and C_SpecializationInfo.GetNumSpecializationsForClassID
	if not getSpecCount or not GetSpecializationInfoForClassID then return nil end
	local specs = {}
	local sex = UnitSex and UnitSex("player") or nil
	local specCount = getSpecCount(classId) or 0
	for specIndex = 1, specCount do
		local specID = GetSpecializationInfoForClassID(classId, specIndex, sex)
		if specID then specs[specID] = true end
	end
	return specs
end

local function panelHasSpecFilter(panel)
	local filter = panel and panel.specFilter
	if type(filter) ~= "table" then return false end
	for _, enabled in pairs(filter) do
		if enabled then return true end
	end
	return false
end

function CooldownPanels.EntryHasSpecFilter(entry)
	local filter = entry and entry.specFilter
	if type(filter) ~= "table" then return false end
	for _, enabled in pairs(filter) do
		if enabled then return true end
	end
	return false
end

local function panelHasRuntimeEntries(panel)
	if type(panel) ~= "table" or type(panel.entries) ~= "table" then return false end
	for _, entry in pairs(panel.entries) do
		if type(entry) == "table" then return true end
	end
	return false
end

panelAllowsSpec = function(panel)
	if not panelHasSpecFilter(panel) then return true end
	local specId = queryPlayerSpecId()
	if not specId then return false end
	local filter = panel and panel.specFilter
	return filter and filter[specId] == true
end

function CooldownPanels.EntryAllowsSpec(entry, currentSpecId)
	if not CooldownPanels.EntryHasSpecFilter(entry) then return true end
	local specId = currentSpecId or queryPlayerSpecId()
	if not specId then return false end
	local filter = entry and entry.specFilter
	return filter and filter[specId] == true
end

local function panelMatchesPlayerClass(panel, classSpecs)
	if not panelHasSpecFilter(panel) then return true end
	if not classSpecs or not next(classSpecs) then return true end
	for specId, enabled in pairs(panel.specFilter) do
		if enabled and classSpecs[specId] then return true end
	end
	return false
end

local function getSpecFilterLabel(panel)
	if not panelHasSpecFilter(panel) then return L["CooldownPanelSpecAny"] or "All specs" end
	local labels = {}
	if panel and panel.specFilter then
		for specId, enabled in pairs(panel.specFilter) do
			if enabled then labels[#labels + 1] = getSpecNameById(specId) end
		end
	end
	table.sort(labels)
	if #labels == 0 then return L["CooldownPanelSpecAny"] or "All specs" end
	return table.concat(labels, ", ")
end

function CooldownPanels:SetPanelEditorName(panelId, value)
	panelId = normalizeId(panelId)
	local panel = panelId and self:GetPanel(panelId) or nil
	local text = type(value) == "string" and value or tostring(value or "")
	if not (panel and text ~= "" and text ~= panel.name) then return end
	panel.name = text
	CooldownPanels.MarkRelativeFrameEntriesDirty()
	refreshStandaloneSettings()
	CooldownPanels:RefreshPanel(panelId)
	CooldownPanels:RefreshEditor()
	if self.BlizzardEditor and self.BlizzardEditor.RefreshPanel then self.BlizzardEditor:RefreshPanel(panelId) end
end

function CooldownPanels:SetPanelEditorEnabled(panelId, enabled)
	panelId = normalizeId(panelId)
	local panel = panelId and self:GetPanel(panelId) or nil
	if not panel then return end
	local nextEnabled = enabled == true
	if (panel.enabled ~= false) == nextEnabled then return end
	panel.enabled = nextEnabled
	CooldownPanels:RebuildSpellIndex()
	Keybinds.MarkPanelsDirty()
	CooldownPanels:RefreshPanel(panelId)
	CooldownPanels:UpdateCursorAnchorState()
	CooldownPanels:RefreshEditor()
end

function CooldownPanels:GetPanelSpecFilterOptions()
	local classMenuData = getClassSpecMenuData()
	local options = {
		{ value = "__all", text = L["CooldownPanelSpecAny"] or "All specs" },
	}
	for _, quickFilter in ipairs(self:GetSpecQuickFilterDefinitions(classMenuData) or {}) do
		if type(quickFilter.specIds) == "table" and #quickFilter.specIds > 0 then
			options[#options + 1] = {
				value = "__quick:" .. tostring(quickFilter.id),
				text = quickFilter.label,
			}
		end
	end
	for _, classData in ipairs(classMenuData) do
		for _, specData in ipairs(classData.specs or {}) do
			if specData.id then
				options[#options + 1] = {
					value = specData.id,
					text = string.format("%s - %s", classData.name or "", specData.name or tostring(specData.id)),
				}
			end
		end
	end
	return options
end

function CooldownPanels:GetEntrySpecFilterOptions() return self:GetPanelSpecFilterOptions() end

function CooldownPanels:GetPanelSpecQuickFilterSpecIds(value)
	local quickId = type(value) == "string" and value:match("^__quick:(.+)$") or nil
	if not quickId then return nil end
	for _, quickFilter in ipairs(self:GetSpecQuickFilterDefinitions() or {}) do
		if quickFilter.id == quickId then return quickFilter.specIds end
	end
	return nil
end

function CooldownPanels:IsPanelSpecFilterOptionSelected(panelId, value)
	panelId = normalizeId(panelId)
	local panel = panelId and self:GetPanel(panelId) or nil
	if not panel then return false end
	if value == "__all" then return not panelHasSpecFilter(panel) end
	local quickSpecIds = self:GetPanelSpecQuickFilterSpecIds(value)
	if quickSpecIds then return self:HasAllPanelSpecFilterEntries(panel, quickSpecIds) end
	local specId = tonumber(value)
	return specId and panel.specFilter and panel.specFilter[specId] == true or false
end

function CooldownPanels:IsEntrySpecFilterOptionSelected(panelId, entryId, value)
	panelId = normalizeId(panelId)
	local panel = panelId and self:GetPanel(panelId) or nil
	local entry = panel and panel.entries and panel.entries[entryId] or nil
	if not entry then return false end
	if value == "__all" then return not CooldownPanels.EntryHasSpecFilter(entry) end
	local quickSpecIds = self:GetPanelSpecQuickFilterSpecIds(value)
	if quickSpecIds then return self:HasAllEntrySpecFilterEntries(entry, quickSpecIds) end
	local specId = tonumber(value)
	return specId and entry.specFilter and entry.specFilter[specId] == true or false
end

function CooldownPanels:CommitEntrySpecFilter(panelId, panel)
	if Helper.UpdatePanelEntrySpecFilterState then Helper.UpdatePanelEntrySpecFilterState(panel) end
	self:RefreshPanel(panelId)
	self:RefreshEditor()
	if self.BlizzardEditor and self.BlizzardEditor.RefreshPanel then self.BlizzardEditor:RefreshPanel(panelId) end
end

function CooldownPanels:SetPanelSpecFilterOptionSelected(panelId, value, selected)
	panelId = normalizeId(panelId)
	local panel = panelId and self:GetPanel(panelId) or nil
	if not panel then return end
	if value == "__all" then
		if selected == true and panelHasSpecFilter(panel) then
			panel.specFilter = {}
			CooldownPanels:CommitPanelSpecFilter(panelId)
		end
		return
	end
	local quickSpecIds = self:GetPanelSpecQuickFilterSpecIds(value)
	if quickSpecIds then
		if CooldownPanels:SetPanelSpecFilterEntries(panel, quickSpecIds, selected == true) then CooldownPanels:CommitPanelSpecFilter(panelId) end
		return
	end
	local specId = tonumber(value)
	if not (specId and specId > 0) then return end
	panel.specFilter = panel.specFilter or {}
	if selected == true then
		if panel.specFilter[specId] == true then return end
		panel.specFilter[specId] = true
	elseif panel.specFilter[specId] ~= nil then
		panel.specFilter[specId] = nil
	else
		return
	end
	CooldownPanels:CommitPanelSpecFilter(panelId)
end

function CooldownPanels:SetEntrySpecFilterOptionSelected(panelId, entryId, value, selected)
	panelId = normalizeId(panelId)
	local panel = panelId and self:GetPanel(panelId) or nil
	local entry = panel and panel.entries and panel.entries[entryId] or nil
	if not entry then return end
	if value == "__all" then
		if selected == true and CooldownPanels.EntryHasSpecFilter(entry) then
			entry.specFilter = nil
			CooldownPanels:CommitEntrySpecFilter(panelId, panel)
		end
		return
	end
	local quickSpecIds = self:GetPanelSpecQuickFilterSpecIds(value)
	if quickSpecIds then
		if CooldownPanels:SetEntrySpecFilterEntries(entry, quickSpecIds, selected == true) then
			CooldownPanels:CommitEntrySpecFilter(panelId, panel)
		end
		return
	end
	local specId = tonumber(value)
	if not (specId and specId > 0) then return end
	entry.specFilter = entry.specFilter or {}
	if selected == true then
		if entry.specFilter[specId] == true then return end
		entry.specFilter[specId] = true
	elseif entry.specFilter[specId] ~= nil then
		entry.specFilter[specId] = nil
		if not next(entry.specFilter) then entry.specFilter = nil end
	else
		return
	end
	CooldownPanels:CommitEntrySpecFilter(panelId, panel)
end

local function isSpellKnownSafe(spellId)
	if not spellId then return false end
	if Api and Api.IsSpellKnown then
		local known = Api.IsSpellKnown(spellId, true)
		if known then return true end
		local overrideId = getEffectiveSpellId(spellId)
		if overrideId and overrideId ~= spellId then return Api.IsSpellKnown(overrideId, true) and true or false end
		return false
	end
	return true
end

local function spellExistsSafe(spellId)
	spellId = Helper.GetPlainPositiveSpellId(spellId)
	if not spellId then return false end
	if Api.DoesSpellExist then return Api.DoesSpellExist(spellId) and true or false end
	if C_Spell and C_Spell.GetSpellInfo then return C_Spell.GetSpellInfo(spellId) ~= nil end
	if Api.GetSpellInfoFn then return Api.GetSpellInfoFn(spellId) ~= nil end
	return true
end

function CooldownPanels:GetPlayerRacialSpellEntries()
	local entries = {}
	local _, raceTag = UnitRace("player")
	local _, classTag = UnitClass("player")
	raceTag = (addon.variables and addon.variables.unitRace) or raceTag
	if not raceTag then return entries end
	local racialCooldowns = {
		Orc = {
			DEATHKNIGHT = 20572,
			HUNTER = 20572,
			ROGUE = 20572,
			WARRIOR = 20572,
			MONK = 33697,
			SHAMAN = 33697,
			MAGE = 33702,
			PRIEST = 33702,
			WARLOCK = 33702,
		},
		Troll = 26297,
		Scourge = 7744,
		Tauren = 20549,
		BloodElf = {
			DEATHKNIGHT = 50613,
			DEMONHUNTER = 202719,
			HUNTER = 80483,
			MAGE = 28730,
			MONK = 129597,
			PALADIN = 155145,
			PRIEST = 232633,
			ROGUE = 25046,
			WARLOCK = 28730,
			WARRIOR = 69179,
		},
		Goblin = 69070,
		Human = 59752,
		Dwarf = 20594,
		NightElf = 58984,
		Gnome = 20589,
		Draenei = {
			DEATHKNIGHT = 59545,
			HUNTER = 59543,
			MAGE = 59548,
			MONK = 121093,
			PALADIN = 59542,
			PRIEST = 59544,
			ROGUE = 370626,
			SHAMAN = 59547,
			WARLOCK = 416250,
			WARRIOR = 28880,
		},
		Worgen = 68992,
		Pandaren = 107079,
		Dracthyr = { 357214, 368970 },
		Nightborne = 260364,
		HighmountainTauren = 255654,
		MagharOrc = 274738,
		ZandalariTroll = 291944,
		Vulpera = 312411,
		VoidElf = 256948,
		LightforgedDraenei = 255647,
		DarkIronDwarf = 265221,
		KulTiran = 287712,
		Mechagnome = 312924,
		EarthenDwarf = 436344,
		Haranir = 1237885,
		Harronir = 1237885,
	}
	local seen = {}
	local function getStaticSeenKey(spellId)
		local numericSpellId = tonumber(spellId)
		if not numericSpellId then return spellId end
		local canonicalID, _, staticGroup = self:GetStaticCanonicalSpellVariantID(numericSpellId)
		if staticGroup and canonicalID then return canonicalID end
		return numericSpellId
	end
	local function resolveRacialKnownVariant(spellId)
		local numericSpellId = tonumber(spellId)
		if not numericSpellId then return nil end
		if spellExistsSafe(numericSpellId) and isSpellKnownSafe(numericSpellId) then return numericSpellId end
		local _, _, staticGroup = self:GetStaticCanonicalSpellVariantID(numericSpellId)
		if type(staticGroup) == "table" then
			for i = 1, #staticGroup do
				local candidateID = tonumber(staticGroup[i])
				if candidateID and spellExistsSafe(candidateID) and isSpellKnownSafe(candidateID) then return candidateID end
			end
		end
		return numericSpellId
	end
	local function addSpell(spellId, racialSlot)
		local numericSpellId = tonumber(spellId)
		if not numericSpellId then return end
		local entrySpellId
		if self:IsRacialSpellID(numericSpellId) then
			entrySpellId = resolveRacialKnownVariant(numericSpellId)
		else
			entrySpellId = self:NormalizePersistentSpellID(numericSpellId, { allowTalentChoiceCanonical = true }) or getBaseSpellId(numericSpellId) or numericSpellId
		end
		local numericEntrySpellId = tonumber(entrySpellId)
		local seenKey = getStaticSeenKey(numericEntrySpellId)
		if seenKey and numericEntrySpellId and not seen[seenKey] and spellExistsSafe(numericEntrySpellId) and isSpellKnownSafe(numericEntrySpellId) then
			seen[seenKey] = true
			entries[#entries + 1] = {
				spellID = numericEntrySpellId,
				name = getSpellName(numericEntrySpellId) or tostring(numericEntrySpellId),
				icon = (C_Spell and C_Spell.GetSpellTexture and C_Spell.GetSpellTexture(numericEntrySpellId)) or nil,
				order = #entries + 1,
				racialSlot = tonumber(racialSlot) or (#entries + 1),
			}
		end
	end
	local candidates = racialCooldowns[raceTag]
	if type(candidates) == "table" then
		if classTag and candidates[classTag] then
			addSpell(candidates[classTag], 1)
		elseif candidates.default then
			addSpell(candidates.default, 1)
		end
		for index, spellId in ipairs(candidates) do
			addSpell(spellId, index)
		end
	else
		addSpell(candidates, 1)
	end
	table.sort(entries, function(a, b)
		return (a.order or 0) < (b.order or 0)
	end)
	if #entries == 0 then
		entries[1] = {
			spellID = 20572,
			name = L["CooldownPanelAddRacial"] or "Racial",
			icon = Helper.PREVIEW_ICON,
			isFallback = true,
			order = 1,
			racialSlot = 1,
		}
	end
	if #entries == 1 then
		entries[2] = {
			spellID = 368970,
			name = (L["CooldownPanelAddRacial"] or "Racial") .. " 2",
			icon = (C_Spell and C_Spell.GetSpellTexture and C_Spell.GetSpellTexture(368970)) or Helper.PREVIEW_ICON,
			isFallback = true,
			order = 2,
			racialSlot = 2,
		}
	end
	return entries
end

function CooldownPanels:GetPlayerRacialSpellIDSet()
	local set = self.playerRacialSpellIDSet
	if type(set) == "table" then return set end
	set = {}
	for _, spellId in ipairs(self.playerRacialSpellIDs or {}) do
		local numericSpellId = tonumber(spellId)
		if numericSpellId then set[numericSpellId] = true end
	end
	self.playerRacialSpellIDSet = set
	return set
end

function CooldownPanels:IsRacialSpellID(spellId)
	local numericSpellId = tonumber(spellId)
	if not numericSpellId then return false end
	local set = self:GetPlayerRacialSpellIDSet()
	return set[numericSpellId] == true
end

function CooldownPanels:GetCurrentPlayerRacialSpellIDs()
	local ids = {}
	local seen = {}
	local racials = self:GetPlayerRacialSpellEntries()
	for i = 1, #racials do
		local racial = racials[i]
		local spellId = tonumber(racial and racial.spellID)
		if spellId and racial.isFallback ~= true and self:IsRacialSpellID(spellId) and not seen[spellId] then
			seen[spellId] = true
			ids[#ids + 1] = spellId
		end
	end
	return ids
end

function CooldownPanels:NormalizePlayerRacialSpellID(spellId, currentPlayerRacialSpellIDs, entry)
	local numericSpellId = tonumber(spellId)
	if not numericSpellId or not self:IsRacialSpellID(numericSpellId) then return spellId end
	if type(currentPlayerRacialSpellIDs) ~= "table" or #currentPlayerRacialSpellIDs == 0 then return numericSpellId end
	local racialSlot = tonumber(entry and entry.racialSlot)
	if racialSlot and racialSlot >= 1 then
		local slotSpellId = tonumber(currentPlayerRacialSpellIDs[math.floor(racialSlot)])
		return slotSpellId or numericSpellId
	end
	for i = 1, #currentPlayerRacialSpellIDs do
		if tonumber(currentPlayerRacialSpellIDs[i]) == numericSpellId then return numericSpellId end
	end
	return tonumber(currentPlayerRacialSpellIDs[1]) or numericSpellId
end

function CooldownPanels:NormalizeActivePanelPlayerRacials(root)
	root = root or ensureRoot()
	if not (root and root.panels) then return false end
	local currentPlayerRacialSpellIDs = self:GetCurrentPlayerRacialSpellIDs()
	if type(currentPlayerRacialSpellIDs) ~= "table" or #currentPlayerRacialSpellIDs == 0 then return false end
	local changed = false
	for _, panel in pairs(root.panels) do
		if panel and panel.enabled ~= false and panelAllowsSpec(panel) then
			local panelChanged = false
			for _, entry in pairs(panel.entries or {}) do
				if entry and entry.type == "SPELL" and entry.spellID then
					local normalizedSpellID = self:NormalizePersistentSpellID(entry.spellID, { allowTalentChoiceCanonical = false }) or entry.spellID
					normalizedSpellID = self:NormalizePlayerRacialSpellID(normalizedSpellID, currentPlayerRacialSpellIDs, entry)
					if normalizedSpellID ~= entry.spellID then
						entry.spellID = normalizedSpellID
						changed = true
						panelChanged = true
					end
				end
			end
			if panelChanged then Helper.InvalidateFixedLayoutCache(panel) end
		end
	end
	if self:DedupeActivePanelPlayerRacials(root) then changed = true end
	return changed
end

function CooldownPanels:DedupeActivePanelPlayerRacials(root)
	root = root or ensureRoot()
	if not (root and root.panels) then return false end
	local changed = false
	for panelId, panel in pairs(root.panels) do
		if panel and panel.enabled ~= false and panelAllowsSpec(panel) and type(panel.entries) == "table" and type(panel.order) == "table" then
			local seen = nil
			local panelChanged = false
			for _, entryId in ipairs(panel.order) do
				local entry = panel.entries[entryId]
				local spellId = entry and entry.type == "SPELL" and tonumber(entry.spellID) or nil
				if spellId and self:IsRacialSpellID(spellId) then
					seen = seen or {}
					if seen[spellId] then
						panel.entries[entryId] = nil
						local runtime = CooldownPanels.runtime
						if runtime and runtime.actionDisplayCounts then runtime.actionDisplayCounts[Helper.GetEntryKey(panelId, entryId)] = nil end
						panelChanged = true
						changed = true
					else
						seen[spellId] = entryId
					end
				end
			end
			if panelChanged then
				Helper.SyncOrder(panel.order, panel.entries)
				Helper.InvalidateFixedLayoutCache(panel)
			end
		end
	end
	return changed
end

function CooldownPanels:RunStorageMigrations(root)
	root = root or ensureRoot()
	if type(root) ~= "table" then return false end
	local version = tonumber(root.version) or 1
	local changed = false
	if version < 2 then
		if self:DedupeActivePanelPlayerRacials(root) then changed = true end
		version = 2
	end
	if version < 3 then
		for _, panel in pairs(root.panels or {}) do
			for _, entry in pairs(panel.entries or {}) do
				if entry.glowReady == true and entry.glowReadyUseGlobal ~= false then
					entry.glowReadyUseGlobal = false
					entry.glowUseGlobal = false
					changed = true
				end
			end
		end
		version = 3
	end
	if version < 4 then
		-- The original tag-filter setter could write exclusions but could never
		-- clear them again. Those prerelease selections are ambiguous, so reset
		-- them once and let subsequent changes use the corrected setter.
		for _, panel in pairs(root.panels or {}) do
			for _, entry in pairs(panel.entries or {}) do
				if type(entry) == "table" then
					local slotID = tonumber(entry.slotID)
					local isTrinketFilterEntry = entry.auraPresetKey == "TRINKET_UPTIME" or (entry.type == "SLOT" and (slotID == 13 or slotID == 14))
					if isTrinketFilterEntry then
						if entry.auraPresetExcludedActivations ~= nil then
							entry.auraPresetExcludedActivations = nil
							changed = true
						end
						if entry.auraPresetExcludedEffects ~= nil then
							entry.auraPresetExcludedEffects = nil
							changed = true
						end
					end
				end
			end
		end
		version = 4
	end
	if version < 5 then
		for panelId, panel in pairs(root.panels or {}) do
			local layout = panel.layout
			if type(layout) == "table" then
				if layout.pandemicGlowStyle == "PROC" then
					layout.pandemicGlowStyle = "MARCHING_ANTS"
					changed = true
				end
				for _, group in ipairs(layout.fixedGroups or {}) do
					local overrides = type(group) == "table" and group.layoutOverrides or nil
					if type(overrides) == "table" and overrides.pandemicGlowStyle == "PROC" then
						overrides.pandemicGlowStyle = "MARCHING_ANTS"
						changed = true
					end
				end
			end
			local effectiveLayoutCache = {}
			for _, entry in pairs(panel.entries or {}) do
				if type(entry) == "table" and entry.type == "CDM_AURA" then
					local layout = self:GetEntryEffectiveLayout(panelId, entry, effectiveLayoutCache, panel) or panel.layout
					local activeStyle = select(3, self:ResolveEntryGlowStyle(layout, entry))
					local pandemicStyle = select(2, self:ResolveEntryPandemicGlowVisual(layout, entry))
					if activeStyle == "PROC" then
						entry.glowUseGlobal = false
						entry.glowStyle = "MARCHING_ANTS"
						changed = true
					end
					if pandemicStyle == "PROC" then
						entry.glowUseGlobal = false
						entry.pandemicGlowStyle = "MARCHING_ANTS"
						changed = true
					end
				end
			end
		end
		version = 5
	end
	if root.version ~= COOLDOWN_PANELS_STORAGE_VERSION then
		root.version = COOLDOWN_PANELS_STORAGE_VERSION
		changed = true
	end
	return changed
end

function CooldownPanels:FindEquivalentSpellEntry(panelId, spellId)
	panelId = normalizeId(panelId)
	local panel = self:GetPanel(panelId)
	local numericSpellId = tonumber(spellId)
	if not (panel and numericSpellId) then return nil end
	for entryId, entry in pairs(panel.entries or {}) do
		if entry and entry.type == "SPELL" and entry.spellID and self:AreSpellVariantsEquivalent(entry.spellID, numericSpellId) then return entryId, entry end
	end
	return nil
end

function CooldownPanels:AddPlayerRacialEntry(panelId, spellId, racialSlot)
	panelId = normalizeId(panelId)
	local numericSpellId = tonumber(spellId)
	if not (panelId and numericSpellId) then return nil, "INVALID" end
	if self:FindEntryByValue(panelId, "SPELL", numericSpellId) or self:FindEquivalentSpellEntry(panelId, numericSpellId) then return nil, "DUPLICATE" end
	local overrides = nil
	local numericRacialSlot = tonumber(racialSlot)
	if numericRacialSlot and numericRacialSlot >= 1 then overrides = { racialSlot = math.floor(numericRacialSlot) } end
	return self:AddEntrySafe(panelId, "SPELL", numericSpellId, overrides)
end

function CooldownPanels:AddPlayerRacialEntries(panelId)
	panelId = normalizeId(panelId)
	if not panelId then return nil end
	local entries = self:GetPlayerRacialSpellEntries()
	if #entries == 0 then return { added = 0, duplicates = 0, total = 0 } end
	local stats = { added = 0, duplicates = 0, total = #entries }
	for _, racial in ipairs(entries) do
		local spellId = tonumber(racial and racial.spellID)
		if spellId then
			local entryId, reason = self:AddPlayerRacialEntry(panelId, spellId, racial.racialSlot)
			if entryId then
				stats.added = stats.added + 1
			elseif reason == "DUPLICATE" then
				stats.duplicates = stats.duplicates + 1
			end
		end
	end
	if stats.added > 0 then self:RefreshEditor() end
	return stats
end

