function CooldownPanels:IsEntryRacialVariantExcluded(entry, spellId)
	local exclusions = entry and entry.racialVariantExclusions
	local numericSpellId = tonumber(spellId)
	if type(exclusions) ~= "table" or not numericSpellId then return false end
	for excludedSpellId, excluded in pairs(exclusions) do
		if excluded == true and self:AreSpellVariantsEquivalent(numericSpellId, excludedSpellId) then return true end
	end
	return false
end

function CooldownPanels:GetRacialExclusionsButtonText(entry)
	local count = 0
	if type(entry and entry.racialVariantExclusions) == "table" then
		for _, excluded in pairs(entry.racialVariantExclusions) do
			if excluded == true then count = count + 1 end
		end
	end
	local label = L["CooldownPanelRacialExclusions"] or "Excluded racials"
	if count > 0 then return string.format("%s (%d)", label, count) end
	return label
end

local function showErrorMessage(msg)
	if UIErrorsFrame and msg then UIErrorsFrame:AddMessage(msg, 1, 0.2, 0.2, 1) end
end

ensureRoot = function()
	if not addon.db then return nil end
	if type(addon.db.cooldownPanels) ~= "table" then addon.db.cooldownPanels = Helper.CreateRoot() end
	local root = addon.db.cooldownPanels
	local needsNormalize = not normalizedRoots[root] or type(root.panels) ~= "table" or type(root.order) ~= "table" or type(root.defaults) ~= "table"
	if needsNormalize then
		Helper.NormalizeRoot(root)
		root._eqolEditorGroupsReady = nil
		root._eqolEditorGroupOrderDirty = true
		local runtime = CooldownPanels.runtime
		if runtime and runtime._eqolPanelIdCacheRoot == root then
			runtime._eqolPanelIdCache = nil
			runtime._eqolPanelIdCacheRoot = nil
		end
		normalizedRoots[root] = true
	end
	if CooldownPanels.EnsureEditorGroupStorage then CooldownPanels.EnsureEditorGroupStorage(root) end
	return root
end

CooldownPanels.EnsureEditorGroupStorage = function(root)
	if not root then return nil end
	if type(root.editorGroups) ~= "table" then
		root.editorGroups = {}
		root._eqolEditorGroupsReady = nil
		root._eqolEditorGroupOrderDirty = true
	end
	if type(root.editorGroupOrder) ~= "table" then
		root.editorGroupOrder = {}
		root._eqolEditorGroupsReady = nil
		root._eqolEditorGroupOrderDirty = true
	end
	if root._eqolEditorGroupsReady == true then
		if root._eqolEditorGroupOrderDirty == true then CooldownPanels:SortEditorGroupOrder(root) end
		return root
	end

	local groups = root.editorGroups
	local order = root.editorGroupOrder
	local groupsByName = {}

	for groupId, group in pairs(groups) do
		if type(group) ~= "table" then
			groups[groupId] = { id = groupId, name = "Group " .. tostring(groupId) }
			group = groups[groupId]
		end
		group.id = normalizeId(group.id) or normalizeId(groupId) or groupId
		group.name = CooldownPanels.NormalizePanelGroupName(group.name) or ("Group " .. tostring(group.id))
		group.parentGroupId = normalizeId(group.parentGroupId)
		groupsByName[group.name] = group.id
	end

	for groupId, group in pairs(groups) do
		local parentGroupId = normalizeId(group.parentGroupId)
		if parentGroupId == groupId or not groups[parentGroupId] then parentGroupId = nil end
		group.parentGroupId = parentGroupId
	end

	for groupId, group in pairs(groups) do
		local seen = { [groupId] = true }
		local parentGroupId = normalizeId(group.parentGroupId)
		while parentGroupId do
			if seen[parentGroupId] then
				group.parentGroupId = nil
				break
			end
			seen[parentGroupId] = true
			local parentGroup = groups[parentGroupId]
			parentGroupId = parentGroup and normalizeId(parentGroup.parentGroupId) or nil
		end
	end

	Helper.SyncOrder(order, groups)

	local panels = root.panels or {}
	for _, panel in pairs(panels) do
		if type(panel) == "table" then
			local groupId = normalizeId(panel.editorGroupId)
			if groupId and groups[groupId] then
				panel.editorGroupId = groupId
			else
				panel.editorGroupId = nil
			end

			local legacyName = CooldownPanels.NormalizePanelGroupName(panel.editorGroup)
			if legacyName and not panel.editorGroupId then
				local existingId = groupsByName[legacyName]
				if not existingId then
					existingId = Helper.GetNextNumericId(groups)
					groups[existingId] = { id = existingId, name = legacyName }
					order[#order + 1] = existingId
					groupsByName[legacyName] = existingId
				end
				panel.editorGroupId = existingId
			end
			panel.editorGroup = nil
		end
	end

	Helper.SyncOrder(order, groups)
	root._eqolEditorGroupsReady = true
	root._eqolEditorGroupOrderDirty = true
	CooldownPanels:SortEditorGroupOrder(root)
	return root
end

function CooldownPanels.GetEditorGroup(root, groupId)
	root = CooldownPanels.EnsureEditorGroupStorage(root)
	groupId = normalizeId(groupId)
	return root and root.editorGroups and groupId and root.editorGroups[groupId] or nil
end

function CooldownPanels.GetEditorGroupName(root, groupId)
	local group = CooldownPanels.GetEditorGroup(root, groupId)
	return group and group.name or nil
end

function CooldownPanels.IsEditorGroupNameBefore(a, b)
	local left = CooldownPanels.NormalizePanelGroupName(a) or ""
	local right = CooldownPanels.NormalizePanelGroupName(b) or ""
	if strcmputf8i then
		local cmp = strcmputf8i(left, right)
		if cmp ~= 0 then return cmp < 0 end
	end
	local leftLower = tostring(left):lower()
	local rightLower = tostring(right):lower()
	if leftLower ~= rightLower then return leftLower < rightLower end
	return tostring(left) < tostring(right)
end

function CooldownPanels:SortEditorGroupOrder(root)
	if not root then return nil end
	if type(root.editorGroups) ~= "table" then root.editorGroups = {} end
	if type(root.editorGroupOrder) ~= "table" then root.editorGroupOrder = {} end
	if root._eqolEditorGroupsReady == true and root._eqolEditorGroupOrderDirty ~= true then return root.editorGroupOrder end
	Helper.SyncOrder(root.editorGroupOrder, root.editorGroups)
	table.sort(root.editorGroupOrder, function(leftId, rightId)
		local leftGroup = root.editorGroups[leftId]
		local rightGroup = root.editorGroups[rightId]
		local leftName = leftGroup and leftGroup.name or tostring(leftId or "")
		local rightName = rightGroup and rightGroup.name or tostring(rightId or "")
		if leftName == rightName then return (tonumber(leftId) or 0) < (tonumber(rightId) or 0) end
		return CooldownPanels.IsEditorGroupNameBefore(leftName, rightName)
	end)
	root._eqolEditorGroupOrderDirty = nil
	return root.editorGroupOrder
end

function CooldownPanels:CanSetEditorGroupParent(root, groupId, parentGroupId)
	root = CooldownPanels.EnsureEditorGroupStorage(root)
	groupId = normalizeId(groupId)
	parentGroupId = normalizeId(parentGroupId)
	if not (root and groupId and root.editorGroups and root.editorGroups[groupId]) then return false end
	if parentGroupId == nil then return true end
	if not root.editorGroups[parentGroupId] or parentGroupId == groupId then return false end
	while parentGroupId do
		if parentGroupId == groupId then return false end
		local parentGroup = root.editorGroups[parentGroupId]
		parentGroupId = parentGroup and normalizeId(parentGroup.parentGroupId) or nil
	end
	return true
end

function CooldownPanels:BuildEditorGroupHierarchy(root)
	root = CooldownPanels.EnsureEditorGroupStorage(root)
	local groups = root and root.editorGroups or {}
	local order = root and root.editorGroupOrder or {}
	local childrenByParent = { ["__root"] = {} }
	local depthByGroup = {}

	local function getParentKey(parentGroupId)
		parentGroupId = normalizeId(parentGroupId)
		if parentGroupId ~= nil then return tostring(parentGroupId) end
		return "__root"
	end

	for _, groupId in ipairs(order) do
		local group = groups[groupId]
		if group then
			local key = getParentKey(group.parentGroupId)
			local bucket = childrenByParent[key]
			if not bucket then
				bucket = {}
				childrenByParent[key] = bucket
			end
			bucket[#bucket + 1] = groupId
		end
	end

	local function assignDepth(parentGroupId, depth)
		local key = getParentKey(parentGroupId)
		for _, childGroupId in ipairs(childrenByParent[key] or {}) do
			if depthByGroup[childGroupId] == nil then
				depthByGroup[childGroupId] = depth
				assignDepth(childGroupId, depth + 1)
			end
		end
	end

	assignDepth(nil, 0)
	return childrenByParent, depthByGroup
end

function CooldownPanels:GetEditorGroupDescendantIdSet(root, groupId)
	local descendants = {}
	groupId = normalizeId(groupId)
	if not groupId then return descendants end
	local childrenByParent = self:BuildEditorGroupHierarchy(root)

	local function collect(parentGroupId)
		local key = parentGroupId ~= nil and tostring(parentGroupId) or "__root"
		for _, childGroupId in ipairs(childrenByParent[key] or {}) do
			descendants[childGroupId] = true
			collect(childGroupId)
		end
	end

	collect(groupId)
	return descendants
end

function CooldownPanels:PopulateEditorGroupRadioMenu(menu, root, selectedGroupId, onSelect, options)
	if not (menu and onSelect) then return false end
	root = CooldownPanels.EnsureEditorGroupStorage(root)
	selectedGroupId = normalizeId(selectedGroupId)
	local childrenByParent, depthByGroup = self:BuildEditorGroupHierarchy(root)
	local skipGroupIds = options and options.skipGroupIds or nil
	local hasGroups = false

	local function appendChoices(parentGroupId)
		local key = parentGroupId ~= nil and tostring(parentGroupId) or "__root"
		for _, groupId in ipairs(childrenByParent[key] or {}) do
			local group = root.editorGroups and root.editorGroups[groupId] or nil
			if group then
				local skip = skipGroupIds and skipGroupIds[groupId] == true
				if not skip then
					hasGroups = true
					local depth = depthByGroup[groupId] or 0
					local prefix = depth > 0 and string.rep("> ", depth) or ""
					local label = prefix .. (group.name or ("Group " .. tostring(groupId)))
					local targetGroupId = normalizeId(groupId)
					menu:CreateRadio(label, function() return selectedGroupId == targetGroupId end, function() onSelect(targetGroupId) end)
				end
				appendChoices(groupId)
			end
		end
	end

	appendChoices(nil)
	return hasGroups
end

function CooldownPanels:CreateEditorGroup(name, parentGroupId)
	local root = ensureRoot()
	if not root then return nil end
	root = CooldownPanels.EnsureEditorGroupStorage(root)
	local groups = root.editorGroups
	local order = root.editorGroupOrder
	local groupId = Helper.GetNextNumericId(groups)
	local groupName = CooldownPanels.NormalizePanelGroupName(name) or (L["CooldownPanelNewGroup"] or "New Group")
	parentGroupId = normalizeId(parentGroupId)
	if parentGroupId and not groups[parentGroupId] then parentGroupId = nil end
	groups[groupId] = { id = groupId, name = groupName, parentGroupId = parentGroupId }
	order[#order + 1] = groupId
	root._eqolEditorGroupOrderDirty = true
	self:SortEditorGroupOrder(root)
	return groupId
end

function CooldownPanels:RenameEditorGroup(groupId, name)
	local root = ensureRoot()
	local group = CooldownPanels.GetEditorGroup(root, groupId)
	if not group then return false end
	name = CooldownPanels.NormalizePanelGroupName(name)
	if not name then return false end
	group.name = name
	root._eqolEditorGroupOrderDirty = true
	self:SortEditorGroupOrder(root)
	return true
end

function CooldownPanels:DeleteEditorGroup(groupId)
	local root = ensureRoot()
	root = CooldownPanels.EnsureEditorGroupStorage(root)
	groupId = normalizeId(groupId)
	if not (root and root.editorGroups and groupId and root.editorGroups[groupId]) then return false end
	local parentGroupId = normalizeId(root.editorGroups[groupId].parentGroupId)
	root.editorGroups[groupId] = nil
	Helper.SyncOrder(root.editorGroupOrder, root.editorGroups)
	for _, group in pairs(root.editorGroups or {}) do
		if group and normalizeId(group.parentGroupId) == groupId then group.parentGroupId = parentGroupId end
	end
	for _, panel in pairs(root.panels or {}) do
		if panel and normalizeId(panel.editorGroupId) == groupId then panel.editorGroupId = parentGroupId end
	end
	root._eqolEditorGroupOrderDirty = true
	return true
end

function CooldownPanels:SetEditorGroupParent(groupId, parentGroupId)
	local root = ensureRoot()
	root = CooldownPanels.EnsureEditorGroupStorage(root)
	groupId = normalizeId(groupId)
	parentGroupId = normalizeId(parentGroupId)
	local group = root and root.editorGroups and groupId and root.editorGroups[groupId] or nil
	if not group then return false end
	if parentGroupId == nil then
		group.parentGroupId = nil
		root._eqolEditorGroupOrderDirty = true
		return true
	end
	if not self:CanSetEditorGroupParent(root, groupId, parentGroupId) then return false end
	group.parentGroupId = parentGroupId
	root._eqolEditorGroupOrderDirty = true
	return true
end

function CooldownPanels:GetEditorPanelGroupState(editor)
	if not editor then return {} end
	editor.panelGroupState = editor.panelGroupState or {}
	return editor.panelGroupState
end

function CooldownPanels:GetEditorPanelGroupStateKey(groupId)
	groupId = normalizeId(groupId)
	if groupId ~= nil then return tostring(groupId) end
	return "__ungrouped"
end

function CooldownPanels:IsEditorPanelGroupCollapsed(editor, groupId)
	local state = self:GetEditorPanelGroupState(editor)
	return state[self:GetEditorPanelGroupStateKey(groupId)] == true
end

function CooldownPanels:ToggleEditorPanelGroupCollapsed(editor, groupId)
	local state = self:GetEditorPanelGroupState(editor)
	local key = self:GetEditorPanelGroupStateKey(groupId)
	if state[key] == true then
		state[key] = nil
	else
		state[key] = true
	end
	return state[key] == true
end

function CooldownPanels:SetPanelEditorGroup(panelId, groupId)
	local root = ensureRoot()
	root = CooldownPanels.EnsureEditorGroupStorage(root)
	panelId = normalizeId(panelId)
	local panel = root and root.panels and panelId and root.panels[panelId] or nil
	if not panel then return false end
	groupId = normalizeId(groupId)
	if groupId and not (root.editorGroups and root.editorGroups[groupId]) then groupId = nil end
	panel.editorGroupId = groupId
	return true
end

local function markRootOrderDirty(root)
	if root then
		root._orderDirty = true
		CooldownPanels.MarkRelativeFrameEntriesDirty()
		local runtime = CooldownPanels.runtime
		if runtime and runtime._eqolPanelIdCacheRoot == root then
			runtime._eqolPanelIdCache = nil
			runtime._eqolPanelIdCacheRoot = nil
		end
	end
end

local function syncRootOrderIfDirty(root, force)
	if not root then return false end
	if not force then
		if not root._orderDirty then return false end
		if InCombatLockdown and InCombatLockdown() then return false end
	end
	Helper.SyncOrder(root.order, root.panels)
	root._orderDirty = nil
	local runtime = CooldownPanels.runtime
	if runtime and runtime._eqolPanelIdCacheRoot == root then
		runtime._eqolPanelIdCache = nil
		runtime._eqolPanelIdCacheRoot = nil
	end
	return true
end

CooldownPanels.GetCachedPanelIds = function(root)
	if not root then return {} end
	CooldownPanels.runtime = CooldownPanels.runtime or {}
	local runtime = CooldownPanels.runtime
	local cached = runtime._eqolPanelIdCache
	if cached and runtime._eqolPanelIdCacheRoot == root then return cached end

	local panelIds = {}
	local seen = {}
	for _, panelId in ipairs(root.order or {}) do
		if root.panels[panelId] and not seen[panelId] then
			seen[panelId] = true
			panelIds[#panelIds + 1] = panelId
		end
	end
	for panelId in pairs(root.panels or {}) do
		if not seen[panelId] then
			seen[panelId] = true
			panelIds[#panelIds + 1] = panelId
		end
	end

	runtime._eqolPanelIdCache = panelIds
	runtime._eqolPanelIdCacheRoot = root
	return panelIds
end

function CooldownPanels:EnsureDB() return ensureRoot() end

function CooldownPanels:GetRoot() return ensureRoot() end

function CooldownPanels:GetPanel(panelId)
	local root = ensureRoot()
	if not root then return nil end
	panelId = normalizeId(panelId)
	local panel = root.panels and root.panels[panelId]
	if panel and not normalizedPanels[panel] then
		Helper.NormalizePanel(panel, root.defaults)
		normalizedPanels[panel] = true
	end
	return panel
end

function CooldownPanels:GetDynamicAnchorId(panelId)
	panelId = normalizeId(panelId)
	return panelId and ("cooldownPanel:" .. tostring(panelId)) or nil
end

function CooldownPanels:GetPanelRuntimeFrame(panelId)
	local runtime = panelId and getRuntime(normalizeId(panelId)) or nil
	return runtime and runtime.frame or nil
end

function CooldownPanels:NotifyDynamicAnchorTargetStateChanged(panelId, available, reason)
	local runtime = self.runtime and self.runtime[panelId]
	if not runtime then return false end
	local frame = runtime.frame
	available = available == true and frame ~= nil

	local initialized = runtime._eqolDynamicAnchorTargetStateInitialized == true
	local changed = initialized
			and (runtime._eqolDynamicAnchorTargetAvailable ~= available or (available and runtime._eqolDynamicAnchorTargetFrame ~= frame))
		or (not initialized and available)
	runtime._eqolDynamicAnchorTargetStateInitialized = true
	runtime._eqolDynamicAnchorTargetAvailable = available
	runtime._eqolDynamicAnchorTargetFrame = frame
	if not changed then return false end

	local dynamicAnchors = addon.DynamicAnchors
	if dynamicAnchors and dynamicAnchors.NotifyTargetChanged then
		dynamicAnchors:NotifyTargetChanged(self:GetDynamicAnchorId(panelId), reason or "COOLDOWN_PANEL_TARGET_STATE_CHANGED", self:GetDynamicAnchorId(panelId))
	end
	return true
end

function CooldownPanels:RegisterDynamicAnchorPanel(panelId)
	local dynamicAnchors = addon.DynamicAnchors
	panelId = normalizeId(panelId)
	local panel = panelId and self:GetPanel(panelId) or nil
	if not (dynamicAnchors and panelId and panel) then return end
	local dynamicId = self:GetDynamicAnchorId(panelId)
	dynamicAnchors:RegisterTarget({
		id = dynamicId,
		owner = "EnhanceQoLCooldownPanels",
		consumerId = dynamicId,
		menuGroup = "COOLDOWN_PANELS",
		menuGroupLabel = L["Cooldown Panels"],
		menuGroupOrder = 300,
		getLabel = function()
			local current = CooldownPanels:GetPanel(panelId)
			return current and current.name or ((L["cooldownPanelReferenceLabel"]):format(tostring(panelId), L["cooldownPanelDefaultName"]))
		end,
		resolve = function()
			local current = CooldownPanels:GetPanel(panelId)
			if not current or current.enabled == false then return nil, { available = false, reason = "CONFIG_DISABLED" } end
			local frame = CooldownPanels:GetPanelRuntimeFrame(panelId)
			if not frame then return nil, { available = false, reason = "FRAME_NOT_CREATED" } end
			if dynamicAnchors.EnsureSimpleTargetHooks then dynamicAnchors:EnsureSimpleTargetHooks(dynamicId, frame) end
			if not CooldownPanels:ShouldShowPanel(panelId) then return nil, { available = false, reason = "DESIRED_HIDDEN" } end
			return frame, { available = true, shown = frame:IsShown() }
		end,
	})
	dynamicAnchors:RegisterConsumer({
		id = dynamicId,
		owner = "EnhanceQoLCooldownPanels",
		getLabel = function()
			local current = CooldownPanels:GetPanel(panelId)
			return current and current.name or dynamicId
		end,
		ensureRule = function()
			local current = CooldownPanels:GetPanel(panelId)
			if not current then return nil end
			current.dynamicAnchor = type(current.dynamicAnchor) == "table" and current.dynamicAnchor or { enabled = false }
			return current.dynamicAnchor
		end,
		getRule = function()
			local current = CooldownPanels:GetPanel(panelId)
			if current and type(current.dynamicAnchor) == "table" then dynamicAnchors:EnsureAssignmentProfile(current.dynamicAnchor, current.name or L["cooldownPanelDefaultName"]) end
			return current and current.dynamicAnchor or nil
		end,
		apply = function()
			if CooldownPanels:GetPanel(panelId) then CooldownPanels:ApplyPanelPosition(panelId) end
		end,
	})
end

function CooldownPanels:RegisterDynamicAnchorPanels()
	for _, panelId in ipairs(self:GetPanelOrder() or {}) do
		self:RegisterDynamicAnchorPanel(panelId)
	end
end

function CooldownPanels:GetPanelOrder()
	local root = ensureRoot()
	if not root then return nil end
	return root.order
end

function CooldownPanels:SetPanelOrder(order)
	local root = ensureRoot()
	if not root or type(order) ~= "table" then return end
	root.order = order
	markRootOrderDirty(root)
	syncRootOrderIfDirty(root, true)
end

function CooldownPanels:SetSelectedPanel(panelId)
	local root = ensureRoot()
	if not root then return end
	panelId = normalizeId(panelId)
	if root.panels and root.panels[panelId] then root.selectedPanel = panelId end
end

function CooldownPanels:GetSelectedPanel()
	local root = ensureRoot()
	if not root then return nil end
	return root.selectedPanel
end

function CooldownPanels:CreatePanel(name)
	local root = ensureRoot()
	if not root then return nil end
	local id = Helper.GetNextNumericId(root.panels)
	local panel = Helper.CreatePanel(name, root.defaults)
	panel.id = id
	root.panels[id] = panel
	root.order[#root.order + 1] = id
	markRootOrderDirty(root)
	Keybinds.MarkPanelsDirty()
	if not root.selectedPanel then root.selectedPanel = id end
	self:RebuildSpellIndex()
	self:RefreshPanel(id)
	self:RegisterDynamicAnchorPanel(id)
	return id, panel
end

function CooldownPanels:DuplicatePanel(panelId)
	local root = ensureRoot()
	panelId = normalizeId(panelId)
	if not root or not root.panels or not panelId then return nil end
	local source = root.panels[panelId]
	if not source then return nil end

	local id = Helper.GetNextNumericId(root.panels)
	local panel = Helper.CopyTableDeep(source)
	if type(panel) ~= "table" then return nil end
	panel.id = id
	panel.editorGroupId = nil
	panel.editorGroup = nil

	local usedNames = {}
	for _, existingPanel in pairs(root.panels or {}) do
		local existingName = existingPanel and existingPanel.name
		if type(existingName) == "string" and existingName ~= "" then usedNames[existingName] = true end
	end
	local baseName = (type(source.name) == "string" and source.name ~= "" and source.name) or (L["CooldownPanelNewPanel"] or "New Panel")
	local copyLabel = L["Copy"] or "Copy"
	panel.name = string.format("%s %s", baseName, copyLabel)
	if usedNames[panel.name] then
		local suffix = 2
		repeat
			panel.name = string.format("%s %s %d", baseName, copyLabel, suffix)
			suffix = suffix + 1
		until not usedNames[panel.name]
	end

	local anchor = ensurePanelAnchor(panel)
	if anchor then
		anchor.x = tonumber(anchor.x) or tonumber(panel.x) or 0
		anchor.y = tonumber(anchor.y) or tonumber(panel.y) or 0
		panel.point = anchor.point or panel.point or "CENTER"
		panel.x = anchor.x
		panel.y = anchor.y
	else
		panel.x = tonumber(panel.x) or 0
		panel.y = tonumber(panel.y) or 0
	end

	Helper.NormalizePanel(panel, root.defaults)
	for _, entry in pairs(panel.entries or {}) do
		Helper.NormalizeEntry(entry, root.defaults)
	end

	root.panels[id] = panel
	self:RegisterDynamicAnchorPanel(id)
	local inserted = false
	for index, currentId in ipairs(root.order or {}) do
		if currentId == panelId then
			table.insert(root.order, index + 1, id)
			inserted = true
			break
		end
	end
	if not inserted then root.order[#root.order + 1] = id end
	markRootOrderDirty(root)
	Keybinds.MarkPanelsDirty()
	self:RebuildSpellIndex()
	self:UpdateCursorAnchorState()
	self:RefreshPanel(id)
	return id, panel
end

cdp.EXPORT.SERIALIZABLE_KEY_TYPES = {
	boolean = true,
	number = true,
	string = true,
}

cdp.EXPORT.SERIALIZABLE_VALUE_TYPES = {
	boolean = true,
	number = true,
	string = true,
}

function cdp.EXPORT.SanitizeValue(value, activeTables)
	local valueType = type(value)
	if cdp.EXPORT.SERIALIZABLE_VALUE_TYPES[valueType] then return value end
	if valueType ~= "table" then return nil end
	if activeTables[value] then return nil end

	activeTables[value] = true
	local clone = {}
	for key, child in pairs(value) do
		if cdp.EXPORT.SERIALIZABLE_KEY_TYPES[type(key)] then
			local sanitized = cdp.EXPORT.SanitizeValue(child, activeTables)
			if sanitized ~= nil then clone[key] = sanitized end
		end
	end
	activeTables[value] = nil
	return clone
end

function cdp.EXPORT.SanitizeTable(source)
	if type(source) ~= "table" then return {} end
	return cdp.EXPORT.SanitizeValue(source, {}) or {}
end

function cdp.EXPORT.EncodePayload(payload)
	local serializer = cdp.EXPORT.SERIALIZER
	local deflate = cdp.EXPORT.DEFLATE
	if not serializer or not deflate then return nil, "NO_LIB" end
	local ok, serialized = pcall(serializer.Serialize, serializer, payload)
	if not ok or type(serialized) ~= "string" or serialized == "" then return nil, "SERIALIZE" end
	local compressed = deflate:CompressDeflate(serialized)
	if not compressed then return nil, "COMPRESS" end
	return deflate:EncodeForPrint(compressed)
end

function cdp.EXPORT.DecodePayload(encoded)
	local serializer = cdp.EXPORT.SERIALIZER
	local deflate = cdp.EXPORT.DEFLATE
	if not serializer or not deflate then return nil, "NO_LIB" end
	encoded = tostring(encoded or "")
	encoded = encoded:gsub("^%s+", ""):gsub("%s+$", "")
	if encoded == "" then return nil, "NO_INPUT" end

	local decoded = deflate:DecodeForPrint(encoded) or deflate:DecodeForWoWChatChannel(encoded) or deflate:DecodeForWoWAddonChannel(encoded)
	if not decoded then return nil, "DECODE" end
	local decompressed = deflate:DecompressDeflate(decoded)
	if not decompressed then return nil, "DECOMPRESS" end
	local ok, payload = serializer:Deserialize(decompressed)
	if not ok or type(payload) ~= "table" then return nil, "DESERIALIZE" end
	local meta = payload.meta
	if type(meta) ~= "table" or meta.addon ~= parentAddonName or meta.kind ~= cdp.EXPORT.KIND then return nil, "INVALID" end
	return payload
end

function cdp.EXPORT.GetUniquePanelName(root, preferredName)
	local usedNames = {}
	for _, existingPanel in pairs(root and root.panels or {}) do
		local existingName = existingPanel and existingPanel.name
		if type(existingName) == "string" and existingName ~= "" then usedNames[existingName] = true end
	end
	local baseName = (type(preferredName) == "string" and preferredName ~= "" and preferredName) or (L["CooldownPanelNewPanel"] or "New Panel")
	if not usedNames[baseName] then return baseName end
	local suffix = 2
	local candidate
	repeat
		candidate = string.format("%s %d", baseName, suffix)
		suffix = suffix + 1
	until not usedNames[candidate]
	return candidate
end

function cdp.EXPORT.GetUniqueGroupName(root, preferredName)
	local usedNames = {}
	for _, group in pairs(root and root.editorGroups or {}) do
		local groupName = group and group.name
		if type(groupName) == "string" and groupName ~= "" then usedNames[groupName] = true end
	end
	local baseName = CooldownPanels.NormalizePanelGroupName(preferredName) or (L["CooldownPanelNewGroup"] or "New Group")
	if not usedNames[baseName] then return baseName end
	local suffix = 2
	local candidate
	repeat
		candidate = string.format("%s %d", baseName, suffix)
		suffix = suffix + 1
	until not usedNames[candidate]
	return candidate
end

function CooldownPanels:ExportPanel(panelId)
	local root = ensureRoot()
	panelId = normalizeId(panelId)
	local panel = root and root.panels and panelId and root.panels[panelId] or nil
	if type(panel) ~= "table" then return nil, "NO_DATA" end
	local exportPanel = Helper.CopyTableDeep(panel)
	exportPanel.editorGroupId = nil
	return cdp.EXPORT.EncodePayload({
		meta = {
			addon = parentAddonName,
			kind = cdp.EXPORT.KIND,
			version = tostring(C_AddOns.GetAddOnMetadata(parentAddonName, "Version") or ""),
			payloadVersion = 1,
			scope = "PANEL",
		},
		data = {
			panel = cdp.EXPORT.SanitizeTable(exportPanel),
		},
	})
end

function CooldownPanels:ExportPanels(panelIds)
	local root = ensureRoot()
	if not (root and root.panels and type(panelIds) == "table") then return nil, "NO_DATA" end

	local panels = {}
	local panelOrder = {}
	for _, panelId in ipairs(panelIds) do
		panelId = normalizeId(panelId)
		local panel = panelId and root.panels[panelId] or nil
		if type(panel) == "table" then
			local exportPanel = Helper.CopyTableDeep(panel)
			exportPanel.editorGroupId = nil
			exportPanel.editorGroup = nil
			panels[panelId] = cdp.EXPORT.SanitizeTable(exportPanel)
			panelOrder[#panelOrder + 1] = panelId
		end
	end

	if #panelOrder == 0 then return nil, "NO_DATA" end
	return cdp.EXPORT.EncodePayload({
		meta = {
			addon = parentAddonName,
			kind = cdp.EXPORT.KIND,
			version = tostring(C_AddOns.GetAddOnMetadata(parentAddonName, "Version") or ""),
			payloadVersion = 1,
			scope = "GROUP",
		},
		data = {
			panelOrder = panelOrder,
			panels = panels,
		},
	})
end

function CooldownPanels:ExportEditorGroup(groupId)
	local root = ensureRoot()
	root = CooldownPanels.EnsureEditorGroupStorage(root)
	groupId = normalizeId(groupId)
	if not (root and root.editorGroups and groupId and root.editorGroups[groupId]) then return nil, "NO_DATA" end

	local groupIds = { groupId }
	local includedGroups = { [groupId] = true }
	local descendants = self:GetEditorGroupDescendantIdSet(root, groupId)
	for descendantId in pairs(descendants) do
		if root.editorGroups[descendantId] then
			includedGroups[descendantId] = true
			groupIds[#groupIds + 1] = descendantId
		end
	end
	table.sort(groupIds, function(left, right) return (tonumber(left) or 0) < (tonumber(right) or 0) end)

	local groups = {}
	for _, exportGroupId in ipairs(groupIds) do
		local group = Helper.CopyTableDeep(root.editorGroups[exportGroupId])
		group.parentGroupId = includedGroups[normalizeId(group.parentGroupId)] and normalizeId(group.parentGroupId) or nil
		groups[exportGroupId] = cdp.EXPORT.SanitizeTable(group)
	end

	local panels = {}
	local panelOrder = {}
	for _, exportPanelId in ipairs(root.order or {}) do
		local panel = root.panels and root.panels[exportPanelId] or nil
		if panel and includedGroups[normalizeId(panel.editorGroupId)] then
			panels[exportPanelId] = cdp.EXPORT.SanitizeTable(panel)
			panelOrder[#panelOrder + 1] = exportPanelId
		end
	end

	return cdp.EXPORT.EncodePayload({
		meta = {
			addon = parentAddonName,
			kind = cdp.EXPORT.KIND,
			version = tostring(C_AddOns.GetAddOnMetadata(parentAddonName, "Version") or ""),
			payloadVersion = 1,
			scope = "GROUP",
		},
		data = {
			rootGroupId = groupId,
			groups = groups,
			groupOrder = groupIds,
			panels = panels,
			panelOrder = panelOrder,
		},
	})
end

function cdp.EXPORT.ImportPanelData(data)
	local root = ensureRoot()
	if not root or type(data) ~= "table" or type(data.panel) ~= "table" then return nil, "NO_DATA" end
	local id = Helper.GetNextNumericId(root.panels)
	local panel = cdp.EXPORT.SanitizeTable(data.panel)
	panel.id = id
	panel.name = cdp.EXPORT.GetUniquePanelName(root, panel.name)
	panel.editorGroupId = nil
	Helper.NormalizePanel(panel, root.defaults)
	for _, entry in pairs(panel.entries or {}) do
		Helper.NormalizeEntry(entry, root.defaults)
	end
	root.panels[id] = panel
	root.order[#root.order + 1] = id
	root.selectedPanel = id
	markRootOrderDirty(root)
	Keybinds.MarkPanelsDirty()
	CooldownPanels:RebuildSpellIndex()
	CooldownPanels:UpdateCursorAnchorState()
	CooldownPanels:RefreshPanel(id)
	return id
end

function cdp.EXPORT.ImportGroupData(data)
	local root = ensureRoot()
	root = CooldownPanels.EnsureEditorGroupStorage(root)
	if not root or type(data) ~= "table" then return nil, "NO_DATA" end
	local hasGroups = type(data.groups) == "table"
	local hasPanels = type(data.panels) == "table"
	if not hasGroups and not hasPanels then return nil, "NO_DATA" end

	local groupIdMap = {}
	if hasGroups then
		for _, oldGroupId in ipairs(data.groupOrder or {}) do
			local group = data.groups[oldGroupId]
			if type(group) == "table" then
				local newGroupId = Helper.GetNextNumericId(root.editorGroups)
				groupIdMap[oldGroupId] = newGroupId
				local groupName = oldGroupId == normalizeId(data.rootGroupId) and cdp.EXPORT.GetUniqueGroupName(root, group.name) or CooldownPanels.NormalizePanelGroupName(group.name)
				root.editorGroups[newGroupId] = {
					id = newGroupId,
					name = groupName or (L["CooldownPanelNewGroup"] or "New Group"),
					parentGroupId = nil,
				}
				root.editorGroupOrder[#root.editorGroupOrder + 1] = newGroupId
			end
		end

		for oldGroupId, newGroupId in pairs(groupIdMap) do
			local group = data.groups[oldGroupId]
			local oldParentId = group and normalizeId(group.parentGroupId)
			root.editorGroups[newGroupId].parentGroupId = oldParentId and groupIdMap[oldParentId] or nil
		end
	end

	local firstPanelId
	for _, oldPanelId in ipairs(data.panelOrder or {}) do
		local oldPanel = data.panels and data.panels[oldPanelId]
		if type(oldPanel) == "table" then
			local newPanelId = Helper.GetNextNumericId(root.panels)
			local panel = cdp.EXPORT.SanitizeTable(oldPanel)
			panel.id = newPanelId
			panel.name = cdp.EXPORT.GetUniquePanelName(root, panel.name)
			panel.editorGroupId = hasGroups and (groupIdMap[normalizeId(panel.editorGroupId)] or groupIdMap[normalizeId(data.rootGroupId)]) or nil
			panel.editorGroup = nil
			Helper.NormalizePanel(panel, root.defaults)
			for _, entry in pairs(panel.entries or {}) do
				Helper.NormalizeEntry(entry, root.defaults)
			end
			root.panels[newPanelId] = panel
			root.order[#root.order + 1] = newPanelId
			firstPanelId = firstPanelId or newPanelId
		end
	end

	if not next(groupIdMap) and not firstPanelId then return nil, "NO_DATA" end
	if next(groupIdMap) then
		root._eqolEditorGroupOrderDirty = true
		CooldownPanels:SortEditorGroupOrder(root)
	end
	root.selectedPanel = firstPanelId or root.selectedPanel
	markRootOrderDirty(root)
	Keybinds.MarkPanelsDirty()
	CooldownPanels:RebuildSpellIndex()
	CooldownPanels:UpdateCursorAnchorState()
	if firstPanelId then CooldownPanels:RefreshPanel(firstPanelId) end
	return firstPanelId or next(groupIdMap) ~= nil
end

function CooldownPanels:ImportPanelOrGroup(encoded)
	local payload, reason = cdp.EXPORT.DecodePayload(encoded)
	if not payload then return false, reason end
	local scope = payload.meta and payload.meta.scope
	local imported, importReason
	if scope == "GROUP" then
		imported, importReason = cdp.EXPORT.ImportGroupData(payload.data)
	else
		imported, importReason = cdp.EXPORT.ImportPanelData(payload.data)
	end
	if not imported then return false, importReason or "NO_DATA" end
	CooldownPanels:RefreshEditor()
	return true
end

function CooldownPanels:ReleaseDeletedPanelRuntime(panelId)
	panelId = normalizeId(panelId)
	local allRuntime = self.runtime
	local runtime = allRuntime and panelId and allRuntime[panelId] or nil
	if not runtime then return end

	runtime.visibleCount = 0
	runtime.visiblePowerSpellCount = 0
	runtime._eqolDeletedPanelRuntime = true
	if runtime.visibleEntries then
		for i = 1, #runtime.visibleEntries do
			runtime.visibleEntries[i] = nil
		end
	end
	if runtime.visiblePowerSpells then
		for i = 1, #runtime.visiblePowerSpells do
			runtime.visiblePowerSpells[i] = nil
		end
	end

	local frame = runtime.frame
	if frame then
		local detachedDriver = self:ApplyVisibilityDriverToFrame(frame, nil)
		if allRuntime.pendingVisibilityDriverUpdates then
			if detachedDriver then
				allRuntime.pendingVisibilityDriverUpdates[frame] = nil
			else
				allRuntime.pendingVisibilityDriverUpdates[frame] = false
			end
		end
		frame._eqolDeletedPanelRuntime = true
		frame._eqolDeletedPanelId = panelId
		frame.panelId = nil
		if frame.EnableMouse then frame:EnableMouse(false) end
		if frame.SetAlpha then frame:SetAlpha(0) end
		if frame.bg then frame.bg:Hide() end
		if frame.label then
			frame.label:SetText("")
			frame.label:Hide()
		end
		if frame.editDropZone then
			frame.editDropZone:Hide()
			frame.editDropZone:EnableMouse(false)
			frame.editDropZone.panelId = nil
		end
		if frame.editPanelHandle then
			frame.editPanelHandle:Hide()
			frame.editPanelHandle:EnableMouse(false)
			frame.editPanelHandle.panelId = nil
		end
		if frame.editMoveHandle then
			frame.editMoveHandle:Hide()
			frame.editMoveHandle:EnableMouse(false)
			frame.editMoveHandle.panelId = nil
		end
		if frame.icons then
			for i = 1, #frame.icons do
				local icon = frame.icons[i]
				if icon then
					self:ClearRuntimeCooldownTextBinding(icon)
					icon.entryId = nil
					icon._eqolRuntimeData = nil
					icon._eqolRuntimeSnapshot = nil
					if CooldownPanels.StopAllIconGlows then CooldownPanels.StopAllIconGlows(icon) end
					if icon.cooldown then
						if icon.cooldown.SetScript then icon.cooldown:SetScript("OnCooldownDone", nil) end
						if icon.cooldown.Clear then icon.cooldown:Clear() end
						icon.cooldown._eqolPanelId = nil
						icon.cooldown._eqolEntryId = nil
						icon.cooldown._eqolCustomCooldownKey = nil
					end
					if icon.count then icon.count:Hide() end
					if icon.charges then icon.charges:Hide() end
					if icon.rangeOverlay then icon.rangeOverlay:Hide() end
					if icon.keybind then icon.keybind:Hide() end
					if icon.staticText then icon.staticText:Hide() end
					if icon.stateTexture then icon.stateTexture:Hide() end
					if icon.stateTextureSecond then icon.stateTextureSecond:Hide() end
					icon:Hide()
				end
			end
		end
		local inCombat = InCombatLockdown and InCombatLockdown()
		local protected = frame.IsProtected and frame:IsProtected()
		if not (inCombat and protected) then
			frame:Hide()
			if frame.ClearAllPoints then frame:ClearAllPoints() end
			if frame.SetParent then pcall(frame.SetParent, frame, nil) end
		end
		runtime.frame = nil
	end

	self:ClearPanelCustomCooldownDurations(panelId)
	allRuntime[panelId] = nil
end

function CooldownPanels:ClearAnchorsToDeletedPanel(root, deletedPanelId)
	deletedPanelId = normalizeId(deletedPanelId)
	local deletedFrameName = deletedPanelId and panelFrameName(deletedPanelId) or nil
	if not (root and root.panels and deletedFrameName) then return end

	local changed = false
	for otherPanelId, otherPanel in pairs(root.panels) do
		local anchor = ensurePanelAnchor(otherPanel)
		if anchor and Helper.NormalizeRelativeFrameName(anchor.relativeFrame) == deletedFrameName then
			anchor.relativeFrame = "UIParent"
			changed = true
			local runtime = self.runtime and self.runtime[normalizeId(otherPanelId)] or nil
			if runtime then
				runtime._eqolRelativeFrameCache = nil
				if self.ClearAppliedAnchorCache then self.ClearAppliedAnchorCache(runtime) end
			end
		end
	end

	if changed then self.MarkRelativeFrameEntriesDirty() end
end

function CooldownPanels:DeletePanel(panelId)
	local root = ensureRoot()
	panelId = normalizeId(panelId)
	if not root or not root.panels or not root.panels[panelId] then return end
	self:HideLayoutEntryStandaloneMenu(panelId)
	self:HideLayoutPanelStandaloneMenu(panelId)
	self:HideLayoutFixedGroupStandaloneMenu(panelId)
	self:ReleaseDeletedPanelRuntime(panelId)
	if addon.DynamicAnchors then
		local dynamicId = self:GetDynamicAnchorId(panelId)
		addon.DynamicAnchors:UnregisterConsumer(dynamicId)
		addon.DynamicAnchors:UnregisterTarget(dynamicId)
	end
	root.panels[panelId] = nil
	markRootOrderDirty(root)
	syncRootOrderIfDirty(root, true)
	self:ClearAnchorsToDeletedPanel(root, panelId)
	Keybinds.MarkPanelsDirty()
	if root.selectedPanel == panelId then root.selectedPanel = root.order[1] end
	self:RebuildSpellIndex()
	self:UpdateCursorAnchorState()
end

function CooldownPanels:AddEntry(panelId, entryType, idValue, overrides)
	local root = ensureRoot()
	if not root then return nil end
	panelId = normalizeId(panelId)
	local panel = self:GetPanel(panelId)
	if not panel then return nil end
	local typeKey = entryType and tostring(entryType):upper() or nil
	if typeKey ~= "SPELL" and typeKey ~= "ITEM" and typeKey ~= "SLOT" and typeKey ~= "STANCE" and typeKey ~= "MACRO" and typeKey ~= "CDM_AURA" then return nil end
	local entryValue = idValue
	local numericValue = tonumber(idValue)
	local itemWasHigherRank = false
	if typeKey == "SPELL" or typeKey == "ITEM" or typeKey == "SLOT" then
		if not numericValue then return nil end
		if typeKey == "SPELL" then
			local exactTalentChoice = type(overrides) == "table" and overrides.talentChoiceExact == true
			if exactTalentChoice and not self:IsTalentChoiceSpellID(numericValue) then return nil end
			if not exactTalentChoice then numericValue = self:NormalizePersistentSpellID(numericValue, { allowTalentChoiceCanonical = true }) or numericValue end
		elseif typeKey == "ITEM" then
			local canonicalItemID, wasHigherRank = self:GetCanonicalItemRankID(numericValue)
			numericValue = canonicalItemID
			itemWasHigherRank = wasHigherRank == true
		end
		entryValue = numericValue
	elseif typeKey == "STANCE" then
		local stanceDef = CooldownPanels.GetStanceDefinition and CooldownPanels:GetStanceDefinition(idValue) or nil
		if not stanceDef then return nil end
		entryValue = stanceDef.id
	elseif typeKey == "MACRO" then
		if numericValue then
			entryValue = numericValue
		elseif type(entryValue) ~= "string" then
			return nil
		end
	elseif typeKey == "CDM_AURA" then
		entryValue = idValue
	end
	if Helper.IsFixedLayout(panel.layout) then
		local resolvedOverrides, fixedError = self:ResolveFixedEntryAddOverrides(panel, overrides)
		if fixedError then return nil end
		overrides = resolvedOverrides
	end
	local entryId = Helper.GetNextNumericId(panel.entries)
	local entry = Helper.CreateEntry(typeKey, entryValue, root.defaults)
	if typeKey == "CDM_AURA" and not (entry and (entry.cooldownID or (CooldownPanels.AuraContainers and entry.spellID))) then return nil end
	entry.id = entryId
	if type(overrides) == "table" then
		for key, value in pairs(overrides) do
			entry[key] = value
		end
	end
	if entry.type == "ITEM" and itemWasHigherRank then entry.useHighestRank = true end
	if entry.type == "MACRO" then
		entry.macroID = tonumber(entry.macroID)
		entry.macroName = CooldownPanels.NormalizeMacroName(entry.macroName)
	elseif entry.type == "STANCE" and CooldownPanels.NormalizeStanceEntry then
		CooldownPanels:NormalizeStanceEntry(entry)
	elseif entry.type == "CDM_AURA" then
		local cdmAuras = CooldownPanels.CDMAuras
		if cdmAuras and cdmAuras.NormalizeEntry then cdmAuras:NormalizeEntry(entry, root.defaults) end
	end
	panel.entries[entryId] = entry
	panel.order[#panel.order + 1] = entryId
	if Helper.UpdatePanelEntrySpecFilterState then Helper.UpdatePanelEntrySpecFilterState(panel) end
	Helper.InvalidateFixedLayoutCache(panel)
	if Helper.IsFixedLayout(panel.layout) then Helper.EnsureFixedSlotAssignments(panel) end
	if entry.type == "ITEM" and entry.itemID then
		updateItemCountCacheForItem(entry.itemID)
	elseif entry.type == "MACRO" then
		local macro = CooldownPanels.ResolveMacroEntry(entry)
		if macro and macro.kind == "ITEM" and macro.itemID then updateItemCountCacheForItem(macro.itemID) end
	end
	self:RebuildSpellIndex()
	self:RefreshPanel(panelId)
	if self.BlizzardEditor and self.BlizzardEditor.RefreshPanel then self.BlizzardEditor:RefreshPanel(panelId) end
	return entryId, entry
end

function CooldownPanels:FindEntryByValue(panelId, entryType, idValue, options)
	panelId = normalizeId(panelId)
	local panel = self:GetPanel(panelId)
	if not panel then return nil end
	local typeKey = entryType and tostring(entryType):upper() or nil
	if typeKey == "CDM_AURA" then
		local cdmAuras = CooldownPanels.CDMAuras
		if cdmAuras and cdmAuras.FindEntryByValue then return cdmAuras:FindEntryByValue(panel, idValue) end
		return nil
	end
	local numericValue = tonumber(idValue)
	local exactTalentChoice = type(options) == "table" and options.talentChoiceExact == true
	local canonicalSpellValue = nil
	if typeKey == "SPELL" and numericValue then
		canonicalSpellValue = exactTalentChoice and numericValue or (self:NormalizePersistentSpellID(numericValue, { allowTalentChoiceCanonical = true }) or numericValue)
	end
	if typeKey == "ITEM" and numericValue then
		local canonicalItemID = self:GetCanonicalItemRankID(numericValue)
		numericValue = canonicalItemID or numericValue
	end
	local macroName = CooldownPanels.NormalizeMacroName(type(idValue) == "string" and idValue or nil)
	local stanceDef = typeKey == "STANCE" and CooldownPanels.GetStanceDefinition and CooldownPanels:GetStanceDefinition(idValue) or nil
	local stanceID = stanceDef and stanceDef.id or nil
	if typeKey ~= "SPELL" and typeKey ~= "ITEM" and typeKey ~= "SLOT" and typeKey ~= "STANCE" and typeKey ~= "MACRO" then return nil end
	for entryId, entry in pairs(panel.entries or {}) do
		if entry and entry.type == typeKey then
			if typeKey == "SPELL" then
				local entrySpellID = tonumber(entry.spellID)
				local entryExactTalentChoice = self:IsEntryTalentChoiceExact(entry)
				if entryExactTalentChoice == exactTalentChoice and exactTalentChoice and entrySpellID == numericValue then return entryId, entry end
				if
					not entryExactTalentChoice
					and not exactTalentChoice
					and entrySpellID
					and numericValue
					and (self:IsRacialSpellID(entrySpellID) or self:IsRacialSpellID(numericValue))
					and self:AreSpellVariantsEquivalent(entrySpellID, numericValue)
				then
					return entryId, entry
				end
				if entryExactTalentChoice == exactTalentChoice and not exactTalentChoice then
					local canonicalEntrySpellID = entrySpellID and (self:NormalizePersistentSpellID(entrySpellID, { allowTalentChoiceCanonical = true }) or entrySpellID) or nil
					if canonicalEntrySpellID and canonicalSpellValue and canonicalEntrySpellID == canonicalSpellValue then return entryId, entry end
				end
			end
			if typeKey == "ITEM" then
				local entryItemID = tonumber(entry.itemID)
				if entryItemID then
					local canonicalEntryItemID = self:GetCanonicalItemRankID(entryItemID) or entryItemID
					if canonicalEntryItemID == numericValue then return entryId, entry end
				end
			end
			if typeKey == "SLOT" and entry.slotID == numericValue then return entryId, entry end
			if typeKey == "STANCE" and stanceID and entry.stanceID == stanceID then return entryId, entry end
			if typeKey == "MACRO" then
				local entryMacroID = tonumber(entry.macroID)
				local entryMacroName = CooldownPanels.NormalizeMacroName(entry.macroName)
				if numericValue and entryMacroID == numericValue then return entryId, entry end
				if macroName and entryMacroName and macroName == entryMacroName then return entryId, entry end
			end
		end
	end
	return nil
end

function CooldownPanels:RemoveEntry(panelId, entryId)
	panelId = normalizeId(panelId)
	entryId = normalizeId(entryId)
	local panel = self:GetPanel(panelId)
	if not panel or not panel.entries or not panel.entries[entryId] then return end
	local state = CooldownPanels.runtime and CooldownPanels.runtime.layoutEntryStandaloneMenu or nil
	if state and normalizeId(state.panelId) == panelId and normalizeId(state.entryId) == entryId then self:HideLayoutEntryStandaloneMenu(panelId, true) end
	panel.entries[entryId] = nil
	local runtime = CooldownPanels.runtime
	if runtime and runtime.actionDisplayCounts then runtime.actionDisplayCounts[Helper.GetEntryKey(panelId, entryId)] = nil end
	self:ClearEntryCustomCooldownDuration(panelId, entryId, true)
	Helper.SyncOrder(panel.order, panel.entries)
	if Helper.UpdatePanelEntrySpecFilterState then Helper.UpdatePanelEntrySpecFilterState(panel) end
	Helper.InvalidateFixedLayoutCache(panel)
	self:RebuildSpellIndex()
	self:RefreshPanel(panelId)
	if self.BlizzardEditor and self.BlizzardEditor.RefreshPanel then self.BlizzardEditor:RefreshPanel(panelId) end
end

function CooldownPanels:RemoveAllEntries(panelId)
	panelId = normalizeId(panelId)
	local panel = self:GetPanel(panelId)
	if not panel or not panel.entries or not next(panel.entries) then return false end

	self:HideLayoutEntryStandaloneMenu(panelId, true)
	self:ClearPanelCooldownManagerSync(panel)
	local runtime = self.runtime
	for entryId in pairs(panel.entries) do
		if runtime and runtime.actionDisplayCounts then runtime.actionDisplayCounts[Helper.GetEntryKey(panelId, entryId)] = nil end
	end
	panel.entries = {}
	panel.order = {}
	self:ClearPanelCustomCooldownDurations(panelId)
	if Helper.UpdatePanelEntrySpecFilterState then Helper.UpdatePanelEntrySpecFilterState(panel) end
	Helper.InvalidateFixedLayoutCache(panel)

	local editor = getEditor()
	if editor and normalizeId(editor.selectedPanelId) == panelId then editor.selectedEntryId = nil end
	local panelRuntime = self.runtime and self.runtime[panelId] or nil
	if panelRuntime then panelRuntime.layoutEditEntryId = nil end

	self:RebuildSpellIndex()
	self:RefreshPanel(panelId)
	self:RefreshEditor()
	if self.BlizzardEditor and self.BlizzardEditor.Refresh then self.BlizzardEditor:Refresh() end
	return true
end

