function cdp.ENTRY.AreSpecRefreshValuesEqual(left, right, visited)
	if issecretvalue and (issecretvalue(left) or issecretvalue(right)) then return nil end
	if left == right then return true end
	local leftType = type(left)
	if leftType ~= type(right) then return false end
	if leftType ~= "table" then
		if leftType == "nil" or leftType == "boolean" or leftType == "number" or leftType == "string" then return false end
		return nil
	end

	visited = visited or {}
	local mapped = visited[left]
	if mapped ~= nil then return mapped == right end
	visited[left] = right

	for key, leftValue in pairs(left) do
		if issecretvalue and (issecretvalue(key) or issecretvalue(leftValue)) then return nil end
		local keyType = type(key)
		if keyType ~= "boolean" and keyType ~= "number" and keyType ~= "string" then return nil end
		local equal = cdp.ENTRY.AreSpecRefreshValuesEqual(leftValue, right[key], visited)
		if equal ~= true then return equal end
	end
	for key in pairs(right) do
		if issecretvalue and issecretvalue(key) then return nil end
		local keyType = type(key)
		if keyType ~= "boolean" and keyType ~= "number" and keyType ~= "string" then return nil end
		local leftValue = left[key]
		if issecretvalue and issecretvalue(leftValue) then return nil end
		if leftValue == nil then return false end
	end
	return true
end

function cdp.ENTRY.CaptureSpecRefreshIndexState(runtime)
	if not runtime then return {} end
	local fields = {
		"activeSpecId",
		"enabledPanels",
		"enabledPanelIds",
		"enabledPanelsBySpec",
		"enabledPanelIdsBySpec",
		"spellIndex",
		"spellEntryIndex",
		"spellEntryMeta",
		"itemEntryIndex",
		"itemEntryMeta",
		"slotEntryIndex",
		"slotEntryMeta",
		"readySoundQueryByStateKey",
		"readySoundSoundByStateKey",
		"readySoundSweepIds",
		"readySoundEventDrivenByStateKey",
		"cdmAuraPanels",
		"cdmAuraPanelIds",
		"cdmAuraEntryIdsByPanel",
		"cdmAuraCooldownKeys",
		"cdmAuraSpellIds",
		"cdmAuraHasSpellOnlyEntries",
		"cdmAuraEntryCount",
		"barPanels",
		"barPanelIds",
		"barEntryIdsByPanel",
		"barEntryCount",
		"itemPanels",
		"itemUsesPanels",
		"itemTrackedIds",
		"itemUsesTrackedIds",
		"powerIndex",
		"powerCostNames",
		"powerCheckSpells",
		"powerAliasIdsBySpell",
		"powerPanelsBySpell",
		"powerCheckActive",
		"chargesIndex",
		"chargesPanels",
		"chargesActive",
		"activeProcTriggerEntryTargets",
		"interruptGlowActive",
		"interruptGlowPanels",
	}
	local state = {}
	for i = 1, #fields do
		local field = fields[i]
		state[field] = runtime[field]
	end
	return state, fields
end

function cdp.ENTRY.CollectSpecRefreshSpellMetaChanges(previousState, runtime)
	if not (previousState and runtime) then return {}, true end
	local previousPanels = previousState.spellEntryMeta
	local currentPanels = runtime.spellEntryMeta
	if issecretvalue and (issecretvalue(previousPanels) or issecretvalue(currentPanels)) then return {}, true end
	if type(previousPanels) ~= "table" or type(currentPanels) ~= "table" then return {}, true end

	local unknownPanels = 0
	local unknownEntries = 0
	local changedPanelIds = {}
	local function isSafeKey(value)
		if issecretvalue and issecretvalue(value) then return false end
		local valueType = type(value)
		return valueType == "boolean" or valueType == "number" or valueType == "string"
	end
	local function compareEntry(previousMeta, currentMeta)
		local equal = cdp.ENTRY.AreSpecRefreshValuesEqual(previousMeta, currentMeta)
		if equal == true then return false, false end
		if equal == nil then return false, true end
		return true, false
	end
	local function comparePanel(previousEntries, currentEntries)
		local equal = cdp.ENTRY.AreSpecRefreshValuesEqual(previousEntries, currentEntries)
		if equal == true then return false, false end
		if equal == nil then return false, true end
		if type(previousEntries) ~= "table" or type(currentEntries) ~= "table" then
			local entries = type(previousEntries) == "table" and previousEntries or currentEntries
			for entryId in pairs(entries or {}) do
				if not isSafeKey(entryId) then unknownEntries = unknownEntries + 1 end
			end
			return true, false
		end
		for entryId, previousMeta in pairs(previousEntries) do
			if not isSafeKey(entryId) or (issecretvalue and issecretvalue(previousMeta)) then
				unknownEntries = unknownEntries + 1
			else
				local currentMeta = currentEntries[entryId]
				if issecretvalue and issecretvalue(currentMeta) then
					unknownEntries = unknownEntries + 1
				else
					local _, entryUnknown = compareEntry(previousMeta, currentMeta)
					if entryUnknown then unknownEntries = unknownEntries + 1 end
				end
			end
		end
		for entryId, currentMeta in pairs(currentEntries) do
			if not isSafeKey(entryId) then
				unknownEntries = unknownEntries + 1
			else
				local previousMeta = previousEntries[entryId]
				if issecretvalue and issecretvalue(previousMeta) then
					-- Already counted while walking the previous entry set.
				elseif previousMeta == nil and issecretvalue and issecretvalue(currentMeta) then
					unknownEntries = unknownEntries + 1
				end
			end
		end
		return true, false
	end

	for panelId, previousEntries in pairs(previousPanels) do
		if not isSafeKey(panelId) or (issecretvalue and issecretvalue(previousEntries)) then
			unknownPanels = unknownPanels + 1
		else
			local currentEntries = currentPanels[panelId]
			if issecretvalue and issecretvalue(currentEntries) then
				unknownPanels = unknownPanels + 1
			else
				local panelChanged, panelUnknown = comparePanel(previousEntries, currentEntries)
				if panelChanged then changedPanelIds[panelId] = true end
				if panelUnknown then unknownPanels = unknownPanels + 1 end
			end
		end
	end
	for panelId, currentEntries in pairs(currentPanels) do
		if not isSafeKey(panelId) then
			unknownPanels = unknownPanels + 1
		else
			local previousEntries = previousPanels[panelId]
			if issecretvalue and issecretvalue(previousEntries) then
				-- Already counted while walking the previous panel set.
			elseif previousEntries == nil then
				if issecretvalue and issecretvalue(currentEntries) then
					unknownPanels = unknownPanels + 1
				else
					local panelChanged, panelUnknown = comparePanel(nil, currentEntries)
					if panelChanged then changedPanelIds[panelId] = true end
					if panelUnknown then unknownPanels = unknownPanels + 1 end
				end
			end
		end
	end

	return changedPanelIds, unknownPanels > 0 or unknownEntries > 0
end

function cdp.ENTRY.BuildSpecRefreshPanelScope(previousState, runtime, changedFields, unknownFields, metaChangedPanels, metaUnknown)
	if not (previousState and runtime) then return nil, 1, 1, 0 end
	local panelUnion = {}
	local panelsBySource = {}
	local unmappedFields = {}
	local unknownCount = 0
	local unmappedCount = 0

	local function isSafeKey(value)
		if issecretvalue and issecretvalue(value) then return false end
		local valueType = type(value)
		return valueType == "boolean" or valueType == "number" or valueType == "string"
	end

	local function countSet(values)
		local count = 0
		for _ in pairs(values or {}) do
			count = count + 1
		end
		return count
	end

	local function recordUnknown()
		unknownCount = unknownCount + 1
	end

	local function recordUnmapped(field)
		if unmappedFields[field] then return end
		unmappedFields[field] = true
		unmappedCount = unmappedCount + 1
	end

	local function markPanel(panelId, source)
		if not isSafeKey(panelId) then
			recordUnknown()
			return
		end
		panelUnion[panelId] = true
		panelsBySource[source] = panelsBySource[source] or {}
		panelsBySource[source][panelId] = true
	end

	local function getTable(value)
		if issecretvalue and issecretvalue(value) then
			recordUnknown()
			return nil, false
		end
		if value == nil then return nil, true end
		if type(value) ~= "table" then
			recordUnknown()
			return nil, false
		end
		return value, true
	end

	local function markPanelSet(panelSet, source)
		local panels, valid = getTable(panelSet)
		if not valid then return end
		for panelId, membership in pairs(panels or {}) do
			if issecretvalue and issecretvalue(membership) then recordUnknown() end
			markPanel(panelId, source)
		end
	end

	local function comparePanelSets(previousPanelSet, currentPanelSet, source)
		local previous, previousValid = getTable(previousPanelSet)
		local current, currentValid = getTable(currentPanelSet)
		if not previousValid or not currentValid then
			markPanelSet(previous, source)
			markPanelSet(current, source)
			return
		end
		local seen = {}
		for panelId, previousMembership in pairs(previous or {}) do
			if not isSafeKey(panelId) then
				recordUnknown()
			else
				seen[panelId] = true
				local currentMembership = current and current[panelId] or nil
				local equal = cdp.ENTRY.AreSpecRefreshValuesEqual(previousMembership, currentMembership)
				if equal == false then
					markPanel(panelId, source)
				elseif equal == nil then
					recordUnknown()
					markPanel(panelId, source)
				end
			end
		end
		for panelId, currentMembership in pairs(current or {}) do
			if not isSafeKey(panelId) then
				recordUnknown()
			elseif not seen[panelId] then
				if issecretvalue and issecretvalue(currentMembership) then recordUnknown() end
				markPanel(panelId, source)
			end
		end
	end

	local function collectPanelMapDiff(field)
		if not (changedFields and changedFields[field]) then return end
		local previousMap, previousValid = getTable(previousState[field])
		local currentMap, currentValid = getTable(runtime[field])
		if not previousValid or not currentValid then
			recordUnmapped(field)
			return
		end
		local seen = {}
		for outerKey, previousPanels in pairs(previousMap or {}) do
			if not isSafeKey(outerKey) then
				recordUnknown()
			else
				seen[outerKey] = true
				comparePanelSets(previousPanels, currentMap and currentMap[outerKey] or nil, field)
			end
		end
		for outerKey, currentPanels in pairs(currentMap or {}) do
			if not isSafeKey(outerKey) then
				recordUnknown()
			elseif not seen[outerKey] then
				comparePanelSets(nil, currentPanels, field)
			end
		end
		if countSet(panelsBySource[field]) == 0 then recordUnmapped(field) end
	end

	local function compareEntryIndexPanels(previousPanelMap, currentPanelMap)
		local source = "spellEntryIndex"
		local previous, previousValid = getTable(previousPanelMap)
		local current, currentValid = getTable(currentPanelMap)
		if not previousValid or not currentValid then
			markPanelSet(previous, source)
			markPanelSet(current, source)
			return
		end
		local seen = {}
		for panelId, previousEntries in pairs(previous or {}) do
			if not isSafeKey(panelId) then
				recordUnknown()
			else
				seen[panelId] = true
				local equal = cdp.ENTRY.AreSpecRefreshValuesEqual(previousEntries, current and current[panelId] or nil)
				if equal == false then
					markPanel(panelId, source)
				elseif equal == nil then
					recordUnknown()
					markPanel(panelId, source)
				end
			end
		end
		for panelId, currentEntries in pairs(current or {}) do
			if not isSafeKey(panelId) then
				recordUnknown()
			elseif not seen[panelId] then
				if issecretvalue and issecretvalue(currentEntries) then recordUnknown() end
				markPanel(panelId, source)
			end
		end
	end

	local function collectEntryIndexDiff()
		local field = "spellEntryIndex"
		if not (changedFields and changedFields[field]) then return end
		local previousMap, previousValid = getTable(previousState[field])
		local currentMap, currentValid = getTable(runtime[field])
		if not previousValid or not currentValid then
			recordUnmapped(field)
			return
		end
		local seen = {}
		for outerKey, previousPanels in pairs(previousMap or {}) do
			if not isSafeKey(outerKey) then
				recordUnknown()
			else
				seen[outerKey] = true
				compareEntryIndexPanels(previousPanels, currentMap and currentMap[outerKey] or nil)
			end
		end
		for outerKey, currentPanels in pairs(currentMap or {}) do
			if not isSafeKey(outerKey) then
				recordUnknown()
			elseif not seen[outerKey] then
				compareEntryIndexPanels(nil, currentPanels)
			end
		end
		if countSet(panelsBySource[field]) == 0 then recordUnmapped(field) end
	end

	local function collectNestedPanelSets(value, source)
		local outerMap, valid = getTable(value)
		if not valid then return end
		for outerKey, panels in pairs(outerMap or {}) do
			if not isSafeKey(outerKey) then recordUnknown() end
			markPanelSet(panels, source)
		end
	end

	for panelId in pairs(metaChangedPanels or {}) do
		markPanel(panelId, "spellEntryMeta")
	end
	if metaUnknown then recordUnknown() end
	if changedFields and changedFields.spellEntryMeta and countSet(panelsBySource.spellEntryMeta) == 0 then recordUnmapped("spellEntryMeta") end

	collectPanelMapDiff("spellIndex")
	collectEntryIndexDiff()

	-- RebuildPowerIndex refreshes usable/resource state for every power-tracked spell.
	-- RebuildChargesIndex can change charge availability even when its panel map stays stable.
	-- Include every affected panel type conservatively instead of deriving a narrower unsafe subset.
	collectNestedPanelSets(previousState.powerPanelsBySpell, "powerTracked")
	collectNestedPanelSets(runtime.powerPanelsBySpell, "powerTracked")
	markPanelSet(previousState.chargesPanels, "chargesTracked")
	markPanelSet(runtime.chargesPanels, "chargesTracked")
	local powerChanged = changedFields
		and (changedFields.powerIndex or changedFields.powerCostNames or changedFields.powerCheckSpells or changedFields.powerAliasIdsBySpell or changedFields.powerPanelsBySpell or changedFields.powerCheckActive)
	if powerChanged and countSet(panelsBySource.powerTracked) == 0 then recordUnmapped("powerTracked") end
	local chargesChanged = changedFields and (changedFields.chargesIndex or changedFields.chargesPanels or changedFields.chargesActive)
	if chargesChanged and countSet(panelsBySource.chargesTracked) == 0 then recordUnmapped("chargesTracked") end

	local scopedFields = {
		spellIndex = true,
		spellEntryIndex = true,
		spellEntryMeta = true,
		powerIndex = true,
		powerCostNames = true,
		powerCheckSpells = true,
		powerAliasIdsBySpell = true,
		powerPanelsBySpell = true,
		powerCheckActive = true,
		chargesIndex = true,
		chargesPanels = true,
		chargesActive = true,
	}
	for field in pairs(changedFields or {}) do
		if not scopedFields[field] then recordUnmapped(field) end
	end
	for _ in pairs(unknownFields or {}) do
		recordUnknown()
	end

	return panelUnion, unknownCount, unmappedCount, countSet(panelUnion)
end

function cdp.ENTRY.BuildSpecAwareRefreshScope(previousState, fields, runtime, racialsChanged)
	if not (previousState and fields and runtime) then return nil, 1, 1, 0 end
	local metaChangedPanels, metaUnknown = cdp.ENTRY.CollectSpecRefreshSpellMetaChanges(previousState, runtime)
	local changedFields = {}
	local unknownFields = {}
	if racialsChanged == true then changedFields.playerRacialNormalization = true end
	for i = 1, #fields do
		local field = fields[i]
		local equal = cdp.ENTRY.AreSpecRefreshValuesEqual(previousState[field], runtime[field])
		if equal == false then
			changedFields[field] = true
		elseif equal == nil then
			unknownFields[field] = true
		end
	end
	return cdp.ENTRY.BuildSpecRefreshPanelScope(previousState, runtime, changedFields, unknownFields, metaChangedPanels, metaUnknown)
end

function CooldownPanels:RebuildSpellIndex()
	self:InvalidateSpellQueryCaches()
	local root = ensureRoot()
	local runtime = self.runtime or {}
	local index = {}
	local readySoundQueryByStateKey = {}
	local readySoundExactStateKeyBySpellId = {}
	local readySoundSoundByStateKey = {}
	local readySoundSweepIds = {}
	local readySoundEventDrivenByStateKey = {}
	local spellEntryIndex = {}
	local spellEntryMeta = {}
	local itemEntryIndex = {}
	local itemEntryMeta = {}
	local slotEntryIndex = {}
	local slotEntryMeta = {}
	local enabledPanels = {}
	local enabledPanelIds = {}
	local cdmAuraPanels = {}
	local cdmAuraPanelIds = {}
	local cdmAuraEntryIdsByPanel = {}
	local cdmAuraCooldownKeys = {}
	local cdmAuraSpellIds = {}
	local cdmAuraHasSpellOnlyEntries = false
	local cdmAuraEntryCount = 0
	local barPanels = {}
	local barPanelIds = {}
	local barEntryIdsByPanel = {}
	local barEntryCount = 0
	local enabledPanelsBySpec = {}
	local enabledPanelIdsBySpec = {}
	local itemPanels = {}
	local itemUsesPanels = {}
	local itemTrackedIds = {}
	local itemUsesTrackedIds = {}
	local rangeCheckSpells = {}
	runtime.interruptGlowActive = false
	runtime.interruptGlowPanels = {}
	self:EnsureFoodRankGroupsLoaded()
	local activeSpecId = queryPlayerSpecId()
	local classSpecs = getPlayerClassSpecMap()
	if classSpecs then
		for specId in pairs(classSpecs) do
			enabledPanelsBySpec[specId] = {}
			enabledPanelIdsBySpec[specId] = {}
		end
	end
	if activeSpecId and not enabledPanelsBySpec[activeSpecId] then
		enabledPanelsBySpec[activeSpecId] = {}
		enabledPanelIdsBySpec[activeSpecId] = {}
	end
	if root and root.panels then
		syncRootOrderIfDirty(root)
		for _, panelId in ipairs(CooldownPanels.GetCachedPanelIds(root)) do
			local panel = root.panels[panelId]
			local hasRuntimeEntries = panelHasRuntimeEntries(panel)
			if panel and panel.enabled ~= false and hasRuntimeEntries then
				if panelHasSpecFilter(panel) then
					local filter = panel.specFilter
					for specId, bucket in pairs(enabledPanelsBySpec) do
						if filter and filter[specId] == true then
							bucket[panelId] = true
							enabledPanelIdsBySpec[specId][#enabledPanelIdsBySpec[specId] + 1] = panelId
						end
					end
				else
					for specId, bucket in pairs(enabledPanelsBySpec) do
						bucket[panelId] = true
						enabledPanelIdsBySpec[specId][#enabledPanelIdsBySpec[specId] + 1] = panelId
					end
				end
			end
			if panel and panel.enabled ~= false and hasRuntimeEntries and panelAllowsSpec(panel) then
				enabledPanels[panelId] = true
				enabledPanelIds[#enabledPanelIds + 1] = panelId
				local layout = panel.layout
				local wantsRangeCheck = layout and layout.rangeOverlayEnabled == true
				for entryId, entry in pairs(panel.entries or {}) do
					local spellId
					local trackedItemId
					local trackedSlotId
					local spellEntryMetaData
					local itemEntryMetaData
					local slotEntryMetaData
					if entry and entry.displayMode == "BAR" then
						local entryIds = barEntryIdsByPanel[panelId]
						if not entryIds then
							barPanels[panelId] = true
							barPanelIds[#barPanelIds + 1] = panelId
							entryIds = {}
							barEntryIdsByPanel[panelId] = entryIds
						end
						entryIds[#entryIds + 1] = entryId
						barEntryCount = barEntryCount + 1
					end
					if entry and entry.type == "CDM_AURA" then
						local entryIds = cdmAuraEntryIdsByPanel[panelId]
						if not entryIds then
							cdmAuraPanels[panelId] = true
							cdmAuraPanelIds[#cdmAuraPanelIds + 1] = panelId
							entryIds = {}
							cdmAuraEntryIdsByPanel[panelId] = entryIds
							end
							entryIds[#entryIds + 1] = entryId
							cdmAuraEntryCount = cdmAuraEntryCount + 1
							local cooldownID = entry.cooldownID
							if type(cooldownID) == "number" and cooldownID > 0 then
								cdmAuraCooldownKeys[cooldownID] = true
							elseif type(cooldownID) == "string" and cooldownID ~= "" then
								cdmAuraCooldownKeys[cooldownID] = true
							end
							local cdmAuraSpellID = tonumber(entry.spellID)
							if cdmAuraSpellID and cdmAuraSpellID > 0 then
								cdmAuraSpellIds[cdmAuraSpellID] = true
								if not cooldownID then cdmAuraHasSpellOnlyEntries = true end
							end
						end
					if entry and entry.type == "SPELL" and entry.spellID then
						spellId = tonumber(entry.spellID)
						if self:IsEntryCDMAuraOverlayEnabled(panel.layout, entry, "SPELL") and spellId and spellId > 0 then
							if not cdmAuraEntryIdsByPanel[panelId] then
								cdmAuraPanels[panelId] = true
								cdmAuraPanelIds[#cdmAuraPanelIds + 1] = panelId
								cdmAuraEntryIdsByPanel[panelId] = {}
							end
							for _, aliasId in ipairs(self:GetEntrySpellAliasIDs(entry, spellId)) do
								cdmAuraSpellIds[aliasId] = true
							end
							cdmAuraEntryCount = cdmAuraEntryCount + 1
						end
					elseif entry and entry.type == "MACRO" then
						local macro = CooldownPanels.ResolveMacroEntry(entry)
						if macro and macro.kind == "SPELL" and macro.spellID then
							spellId = tonumber(macro.spellID)
						elseif macro and macro.kind == "ITEM" and entry.showCooldown ~= false then
							itemPanels[panelId] = true
						end
						if macro and macro.kind == "ITEM" then
							trackedItemId = tonumber(macro.itemID)
							if entry.showItemUses == true then itemUsesPanels[panelId] = true end
						end
					end
					if spellId then
						local effectiveId, resolvedSpellId, _, variantGroup = self:ResolveEntryTrackedSpellID(entry, spellId)
						effectiveId = effectiveId or getEffectiveSpellId(spellId) or spellId
						resolvedSpellId = resolvedSpellId or spellId
						if shouldTrackPassiveSpell(entry) or not isSpellPassiveSafe(resolvedSpellId, effectiveId) then
							local showCooldown = entry.showCooldown ~= false
							local staticTextShowOnCooldown = entry.staticTextShowOnCooldown == true
							local showCharges = CooldownPanels:ShouldShowEntryCharges(layout, entry, "SPELL")
							local alwaysShow = entry.alwaysShow ~= false
							local trackPower = self:ResolveEntryCheckPower(layout, entry)
								or self:ResolveEntryHideWhenNoResource(layout, entry)
								or (entry.type == "SPELL" and self:ResolveEntryGlowReady(layout, entry) and self:ResolveEntryReadyGlowCheckPower(layout, entry))
							spellEntryMetaData = cdp.ENTRY.EnsureSpellEntryMeta(spellEntryMeta, panelId, entryId)
							spellEntryMetaData.panelId = panelId
							spellEntryMetaData.entryId = entryId
							spellEntryMetaData.baseSpellId = spellId
							spellEntryMetaData.resolvedSpellId = resolvedSpellId
							spellEntryMetaData.effectiveSpellId = effectiveId
							spellEntryMetaData.variantGroupKind = variantGroup and variantGroup.kind or nil
							spellEntryMetaData.variantGroupKey = variantGroup and variantGroup.key or nil
							spellEntryMetaData.trackCooldown = showCooldown or staticTextShowOnCooldown
							spellEntryMetaData.trackCharges = showCharges
							spellEntryMetaData.trackPower = trackPower == true
							spellEntryMetaData.alwaysShow = alwaysShow
							spellEntryMetaData.visibilityOnCooldown = showCooldown and not alwaysShow
							spellEntryMetaData.visibilityOnCharges = showCharges and not alwaysShow
							spellEntryMetaData.localCooldownSafe = spellEntryMetaData.trackCooldown == true and spellEntryMetaData.visibilityOnCooldown ~= true
							spellEntryMetaData.localChargesSafe = spellEntryMetaData.trackCharges == true and spellEntryMetaData.visibilityOnCharges ~= true
							spellEntryMetaData.localPowerSafe = spellEntryMetaData.trackPower == true and self:ResolveEntryHideWhenNoResource(layout, entry) ~= true
							for _, aliasId in ipairs(self:GetEntrySpellAliasIDs(entry, spellId)) do
								index[aliasId] = index[aliasId] or {}
								index[aliasId][panelId] = true
								cdp.ENTRY.RegisterSpellAlias(spellEntryIndex, aliasId, panelId, entryId, spellEntryMetaData)
							end
							if entry.interruptGlow == true and self:IsInterruptGlowSupported(entry) then
								runtime.interruptGlowActive = true
								runtime.interruptGlowPanels[panelId] = true
							end
							if wantsRangeCheck and effectiveId then rangeCheckSpells[effectiveId] = true end
						end
					end
					if entry and (entry.type == "ITEM" or entry.type == "SLOT") and entry.showCooldown ~= false then itemPanels[panelId] = true end
					if entry and entry.type == "ITEM" and entry.showItemUses == true then itemUsesPanels[panelId] = true end
					if entry and entry.type == "ITEM" then trackedItemId = tonumber(entry.itemID) or trackedItemId end
					if entry and entry.type == "SLOT" then trackedSlotId = tonumber(entry.slotID) end
					if trackedItemId then
						local trackUses = entry and entry.showItemUses == true
						itemEntryMetaData = cdp.ENTRY.EnsureItemEntryMeta(itemEntryMeta, panelId, entryId)
						itemEntryMetaData.panelId = panelId
						itemEntryMetaData.entryId = entryId
						itemEntryMetaData.baseItemId = trackedItemId
						itemEntryMetaData.trackUses = trackUses == true
						itemEntryMetaData.showWhenEmpty = entry and entry.showWhenEmpty == true or false
						itemEntryMetaData.alwaysShow = entry and entry.alwaysShow ~= false or false
						local tracked = false
						if entry and entry.type == "ITEM" and entry.useHighestRank == true then
							local rankMap = self.itemHighestRankByID
							local group = rankMap and rankMap[trackedItemId] or nil
							if type(group) == "table" then
								for i = 1, #group do
									local candidateId = tonumber(group[i])
									if candidateId then
										itemTrackedIds[candidateId] = true
										if trackUses then itemUsesTrackedIds[candidateId] = true end
										cdp.ENTRY.RegisterItemAlias(itemEntryIndex, candidateId, panelId, entryId, itemEntryMetaData)
										tracked = true
									end
								end
							end
						end
						if not tracked then
							itemTrackedIds[trackedItemId] = true
							if trackUses then itemUsesTrackedIds[trackedItemId] = true end
							cdp.ENTRY.RegisterItemAlias(itemEntryIndex, trackedItemId, panelId, entryId, itemEntryMetaData)
						end
					end
					if trackedSlotId and entry and entry.type == "SLOT" and entry.showCooldown ~= false then
						slotEntryMetaData = cdp.ENTRY.EnsureSlotEntryMeta(slotEntryMeta, panelId, entryId)
						slotEntryMetaData.panelId = panelId
						slotEntryMetaData.entryId = entryId
						slotEntryMetaData.slotId = trackedSlotId
						slotEntryMetaData.showWhenNoCooldown = entry.showWhenNoCooldown == true
						slotEntryMetaData.alwaysShow = entry.alwaysShow ~= false
						cdp.ENTRY.RegisterSlotAlias(slotEntryIndex, trackedSlotId, panelId, entryId, slotEntryMetaData)
					end
				end
				for i = 1, #(panel.order or {}) do
					local orderedEntryId = panel.order[i]
					local orderedEntry = panel.entries and panel.entries[orderedEntryId] or nil
					local orderedSpellId = orderedEntry and orderedEntry.type == "SPELL" and tonumber(orderedEntry.spellID) or nil
					if orderedSpellId then
						local _, enabledField, soundField = self:GetEntrySoundConfig(orderedEntry)
						if enabledField and soundField and orderedEntry[enabledField] == true then
							local soundName = normalizeSoundName(orderedEntry[soundField])
							if soundName and soundName ~= "None" then
								local stateKey = self:GetEntryReadySoundStateKey(orderedEntry, orderedSpellId)
								local querySpellId = self:GetEntryReadySoundQuerySpellId(orderedEntry, orderedSpellId)
								if stateKey and querySpellId and readySoundQueryByStateKey[stateKey] == nil then
									local chargesInfo = Api.GetSpellChargesInfo and Api.GetSpellChargesInfo(querySpellId) or nil
									readySoundQueryByStateKey[stateKey] = querySpellId
									readySoundSoundByStateKey[stateKey] = soundName
									readySoundSweepIds[#readySoundSweepIds + 1] = querySpellId
									readySoundEventDrivenByStateKey[stateKey] = type(chargesInfo) == "table" and chargesInfo.maxCharges ~= nil
									if self:IsEntryTalentChoiceExact(orderedEntry) then
										local aliasIds = self:GetEntrySpellAliasIDs(orderedEntry, orderedSpellId)
										for aliasIndex = 1, #(aliasIds or {}) do
											readySoundExactStateKeyBySpellId[aliasIds[aliasIndex]] = stateKey
										end
									end
								end
							end
						end
					end
				end
			end
		end
	end
	self.runtime = runtime
	runtime.disabledPanelIds = runtime.disabledPanelIds or {}
	for i = 1, #runtime.disabledPanelIds do
		runtime.disabledPanelIds[i] = nil
	end
	for panelId in pairs(runtime.enabledPanels or {}) do
		if not enabledPanels[panelId] then runtime.disabledPanelIds[#runtime.disabledPanelIds + 1] = panelId end
	end
	runtime.activeSpecId = activeSpecId
	runtime.enabledPanelsBySpec = enabledPanelsBySpec
	runtime.enabledPanelIdsBySpec = enabledPanelIdsBySpec
	runtime.spellIndex = index
	runtime.readySoundQueryByStateKey = readySoundQueryByStateKey
	runtime.readySoundExactStateKeyBySpellId = readySoundExactStateKeyBySpellId
	runtime.readySoundSoundByStateKey = readySoundSoundByStateKey
	runtime.readySoundSweepIds = readySoundSweepIds
	runtime.readySoundEventDrivenByStateKey = readySoundEventDrivenByStateKey
	runtime.spellEntryIndex = spellEntryIndex
	runtime.spellEntryMeta = spellEntryMeta
	runtime.itemEntryIndex = itemEntryIndex
	runtime.itemEntryMeta = itemEntryMeta
	runtime.slotEntryIndex = slotEntryIndex
	runtime.slotEntryMeta = slotEntryMeta
	runtime.enabledPanels = enabledPanels
	runtime.enabledPanelIds = enabledPanelIds
	runtime.cdmAuraPanels = cdmAuraPanels
	runtime.cdmAuraPanelIds = cdmAuraPanelIds
	runtime.cdmAuraEntryIdsByPanel = cdmAuraEntryIdsByPanel
	runtime.cdmAuraCooldownKeys = cdmAuraCooldownKeys
	runtime.cdmAuraSpellIds = cdmAuraSpellIds
	runtime.cdmAuraHasSpellOnlyEntries = cdmAuraHasSpellOnlyEntries
	runtime.cdmAuraEntryCount = cdmAuraEntryCount
	runtime.barPanels = barPanels
	runtime.barPanelIds = barPanelIds
	runtime.barEntryIdsByPanel = barEntryIdsByPanel
	runtime.barEntryCount = barEntryCount
	runtime.barStaticGeneration = (runtime.barStaticGeneration or 0) + 1
	runtime.barLabelGeneration = (runtime.barLabelGeneration or 0) + 1
	runtime.itemPanels = itemPanels
	runtime.itemUsesPanels = itemUsesPanels
	runtime.itemTrackedIds = itemTrackedIds
	runtime.itemUsesTrackedIds = itemUsesTrackedIds
	if updateRangeCheckSpells then updateRangeCheckSpells(rangeCheckSpells) end
	if self.UpdateActiveProcTriggerIndex then self:UpdateActiveProcTriggerIndex() end
	self:RebuildPowerIndex()
	self:RebuildChargesIndex()
	self:PrimeReadySoundStates()
	local cdmAuras = self.CDMAuras
	if cdmAuras and cdmAuras.HandleRuntimeIndexChanged then
		cdmAuras:HandleRuntimeIndexChanged("RebuildSpellIndex", false)
	elseif cdmAuras and cdmAuras.UpdateEventRegistration then
		cdmAuras:UpdateEventRegistration()
	end
	if self.UpdateEventRegistration then self:UpdateEventRegistration() end
	return index
end

function CooldownPanels:RebuildPowerIndex()
	local root = ensureRoot()
	local runtime = self.runtime
	local enabledPanels = runtime and runtime.enabledPanels or nil
	local enabledPanelIds = runtime and runtime.enabledPanelIds or nil
	local powerIndex = {}
	local powerCostNames = {}
	local powerCheckSpells = {}
	local powerPanelsBySpell = {}
	local powerAliasIdsBySpell = {}
	local powerCheckActive = false
	if root and root.panels then
		if enabledPanelIds then
			for i = 1, #enabledPanelIds do
				local panelId = enabledPanelIds[i]
				local panel = root.panels[panelId]
				local layout = panel and panel.layout or {}
				if panel and (not enabledPanels or enabledPanels[panelId]) then
					local effectiveLayoutCache = {}
					for _, entry in pairs(panel.entries or {}) do
						local trackEntryPower = false
						if entry then
							local entryLayout = self:GetEntryEffectiveLayout(panelId, entry, effectiveLayoutCache, panel) or layout
							trackEntryPower = self:ResolveEntryCheckPower(entryLayout, entry)
								or self:ResolveEntryHideWhenNoResource(entryLayout, entry)
								or (entry.type == "SPELL" and self:ResolveEntryGlowReady(entryLayout, entry) and self:ResolveEntryReadyGlowCheckPower(entryLayout, entry))
						end
						if entry and trackEntryPower then
							local baseId
							if entry.type == "SPELL" and entry.spellID then
								baseId = tonumber(entry.spellID)
							elseif entry.type == "MACRO" then
								local macro = CooldownPanels.ResolveMacroEntry(entry)
								if macro and macro.kind == "SPELL" and macro.spellID then baseId = tonumber(macro.spellID) end
							end
							if baseId then
								local effectiveId, resolvedSpellId = self:ResolveEntryTrackedSpellID(entry, baseId)
								effectiveId = effectiveId or getEffectiveSpellId(baseId) or baseId
								resolvedSpellId = resolvedSpellId or baseId
								if shouldTrackPassiveSpell(entry) or not isSpellPassiveSafe(resolvedSpellId, effectiveId) then
									powerCheckActive = true
									powerCheckSpells[effectiveId] = true
									if not powerAliasIdsBySpell[effectiveId] then powerAliasIdsBySpell[effectiveId] = self:GetEntrySpellAliasIDs(entry, effectiveId) end
									powerPanelsBySpell[effectiveId] = powerPanelsBySpell[effectiveId] or {}
									powerPanelsBySpell[effectiveId][panelId] = true
									local costs = Api.GetSpellPowerCost and Api.GetSpellPowerCost(effectiveId)
									if type(costs) == "table" then
										local names = getSpellPowerCostNamesFromCosts(costs)
										if names then
											powerCostNames[baseId] = names
											for _, name in ipairs(names) do
												local key = string.upper(name)
												if key ~= "" then
													powerIndex[key] = powerIndex[key] or {}
													powerIndex[key][effectiveId] = true
												end
											end
										end
									end
								end
							end
						end
					end
				end
			end
		else
			for panelId, panel in pairs(root.panels) do
				local layout = panel.layout or {}
				if panel.enabled ~= false and panelAllowsSpec(panel) then
					local normalizedPanelId = normalizeId(panelId)
					local effectiveLayoutCache = {}
					for _, entry in pairs(panel.entries or {}) do
						local trackEntryPower = false
						if entry then
							local entryLayout = self:GetEntryEffectiveLayout(normalizedPanelId, entry, effectiveLayoutCache, panel) or layout
							trackEntryPower = self:ResolveEntryCheckPower(entryLayout, entry)
								or self:ResolveEntryHideWhenNoResource(entryLayout, entry)
								or (entry.type == "SPELL" and self:ResolveEntryGlowReady(entryLayout, entry) and self:ResolveEntryReadyGlowCheckPower(entryLayout, entry))
						end
						if entry and trackEntryPower then
							local baseId
							if entry.type == "SPELL" and entry.spellID then
								baseId = tonumber(entry.spellID)
							elseif entry.type == "MACRO" then
								local macro = CooldownPanels.ResolveMacroEntry(entry)
								if macro and macro.kind == "SPELL" and macro.spellID then baseId = tonumber(macro.spellID) end
							end
							if baseId then
								local effectiveId, resolvedSpellId = self:ResolveEntryTrackedSpellID(entry, baseId)
								effectiveId = effectiveId or getEffectiveSpellId(baseId) or baseId
								resolvedSpellId = resolvedSpellId or baseId
								if shouldTrackPassiveSpell(entry) or not isSpellPassiveSafe(resolvedSpellId, effectiveId) then
									powerCheckActive = true
									powerCheckSpells[effectiveId] = true
									if not powerAliasIdsBySpell[effectiveId] then powerAliasIdsBySpell[effectiveId] = self:GetEntrySpellAliasIDs(entry, effectiveId) end
									powerPanelsBySpell[effectiveId] = powerPanelsBySpell[effectiveId] or {}
									powerPanelsBySpell[effectiveId][normalizedPanelId] = true
									local costs = Api.GetSpellPowerCost and Api.GetSpellPowerCost(effectiveId)
									if type(costs) == "table" then
										local names = getSpellPowerCostNamesFromCosts(costs)
										if names then
											powerCostNames[baseId] = names
											for _, name in ipairs(names) do
												local key = string.upper(name)
												if key ~= "" then
													powerIndex[key] = powerIndex[key] or {}
													powerIndex[key][effectiveId] = true
												end
											end
										end
									end
								end
							end
						end
					end
				end
			end
		end
	end
	if powerCheckActive and not next(powerCheckSpells) then powerCheckActive = false end
	self.runtime = self.runtime or {}
	runtime = self.runtime
	runtime.powerIndex = powerIndex
	runtime.powerCostNames = powerCostNames
	runtime.powerCheckSpells = powerCheckSpells
	runtime.powerAliasIdsBySpell = powerAliasIdsBySpell
	runtime.powerPanelsBySpell = powerPanelsBySpell
	runtime.powerCheckActive = powerCheckActive == true
	runtime.powerInsufficient = runtime.powerInsufficient or {}
	wipe(runtime.powerInsufficient)
	runtime.spellUnusable = runtime.spellUnusable or {}
	wipe(runtime.spellUnusable)
	updatePowerEventRegistration()
	if Api.IsSpellUsableFn then
		for spellId in pairs(powerCheckSpells) do
			local checkId = getEffectiveSpellId(spellId) or spellId
			local isUsable, insufficientPower = Api.IsSpellUsableFn(checkId)
			setPowerInsufficient(runtime, checkId, isUsable, insufficientPower)
		end
	end
end

function CooldownPanels:RebuildChargesIndex()
	local root = ensureRoot()
	local runtime = self.runtime
	local enabledPanels = runtime and runtime.enabledPanels or nil
	local enabledPanelIds = runtime and runtime.enabledPanelIds or nil
	local chargesIndex = {}
	local chargesPanels = {}
	if root and root.panels then
		if enabledPanelIds then
			for i = 1, #enabledPanelIds do
				local panelId = enabledPanelIds[i]
				local panel = root.panels[panelId]
				if panel and (not enabledPanels or enabledPanels[panelId]) then
					local layout = panel.layout
					for _, entry in pairs(panel.entries or {}) do
						local baseId
						local macro = entry and entry.type == "MACRO" and CooldownPanels.ResolveMacroEntry(entry) or nil
						local resolvedType = (macro and macro.kind) or (entry and entry.type)
						if CooldownPanels:ShouldShowEntryCharges(layout, entry, resolvedType) then
							if entry.type == "SPELL" and entry.spellID then
								baseId = tonumber(entry.spellID)
							elseif entry.type == "MACRO" then
								if macro and macro.kind == "SPELL" and macro.spellID then baseId = tonumber(macro.spellID) end
							end
						end
						if baseId then
							local effectiveId, resolvedSpellId = self:ResolveEntryTrackedSpellID(entry, baseId)
							effectiveId = effectiveId or getEffectiveSpellId(baseId) or baseId
							resolvedSpellId = resolvedSpellId or baseId
							if shouldTrackPassiveSpell(entry) or not isSpellPassiveSafe(resolvedSpellId, effectiveId) then
								chargesPanels[panelId] = true
								if Api.GetSpellChargesInfo then
									local info = Api.GetSpellChargesInfo(effectiveId)
									if type(info) == "table" then
										chargesIndex[effectiveId] = chargesIndex[effectiveId] or {}
										chargesIndex[effectiveId][panelId] = true
									end
								end
							end
						end
					end
				end
			end
		else
			for panelId, panel in pairs(root.panels) do
				if panel and panel.enabled ~= false and panelAllowsSpec(panel) then
					local layout = panel.layout
					for _, entry in pairs(panel.entries or {}) do
						local baseId
						local macro = entry and entry.type == "MACRO" and CooldownPanels.ResolveMacroEntry(entry) or nil
						local resolvedType = (macro and macro.kind) or (entry and entry.type)
						if CooldownPanels:ShouldShowEntryCharges(layout, entry, resolvedType) then
							if entry.type == "SPELL" and entry.spellID then
								baseId = tonumber(entry.spellID)
							elseif entry.type == "MACRO" then
								if macro and macro.kind == "SPELL" and macro.spellID then baseId = tonumber(macro.spellID) end
							end
						end
						if baseId then
							local effectiveId, resolvedSpellId = self:ResolveEntryTrackedSpellID(entry, baseId)
							effectiveId = effectiveId or getEffectiveSpellId(baseId) or baseId
							resolvedSpellId = resolvedSpellId or baseId
							if shouldTrackPassiveSpell(entry) or not isSpellPassiveSafe(resolvedSpellId, effectiveId) then
								chargesPanels[panelId] = true
								if Api.GetSpellChargesInfo then
									local info = Api.GetSpellChargesInfo(effectiveId)
									if type(info) == "table" then
										chargesIndex[effectiveId] = chargesIndex[effectiveId] or {}
										chargesIndex[effectiveId][panelId] = true
									end
								end
							end
						end
					end
				end
			end
		end
	end
	self.runtime = self.runtime or {}
	runtime = self.runtime
	runtime.chargesIndex = chargesIndex
	runtime.chargesPanels = chargesPanels
	runtime.chargesActive = next(chargesIndex) and true or false
	runtime.chargesState = runtime.chargesState or {}
	for spellId in pairs(runtime.chargesState) do
		if not chargesIndex[spellId] then runtime.chargesState[spellId] = nil end
	end
end

function CooldownPanels:NormalizeAll()
	local root = ensureRoot()
	if not root then return end
	Helper.NormalizeRoot(root)
	root._eqolEditorGroupsReady = nil
	root._eqolEditorGroupOrderDirty = true
	normalizedRoots[root] = true
	Helper.SyncOrder(root.order, root.panels)
	root._orderDirty = nil
	local currentPlayerRacialSpellIDs = self:GetCurrentPlayerRacialSpellIDs()
	for panelId, panel in pairs(root.panels) do
		if panel and panel.id == nil then panel.id = panelId end
		Helper.NormalizePanel(panel, root.defaults)
		Helper.InvalidateFixedLayoutCache(panel)
		normalizedPanels[panel] = true
		Helper.SyncOrder(panel.order, panel.entries)
		local normalizePlayerRacials = panel and panel.enabled ~= false and panelAllowsSpec(panel)
		for entryId, entry in pairs(panel.entries) do
			if entry and entry.id == nil then entry.id = entryId end
			Helper.NormalizeEntry(entry, root.defaults)
			if entry and entry.type == "SPELL" and entry.spellID then
				local normalizedSpellID = self:NormalizePersistentSpellID(entry.spellID, { allowTalentChoiceCanonical = false }) or entry.spellID
				if normalizePlayerRacials then normalizedSpellID = self:NormalizePlayerRacialSpellID(normalizedSpellID, currentPlayerRacialSpellIDs, entry) end
				entry.spellID = normalizedSpellID
			end
			if entry and entry.type == "ITEM" then
				local canonicalItemID, wasHigherRank = self:GetCanonicalItemRankID(entry.itemID)
				if canonicalItemID then entry.itemID = canonicalItemID end
				if wasHigherRank then entry.useHighestRank = true end
			end
		end
		if Helper.UpdatePanelEntrySpecFilterState then Helper.UpdatePanelEntrySpecFilterState(panel) end
		local seenSpellVariantEntries = nil
		local removedDuplicateVariantEntry = false
		for _, entryId in ipairs(panel.order or {}) do
			local entry = panel.entries and panel.entries[entryId]
			if entry and entry.type == "SPELL" and entry.spellID then
				local canonicalSpellID, _, spellGroup = self:GetCanonicalSpellVariantID(entry.spellID, { staticOnly = true })
				if canonicalSpellID and spellGroup then
					seenSpellVariantEntries = seenSpellVariantEntries or {}
					if seenSpellVariantEntries[canonicalSpellID] then
						panel.entries[entryId] = nil
						local runtime = CooldownPanels.runtime
						if runtime and runtime.actionDisplayCounts then runtime.actionDisplayCounts[Helper.GetEntryKey(panelId, entryId)] = nil end
						removedDuplicateVariantEntry = true
					else
						seenSpellVariantEntries[canonicalSpellID] = entryId
					end
				end
			end
		end
		if removedDuplicateVariantEntry then
			Helper.SyncOrder(panel.order, panel.entries)
			if Helper.UpdatePanelEntrySpecFilterState then Helper.UpdatePanelEntrySpecFilterState(panel) end
			Helper.InvalidateFixedLayoutCache(panel)
		end
		if Helper.IsFixedLayout(panel.layout) then Helper.EnsureFixedSlotAssignments(panel) end
	end
	self:DedupeActivePanelPlayerRacials(root)
	self:RunStorageMigrations(root)
	self:RebuildSpellIndex()
end

function CooldownPanels:AddEntrySafe(panelId, entryType, idValue, overrides)
	local typeKey = entryType and tostring(entryType):upper() or nil
	local function addWithFixedChecks(finalType, finalValue, finalOverrides)
		local panel = self:GetPanel(panelId)
		local resolvedOverrides = finalOverrides
		local fixedError = nil
		if panel and Helper.IsFixedLayout(panel.layout) then
			resolvedOverrides, fixedError = self:ResolveFixedEntryAddOverrides(panel, finalOverrides)
		end
		if fixedError then
			showErrorMessage(fixedError)
			return nil
		end
		return self:AddEntry(panelId, finalType, finalValue, resolvedOverrides)
	end
	if typeKey == "CDM_AURA" then
		local cdmAuras = CooldownPanels.CDMAuras
		if cdmAuras and cdmAuras.AddEntrySafe then return cdmAuras:AddEntrySafe(panelId, idValue, overrides) end
		return nil
	end
	local numericValue = tonumber(idValue)
	local baseValue = numericValue
	if typeKey == "SPELL" and numericValue then
		baseValue = getBaseSpellId(numericValue) or numericValue
		if not spellExistsSafe(numericValue) and not spellExistsSafe(baseValue) then
			showErrorMessage(L["CooldownPanelSpellInvalid"] or "Spell does not exist.")
			return nil
		end
		local exactTalentChoice = type(overrides) == "table" and overrides.talentChoiceExact == true
		if exactTalentChoice then
			if not self:IsTalentChoiceSpellID(numericValue) then return nil end
			baseValue = numericValue
		else
			baseValue = self:NormalizePersistentSpellID(numericValue, { allowTalentChoiceCanonical = true }) or baseValue
		end
	end
	if typeKey == "STANCE" then
		local stanceDef = CooldownPanels.GetStanceDefinition and CooldownPanels:GetStanceDefinition(idValue) or nil
		if not stanceDef then
			local stanceLabel = (CooldownPanels.GetStanceTypeLabel and CooldownPanels:GetStanceTypeLabel()) or (_G.STANCE or "Stance")
			showErrorMessage((stanceLabel or (_G.STANCE or "Stance")) .. " does not exist.")
			return nil
		end
		if self:FindEntryByValue(panelId, typeKey, stanceDef.id) then
			showErrorMessage(L["CooldownPanelEntry"] and (L["CooldownPanelEntry"] .. " already exists.") or "Entry already exists.")
			return nil
		end
		local finalOverrides = {}
		if type(overrides) == "table" then
			for key, value in pairs(overrides) do
				finalOverrides[key] = value
			end
		end
		local defaults = CooldownPanels.GetStanceDefaultOverrides and CooldownPanels:GetStanceDefaultOverrides() or nil
		if type(defaults) == "table" then
			for key, value in pairs(defaults) do
				if finalOverrides[key] == nil then finalOverrides[key] = value end
			end
		end
		return addWithFixedChecks(typeKey, stanceDef.id, finalOverrides)
	end
	if typeKey == "MACRO" then
		local macroName = nil
		if type(overrides) == "table" then macroName = CooldownPanels.NormalizeMacroName(overrides.macroName) end
		if not macroName then macroName = CooldownPanels.NormalizeMacroName(type(idValue) == "string" and idValue or nil) end
		if not macroName and numericValue and Api.GetMacroInfo then
			local infoName = Api.GetMacroInfo(numericValue)
			macroName = CooldownPanels.NormalizeMacroName(infoName)
		end
		if numericValue and not macroName then
			showErrorMessage((_G.MACRO or "Macro") .. " does not exist.")
			return nil
		end
		if not numericValue and macroName and Api.GetMacroIndexByName then
			local macroId = Api.GetMacroIndexByName(macroName)
			if type(macroId) == "number" and macroId > 0 then
				numericValue = macroId
				baseValue = macroId
			end
		end
		if not numericValue and not macroName then
			showErrorMessage((_G.MACRO or "Macro") .. " does not exist.")
			return nil
		end
		if self:FindEntryByValue(panelId, typeKey, numericValue or macroName) then
			showErrorMessage(L["CooldownPanelEntry"] and (L["CooldownPanelEntry"] .. " already exists.") or "Entry already exists.")
			return nil
		end
		local finalOverrides = {}
		if type(overrides) == "table" then
			for key, value in pairs(overrides) do
				finalOverrides[key] = value
			end
		end
		finalOverrides.macroName = macroName
		return addWithFixedChecks(typeKey, numericValue or idValue, finalOverrides)
	end
	local finalOverrides = overrides
	if typeKey == "ITEM" and numericValue then
		local canonicalItemID, wasHigherRank = self:GetCanonicalItemRankID(baseValue)
		if canonicalItemID then baseValue = canonicalItemID end
		if Api.GetItemInfoInstantFn and not Api.GetItemInfoInstantFn(baseValue) then
			showErrorMessage(L["Item id does not exist"] or "Item id does not exist")
			return nil
		end
		if wasHigherRank then
			finalOverrides = {}
			if type(overrides) == "table" then
				for key, value in pairs(overrides) do
					finalOverrides[key] = value
				end
			end
			finalOverrides.useHighestRank = true
		end
	end
	if self:FindEntryByValue(panelId, typeKey, baseValue, finalOverrides) then
		showErrorMessage(L["CooldownPanelEntry"] and (L["CooldownPanelEntry"] .. " already exists.") or "Entry already exists.")
		return nil
	end
	return addWithFixedChecks(typeKey, baseValue, finalOverrides)
end

function CooldownPanels:HandleCursorDrop(panelId, targetSlot)
	panelId = normalizeId(panelId or self:GetSelectedPanel())
	if not panelId then return false end
	local cursorType, cursorId, _, cursorSpellId = Api.GetCursorInfo()
	if not cursorType then return false end
	local dropOverrides = targetSlot and self:GetFixedDropEntryOverrides(panelId, targetSlot) or nil
	local requiresPostAddMove = false
	if dropOverrides and dropOverrides.fixedGroupId then
		local panel = self:GetPanel(panelId)
		local targetGroup = panel and CooldownPanels.GetFixedGroupById(panel, dropOverrides.fixedGroupId) or nil
		requiresPostAddMove = targetGroup and not CooldownPanels.IsFixedGroupStatic(targetGroup) or false
	end
	local function mergeDropOverrides(baseOverrides)
		if not dropOverrides then return baseOverrides end
		local merged = {}
		if type(baseOverrides) == "table" then
			for key, value in pairs(baseOverrides) do
				merged[key] = value
			end
		end
		for key, value in pairs(dropOverrides) do
			merged[key] = value
		end
		return merged
	end

	local added = false
	local addedEntryId
	if cursorType == "spell" then
		local spellId = cursorSpellId or cursorId
		if spellId then addedEntryId = self:AddEntrySafe(panelId, "SPELL", spellId, mergeDropOverrides()) end
	elseif cursorType == "item" then
		if cursorId then addedEntryId = self:AddEntrySafe(panelId, "ITEM", cursorId, mergeDropOverrides()) end
	elseif cursorType == "macro" then
		if cursorId then
			local macroName = Api.GetMacroInfo and Api.GetMacroInfo(cursorId) or nil
			addedEntryId = self:AddEntrySafe(panelId, "MACRO", cursorId, mergeDropOverrides({ macroName = macroName }))
		end
	elseif cursorType == "action" and Api.GetActionInfo then
		local actionType, actionId = Api.GetActionInfo(cursorId)
		if actionType == "spell" then
			addedEntryId = self:AddEntrySafe(panelId, "SPELL", actionId, mergeDropOverrides())
		elseif actionType == "item" then
			addedEntryId = self:AddEntrySafe(panelId, "ITEM", actionId, mergeDropOverrides())
		elseif actionType == "macro" then
			local macroID = tonumber(actionId)
			local macroName = Api.GetActionText and CooldownPanels.NormalizeMacroName(Api.GetActionText(cursorId)) or nil
			if macroName and Api.GetMacroIndexByName then
				local byName = Api.GetMacroIndexByName(macroName)
				if type(byName) == "number" and byName > 0 then macroID = byName end
			end
			if not macroName and macroID and Api.GetMacroInfo then macroName = CooldownPanels.NormalizeMacroName(Api.GetMacroInfo(macroID)) end
			addedEntryId = self:AddEntrySafe(panelId, "MACRO", macroID or macroName, mergeDropOverrides({ macroName = macroName }))
		end
	end

	added = addedEntryId ~= nil
	if added and targetSlot and requiresPostAddMove then self:MoveEntryToFixedSlot(panelId, addedEntryId, targetSlot) end
	if added then Api.ClearCursor() end
	return added, addedEntryId
end

function CooldownPanels:SelectPanel(panelId)
	local root = ensureRoot()
	if not root then return end
	panelId = normalizeId(panelId)
	if not root.panels or not root.panels[panelId] then return end
	local previousPanelId = normalizeId(root.selectedPanel)
	local editor = getEditor()
	local layoutEditActive = editor and editor.layoutEditActive == true
	local previousLayoutPanelId = layoutEditActive and normalizeId(editor._eqolLayoutPanelId or previousPanelId) or nil
	if previousPanelId and previousPanelId ~= panelId then self:HideLayoutEntryStandaloneMenu(previousPanelId) end
	if previousPanelId and previousPanelId ~= panelId then self:HideLayoutPanelStandaloneMenu(previousPanelId) end
	if previousPanelId and previousPanelId ~= panelId then self:HideLayoutFixedGroupStandaloneMenu(previousPanelId) end
	root.selectedPanel = panelId
	if editor then
		editor.selectedPanelId = panelId
		editor.selectedEntryId = nil
		if layoutEditActive then editor._eqolLayoutPanelId = panelId end
	end
	local openLayoutPanelDialog = layoutEditActive and previousPanelId ~= panelId
	local panelChanged = previousPanelId ~= panelId
	local layoutPanelChanged = layoutEditActive and previousLayoutPanelId ~= panelId
	local needsLiveRefresh = self:IsAnyPanelLayoutEditActive() and (panelChanged or layoutPanelChanged)
	if needsLiveRefresh then
		if previousLayoutPanelId and previousLayoutPanelId ~= panelId and self:GetPanel(previousLayoutPanelId) then self:RefreshPanel(previousLayoutPanelId) end
		if previousPanelId and previousPanelId ~= panelId and previousPanelId ~= previousLayoutPanelId and self:GetPanel(previousPanelId) then self:RefreshPanel(previousPanelId) end
		self:RefreshPanel(panelId)
	end
	self:UpdateCursorAnchorState()
	self:RefreshEditor()
	if openLayoutPanelDialog and not (editor and editor._eqolSuppressLayoutPanelDialog == true) then self:OpenLayoutPanelStandaloneMenu(panelId) end
end

function CooldownPanels:SelectEntry(entryId)
	entryId = normalizeId(entryId)
	local editor = getEditor()
	if not editor then return end
	editor.selectedEntryId = entryId
	local panelId = editor.selectedPanelId
	if panelId then
		local runtime = getRuntime(panelId)
		runtime.layoutEditEntryId = entryId
	end
	refreshStandaloneSettingValues()
	self:RefreshEditor()
end

function CooldownPanels:IsPanelLayoutEditAvailable(panelId)
	panelId = normalizeId(panelId)
	if not panelId then return false end
	local panel = self:GetPanel(panelId)
	if not panel then return false end
	return true
end

function CooldownPanels:IsPanelLayoutEditActive(panelId)
	panelId = normalizeId(panelId)
	if not panelId then return false end
	local editor = getEditor()
	local editorShown = editor and editor.frame and editor.frame:IsShown()
	local blizzardEditor = self.BlizzardEditor
	local blizzardFrame = blizzardEditor and blizzardEditor.frame or nil
	local blizzardEditorShown = editor and editor._eqolBlizzardEditorLayoutEdit == true and blizzardFrame and blizzardFrame.IsShown and blizzardFrame:IsShown()
	if not (editorShown or blizzardEditorShown) then return false end
	if editor.layoutEditActive ~= true then return false end
	if normalizeId(editor.selectedPanelId) ~= panelId then return false end
	return self:IsPanelLayoutEditAvailable(panelId)
end

function CooldownPanels:IsAnyPanelLayoutEditActive()
	local editor = getEditor()
	if not (editor and editor.layoutEditActive == true) then return false end
	if editor.frame and editor.frame:IsShown() then return true end
	local blizzardEditor = self.BlizzardEditor
	local blizzardFrame = blizzardEditor and blizzardEditor.frame or nil
	return editor._eqolBlizzardEditorLayoutEdit == true and blizzardFrame and blizzardFrame.IsShown and blizzardFrame:IsShown() or false
end

function CooldownPanels:SetEditorLayoutEditEnabled(enabled)
	local editor = getEditor()
	if not editor then return end
	enabled = enabled == true
	if enabled and not self:IsPanelLayoutEditAvailable(editor.selectedPanelId) then
		self:RefreshEditor()
		return
	end
	if editor.layoutEditActive == enabled then
		self:RefreshEditor()
		return
	end
	local previousPanelId = normalizeId(editor._eqolLayoutPanelId)
	editor.layoutEditActive = enabled
	if not enabled then editor._eqolBlizzardEditorLayoutEdit = nil end
	local nextPanelId = enabled and normalizeId(editor.selectedPanelId) or nil
	editor._eqolLayoutPanelId = nextPanelId
	if not enabled then
		stopCursorFollow()
		setFakeCursorMode("hidden")
	end
	if not enabled then self:HideLayoutEntryStandaloneMenu(previousPanelId or editor.selectedPanelId) end
	if not enabled then self:HideLayoutPanelStandaloneMenu(previousPanelId or editor.selectedPanelId) end
	if not enabled then self:HideLayoutFixedGroupStandaloneMenu(previousPanelId or editor.selectedPanelId) end
	if previousPanelId and self:GetPanel(previousPanelId) then self:RefreshPanel(previousPanelId) end
	if enabled and nextPanelId then
		local nextPanel = self:GetPanel(nextPanelId)
		if nextPanel and panelUsesFakeCursor(nextPanel) then
			stopCursorFollow()
			resetFakeCursorFrame()
			local frame = showFakeCursorFrame()
			frame:SetAlpha(1)
			if frame.texture then frame.texture:Show() end
			frame:EnableMouse(false)
		end
	end
	if nextPanelId and self:GetPanel(nextPanelId) then self:RefreshPanel(nextPanelId) end
	self:UpdateCursorAnchorState()
	self:RefreshEditor()
	if enabled and nextPanelId and not editor._eqolSuppressLayoutPanelDialog then self:OpenLayoutPanelStandaloneMenu(nextPanelId) end
end

function CooldownPanels:PreparePanelForFixedLayoutEdit(panelId)
	panelId = normalizeId(panelId)
	local panel = self:GetPanel(panelId)
	if not panel then return false end
	panel.layout = panel.layout or Helper.CopyTableShallow(Helper.PANEL_LAYOUT_DEFAULTS)
	local layout = panel.layout
	if not Helper.IsFixedLayout(layout) then return false end
	local changed = false
	local maxColumn, maxRow = Helper.EnsureFixedSlotAssignments(panel)
	local nextColumns = Helper.NormalizeFixedGridSize(layout.fixedGridColumns, 0)
	local nextRows = Helper.NormalizeFixedGridSize(layout.fixedGridRows, 0)
	if nextColumns <= 0 then nextColumns = math.max(maxColumn or 0, 1) end
	if nextRows <= 0 then nextRows = math.max(maxRow or 0, 1) end
	if layout.fixedGridColumns ~= nextColumns then
		layout.fixedGridColumns = nextColumns
		changed = true
	end
	if layout.fixedGridRows ~= nextRows then
		layout.fixedGridRows = nextRows
		changed = true
	end
	if changed then
		refreshStandaloneSettingValues()
	end
	return changed
end

function CooldownPanels:BeginStandalonePanelDrag(panelId)
	panelId = normalizeId(panelId)
	local panel = panelId and self:GetPanel(panelId) or nil
	local runtime = panelId and getRuntime(panelId) or nil
	local frame = runtime and runtime.frame
	if not (panel and frame and self:IsPanelLayoutEditActive(panelId)) then return false end
	local anchor = ensurePanelAnchor(panel)
	local usesFakeCursor = panelUsesFakeCursor(panel)
	if usesFakeCursor or not anchorUsesUIParent(anchor) then return false end
	if InCombatLockdown and InCombatLockdown() then return false end
	if frame.SetMovable then frame:SetMovable(true) end
	if frame.EnableMouse then
		runtime._eqolStandalonePanelDragMouseEnabled = true
		frame:EnableMouse(true)
	end
	runtime._eqolStandalonePanelDragging = true
	frame:StartMoving()
	return true
end

function CooldownPanels:FinishStandalonePanelDrag(panelId)
	panelId = normalizeId(panelId)
	local panel = panelId and self:GetPanel(panelId) or nil
	local runtime = panelId and getRuntime(panelId) or nil
	local frame = runtime and runtime.frame
	if not (panel and frame and runtime and runtime._eqolStandalonePanelDragging) then return false end
	runtime._eqolStandalonePanelDragging = nil
	frame:StopMovingOrSizing()
	if runtime._eqolStandalonePanelDragMouseEnabled then
		runtime._eqolStandalonePanelDragMouseEnabled = nil
		frame:EnableMouse(false)
	end
	local anchor = ensurePanelAnchor(panel)
	local point, _, relativePoint, x, y = frame:GetPoint(1)
	point = Helper.NormalizeAnchor(point, anchor and anchor.point or "CENTER")
	relativePoint = Helper.NormalizeAnchor(relativePoint, anchor and anchor.relativePoint or point)
	x = tonumber(x) or 0
	y = tonumber(y) or 0
	self:HandlePositionChanged(panelId, {
		point = point,
		relativePoint = relativePoint,
		x = x,
		y = y,
	})
	CooldownPanels.ClearAppliedAnchorCache(runtime)
	self:ApplyPanelPosition(panelId)
	refreshStandaloneSettingValues()
	return true
end

function CooldownPanels.ShowIconTooltip(self)
	if not self or not self._eqolTooltipEnabled then return end
	if self._eqolNativeAuraTooltipOwner then
		if GameTooltip and GameTooltip.IsOwned and GameTooltip:IsOwned(self) then GameTooltip:Hide() end
		return
	end
	local entry = self._eqolTooltipEntry
	if not entry or not GameTooltip then return end

	GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
	local resolvedEntry = entry
	local runtimeData = self._eqolRuntimeData
	if entry.type == "MACRO" then
		local macro = CooldownPanels.ResolveMacroEntry(entry)
		if macro and macro.kind == "SPELL" and macro.spellID then
			resolvedEntry = { type = "SPELL", spellID = macro.spellID }
		elseif macro and macro.kind == "ITEM" and macro.itemID then
			resolvedEntry = { type = "ITEM", itemID = macro.itemID }
		end
	end
	if resolvedEntry.type == "SPELL" and resolvedEntry.spellID and GameTooltip.SetSpellByID then
		local tooltipSpellID = runtimeData and runtimeData.resolvedType == "SPELL" and (runtimeData.effectiveSpellId or runtimeData.spellId or runtimeData.resolvedSpellId) or nil
		if not tooltipSpellID then tooltipSpellID = CooldownPanels:ResolveEntryTrackedSpellID(resolvedEntry, resolvedEntry.spellID) end
		GameTooltip:SetSpellByID(tooltipSpellID or getEffectiveSpellId(resolvedEntry.spellID) or resolvedEntry.spellID)
	elseif resolvedEntry.type == "CDM_AURA" and resolvedEntry.auraPresetKey then
		GameTooltip:SetText(getEntryName(resolvedEntry), 1, 0.82, 0)
	elseif resolvedEntry.type == "CDM_AURA" and resolvedEntry.spellID and GameTooltip.SetSpellByID then
		GameTooltip:SetSpellByID(getEffectiveSpellId(resolvedEntry.spellID) or resolvedEntry.spellID)
	elseif resolvedEntry.type == "ITEM" and resolvedEntry.itemID and GameTooltip.SetItemByID then
		GameTooltip:SetItemByID(resolvedEntry.itemID)
	elseif resolvedEntry.type == "MACRO" then
		local macro = CooldownPanels.ResolveMacroEntry(entry)
		if macro and macro.macroName then
			GameTooltip:SetText(macro.macroName)
		else
			GameTooltip:SetText(_G.MACRO or "Macro")
		end
	elseif entry.type == "SLOT" and entry.slotID then
		local shown = false
		if GameTooltip.SetInventoryItem then shown = GameTooltip:SetInventoryItem("player", entry.slotID) end
		if not shown then GameTooltip:SetText(getSlotLabel(entry.slotID)) end
	elseif entry.type == "STANCE" or entry.type == "CDM_AURA" then
		GameTooltip:SetText(getEntryName(entry))
	else
		return
	end
	GameTooltip:Show()
end

function CooldownPanels.HideIconTooltip(self)
	if GameTooltip and (not GameTooltip.IsOwned or not self or GameTooltip:IsOwned(self)) then GameTooltip:Hide() end
end

cdp.RUNTIME.CreateCDMAuraHelpButton = function(parent)
	if not parent then return nil end
	local button = CreateFrame("Button", nil, parent)
	button:SetSize(32, 32)
	button:SetNormalTexture("Interface\\common\\help-i")
	button:SetHighlightTexture("Interface\\common\\help-i")
	if button:GetHighlightTexture() then button:GetHighlightTexture():SetAlpha(0.7) end
	button.ring = button:CreateTexture(nil, "BORDER")
	button.ring:SetTexture("Interface\\Minimap\\MiniMap-TrackingBorder")
	button.ring:SetSize(44, 44)
	button.ring:SetPoint("CENTER", button, "CENTER", 8, -9)
	button:SetScript("OnEnter", function(self)
		if not GameTooltip then return end
		GameTooltip:SetOwner(self, "ANCHOR_RIGHT", 6, 0)
		GameTooltip:ClearLines()
		GameTooltip:SetText(L["CooldownPanelCDMAuraHelpTitle"] or "Tracked Auras")
		GameTooltip:AddLine(L["CooldownPanelCDMAuraHelpTooltip"] or "Auras must be enabled in WoW's Cooldown Manager before EnhanceQoL can display them.", 1, 1, 1, true)
		GameTooltip:Show()
	end)
	button:SetScript("OnLeave", function()
		if GameTooltip then GameTooltip:Hide() end
	end)
	return button
end

function CooldownPanels.SetIconTooltipMouseState(icon, enabled)
	if not icon then return end
	local mouseEnabled = enabled == true
	if icon.SetMouseClickEnabled then
		if icon._eqolTooltipMouseClickEnabled ~= mouseEnabled then
			icon:SetMouseClickEnabled(mouseEnabled)
			icon._eqolTooltipMouseClickEnabled = mouseEnabled
		end
	end
	if icon.SetMouseMotionEnabled and icon._eqolTooltipMouseMotionEnabled ~= mouseEnabled then
		icon:SetMouseMotionEnabled(mouseEnabled)
		icon._eqolTooltipMouseMotionEnabled = mouseEnabled
	end
	if icon.EnableMouse and icon._eqolTooltipMouseEnabled ~= mouseEnabled then
		icon:EnableMouse(mouseEnabled)
		icon._eqolTooltipMouseEnabled = mouseEnabled
	end
	if not mouseEnabled and GameTooltip and GameTooltip.IsOwned and GameTooltip.Hide and GameTooltip:IsOwned(icon) then GameTooltip:Hide() end
end

function CooldownPanels.ApplyIconTooltip(icon, entry, enabled, nativeAuraTooltipOwner)
	if not icon then return end
	local tooltipEnabled = enabled == true and entry ~= nil
	-- Native AuraButtons always propagate their input to the host icon. Keep the
	-- host mouse-enabled so panels still block click-through, but give the native
	-- secret-safe AuraButton exclusive ownership of the tooltip.
	nativeAuraTooltipOwner = tooltipEnabled and nativeAuraTooltipOwner == true
	if
		icon._eqolTooltipEntry == entry
		and icon._eqolTooltipEnabled == tooltipEnabled
		and icon._eqolNativeAuraTooltipOwner == nativeAuraTooltipOwner
	then
		return
	end
	icon._eqolTooltipEntry = entry
	icon._eqolTooltipEnabled = tooltipEnabled
	icon._eqolNativeAuraTooltipOwner = nativeAuraTooltipOwner
	CooldownPanels.SetIconTooltipMouseState(icon, tooltipEnabled)
	if nativeAuraTooltipOwner and GameTooltip and GameTooltip.IsOwned and GameTooltip:IsOwned(icon) then GameTooltip:Hide() end
end

function CooldownPanels:GetCooldownFontDefaults(frame)
	local icon = frame and frame.icons and frame.icons[1]
	local fontString = icon and icon.cooldown and icon.cooldown.GetCountdownFontString and icon.cooldown:GetCountdownFontString()
	if fontString and fontString.GetFont then
		local fontPath, fontSize, fontStyle = fontString:GetFont()
		if fontPath then return fontPath, fontSize, fontStyle end
	end
	return Helper.GetCountFontDefaults(frame)
end

function CooldownPanels:GetGlobalFontConfigKey()
	if addon.functions and addon.functions.GetGlobalFontConfigKey then return addon.functions.GetGlobalFontConfigKey() end
	return "__EQOL_GLOBAL_FONT__"
end

function CooldownPanels:GetFontDropdownValue(value)
	if addon.functions and addon.functions.IsGlobalFontConfigValue and addon.functions.IsGlobalFontConfigValue(value) then return self:GetGlobalFontConfigKey() end
	if type(value) == "string" and value ~= "" then return value end
	return self:GetGlobalFontConfigKey()
end

function CooldownPanels:NormalizeDurationTextProfile(value, fallback)
	local durationText = addon.DurationText
	if durationText and durationText.GetProfileKey then return durationText:GetProfileKey(value or fallback or "MINIMAL") end
	return type(value) == "string" and value ~= "" and value or fallback or "MINIMAL"
end

function CooldownPanels:GetPanelDurationTextProfile(panel)
	if panel and panel.layout and panel.layout.durationTextProfile ~= nil then
		return self:NormalizeDurationTextProfile(panel.layout.durationTextProfile, "MINIMAL")
	end
	if panel and panel.barDurationTextProfile ~= nil then return self:NormalizeDurationTextProfile(panel.barDurationTextProfile, "MINIMAL") end
	return self:NormalizeDurationTextProfile(nil, "MINIMAL")
end

function CooldownPanels:GetLayoutDurationTextProfile(layout)
	if layout and layout.durationTextProfile ~= nil then return self:NormalizeDurationTextProfile(layout.durationTextProfile, "MINIMAL") end
	return self:NormalizeDurationTextProfile(nil, "MINIMAL")
end

function CooldownPanels:ApplyCooldownFrameDurationTextProfile(cooldownFrame, profileKey)
	if not (cooldownFrame and addon.functions and addon.functions.ApplyDurationTextProfileToCooldownFrame) then return false end
	return addon.functions.ApplyDurationTextProfileToCooldownFrame(cooldownFrame, self:NormalizeDurationTextProfile(profileKey, "MINIMAL"))
end

function CooldownPanels:ResolveEntryCooldownTextStyle(layout, entry, fallbackFontPath, fallbackFontSize, fallbackFontStyle)
	local panelCache = CooldownPanels._styleCacheRoots.cooldownTextPanel[layout]
	local globalFontStateVersion = addon.functions and addon.functions.GetGlobalFontStateVersion and addon.functions.GetGlobalFontStateVersion() or 0
	local srcFont = layout and layout.cooldownTextFont or nil
	local srcSize = layout and layout.cooldownTextSize or nil
	local srcStyle = layout and layout.cooldownTextStyle or nil
	local srcColor = layout and layout.cooldownTextColor or nil
	local srcX = layout and layout.cooldownTextX or nil
	local srcY = layout and layout.cooldownTextY or nil
	if
		not panelCache
		or panelCache.globalFontStateVersion ~= globalFontStateVersion
		or panelCache.fallbackFontPath ~= fallbackFontPath
		or panelCache.fallbackFontSize ~= fallbackFontSize
		or panelCache.fallbackFontStyle ~= fallbackFontStyle
		or panelCache.srcFont ~= srcFont
		or panelCache.srcSize ~= srcSize
		or panelCache.srcStyle ~= srcStyle
		or panelCache.srcColor ~= srcColor
		or panelCache.srcX ~= srcX
		or panelCache.srcY ~= srcY
	then
		panelCache = panelCache or {}
		panelCache.globalFontStateVersion = globalFontStateVersion
		panelCache.fallbackFontPath = fallbackFontPath
		panelCache.fallbackFontSize = fallbackFontSize
		panelCache.fallbackFontStyle = fallbackFontStyle
		panelCache.srcFont = srcFont
		panelCache.srcSize = srcSize
		panelCache.srcStyle = srcStyle
		panelCache.srcColor = srcColor
		panelCache.srcX = srcX
		panelCache.srcY = srcY
		panelCache.fontPath = Helper.ResolveFontPath(srcFont, fallbackFontPath)
		panelCache.fontSize = Helper.ClampInt(srcSize, 6, 64, fallbackFontSize or 12)
		panelCache.fontStyleChoice = Helper.NormalizeFontStyleChoice(srcStyle, fallbackFontStyle)
		panelCache.fontStyle = Helper.NormalizeFontStyle(panelCache.fontStyleChoice, fallbackFontStyle) or ""
		local r, g, b, a = Helper.ResolveColor(srcColor, Helper.PANEL_LAYOUT_DEFAULTS.cooldownTextColor)
		panelCache.fontColor = CooldownPanels.FillCachedColor(panelCache.fontColor, r, g, b, a)
		panelCache.fontX = Helper.ClampInt(srcX, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, 0)
		panelCache.fontY = Helper.ClampInt(srcY, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, 0)
		panelCache.version = (panelCache.version or 0) + 1
		CooldownPanels._styleCacheRoots.cooldownTextPanel[layout] = panelCache
	end
	if not entry or entry.cooldownTextUseGlobal ~= false then
		return panelCache.fontPath, panelCache.fontSize, panelCache.fontStyleChoice, panelCache.fontStyle, panelCache.fontColor, panelCache.fontX, panelCache.fontY
	end
	local cache = CooldownPanels._styleCacheRoots.cooldownTextEntry[entry]
	if
		not cache
		or cache.panelVersion ~= panelCache.version
		or cache.srcFont ~= entry.cooldownTextFont
		or cache.srcSize ~= entry.cooldownTextSize
		or cache.srcStyle ~= entry.cooldownTextStyle
		or cache.srcColor ~= entry.cooldownTextColor
		or cache.srcX ~= entry.cooldownTextX
		or cache.srcY ~= entry.cooldownTextY
	then
		cache = cache or {}
		cache.panelVersion = panelCache.version
		cache.srcFont = entry.cooldownTextFont
		cache.srcSize = entry.cooldownTextSize
		cache.srcStyle = entry.cooldownTextStyle
		cache.srcColor = entry.cooldownTextColor
		cache.srcX = entry.cooldownTextX
		cache.srcY = entry.cooldownTextY
		cache.fontPath = Helper.ResolveFontPath(entry.cooldownTextFont, panelCache.fontPath)
		cache.fontSize = Helper.ClampInt(entry.cooldownTextSize, 6, 64, panelCache.fontSize)
		cache.fontStyleChoice = Helper.NormalizeFontStyleChoice(entry.cooldownTextStyle, panelCache.fontStyleChoice)
		cache.fontStyle = Helper.NormalizeFontStyle(cache.fontStyleChoice, panelCache.fontStyle) or ""
		local r, g, b, a = Helper.ResolveColor(entry.cooldownTextColor, panelCache.fontColor)
		cache.fontColor = CooldownPanels.FillCachedColor(cache.fontColor, r, g, b, a)
		cache.fontX = Helper.ClampInt(entry.cooldownTextX, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, panelCache.fontX)
		cache.fontY = Helper.ClampInt(entry.cooldownTextY, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, panelCache.fontY)
		CooldownPanels._styleCacheRoots.cooldownTextEntry[entry] = cache
	end
	return cache.fontPath, cache.fontSize, cache.fontStyleChoice, cache.fontStyle, cache.fontColor, cache.fontX, cache.fontY
end

function CooldownPanels:ApplyCooldownTextFontStringStyle(icon, layout, entry, fontString, anchorFrame, defaultsOwner)
	if not (icon and fontString) then return end
	anchorFrame = anchorFrame or icon.cooldown or icon
	defaultsOwner = defaultsOwner or fontString
	if not defaultsOwner._eqolCooldownTextDefaults then
		local defaultsFontString = defaultsOwner.GetCountdownFontString and defaultsOwner:GetCountdownFontString() or fontString
		local fontPath, fontSize, fontStyle = defaultsFontString:GetFont()
		defaultsOwner._eqolCooldownTextDefaults = {
			font = fontPath,
			size = fontSize,
			style = fontStyle,
		}
	end
	local defaults = defaultsOwner._eqolCooldownTextDefaults
	local fontPath, fontSize, fontStyleChoice, fontStyle, fontColor, fontX, fontY =
		self:ResolveEntryCooldownTextStyle(layout, entry, defaults and defaults.font, defaults and defaults.size, defaults and defaults.style)
	if
		fontString._eqolCooldownFont ~= fontPath
		or fontString._eqolCooldownFontSize ~= fontSize
		or fontString._eqolCooldownFontStyle ~= fontStyle
		or fontString._eqolCooldownFontStyleChoice ~= fontStyleChoice
	then
		if Helper.SetFont then
			Helper.SetFont(fontString, fontPath, fontSize, fontStyle, defaults and defaults.font)
		else
			fontString:SetFont(fontPath, fontSize, fontStyle)
		end
		if addon.functions and addon.functions.ApplyFontStyleShadow then
			addon.functions.ApplyFontStyleShadow(fontString, fontStyleChoice, defaults and defaults.style)
		end
		fontString._eqolCooldownFont = fontPath
		fontString._eqolCooldownFontSize = fontSize
		fontString._eqolCooldownFontStyle = fontStyle
		fontString._eqolCooldownFontStyleChoice = fontStyleChoice
	end
	if
		fontString._eqolCooldownAnchor ~= "CENTER"
		or fontString._eqolCooldownAnchorFrame ~= anchorFrame
		or fontString._eqolCooldownX ~= fontX
		or fontString._eqolCooldownY ~= fontY
	then
		fontString:ClearAllPoints()
		fontString:SetPoint("CENTER", anchorFrame, "CENTER", fontX, fontY)
		fontString._eqolCooldownAnchor = "CENTER"
		fontString._eqolCooldownAnchorFrame = anchorFrame
		fontString._eqolCooldownX = fontX
		fontString._eqolCooldownY = fontY
	end
	local r = fontColor[1] or 1
	local g = fontColor[2] or 1
	local b = fontColor[3] or 1
	local a = fontColor[4] or 1
	if fontString._eqolCooldownColorR ~= r or fontString._eqolCooldownColorG ~= g or fontString._eqolCooldownColorB ~= b or fontString._eqolCooldownColorA ~= a then
		fontString:SetTextColor(r, g, b, a)
		fontString._eqolCooldownColorR = r
		fontString._eqolCooldownColorG = g
		fontString._eqolCooldownColorB = b
		fontString._eqolCooldownColorA = a
	end
end

function CooldownPanels:ApplyEntryCooldownTextStyle(icon, layout, entry)
	if not (icon and icon.cooldown and icon.cooldown.GetCountdownFontString) then return end
	local fontString = icon.cooldown:GetCountdownFontString()
	if not fontString then return end
	self:ApplyCooldownFrameDurationTextProfile(icon.cooldown, self:GetLayoutDurationTextProfile(layout))
	self:ApplyCooldownTextFontStringStyle(icon, layout, entry, fontString, icon.cooldown, icon.cooldown)
	if icon.cooldownText then self:ApplyCooldownTextFontStringStyle(icon, layout, entry, icon.cooldownText, icon.overlay, icon.cooldown) end
end

function CooldownPanels:ClearRuntimeCooldownTextBinding(icon)
	if not icon then return end
	if addon.functions and addon.functions.ReleaseDurationTextBinding then addon.functions.ReleaseDurationTextBinding(icon, "cooldownText", true) end
	if icon.cooldownText then
		icon.cooldownText:SetAlpha(1)
		icon.cooldownText:Hide()
	end
end

function CooldownPanels:ConfigureNumericCooldownTextDuration(icon, startTime, duration, rate)
	local durationUtil = _G.C_DurationUtil
	if not (icon and durationUtil and durationUtil.CreateDuration) then return nil end
	local durationObject = icon._eqolCooldownTextNumericDuration
	if not durationObject then
		durationObject = durationUtil.CreateDuration()
		icon._eqolCooldownTextNumericDuration = durationObject
	end
	if not (durationObject and durationObject.SetTimeFromStart) then return nil end
	durationObject:SetTimeFromStart(startTime, duration, rate or 1)
	return durationObject
end

function CooldownPanels:ApplyRuntimeCooldownTextBinding(icon, data, durationObject, cooldownTextIsGCD, forceHide)
	if not (icon and icon.cooldown) then return false end
	local showCooldownText = data and data.showCooldownText ~= false and forceHide ~= true
	if showCooldownText and cooldownTextIsGCD ~= true and durationObject and icon.cooldownText and addon.functions and addon.functions.BindDurationText then
		self:ApplyEntryCooldownTextStyle(icon, data.layout, data.entry)
		icon.cooldownText:SetAlpha(1)
		local binding = addon.functions.BindDurationText(icon.cooldownText, durationObject, {
			owner = icon,
			key = "cooldownText",
			clearText = true,
			profileKey = self:GetLayoutDurationTextProfile(data.layout),
		})
		if binding then
			icon.cooldown:SetHideCountdownNumbers(true)
			icon.cooldownText:Show()
			return true
		end
	end
	self:ClearRuntimeCooldownTextBinding(icon)
	icon.cooldown:SetHideCountdownNumbers(cooldownTextIsGCD == true or not showCooldownText)
	return false
end

function CooldownPanels:ApplyRuntimeCooldownDurationTextProfile(icon, layout)
	if not (icon and icon.cooldown) then return false end
	return self:ApplyCooldownFrameDurationTextProfile(icon.cooldown, self:GetLayoutDurationTextProfile(layout))
end

function CooldownPanels:ResolveEntryStackTextStyle(layout, entry, fallbackFontPath, fallbackFontSize, fallbackFontStyle)
	local panelCache = CooldownPanels._styleCacheRoots.stackTextPanel[layout]
	local globalFontStateVersion = addon.functions and addon.functions.GetGlobalFontStateVersion and addon.functions.GetGlobalFontStateVersion() or 0
	local srcFont = layout and layout.stackFont or nil
	local srcSize = layout and layout.stackFontSize or nil
	local srcStyle = layout and layout.stackFontStyle or nil
	local srcColor = layout and layout.stackColor or nil
	local srcAnchor = layout and layout.stackAnchor or nil
	local srcX = layout and layout.stackX or nil
	local srcY = layout and layout.stackY or nil
	if
		not panelCache
		or panelCache.globalFontStateVersion ~= globalFontStateVersion
		or panelCache.fallbackFontPath ~= fallbackFontPath
		or panelCache.fallbackFontSize ~= fallbackFontSize
		or panelCache.fallbackFontStyle ~= fallbackFontStyle
		or panelCache.srcFont ~= srcFont
		or panelCache.srcSize ~= srcSize
		or panelCache.srcStyle ~= srcStyle
		or panelCache.srcColor ~= srcColor
		or panelCache.srcAnchor ~= srcAnchor
		or panelCache.srcX ~= srcX
		or panelCache.srcY ~= srcY
	then
		panelCache = panelCache or {}
		panelCache.globalFontStateVersion = globalFontStateVersion
		panelCache.fallbackFontPath = fallbackFontPath
		panelCache.fallbackFontSize = fallbackFontSize
		panelCache.fallbackFontStyle = fallbackFontStyle
		panelCache.srcFont = srcFont
		panelCache.srcSize = srcSize
		panelCache.srcStyle = srcStyle
		panelCache.srcColor = srcColor
		panelCache.srcAnchor = srcAnchor
		panelCache.srcX = srcX
		panelCache.srcY = srcY
		panelCache.fontPath = Helper.ResolveFontPath(srcFont, fallbackFontPath)
		panelCache.fontSize = Helper.ClampInt(srcSize, 6, 64, fallbackFontSize or 12)
		panelCache.fontStyleChoice = Helper.NormalizeFontStyleChoice(srcStyle, fallbackFontStyle)
		panelCache.fontStyle = Helper.NormalizeFontStyle(panelCache.fontStyleChoice, fallbackFontStyle) or ""
		local r, g, b, a = Helper.ResolveColor(srcColor, Helper.PANEL_LAYOUT_DEFAULTS.stackColor or { 1, 1, 1, 1 })
		panelCache.fontColor = CooldownPanels.FillCachedColor(panelCache.fontColor, r, g, b, a)
		panelCache.anchor = Helper.NormalizeAnchor(srcAnchor, Helper.PANEL_LAYOUT_DEFAULTS.stackAnchor or "BOTTOMRIGHT")
		panelCache.x = Helper.ClampInt(srcX, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, Helper.PANEL_LAYOUT_DEFAULTS.stackX or 0)
		panelCache.y = Helper.ClampInt(srcY, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, Helper.PANEL_LAYOUT_DEFAULTS.stackY or 0)
		panelCache.version = (panelCache.version or 0) + 1
		CooldownPanels._styleCacheRoots.stackTextPanel[layout] = panelCache
	end
	if not entry or entry.stackStyleUseGlobal ~= false then
		return panelCache.fontPath, panelCache.fontSize, panelCache.fontStyleChoice, panelCache.fontStyle, panelCache.fontColor, panelCache.anchor, panelCache.x, panelCache.y
	end
	local cache = CooldownPanels._styleCacheRoots.stackTextEntry[entry]
	if
		not cache
		or cache.panelVersion ~= panelCache.version
		or cache.srcFont ~= entry.stackFont
		or cache.srcSize ~= entry.stackFontSize
		or cache.srcStyle ~= entry.stackFontStyle
		or cache.srcColor ~= entry.stackColor
		or cache.srcAnchor ~= entry.stackAnchor
		or cache.srcX ~= entry.stackX
		or cache.srcY ~= entry.stackY
	then
		cache = cache or {}
		cache.panelVersion = panelCache.version
		cache.srcFont = entry.stackFont
		cache.srcSize = entry.stackFontSize
		cache.srcStyle = entry.stackFontStyle
		cache.srcColor = entry.stackColor
		cache.srcAnchor = entry.stackAnchor
		cache.srcX = entry.stackX
		cache.srcY = entry.stackY
		cache.fontPath = Helper.ResolveFontPath(entry.stackFont, panelCache.fontPath)
		cache.fontSize = Helper.ClampInt(entry.stackFontSize, 6, 64, panelCache.fontSize)
		cache.fontStyleChoice = Helper.NormalizeFontStyleChoice(entry.stackFontStyle, panelCache.fontStyleChoice)
		cache.fontStyle = Helper.NormalizeFontStyle(cache.fontStyleChoice, panelCache.fontStyle) or ""
		local r, g, b, a = Helper.ResolveColor(entry.stackColor, panelCache.fontColor)
		cache.fontColor = CooldownPanels.FillCachedColor(cache.fontColor, r, g, b, a)
		cache.anchor = Helper.NormalizeAnchor(entry.stackAnchor, panelCache.anchor)
		cache.x = Helper.ClampInt(entry.stackX, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, panelCache.x)
		cache.y = Helper.ClampInt(entry.stackY, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, panelCache.y)
		CooldownPanels._styleCacheRoots.stackTextEntry[entry] = cache
	end
	return cache.fontPath, cache.fontSize, cache.fontStyleChoice, cache.fontStyle, cache.fontColor, cache.anchor, cache.x, cache.y
end

function CooldownPanels:ApplyEntryStackTextStyle(icon, layout, entry, fallbackFontPath, fallbackFontSize, fallbackFontStyle)
	if not (icon and icon.count) then return end
	local fontPath, fontSize, fontStyleChoice, fontStyle, fontColor, anchor, x, y =
		self:ResolveEntryStackTextStyle(layout, entry, fallbackFontPath, fallbackFontSize, fallbackFontStyle)
	if icon.count._eqolStackAnchor ~= anchor or icon.count._eqolStackX ~= x or icon.count._eqolStackY ~= y then
		icon.count:ClearAllPoints()
		icon.count:SetPoint(anchor, icon, anchor, x, y)
		icon.count._eqolStackAnchor = anchor
		icon.count._eqolStackX = x
		icon.count._eqolStackY = y
	end
	if
		icon.count._eqolStackFont ~= fontPath
		or icon.count._eqolStackFontSize ~= fontSize
		or icon.count._eqolStackFontStyle ~= fontStyle
		or icon.count._eqolStackFontStyleChoice ~= fontStyleChoice
	then
		if Helper.SetFont then
			Helper.SetFont(icon.count, fontPath, fontSize, fontStyle, fallbackFontPath)
		else
			icon.count:SetFont(fontPath, fontSize, fontStyle)
		end
		if addon.functions and addon.functions.ApplyFontStyleShadow then addon.functions.ApplyFontStyleShadow(icon.count, fontStyleChoice, fallbackFontStyle) end
		icon.count._eqolStackFont = fontPath
		icon.count._eqolStackFontSize = fontSize
		icon.count._eqolStackFontStyle = fontStyle
		icon.count._eqolStackFontStyleChoice = fontStyleChoice
	end
	local r = fontColor[1] or 1
	local g = fontColor[2] or 1
	local b = fontColor[3] or 1
	local a = fontColor[4] or 1
	if icon.count._eqolStackColorR ~= r or icon.count._eqolStackColorG ~= g or icon.count._eqolStackColorB ~= b or icon.count._eqolStackColorA ~= a then
		icon.count:SetTextColor(r, g, b, a)
		icon.count._eqolStackColorR = r
		icon.count._eqolStackColorG = g
		icon.count._eqolStackColorB = b
		icon.count._eqolStackColorA = a
	end
end

