		panelCache.readyInset = panelReadyInset
		panelCache.style = cdp.ENTRY.NormalizeGlowStyleForIconShape(srcStyle, panelReadyStyle, srcShape)
		panelCache.inset = Helper.NormalizeGlowInset(srcInset, panelReadyInset)
		panelCache.version = (panelCache.version or 0) + 1
		CooldownPanels._styleCacheRoots.procGlowPanel[layout] = panelCache
	end
	if not entry or entry.procGlowUseGlobal ~= false then
		return cdp.ENTRY.NormalizeGlowStyleForEntryDisplayMode(panelCache.style, entry), panelCache.inset
	end
	local cache = CooldownPanels._styleCacheRoots.procGlowEntry[entry]
	if not cache or cache.panelVersion ~= panelCache.version or cache.srcStyle ~= entry.procGlowStyle or cache.srcInset ~= entry.procGlowInset then
		cache = cache or {}
		cache.panelVersion = panelCache.version
		cache.srcStyle = entry.procGlowStyle
		cache.srcInset = entry.procGlowInset
		cache.style = cdp.ENTRY.NormalizeGlowStyleForIconShape(entry.procGlowStyle, panelCache.style, srcShape)
		cache.inset = Helper.NormalizeGlowInset(entry.procGlowInset, panelCache.inset)
		CooldownPanels._styleCacheRoots.procGlowEntry[entry] = cache
	end
	return cdp.ENTRY.NormalizeGlowStyleForEntryDisplayMode(cache.style, entry), cache.inset
end

function CooldownPanels:ResolveEntryProcGlowEnabled(layout, entry)
	local panelValue = not (layout and layout.procGlowEnabled == false)
	if not entry or entry.procGlowUseGlobal ~= false then return panelValue end
	return entry.procGlowEnabled ~= false
end

function CooldownPanels:ResolveGlowPixelOptions(layout, entry)
	layout = layout or Helper.PANEL_LAYOUT_DEFAULTS
	local cache = CooldownPanels._styleCacheRoots.glowPixelOptions[layout]
	local srcBorder = layout and layout.glowPixelBorder or nil
	local srcCount = layout and layout.glowPixelCount or nil
	local srcSpeed = layout and layout.glowPixelSpeed or nil
	local srcThickness = layout and layout.glowPixelThickness or nil
	if not cache or cache.srcBorder ~= srcBorder or cache.srcCount ~= srcCount or cache.srcSpeed ~= srcSpeed or cache.srcThickness ~= srcThickness then
		cache = cache or {}
		cache.srcBorder = srcBorder
		cache.srcCount = srcCount
		cache.srcSpeed = srcSpeed
		cache.srcThickness = srcThickness
		cache.border = srcBorder == true
		cache.count = Helper.NormalizeGlowPixelCount(srcCount, Helper.PANEL_LAYOUT_DEFAULTS.glowPixelCount or 8)
		cache.frequency = Helper.NormalizeGlowPixelSpeed(srcSpeed, Helper.PANEL_LAYOUT_DEFAULTS.glowPixelSpeed or 0.25)
		cache.thickness = Helper.NormalizeGlowPixelThickness(srcThickness, Helper.PANEL_LAYOUT_DEFAULTS.glowPixelThickness or 2)
		CooldownPanels._styleCacheRoots.glowPixelOptions[layout] = cache
	end
	if not entry or not (entry.glowUseGlobal == false or entry.procGlowUseGlobal == false) then return cache end
	local entryCache = CooldownPanels._styleCacheRoots.glowPixelEntry[entry]
	if
		not entryCache
		or entryCache.panelCache ~= cache
		or entryCache.srcBorder ~= entry.glowPixelBorder
		or entryCache.srcCount ~= entry.glowPixelCount
		or entryCache.srcSpeed ~= entry.glowPixelSpeed
		or entryCache.srcThickness ~= entry.glowPixelThickness
	then
		entryCache = entryCache or {}
		entryCache.panelCache = cache
		entryCache.srcBorder = entry.glowPixelBorder
		entryCache.srcCount = entry.glowPixelCount
		entryCache.srcSpeed = entry.glowPixelSpeed
		entryCache.srcThickness = entry.glowPixelThickness
		entryCache.border = type(entry.glowPixelBorder) == "boolean" and entry.glowPixelBorder == true or cache.border == true
		entryCache.count = Helper.NormalizeGlowPixelCount(entry.glowPixelCount, cache.count)
		entryCache.frequency = Helper.NormalizeGlowPixelSpeed(entry.glowPixelSpeed, cache.frequency)
		entryCache.thickness = Helper.NormalizeGlowPixelThickness(entry.glowPixelThickness, cache.thickness)
		CooldownPanels._styleCacheRoots.glowPixelEntry[entry] = entryCache
	end
	return entryCache
end

function CooldownPanels:SetEntryGlowPixelOption(entry, layout, field, value)
	if not entry then return false end
	local panelOptions = self:ResolveGlowPixelOptions(layout, nil)
	local currentValue = entry[field]
	local nextValue
	if field == "glowPixelBorder" then
		local normalized = value == true
		nextValue = normalized == (panelOptions and panelOptions.border == true) and nil or normalized
	elseif field == "glowPixelCount" then
		local fallback = panelOptions and panelOptions.count or Helper.PANEL_LAYOUT_DEFAULTS.glowPixelCount or 8
		local normalized = Helper.NormalizeGlowPixelCount(value, fallback)
		nextValue = normalized == fallback and nil or normalized
	elseif field == "glowPixelSpeed" then
		local fallback = panelOptions and panelOptions.frequency or Helper.PANEL_LAYOUT_DEFAULTS.glowPixelSpeed or 0.25
		local normalized = Helper.NormalizeGlowPixelSpeed(value, fallback)
		nextValue = normalized == fallback and nil or normalized
	elseif field == "glowPixelThickness" then
		local fallback = panelOptions and panelOptions.thickness or Helper.PANEL_LAYOUT_DEFAULTS.glowPixelThickness or 2
		local normalized = Helper.NormalizeGlowPixelThickness(value, fallback)
		nextValue = normalized == fallback and nil or normalized
	else
		return false
	end
	if currentValue == nextValue then return false end
	entry[field] = nextValue
	return true
end

function CooldownPanels:ClearEntryStateTexture(entry)
	if type(entry) ~= "table" then return end
	entry.stateTextureInput = ""
	entry.stateTextureType = nil
	entry.stateTextureAtlas = nil
	entry.stateTextureFileID = nil
end

function CooldownPanels:ApplyEntryStateTextureInput(entry, value)
	if type(entry) ~= "table" then return false, nil end
	local input = Helper.NormalizeTextureInput(value)
	if input == "" then
		self:ClearEntryStateTexture(entry)
		return true, nil
	end

	local resolvedType, resolvedValue = Helper.ResolveTextureInput(input)
	if not resolvedType then return false, string.format(L["CooldownPanelStateTextureInvalid"] or "Texture '%s' was not found. Use a valid atlas name or FileDataID.", input) end

	local wasConfigured = self:HasConfiguredStateTexture(entry)
	entry.stateTextureInput = input
	entry.stateTextureType = resolvedType
	if resolvedType == "ATLAS" then
		entry.stateTextureAtlas = resolvedValue
		entry.stateTextureFileID = nil
	else
		entry.stateTextureFileID = resolvedValue
		entry.stateTextureAtlas = nil
	end
	if not wasConfigured then
		entry.stateTextureScale = 6
		entry.stateTextureHeight = 1.4
	end
	return true, nil
end

function CooldownPanels:ResolveEntryStateTexture(entry)
	if type(entry) ~= "table" then return nil end
	local input = Helper.NormalizeTextureInput(entry.stateTextureInput)
	if input == "" then return nil end

	local textureType = type(entry.stateTextureType) == "string" and strupper(entry.stateTextureType) or nil
	local textureValue
	if textureType == "ATLAS" and type(entry.stateTextureAtlas) == "string" and entry.stateTextureAtlas ~= "" then
		textureValue = entry.stateTextureAtlas
	elseif textureType == "FILEID" then
		local fileID = tonumber(entry.stateTextureFileID)
		if fileID and fileID > 0 then textureValue = fileID end
	end

	if not textureValue then
		local resolvedType, resolvedValue = Helper.ResolveTextureInput(input)
		if not resolvedType then
			self:ClearEntryStateTexture(entry)
			return nil
		end
		textureType = resolvedType
		textureValue = resolvedValue
		entry.stateTextureInput = input
		entry.stateTextureType = resolvedType
		if resolvedType == "ATLAS" then
			entry.stateTextureAtlas = resolvedValue
			entry.stateTextureFileID = nil
		else
			entry.stateTextureFileID = resolvedValue
			entry.stateTextureAtlas = nil
		end
	end
	local scale = Helper.ClampNumber(entry.stateTextureScale, 0.1, 8, 1)
	local width = Helper.ClampNumber(entry.stateTextureWidth, 0.1, 8, 1)
	local height = Helper.ClampNumber(entry.stateTextureHeight, 0.1, 8, 1)
	local angle = Helper.ClampNumber(entry.stateTextureAngle, 0, 360, 0)
	local doubleTexture = entry.stateTextureDouble == true
	local mirror = entry.stateTextureMirror == true
	local mirrorSecond = entry.stateTextureMirrorSecond == true
	local mirrorVertical = entry.stateTextureMirrorVertical == true
	local mirrorVerticalSecond = entry.stateTextureMirrorVerticalSecond == true
	local spacingX = Helper.ClampInt(entry.stateTextureSpacingX, 0, Helper.STATE_TEXTURE_SPACING_RANGE or 2000, 0)
	local spacingY = Helper.ClampInt(entry.stateTextureSpacingY, 0, Helper.STATE_TEXTURE_SPACING_RANGE or 2000, 0)
	return textureType, textureValue, width, height, scale, angle, doubleTexture, mirror, mirrorSecond, mirrorVertical, mirrorVerticalSecond, spacingX, spacingY
end

function CooldownPanels:HasConfiguredStateTexture(entry)
	if type(entry) ~= "table" then return false end
	local input = Helper.NormalizeTextureInput(entry.stateTextureInput)
	if input == "" then return false end
	local textureType = type(entry.stateTextureType) == "string" and strupper(entry.stateTextureType) or nil
	if textureType == "ATLAS" then return type(entry.stateTextureAtlas) == "string" and entry.stateTextureAtlas ~= "" end
	if textureType == "FILEID" then
		local fileID = tonumber(entry.stateTextureFileID)
		return fileID ~= nil and fileID > 0
	end
	local resolvedType = self:ResolveEntryStateTexture(entry)
	return resolvedType ~= nil
end

function CooldownPanels:ResolveEntryNoDesaturation(layout, entry)
	local panelValue = layout and layout.noDesaturation == true
	if not entry or entry.noDesaturationUseGlobal ~= false then return panelValue end
	return entry.noDesaturation == true
end

function CooldownPanels:ResolveEntryCooldownVisibility(layout, entry)
	local hideOnCooldown = layout and layout.hideOnCooldown == true
	local showOnCooldown = layout and layout.showOnCooldown == true
	if showOnCooldown then hideOnCooldown = false end
	if not entry or entry.cooldownVisibilityUseGlobal ~= false then return hideOnCooldown, showOnCooldown end
	hideOnCooldown = entry.hideOnCooldown == true
	showOnCooldown = entry.showOnCooldown == true
	if showOnCooldown then hideOnCooldown = false end
	return hideOnCooldown, showOnCooldown
end

function CooldownPanels:ResolveEntryCDMAuraAlwaysShowMode(layout, entry)
	local values = self.CDM_AURA_ALWAYS_SHOW_MODE or {}
	local panelValue = self:NormalizeCDMAuraAlwaysShowMode(layout and layout.cdmAuraAlwaysShowMode, Helper.PANEL_LAYOUT_DEFAULTS.cdmAuraAlwaysShowMode or values.HIDE or "HIDE")
	if not entry or entry.type ~= "CDM_AURA" or entry.cdmAuraAlwaysShowUseGlobal ~= false then return panelValue end
	return self:NormalizeCDMAuraAlwaysShowMode(entry.cdmAuraAlwaysShowMode, panelValue)
end

function CooldownPanels:ResolveEntryCheckPower(layout, entry)
	local panelValue = layout and layout.checkPower == true
	if not entry or entry.checkPowerUseGlobal ~= false then return panelValue end
	return entry.checkPower == true
end

function CooldownPanels:ResolveEntryHideWhenNoResource(layout, entry)
	local panelValue = layout and layout.hideWhenNoResource == true
	if not entry then return panelValue end
	local entryType = entry.type
	if entryType == "MACRO" then
		local macro = CooldownPanels.ResolveMacroEntry(entry)
		entryType = (macro and macro.kind) or entryType
	end
	if entryType ~= "SPELL" then return false end
	if entry.hideWhenNoResourceUseGlobal ~= false then return panelValue end
	return entry.hideWhenNoResource == true
end

function CooldownPanels:ResolveEntryShowIconTexture(layout, entry)
	local panelValue = not (layout and layout.showIconTexture == false)
	if not entry then return panelValue end
	if self:HasConfiguredStateTexture(entry) then return false end
	if entry.hideIcon == true then return false end
	if entry.showIconTextureUseGlobal == false then return true end
	return panelValue
end

function CooldownPanels:ShouldShowEditorGhostIcon(layout, entry, showIconTexture, editorContext)
	if editorContext ~= true or not entry then return false end
	if showIconTexture == false then return true end
	return Helper.ClampInt(layout and layout.iconOffsetX, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, 0) ~= 0
		or Helper.ClampInt(layout and layout.iconOffsetY, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, 0) ~= 0
		or Helper.ClampInt(entry.iconOffsetX, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, 0) ~= 0
		or Helper.ClampInt(entry.iconOffsetY, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, 0) ~= 0
end

function CooldownPanels:ResolveEntryCooldownVisuals(layout, entry)
	local panelShowChargesCooldown = layout and layout.showChargesCooldown == true
	local panelHideChargeCooldownText = layout and layout.hideChargeCooldownText == true
	local panelDrawEdge = not (layout and layout.cooldownDrawEdge == false)
	local panelDrawBling = not (layout and layout.cooldownDrawBling == false)
	local panelDrawSwipe = not (layout and layout.cooldownDrawSwipe == false)
	local panelGcdDrawEdge = layout and layout.cooldownGcdDrawEdge == true
	local panelGcdDrawBling = layout and layout.cooldownGcdDrawBling == true
	local panelGcdDrawSwipe = layout and layout.cooldownGcdDrawSwipe == true
	if not entry or entry.cooldownVisualsUseGlobal ~= false then
		return panelShowChargesCooldown, panelDrawEdge, panelDrawBling, panelDrawSwipe, panelGcdDrawEdge, panelGcdDrawBling, panelGcdDrawSwipe, panelHideChargeCooldownText
	end
	return entry.showChargesCooldown == true,
		entry.cooldownDrawEdge == true,
		entry.cooldownDrawBling == true,
		entry.cooldownDrawSwipe == true,
		entry.cooldownGcdDrawEdge == true,
		entry.cooldownGcdDrawBling == true,
		entry.cooldownGcdDrawSwipe == true,
		entry.hideChargeCooldownText == true
end

function CooldownPanels:IsDefaultCooldownSwipeColor(color, alreadyNormalized)
	local defaultColor = Helper.PANEL_LAYOUT_DEFAULTS.cooldownSwipeColor or { 0, 0, 0, 0.8 }
	if alreadyNormalized ~= true then color = Helper.NormalizeColor(color, defaultColor) end
	return color[1] == defaultColor[1] and color[2] == defaultColor[2] and color[3] == defaultColor[3] and color[4] == defaultColor[4]
end

function CooldownPanels:GetResolvedCooldownSwipeColor(layout, entry)
	local defaultColor = Helper.PANEL_LAYOUT_DEFAULTS.cooldownSwipeColor or { 0, 0, 0, 0.8 }
	local color
	if entry and entry.cooldownVisualsUseGlobal == false then
		color = Helper.NormalizeColor(entry.cooldownSwipeColor, Helper.ENTRY_DEFAULTS.cooldownSwipeColor or defaultColor)
	else
		color = Helper.NormalizeColor(layout and layout.cooldownSwipeColor, defaultColor)
	end
	return color
end

function CooldownPanels:GetCustomCooldownSwipeColor(layout, entry)
	local color = self:GetResolvedCooldownSwipeColor(layout, entry)
	if self:IsDefaultCooldownSwipeColor(color, true) then return nil end
	return color
end

function CooldownPanels:ShouldIgnoreEntryCooldownGCD(layout, entry)
	local _, _, _, _, gcdDrawEdge, gcdDrawBling, gcdDrawSwipe = self:ResolveEntryCooldownVisuals(layout, entry)
	return gcdDrawEdge ~= true and gcdDrawBling ~= true and gcdDrawSwipe ~= true
end

function CooldownPanels:ResolveEntryIconVisualLayout(layout, entry, baseSize)
	if type(entry) == "number" and baseSize == nil and type(layout) == "table" and layout.id ~= nil and layout.type ~= nil then
		baseSize = entry
		entry = layout
		layout = nil
	end
	local fallbackSize = Helper.ClampInt(baseSize, 12, 128, Helper.PANEL_LAYOUT_DEFAULTS.iconSize)
	local layoutBaseSize = Helper.ClampInt(layout and layout.iconSize, 12, 128, Helper.PANEL_LAYOUT_DEFAULTS.iconSize)
	local rowScale = layoutBaseSize > 0 and (fallbackSize / layoutBaseSize) or 1
	local fallbackWidth = layout and layout.iconSizeSeparate == true and Helper.ClampInt((tonumber(layout.iconWidth) or layoutBaseSize) * rowScale, 12, 128, fallbackSize) or fallbackSize
	local fallbackHeight = layout and layout.iconSizeSeparate == true and Helper.ClampInt((tonumber(layout.iconHeight) or layoutBaseSize) * rowScale, 12, 128, fallbackSize) or fallbackSize
	local layoutOffsetX = Helper.ClampInt(layout and layout.iconOffsetX, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, 0)
	local layoutOffsetY = Helper.ClampInt(layout and layout.iconOffsetY, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, 0)
	if not entry then return fallbackSize, layoutOffsetX, layoutOffsetY, fallbackWidth, fallbackHeight end
	local cache = CooldownPanels._styleCacheRoots.iconLayoutEntry[entry]
	if
		not cache
		or cache.baseSize ~= fallbackSize
		or cache.baseWidth ~= fallbackWidth
		or cache.baseHeight ~= fallbackHeight
		or cache.layoutOffsetX ~= layoutOffsetX
		or cache.layoutOffsetY ~= layoutOffsetY
		or cache.iconSizeUseGlobal ~= entry.iconSizeUseGlobal
		or cache.iconSize ~= entry.iconSize
		or cache.iconSizeSeparate ~= entry.iconSizeSeparate
		or cache.iconWidth ~= entry.iconWidth
		or cache.iconHeight ~= entry.iconHeight
		or cache.iconOffsetX ~= entry.iconOffsetX
		or cache.iconOffsetY ~= entry.iconOffsetY
	then
		cache = cache or {}
		cache.baseSize = fallbackSize
		cache.baseWidth = fallbackWidth
		cache.baseHeight = fallbackHeight
		cache.layoutOffsetX = layoutOffsetX
		cache.layoutOffsetY = layoutOffsetY
		cache.iconSizeUseGlobal = entry.iconSizeUseGlobal
		cache.iconSize = entry.iconSize
		cache.iconSizeSeparate = entry.iconSizeSeparate
		cache.iconWidth = entry.iconWidth
		cache.iconHeight = entry.iconHeight
		cache.iconOffsetX = entry.iconOffsetX
		cache.iconOffsetY = entry.iconOffsetY
		if entry.iconSizeUseGlobal == false and entry.iconSizeSeparate == true then
			cache.width = Helper.ClampInt(entry.iconWidth, 12, 128, fallbackWidth)
			cache.height = Helper.ClampInt(entry.iconHeight, 12, 128, fallbackHeight)
			cache.size = math.max(cache.width, cache.height)
		else
			cache.size = entry.iconSizeUseGlobal == false and Helper.ClampInt(entry.iconSize, 12, 128, fallbackSize) or fallbackSize
			cache.width = entry.iconSizeUseGlobal == false and cache.size or fallbackWidth
			cache.height = entry.iconSizeUseGlobal == false and cache.size or fallbackHeight
		end
		cache.offsetX = layoutOffsetX + Helper.ClampInt(entry.iconOffsetX, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, 0)
		cache.offsetY = layoutOffsetY + Helper.ClampInt(entry.iconOffsetY, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, 0)
		CooldownPanels._styleCacheRoots.iconLayoutEntry[entry] = cache
	end
	return cache.size, cache.offsetX, cache.offsetY, cache.width, cache.height
end

CooldownPanels._eqolFixedVisualCacheUtil = CooldownPanels._eqolFixedVisualCacheUtil or {}

function CooldownPanels._eqolFixedVisualCacheUtil.ClearSparseTable(tbl)
	if type(tbl) ~= "table" then return end
	for key in pairs(tbl) do
		tbl[key] = nil
	end
end

function CooldownPanels._eqolFixedVisualCacheUtil.GetSharedLayoutCache(fixedLayoutCache)
	if type(fixedLayoutCache) ~= "table" then return nil end
	local layouts = cdp.FIXED_VISUAL and cdp.FIXED_VISUAL.LAYOUTS or nil
	if type(layouts) ~= "table" then return nil end
	local shared = layouts[fixedLayoutCache]
	if type(shared) ~= "table" then
		shared = {
			orderedCellsByGroupId = {},
			dynamicPlacementsByGroupId = {},
			groupStateById = {},
		}
		layouts[fixedLayoutCache] = shared
	end
	return shared
end

function CooldownPanels._eqolFixedVisualCacheUtil.SyncSharedGroupState(shared, group)
	if type(shared) ~= "table" or type(group) ~= "table" then return nil end
	local groupId = type(group.id) == "string" and group.id or tostring(group.id or "")
	local state = shared.groupStateById and shared.groupStateById[groupId] or nil
	if type(state) ~= "table" then
		state = {}
		shared.groupStateById[groupId] = state
	end
	local mode = group.mode
	local columns = group.columns
	local rows = group.rows
	local column = group.column
	local row = group.row
	local startPoint = group.dynamicStartPoint
	local direction = group.dynamicDirection
	if
		state.groupRef ~= group
		or state.mode ~= mode
		or state.columns ~= columns
		or state.rows ~= rows
		or state.column ~= column
		or state.row ~= row
		or state.startPoint ~= startPoint
		or state.direction ~= direction
	then
		shared.orderedCellsByGroupId[groupId] = nil
		shared.dynamicPlacementsByGroupId[groupId] = nil
		state.groupRef = group
		state.mode = mode
		state.columns = columns
		state.rows = rows
		state.column = column
		state.row = row
		state.startPoint = startPoint
		state.direction = direction
	end
	return groupId
end

function CooldownPanels._eqolFixedVisualCacheUtil.Prepare(frame, panel, fixedGridColumns, fixedLayoutCache)
	if not frame then return nil end
	local cache = frame._eqolFixedVisualCache
	if type(cache) ~= "table" then
		cache = {}
		frame._eqolFixedVisualCache = cache
	end
	local sharedLayoutCache = CooldownPanels._eqolFixedVisualCacheUtil.GetSharedLayoutCache(fixedLayoutCache)
	cache.panel = panel
	cache.fixedGridColumns = fixedGridColumns
	cache.fixedLayoutCacheRef = fixedLayoutCache
	cache.sharedLayoutCache = sharedLayoutCache
	cache.slotCenterX = cache.slotCenterX or {}
	cache.slotCenterY = cache.slotCenterY or {}
	cache.slotCenterMissing = cache.slotCenterMissing or {}
	cache.orderedCellsByGroupId = cache.orderedCellsByGroupId or {}
	cache.dynamicPlacementsByGroupId = cache.dynamicPlacementsByGroupId or {}
	CooldownPanels._eqolFixedVisualCacheUtil.ClearSparseTable(cache.slotCenterX)
	CooldownPanels._eqolFixedVisualCacheUtil.ClearSparseTable(cache.slotCenterY)
	CooldownPanels._eqolFixedVisualCacheUtil.ClearSparseTable(cache.slotCenterMissing)
	if not sharedLayoutCache then
		CooldownPanels._eqolFixedVisualCacheUtil.ClearSparseTable(cache.orderedCellsByGroupId)
		CooldownPanels._eqolFixedVisualCacheUtil.ClearSparseTable(cache.dynamicPlacementsByGroupId)
	end
	return cache
end

function CooldownPanels._eqolFixedVisualCacheUtil.GetSlotCenter(cache, icons, fixedGridColumns, column, row)
	column = Helper.NormalizeSlotCoordinate(column)
	row = Helper.NormalizeSlotCoordinate(row)
	if not (icons and fixedGridColumns > 0 and column and row) then return nil, nil end
	local index = ((row - 1) * fixedGridColumns) + column

	if cache and cache.slotCenterX and cache.slotCenterY and cache.slotCenterMissing then
		if cache.slotCenterMissing[index] then return nil, nil end
		local cachedX = cache.slotCenterX[index]
		local cachedY = cache.slotCenterY[index]
		if cachedX ~= nil and cachedY ~= nil then return cachedX, cachedY end
		local icon = icons[index]
		local slot = icon and (icon.slotAnchor or icon) or nil
		if not (slot and slot.GetCenter) then
			cache.slotCenterMissing[index] = true
			return nil, nil
		end
		local x, y = slot:GetCenter()
		if not (x and y) then
			cache.slotCenterMissing[index] = true
			return nil, nil
		end
		cache.slotCenterX[index] = x
		cache.slotCenterY[index] = y
		return x, y
	end

	local icon = icons[index]
	local slot = icon and (icon.slotAnchor or icon) or nil
	if not (slot and slot.GetCenter) then return nil, nil end
	local x, y = slot:GetCenter()
	if not (x and y) then return nil, nil end
	return x, y
end

function CooldownPanels._eqolFixedVisualCacheUtil.GetOrderedCells(cache, group)
	if type(group) ~= "table" then return nil end
	local store = nil
	local key = nil
	if cache and cache.sharedLayoutCache then
		key = CooldownPanels._eqolFixedVisualCacheUtil.SyncSharedGroupState(cache.sharedLayoutCache, group)
		store = cache.sharedLayoutCache.orderedCellsByGroupId
	elseif cache and cache.orderedCellsByGroupId then
		key = type(group.id) == "string" and group.id or tostring(group.id or "")
		store = cache.orderedCellsByGroupId
	end
	if not store then return Helper.GetFixedGroupOrderedCells and Helper.GetFixedGroupOrderedCells(group) or nil end
	local cached = store[key]
	if cached ~= nil then
		if cached == false then return nil end
		return cached
	end
	cached = Helper.GetFixedGroupOrderedCells and Helper.GetFixedGroupOrderedCells(group) or nil
	store[key] = cached or false
	return cached
end

function CooldownPanels._eqolFixedVisualCacheUtil.GetDynamicPlacement(cache, group, index, count)
	if type(group) ~= "table" then return nil end
	local placementsByGroupId = nil
	local groupKey = nil
	if cache and cache.sharedLayoutCache then
		groupKey = CooldownPanels._eqolFixedVisualCacheUtil.SyncSharedGroupState(cache.sharedLayoutCache, group)
		placementsByGroupId = cache.sharedLayoutCache.dynamicPlacementsByGroupId
	elseif cache and cache.dynamicPlacementsByGroupId then
		groupKey = type(group.id) == "string" and group.id or tostring(group.id or "")
		placementsByGroupId = cache.dynamicPlacementsByGroupId
	end
	if not placementsByGroupId then return Helper.GetFixedGroupDynamicPlacement and Helper.GetFixedGroupDynamicPlacement(group, index, count) or nil end
	local groupCache = placementsByGroupId[groupKey]
	if type(groupCache) ~= "table" then
		groupCache = {}
		placementsByGroupId[groupKey] = groupCache
	end
	local countKey = tostring(count or 0)
	local countCache = groupCache[countKey]
	if type(countCache) ~= "table" then
		countCache = {}
		groupCache[countKey] = countCache
	end
	local cached = countCache[index]
	if cached ~= nil then
		if cached == false then return nil end
		return cached
	end
	cached = Helper.GetFixedGroupDynamicPlacement and Helper.GetFixedGroupDynamicPlacement(group, index, count) or nil
	countCache[index] = cached or false
	return cached
end

function CooldownPanels:ResolveFixedGroupSlotSpacingOffset(panel, frame, entry, layout, fixedGridColumns, slotColumn, slotRow, visualSize, fixedContext, fixedLayoutCache)
	if not (panel and frame and entry and layout) then return 0, 0 end
	if not fixedLayoutCache and not Helper.IsFixedLayout(panel.layout) then return 0, 0 end
	fixedGridColumns = Helper.NormalizeFixedGridSize(fixedGridColumns, 0)
	slotColumn = Helper.NormalizeSlotCoordinate(slotColumn)
	slotRow = Helper.NormalizeSlotCoordinate(slotRow)
	visualSize = Helper.ClampInt(visualSize, 12, 128, Helper.PANEL_LAYOUT_DEFAULTS.iconSize)
	if fixedGridColumns <= 0 or not (slotColumn and slotRow and visualSize) then return 0, 0 end

	local groupId = Helper.NormalizeFixedGroupId(entry.fixedGroupId)
	if not groupId then return 0, 0 end
	local group = fixedLayoutCache and fixedLayoutCache.groupById and fixedLayoutCache.groupById[groupId] or nil
	if not group then group = CooldownPanels.GetFixedGroupById(panel, groupId) end
	if not group then return 0, 0 end
	local frameCache = frame and frame._eqolFixedVisualCache or nil
	local cacheUtil = CooldownPanels._eqolFixedVisualCacheUtil

	local baseSpacing = Helper.ClampInt(panel.layout and panel.layout.spacing, 0, Helper.SPACING_RANGE or 200, Helper.PANEL_LAYOUT_DEFAULTS.spacing)
	local targetSpacing = Helper.ClampInt(layout and layout.spacing, 0, Helper.SPACING_RANGE or 200, baseSpacing)
	local desiredStep = visualSize + targetSpacing
	local centerOffsetX, centerOffsetY = 0, 0
	local placementCount = nil
	local placementIndex = nil
	local placement = nil
	local centerGrowth = false
	if not CooldownPanels.IsFixedGroupStatic(group) and Helper.GetFixedGroupDynamicPlacement then
		centerGrowth = Helper.IsFixedGroupCenterGrowth and Helper.IsFixedGroupCenterGrowth(group) == true
		if type(fixedContext) == "table" then
			placementCount = math.floor(tonumber(fixedContext.dynamicCount) or 0)
			placementIndex = math.floor(tonumber(fixedContext.dynamicLocalIndex) or 0)
		end
		if placementCount == nil or placementCount < 1 or placementIndex == nil or placementIndex < 1 then
			local cache = fixedLayoutCache or (Helper.GetFixedLayoutCache and Helper.GetFixedLayoutCache(panel) or nil)
			local groupEntryIds = cache and cache.groupEntryIds and cache.groupEntryIds[group.id] or nil
			if groupEntryIds then
				placementCount = #groupEntryIds
				for index = 1, placementCount do
					if groupEntryIds[index] == entry.id then
						placementIndex = index
						break
					end
				end
			end
		end
		if placementCount and placementCount > 0 and placementIndex and placementIndex > 0 then
			placement = cacheUtil.GetDynamicPlacement(frameCache, group, placementIndex, placementCount)
			if placement then
				slotColumn = Helper.NormalizeSlotCoordinate(placement.column, slotColumn)
				slotRow = Helper.NormalizeSlotCoordinate(placement.row, slotRow)
				if not centerGrowth then
					centerOffsetX = (tonumber(placement.offsetSlotsX) or 0) * desiredStep
					centerOffsetY = (tonumber(placement.offsetSlotsY) or 0) * desiredStep
				end
			end
		end
	end

	local icons = frame.icons or nil

	if centerGrowth and placement then
		local rowCount = math.floor(tonumber(placement.rowCount) or 0)
		local columnIndex = tonumber(placement.columnIndex)
		local rowIndex = tonumber(placement.rowIndex)
		local currentX, currentY = cacheUtil.GetSlotCenter(frameCache, icons, fixedGridColumns, slotColumn, slotRow)
		local leftX = select(1, cacheUtil.GetSlotCenter(frameCache, icons, fixedGridColumns, group.column, placement.row))
		local rightX = select(1, cacheUtil.GetSlotCenter(frameCache, icons, fixedGridColumns, group.column + group.columns - 1, placement.row))
		local startPoint = Helper.NormalizeFixedGroupStartPoint(group.dynamicStartPoint, "TOPLEFT")
		local startRow = startPoint == "BOTTOM" and (group.row + group.rows - 1) or group.row
		local _, startY = cacheUtil.GetSlotCenter(frameCache, icons, fixedGridColumns, group.column, startRow)
		if currentX and currentY and leftX and rightX and startY and rowCount > 0 and columnIndex ~= nil and rowIndex ~= nil then
			local desiredCenterX = ((leftX + rightX) / 2) + ((columnIndex - ((rowCount - 1) / 2)) * desiredStep)
			local desiredCenterY = startY + ((startPoint == "BOTTOM" and rowIndex or -rowIndex) * desiredStep)
			return desiredCenterX - currentX, desiredCenterY - currentY
		end
	end

	if targetSpacing == baseSpacing and centerOffsetX == 0 and centerOffsetY == 0 then return 0, 0 end

	local anchorColumn = group.column
	local anchorRow = group.row
	if not CooldownPanels.IsFixedGroupStatic(group) and Helper.GetFixedGroupDynamicPlacement and placementCount and placementCount > 0 then
		local anchorPlacement = cacheUtil.GetDynamicPlacement(frameCache, group, 1, placementCount)
		anchorColumn = anchorPlacement and anchorPlacement.column or anchorColumn
		anchorRow = anchorPlacement and anchorPlacement.row or anchorRow
	elseif not CooldownPanels.IsFixedGroupStatic(group) then
		local orderedCells = cacheUtil.GetOrderedCells(frameCache, group)
		local anchorCell = orderedCells and orderedCells[1] or nil
		anchorColumn = anchorCell and anchorCell.column or anchorColumn
		anchorRow = anchorCell and anchorCell.row or anchorRow
	end
	anchorColumn = Helper.NormalizeSlotCoordinate(anchorColumn)
	anchorRow = Helper.NormalizeSlotCoordinate(anchorRow)
	if not (anchorColumn and anchorRow) then return 0, 0 end

	local anchorX, anchorY = cacheUtil.GetSlotCenter(frameCache, icons, fixedGridColumns, anchorColumn, anchorRow)
	local currentX, currentY = cacheUtil.GetSlotCenter(frameCache, icons, fixedGridColumns, slotColumn, slotRow)
	if not (anchorX and anchorY and currentX and currentY) then return 0, 0 end

	local desiredDeltaX = (slotColumn - anchorColumn) * desiredStep
	local desiredDeltaY = (anchorRow - slotRow) * desiredStep
	local actualDeltaX = currentX - anchorX
	local actualDeltaY = currentY - anchorY
	return (desiredDeltaX - actualDeltaX) + centerOffsetX, (desiredDeltaY - actualDeltaY) + centerOffsetY
end

function CooldownPanels:ApplyEntryIconVisualLayout(icon, layout, entry, panel, fixedGridColumns, slotColumn, slotRow, fixedContext, fixedLayoutCache)
	if not icon then return end
	local slotAnchor = icon.slotAnchor
	local baseSize = Helper.ClampInt(icon._eqolBaseSlotSize, 12, 128, Helper.PANEL_LAYOUT_DEFAULTS.iconSize)
	local size, offsetX, offsetY, width, height = self:ResolveEntryIconVisualLayout(layout, entry, baseSize)
	width = width or size
	height = height or size
	local fixedOffsetX, fixedOffsetY = 0, 0
	if panel and entry then
		fixedOffsetX, fixedOffsetY = self:ResolveFixedGroupSlotSpacingOffset(
			panel,
			icon:GetParent(),
			entry,
			layout,
			fixedGridColumns,
			slotColumn or icon._eqolPreviewCellColumn or icon._eqolLayoutSlotColumn,
			slotRow or icon._eqolPreviewCellRow or icon._eqolLayoutSlotRow,
			math.max(width, height),
			fixedContext,
			fixedLayoutCache
		)
	end
	offsetX = offsetX + (fixedOffsetX or 0)
	offsetY = offsetY + (fixedOffsetY or 0)
	width = cdp.PIXEL.SnapSize(width, icon)
	height = cdp.PIXEL.SnapSize(height, icon)
	offsetX = cdp.PIXEL.Snap(offsetX, slotAnchor or icon)
	offsetY = cdp.PIXEL.Snap(offsetY, slotAnchor or icon)
	local currentWidth, currentHeight = icon:GetSize()
	local previewBlingSize = icon.previewBling and (size * 1.5) or nil
	local iconShape = cdp.ENTRY.NormalizeIconShape(layout and layout.iconShape, Helper.PANEL_LAYOUT_DEFAULTS.iconShape)
	local iconZoom = addon.IconShape and addon.IconShape.NormalizeIconZoom and addon.IconShape.NormalizeIconZoom(layout and layout.iconZoom) or Helper.ClampInt(layout and layout.iconZoom, 0, 35, 0)
	local nativeAuraCrop = CooldownPanels.AuraContainers ~= nil and entry and entry.type == "CDM_AURA" or false
	if
		icon._eqolVisualSize == size
		and icon._eqolVisualWidth == width
		and icon._eqolVisualHeight == height
		and icon._eqolVisualShape == iconShape
		and icon._eqolVisualIconZoom == iconZoom
		and icon._eqolUseNativeAuraCrop == nativeAuraCrop
		and currentWidth == width
		and currentHeight == height
		and icon._eqolVisualAnchor == slotAnchor
		and icon._eqolVisualOffsetX == offsetX
		and icon._eqolVisualOffsetY == offsetY
		and ((not icon.previewGlowBorder) or icon.previewGlowBorder._eqolSize == size)
		and ((not icon.previewBling) or (icon.previewBling._eqolVisualAnchor == icon and icon.previewBling._eqolVisualSize == previewBlingSize))
	then
		return
	end
	if icon._eqolVisualWidth ~= width or icon._eqolVisualHeight ~= height or currentWidth ~= width or currentHeight ~= height then
		cdp.PIXEL.SetSize(icon, width, height)
		icon._eqolVisualSize = size
		icon._eqolVisualWidth = width
		icon._eqolVisualHeight = height
	end
	if slotAnchor then
		local point, relativeTo, relativePoint, currentX, currentY = icon:GetPoint(1)
		local needsAnchorUpdate = icon:GetNumPoints() ~= 1
			or icon._eqolVisualAnchor ~= slotAnchor
			or icon._eqolVisualOffsetX ~= offsetX
			or icon._eqolVisualOffsetY ~= offsetY
			or point ~= "CENTER"
			or relativeTo ~= slotAnchor
			or relativePoint ~= "CENTER"
			or currentX ~= offsetX
			or currentY ~= offsetY
		if needsAnchorUpdate then
			icon:ClearAllPoints()
			icon:SetPoint("CENTER", slotAnchor, "CENTER", offsetX, offsetY)
			icon._eqolVisualAnchor = slotAnchor
			icon._eqolVisualOffsetX = offsetX
			icon._eqolVisualOffsetY = offsetY
		end
	end
	cdp.PIXEL.AlignHostToPixelGrid(icon)
	CooldownPanels.UpdatePreviewGlowBorderLayout(icon, size)
	icon._eqolUseNativeAuraCrop = nativeAuraCrop
	cdp.ENTRY.ApplyIconShape(icon, layout)
	icon._eqolVisualShape = iconShape
	icon._eqolVisualIconZoom = iconZoom
	if icon.previewBling then
		if icon.previewBling._eqolVisualAnchor ~= icon then
			icon.previewBling:ClearAllPoints()
			icon.previewBling:SetPoint("CENTER", icon, "CENTER", 0, 0)
			icon.previewBling._eqolVisualAnchor = icon
		end
		if icon.previewBling._eqolVisualSize ~= previewBlingSize then
			icon.previewBling:SetSize(previewBlingSize, previewBlingSize)
			icon.previewBling._eqolVisualSize = previewBlingSize
		end
	end
end

function CooldownPanels:ApplyEditorGhostIcon(icon)
	local texture = icon and icon.editorGhostTexture or nil
	local source = icon and icon.texture or nil
	if not texture or not source then return end
	texture:SetTexture(source:GetTexture())
	texture:SetTexCoord(source:GetTexCoord())
	texture:SetShown(true)
	texture:SetDesaturated(true)
	texture:SetAlpha(0.32)
	texture._eqolGhostShown = true
end

function CooldownPanels:HideEditorGhostIcon(icon)
	local texture = icon and icon.editorGhostTexture or nil
	if not texture then return end
	texture:SetTexture(nil)
	texture:Hide()
	texture._eqolGhostShown = false
end

function CooldownPanels:ApplyStaticTextFontString(fontString, anchorFrame, layout, entry, defaultFontPath, defaultFontSize, defaultFontStyle, cooldownActive)
	if not (fontString and anchorFrame) then return false end
	if not entry or type(entry.staticText) ~= "string" or entry.staticText == "" then
		fontString:Hide()
		return false
	end
	if entry.staticTextShowOnCooldown == true and not cooldownActive then
		fontString:Hide()
		return false
	end
	local text = entry.staticText
	if text:find("\\n", 1, true) then text = text:gsub("\\n", "\n") end
	if text:find("|n", 1, true) then text = text:gsub("|n", "\n") end
	local fontPath, fontSize, fontStyleChoice, fontStyle, fontColor, anchor, x, y =
		CooldownPanels:ResolveEntryStaticTextStyle(layout, entry, defaultFontPath, defaultFontSize, defaultFontStyle)
	if Helper.SetFont then
		Helper.SetFont(fontString, fontPath, fontSize, fontStyle, defaultFontPath)
	else
		fontString:SetFont(fontPath, fontSize, fontStyle)
	end
	if addon.functions and addon.functions.ApplyFontStyleShadow then
		addon.functions.ApplyFontStyleShadow(fontString, fontStyleChoice, defaultFontStyle)
	end
	fontString:SetTextColor(fontColor[1] or 1, fontColor[2] or 1, fontColor[3] or 1, fontColor[4] or 1)
	if fontString.SetJustifyH then
		fontString:SetJustifyH(anchor == "LEFT" and "LEFT" or anchor == "RIGHT" and "RIGHT" or "CENTER")
	end
	fontString:ClearAllPoints()
	fontString:SetPoint(anchor, anchorFrame, anchor, x, y)
	fontString:SetText(text)
	fontString:Show()
	return true
end

local function applyStaticText(icon, layout, entry, defaultFontPath, defaultFontSize, defaultFontStyle, cooldownActive)
	if not icon or not icon.staticText then return end
	CooldownPanels:ApplyStaticTextFontString(icon.staticText, icon.overlay or icon, layout, entry, defaultFontPath, defaultFontSize, defaultFontStyle, cooldownActive)
end

local function applyStateTexture(icon, data)
	local texture = icon and icon.stateTexture or nil
	local textureSecond = icon and icon.stateTextureSecond or nil
	if not texture then return end
	local desaturated = data and data.stateTextureDesaturated == true
	if not (data and data.stateTextureShown == true and data.stateTextureType and data.stateTextureValue) then
		if texture.SetDesaturated then texture:SetDesaturated(false) end
		texture:Hide()
		if textureSecond then
			if textureSecond.SetDesaturated then textureSecond:SetDesaturated(false) end
			textureSecond:Hide()
		end
		return
	end

	local scale = Helper.ClampNumber(data.stateTextureScale, 0.1, 8, 1)
	local widthScale = Helper.ClampNumber(data.stateTextureWidth, 0.1, 8, 1)
	local heightScale = Helper.ClampNumber(data.stateTextureHeight, 0.1, 8, 1)
	local angle = Helper.ClampNumber(data.stateTextureAngle, 0, 360, 0)
	local doubleTexture = data.stateTextureDouble == true
	local mirror = data.stateTextureMirror == true
	local mirrorSecond = data.stateTextureMirrorSecond == true
	local mirrorVertical = data.stateTextureMirrorVertical == true
	local mirrorVerticalSecond = data.stateTextureMirrorVerticalSecond == true
	local spacingX = Helper.ClampInt(data.stateTextureSpacingX, 0, Helper.STATE_TEXTURE_SPACING_RANGE or 2000, 0)
	local spacingY = Helper.ClampInt(data.stateTextureSpacingY, 0, Helper.STATE_TEXTURE_SPACING_RANGE or 2000, 0)
	local atlasInfo = data.stateTextureType == "ATLAS" and Api.GetAtlasInfo and Api.GetAtlasInfo(data.stateTextureValue) or nil
	local baseWidth, baseHeight
	if atlasInfo and atlasInfo.width and atlasInfo.height then
		baseWidth = atlasInfo.width
		baseHeight = atlasInfo.height
	else
		baseWidth, baseHeight = icon:GetSize()
		baseWidth = baseWidth or 36
		baseHeight = baseHeight or 36
	end
	local width = baseWidth * scale * widthScale
	local height = baseHeight * scale * heightScale

	local function setRegionTexCoord(region, left, right, top, bottom, mirroredHorizontal, mirroredVertical)
		if mirroredHorizontal then
			left, right = right, left
		end
		if mirroredVertical then
			top, bottom = bottom, top
		end
		region:SetTexCoord(left, right, top, bottom)
	end

	local function applyRegion(region, offsetX, offsetY, mirroredHorizontal, mirroredVertical)
		if not region then return end
		region:ClearAllPoints()
		region:SetPoint("CENTER", icon, "CENTER", offsetX or 0, offsetY or 0)
		region:SetSize(width, height)
		if data.stateTextureType == "ATLAS" then
			local atlas = data.stateTextureValue
			region:SetTexture(nil)
			region:SetAtlas(atlas, true)
			if atlasInfo then
				local left = atlasInfo.leftTexCoord or 0
				local right = atlasInfo.rightTexCoord or 1
				local top = atlasInfo.topTexCoord or 0
				local bottom = atlasInfo.bottomTexCoord or 1
				setRegionTexCoord(region, left, right, top, bottom, mirroredHorizontal, mirroredVertical)
			end
		else
			local fileID = tonumber(data.stateTextureValue)
			region:SetTexture(nil)
			region:SetTexture(fileID)
			setRegionTexCoord(region, 0, 1, 0, 1, mirroredHorizontal, mirroredVertical)
		end
		if region.SetDesaturated then region:SetDesaturated(desaturated) end
		if region.SetRotation then region:SetRotation(math.rad(angle)) end
		region:Show()
	end

	if doubleTexture and textureSecond then
		local halfX = spacingX / 2
		local halfY = spacingY / 2
		local secondMirrored = (mirrorSecond and not mirror) or ((not mirrorSecond) and mirror)
		local secondMirroredVertical = (mirrorVerticalSecond and not mirrorVertical) or ((not mirrorVerticalSecond) and mirrorVertical)
		applyRegion(texture, -halfX, -halfY, mirror, mirrorVertical)
		applyRegion(textureSecond, halfX, halfY, secondMirrored, secondMirroredVertical)
	else
		applyRegion(texture, 0, 0, mirror, mirrorVertical)
		if textureSecond then
			if textureSecond.SetDesaturated then textureSecond:SetDesaturated(false) end
			textureSecond:Hide()
		end
	end
end

CooldownPanels.ApplyStateTexture = applyStateTexture

function cdp.RUNTIME.ClearIconSnapshot(icon)
	if not icon then return end
	CooldownPanels:ClearRuntimeCooldownTextBinding(icon)
	icon._eqolRuntimeSnapshot = nil
end

function cdp.RUNTIME.EnsureIconSnapshot(icon)
	if not icon then return nil end
	local snapshot = icon._eqolRuntimeSnapshot
	if type(snapshot) ~= "table" then
		snapshot = {}
		icon._eqolRuntimeSnapshot = snapshot
	end
	return snapshot
end

function cdp.RUNTIME.GetFixedContextSignature(fixedContext)
	if type(fixedContext) ~= "table" then return nil, nil end
	return tonumber(fixedContext.dynamicLocalIndex) or 0, tonumber(fixedContext.dynamicCount) or 0
end

function cdp.RUNTIME.GetTableField(tbl, key)
	if type(tbl) ~= "table" then return nil end
	return tbl[key]
end

function cdp.RUNTIME.HasPlacementChange(icon, snapshot, data, fixedLayoutCache, fixedGridColumns, slotColumn, slotRow, layoutEditActive)
	if not (icon and snapshot and data) then return true end
	if icon._eqolVisualSize == nil or icon._eqolVisualAnchor == nil or icon._eqolVisualOffsetX == nil or icon._eqolVisualOffsetY == nil then return true end
	local entry = data.entry
	local layout = data.layout
	local fixedLocalIndex, fixedCount = cdp.RUNTIME.GetFixedContextSignature(data.fixedContext)
	local entryIconSizeUseGlobal, entryIconSize, entryIconSizeSeparate, entryIconWidth, entryIconHeight, entryIconOffsetX, entryIconOffsetY, entryFixedGroupId
	if entry then
		entryIconSizeUseGlobal = entry.iconSizeUseGlobal
		entryIconSize = entry.iconSize
		entryIconSizeSeparate = entry.iconSizeSeparate
		entryIconWidth = entry.iconWidth
		entryIconHeight = entry.iconHeight
		entryIconOffsetX = entry.iconOffsetX
		entryIconOffsetY = entry.iconOffsetY
		entryFixedGroupId = entry.fixedGroupId
	end
	local layoutIconOffsetX, layoutIconOffsetY, layoutIconSizeSeparate, layoutIconWidth, layoutIconHeight, layoutIconShape, layoutIconZoom, layoutSpacing
	if layout then
		layoutIconOffsetX = layout.iconOffsetX
		layoutIconOffsetY = layout.iconOffsetY
		layoutIconSizeSeparate = layout.iconSizeSeparate
		layoutIconWidth = layout.iconWidth
		layoutIconHeight = layout.iconHeight
		layoutIconShape = layout.iconShape
		layoutIconZoom = layout.iconZoom
		layoutSpacing = layout.spacing
	end
	return snapshot.entryId ~= data.entryId
		or snapshot.baseSlotSize ~= icon._eqolBaseSlotSize
		or snapshot.fixedLayoutCache ~= fixedLayoutCache
		or snapshot.fixedGridColumns ~= fixedGridColumns
		or snapshot.slotColumn ~= slotColumn
		or snapshot.slotRow ~= slotRow
		or snapshot.layoutEditActive ~= (layoutEditActive == true)
		or snapshot.entryIconSizeUseGlobal ~= entryIconSizeUseGlobal
		or snapshot.entryIconSize ~= entryIconSize
		or snapshot.entryIconSizeSeparate ~= entryIconSizeSeparate
		or snapshot.entryIconWidth ~= entryIconWidth
		or snapshot.entryIconHeight ~= entryIconHeight
		or snapshot.entryIconOffsetX ~= entryIconOffsetX
		or snapshot.entryIconOffsetY ~= entryIconOffsetY
		or snapshot.entryFixedGroupId ~= entryFixedGroupId
		or snapshot.layoutIconOffsetX ~= layoutIconOffsetX
		or snapshot.layoutIconOffsetY ~= layoutIconOffsetY
		or snapshot.layoutIconSizeSeparate ~= layoutIconSizeSeparate
		or snapshot.layoutIconWidth ~= layoutIconWidth
		or snapshot.layoutIconHeight ~= layoutIconHeight
		or snapshot.layoutIconShape ~= layoutIconShape
		or snapshot.layoutIconZoom ~= layoutIconZoom
		or snapshot.layoutSpacing ~= layoutSpacing
		or snapshot.fixedLocalIndex ~= fixedLocalIndex
		or snapshot.fixedCount ~= fixedCount
end

function cdp.RUNTIME.WritePlacementSnapshot(icon, snapshot, data, fixedLayoutCache, fixedGridColumns, slotColumn, slotRow, layoutEditActive)
	if not (icon and snapshot and data) then return end
	local entry = data.entry
	local layout = data.layout
	local fixedLocalIndex, fixedCount = cdp.RUNTIME.GetFixedContextSignature(data.fixedContext)
	snapshot.entryId = data.entryId
	snapshot.baseSlotSize = icon._eqolBaseSlotSize
	snapshot.fixedLayoutCache = fixedLayoutCache
	snapshot.fixedGridColumns = fixedGridColumns
	snapshot.slotColumn = slotColumn
	snapshot.slotRow = slotRow
	snapshot.layoutEditActive = layoutEditActive == true
	snapshot.entryIconSizeUseGlobal = cdp.RUNTIME.GetTableField(entry, "iconSizeUseGlobal")
	snapshot.entryIconSize = cdp.RUNTIME.GetTableField(entry, "iconSize")
	snapshot.entryIconSizeSeparate = cdp.RUNTIME.GetTableField(entry, "iconSizeSeparate")
	snapshot.entryIconWidth = cdp.RUNTIME.GetTableField(entry, "iconWidth")
	snapshot.entryIconHeight = cdp.RUNTIME.GetTableField(entry, "iconHeight")
	snapshot.entryIconOffsetX = cdp.RUNTIME.GetTableField(entry, "iconOffsetX")
	snapshot.entryIconOffsetY = cdp.RUNTIME.GetTableField(entry, "iconOffsetY")
	snapshot.entryFixedGroupId = cdp.RUNTIME.GetTableField(entry, "fixedGroupId")
	snapshot.layoutIconOffsetX = cdp.RUNTIME.GetTableField(layout, "iconOffsetX")
	snapshot.layoutIconOffsetY = cdp.RUNTIME.GetTableField(layout, "iconOffsetY")
	snapshot.layoutIconSizeSeparate = cdp.RUNTIME.GetTableField(layout, "iconSizeSeparate")
	snapshot.layoutIconWidth = cdp.RUNTIME.GetTableField(layout, "iconWidth")
	snapshot.layoutIconHeight = cdp.RUNTIME.GetTableField(layout, "iconHeight")
	snapshot.layoutIconShape = cdp.RUNTIME.GetTableField(layout, "iconShape")
	snapshot.layoutIconZoom = cdp.RUNTIME.GetTableField(layout, "iconZoom")
	snapshot.layoutSpacing = cdp.RUNTIME.GetTableField(layout, "spacing")
	snapshot.fixedLocalIndex = fixedLocalIndex
	snapshot.fixedCount = fixedCount
end

function cdp.RUNTIME.HasBaseDecorChange(snapshot, data, showTooltips)
	if not (snapshot and data) then return true end
	local keybindVisible = data.showKeybinds == true and data.keybindText ~= nil
	return snapshot.entryId ~= data.entryId
		or snapshot.decorEntry ~= data.entry
		or snapshot.showIconTexture ~= (data.showIconTexture ~= false)
		or snapshot.tooltipEnabled ~= (showTooltips == true)
		or snapshot.nativeAuraTooltipOwner ~= (data.nativeAuraTooltipOwner == true)
		or snapshot.keybindVisible ~= keybindVisible
		or snapshot.keybindText ~= data.keybindText
end

function cdp.RUNTIME.WriteBaseDecorSnapshot(snapshot, data, showTooltips)
	if not (snapshot and data) then return end
	snapshot.entryId = data.entryId
	snapshot.decorEntry = data.entry
	snapshot.showIconTexture = data.showIconTexture ~= false
	snapshot.tooltipEnabled = showTooltips == true
	snapshot.nativeAuraTooltipOwner = data.nativeAuraTooltipOwner == true
	snapshot.keybindVisible = data.showKeybinds == true and data.keybindText ~= nil
	snapshot.keybindText = data.keybindText
end

function cdp.RUNTIME.HasTextureChange(snapshot, data)
	if not data then return true end
	local iconTexture = data.icon or Helper.PREVIEW_ICON
	local issecretvalue = Api and Api.issecretvalue or nil
	if issecretvalue and issecretvalue(iconTexture) then return true end
	if not snapshot or snapshot.iconTextureComparable ~= true then return true end
	return snapshot.iconTexture ~= iconTexture
end

function cdp.RUNTIME.WriteTextureSnapshot(snapshot, data)
	if not (snapshot and data) then return end
	local iconTexture = data.icon or Helper.PREVIEW_ICON
	local issecretvalue = Api and Api.issecretvalue or nil
	if issecretvalue and issecretvalue(iconTexture) then
		snapshot.iconTextureComparable = false
		snapshot.iconTexture = nil
		return
	end
	snapshot.iconTextureComparable = true
	snapshot.iconTexture = iconTexture
end

function cdp.RUNTIME.EnsureCooldownTextDefaults(icon)
	if not (icon and icon.cooldown and icon.cooldown.GetCountdownFontString) then return nil, nil, nil end
	local defaults = icon.cooldown._eqolCooldownTextDefaults
	if defaults then return defaults.font, defaults.size, defaults.style end
	local fontString = icon.cooldown:GetCountdownFontString()
	if not (fontString and fontString.GetFont) then return nil, nil, nil end
	local fontPath, fontSize, fontStyle = fontString:GetFont()
	icon.cooldown._eqolCooldownTextDefaults = {
		font = fontPath,
		size = fontSize,
		style = fontStyle,
	}
	return fontPath, fontSize, fontStyle
end

