function cdp.RUNTIME.GetHealthItemPingCategory(itemID)
	itemID = Helper.GetPlainPositiveSpellId(itemID)
	if not itemID then return nil end
	if not cdp.RUNTIME.healthItemPingCategoryByID then
		cdp.RUNTIME.healthItemPingCategoryByID = {
			[5512] = 1711,
			[224464] = 2566,
		}
		local healthItems = addon.Health and addon.Health.healthList
		for index = 1, #(healthItems or {}) do
			local healthItem = healthItems[index]
			local healthItemID = Helper.GetPlainPositiveSpellId(healthItem and healthItem.id)
			if healthItemID and healthItem.type == "potion" then cdp.RUNTIME.healthItemPingCategoryByID[healthItemID] = 30 end
		end
	end
	return cdp.RUNTIME.healthItemPingCategoryByID[itemID]
end

function cdp.RUNTIME.GetCooldownPingTargetInfo(frame)
	local data = frame and frame._eqolRuntimeData
	local entry = data and data.entry
	if not (data and entry) or entry.type == "CDM_AURA" or entry.displayMode == "BAR" then return nil end

	if data.resolvedType == "SPELL" then
		local spellID = Helper.GetPlainPositiveSpellId(data.spellId or data.effectiveSpellId or entry.spellID)
		if spellID then return { spellID = spellID } end
	elseif data.resolvedType == "ITEM" then
		local itemID = Helper.GetPlainPositiveSpellId(data.resolvedItemId)
		if not itemID then
			local macro = entry.type == "MACRO" and CooldownPanels.ResolveMacroEntry(entry) or nil
			itemID = Helper.GetPlainPositiveSpellId(CooldownPanels.ResolveEntryItemID(entry, (macro and macro.itemID) or entry.itemID))
		end
		local spellCategoryID = cdp.RUNTIME.GetHealthItemPingCategory(itemID)
		if spellCategoryID then return { spellCategoryID = spellCategoryID } end
		if itemID then return { itemID = itemID } end
	elseif data.resolvedType == "SLOT" then
		local slotID = tonumber(entry.slotID)
		local itemID = slotID and Api.GetInventoryItemID and Helper.GetPlainPositiveSpellId(Api.GetInventoryItemID("player", slotID)) or nil
		if itemID then return { itemID = itemID } end
	elseif data.resolvedType == "STANCE" then
		local stanceDef = CooldownPanels.GetStanceDefinition and CooldownPanels:GetStanceDefinition(entry) or nil
		local spellID = Helper.GetPlainPositiveSpellId(stanceDef and stanceDef.spellID)
		if spellID then return { spellID = spellID } end
	end

	return nil
end

function cdp.RUNTIME.CooldownPingFrameGetTargetInfo(self) return self._eqolCooldownPingTargetInfo or {} end
function cdp.RUNTIME.CooldownPingFrameGetIsPingable(self) return self._eqolCooldownPingTargetInfo ~= nil end

function cdp.RUNTIME.ConfigureCooldownPingFrame(frame)
	if not frame then return end
	frame.GetTargetInfo = cdp.RUNTIME.CooldownPingFrameGetTargetInfo
	frame.GetIsPingable = cdp.RUNTIME.CooldownPingFrameGetIsPingable
	cdp.RUNTIME.UpdateCooldownPingReceiver(frame, false)
end

function cdp.RUNTIME.UpdateCooldownPingReceiver(frame, enabled)
	if not frame then return end
	local targetInfo = enabled == true and cdp.RUNTIME.GetCooldownPingTargetInfo(frame) or nil
	frame._eqolCooldownPingTargetInfo = targetInfo
	if targetInfo then
		frame:SetAttribute("ping-receiver", true)
	else
		frame:ClearAttribute("ping-receiver")
	end
end

local function createIconFrame(parent)
	local icon = CreateFrame("Frame", nil, parent, "PingableCooldownViewerItemTemplate")
	cdp.RUNTIME.ConfigureCooldownPingFrame(icon)
	icon:Hide()
	icon:EnableMouse(false)
	icon:SetScript("OnEnter", CooldownPanels.ShowIconTooltip)
	icon:SetScript("OnLeave", CooldownPanels.HideIconTooltip)

	icon.slotAnchor = CreateFrame("Frame", nil, parent)
	icon.slotAnchor:EnableMouse(false)
	icon.slotAnchorHandle = CreateFrame("Button", nil, icon.slotAnchor)
	icon.slotAnchorHandle:SetAllPoints(icon.slotAnchor)
	icon.slotAnchorHandle:EnableMouse(false)
	icon.slotAnchorHandle:Hide()

	icon.editorGhostTexture = icon.slotAnchor:CreateTexture(nil, "ARTWORK")
	icon.editorGhostTexture:SetAllPoints(icon.slotAnchor)
	icon.editorGhostTexture:Hide()

	icon.texture = icon:CreateTexture(nil, "ARTWORK")
	icon.texture:SetAllPoints(icon)

	icon.cooldown = CreateFrame("Cooldown", nil, icon, "CooldownFrameTemplate")
	icon.cooldown:SetAllPoints(icon)
	icon.cooldown:SetHideCountdownNumbers(true)
	icon.cooldown._eqolOwnerIcon = icon

	icon.overlay = CreateFrame("Frame", nil, icon)
	icon.overlay:SetAllPoints(icon)
	icon.overlay:SetFrameStrata(icon.cooldown:GetFrameStrata() or icon:GetFrameStrata())
	icon.overlay:SetFrameLevel((icon.cooldown:GetFrameLevel() or icon:GetFrameLevel()) + 5)
	icon.overlay:EnableMouse(false)

	icon.cooldownText = icon.overlay:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
	icon.cooldownText:SetPoint("CENTER", icon.overlay, "CENTER", 0, 0)
	if icon.cooldownText.SetDrawLayer then icon.cooldownText:SetDrawLayer("OVERLAY", 7) end
	icon.cooldownText:Hide()

	icon.layoutHandle = CreateFrame("Button", nil, icon)
	icon.layoutHandle:SetAllPoints(icon)
	icon.layoutHandle:SetFrameStrata(icon.overlay:GetFrameStrata() or icon:GetFrameStrata())
	icon.layoutHandle:SetFrameLevel((icon.overlay:GetFrameLevel() or icon:GetFrameLevel()) + 20)
	icon.layoutHandle:EnableMouse(false)
	icon.layoutHandle:Hide()

	icon.border = CreateFrame("Frame", nil, icon, "BackdropTemplate")
	icon.border:SetFrameStrata(icon.cooldown:GetFrameStrata() or icon:GetFrameStrata())
	icon.border:SetFrameLevel((icon.cooldown:GetFrameLevel() or icon:GetFrameLevel()) + 1)
	icon.border:EnableMouse(false)
	icon.border:Hide()

	icon.count = icon.overlay:CreateFontString(nil, "OVERLAY", "NumberFontNormalSmall")
	icon.count:SetPoint("BOTTOMRIGHT", icon.overlay, "BOTTOMRIGHT", -1, 1)
	icon.count:Hide()

	icon.charges = icon.overlay:CreateFontString(nil, "OVERLAY", "NumberFontNormalSmall")
	icon.charges:SetPoint("TOP", icon.overlay, "TOP", 0, -1)
	icon.charges:Hide()

	icon.rangeOverlay = icon:CreateTexture(nil, "ARTWORK", nil, 1)
	icon.rangeOverlay:SetAllPoints(icon)
	icon.rangeOverlay:Hide()

	icon.stateTexture = icon:CreateTexture(nil, "ARTWORK", nil, 1)
	icon.stateTexture:SetBlendMode("BLEND")
	icon.stateTexture:Hide()

	icon.stateTextureSecond = icon:CreateTexture(nil, "ARTWORK", nil, 1)
	icon.stateTextureSecond:SetBlendMode("BLEND")
	icon.stateTextureSecond:Hide()

	icon.keybind = icon.overlay:CreateFontString(nil, "OVERLAY", "NumberFontNormalSmall")
	icon.keybind:SetPoint("TOPLEFT", icon.overlay, "TOPLEFT", 2, -2)
	icon.keybind:Hide()

	icon.staticText = icon.overlay:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
	icon.staticText:SetPoint("CENTER", icon.overlay, "CENTER", 0, 0)
	icon.staticText:SetJustifyH("CENTER")
	icon.staticText:SetJustifyV("MIDDLE")
	if icon.staticText.SetWordWrap then icon.staticText:SetWordWrap(true) end
	icon.staticText:Hide()

	icon.previewGlowBorder = CreateFrame("Frame", nil, icon, "BackdropTemplate")
	icon.previewGlowBorder:SetFrameStrata(icon.cooldown:GetFrameStrata() or icon:GetFrameStrata())
	icon.previewGlowBorder:SetFrameLevel((icon.cooldown:GetFrameLevel() or icon:GetFrameLevel()) + 2)
	icon.previewGlowBorder:EnableMouse(false)
	icon.previewGlowBorder:SetBackdrop({
		edgeFile = "Interface\\Buttons\\WHITE8x8",
		edgeSize = 2,
		insets = { left = 0, right = 0, top = 0, bottom = 0 },
	})
	icon.previewGlowBorder:SetBackdropColor(0, 0, 0, 0)
	icon.previewGlowBorder:Hide()

	icon.previewBling = icon:CreateTexture(nil, "OVERLAY")
	icon.previewBling:SetTexture("Interface\\Cooldown\\star4")
	icon.previewBling:SetVertexColor(0.3, 0.6, 1, 0.9)
	icon.previewBling:SetBlendMode("ADD")
	icon.previewBling:Hide()

	icon.previewSoundBorder = CreateFrame("Frame", nil, icon.overlay, "BackdropTemplate")
	icon.previewSoundBorder:SetSize(14, 14)
	icon.previewSoundBorder:SetPoint("TOPRIGHT", icon.overlay, "TOPRIGHT", -1, -1)
	icon.previewSoundBorder:SetBackdrop({
		bgFile = "Interface\\Buttons\\WHITE8x8",
		edgeFile = "Interface\\Buttons\\WHITE8x8",
		edgeSize = 1,
	})
	icon.previewSoundBorder:SetBackdropColor(0, 0, 0, 0.55)
	icon.previewSoundBorder:SetBackdropBorderColor(0.9, 0.9, 0.9, 0.9)
	icon.previewSoundBorder:Hide()

	icon.previewSound = icon.previewSoundBorder:CreateTexture(nil, "OVERLAY")
	icon.previewSound:SetTexture("Interface\\Common\\VoiceChat-Speaker")
	icon.previewSound:SetSize(12, 12)
	icon.previewSound:SetPoint("CENTER", icon.previewSoundBorder, "CENTER", 0, 0)
	icon.previewSound:SetAlpha(0.95)

	return icon
end

function CooldownPanels.HidePreviewGlowBorder(icon)
	local border = icon and icon.previewGlowBorder
	if border then border:Hide() end
end

function CooldownPanels.UpdatePreviewGlowBorderLayout(icon, rowSize)
	local border = icon and icon.previewGlowBorder
	if not border then return end

	local size = tonumber(rowSize) or 24
	local edgeSize = math.min(6, math.max(2, math.floor((size * 0.08) + 0.5)))
	local offset = math.min(6, math.max(1, math.floor((size * 0.1) + 0.5)))
	local resolvedEdgeSize = cdp.PIXEL.SizeFromPixels(edgeSize, border)
	local resolvedOffset = cdp.PIXEL.Snap(offset, icon)

	if border._eqolEdgeSize ~= edgeSize or border._eqolResolvedEdgeSize ~= resolvedEdgeSize then
		border:SetBackdrop({
			edgeFile = "Interface\\Buttons\\WHITE8x8",
			edgeSize = resolvedEdgeSize,
			insets = { left = 0, right = 0, top = 0, bottom = 0 },
		})
		border:SetBackdropColor(0, 0, 0, 0)
		border._eqolEdgeSize = edgeSize
		border._eqolResolvedEdgeSize = resolvedEdgeSize
	end

	if border._eqolOffset ~= offset or border._eqolResolvedOffset ~= resolvedOffset or border._eqolSize ~= size then
		cdp.PIXEL.SetOutside(border, icon, offset)
		border._eqolOffset = offset
		border._eqolResolvedOffset = resolvedOffset
		border._eqolSize = size
	end
end

function CooldownPanels.ShowPreviewGlowBorder(icon, glowColor)
	local border = icon and icon.previewGlowBorder
	if not border then return end

	local fallbackColor = (Helper and Helper.PANEL_LAYOUT_DEFAULTS and Helper.PANEL_LAYOUT_DEFAULTS.readyGlowColor) or { 1, 0.82, 0.2, 1 }
	local color = Helper.NormalizeColor(glowColor, fallbackColor)
	CooldownPanels.UpdatePreviewGlowBorderLayout(icon, icon:GetWidth())
	border:SetBackdropBorderColor(color[1] or 1, color[2] or 0.82, color[3] or 0.2, color[4] or 1)
	border:Show()
end

local function ensureIconCount(frame, count)
	frame.icons = frame.icons or {}
	local icons = frame.icons
	local previousCount = tonumber(frame._eqolEnsuredIconCount) or 0
	for i = 1, count do
		if not icons[i] then
			icons[i] = createIconFrame(frame)
			icons[i]:Hide()
		end
	end
	if count < previousCount then
		for i = count + 1, previousCount do
			local icon = icons[i]
			if icon then icon:Hide() end
		end
	end
	frame._eqolEnsuredIconCount = count
end

local ASSISTED_HIGHLIGHT_CONFIG = {
	atlas = "RotationHelper_Ants_Flipbook_2x",
	rows = 6,
	columns = 5,
	frames = 30,
	duration = 1.0,
	scale = 1.45,
	fallbackTexture = "Interface\\Buttons\\UI-ActionButton-Border",
}

local function resizeAssistedHighlight(frame)
	if not frame then return end
	local highlight = frame._eqolAssistedHighlight
	if not (highlight and highlight.Texture) then return end
	local width, height = frame:GetSize()
	if not width or width <= 0 or not height or height <= 0 then return end
	highlight.Texture:SetSize(width * ASSISTED_HIGHLIGHT_CONFIG.scale, height * ASSISTED_HIGHLIGHT_CONFIG.scale)
end

local function ensureAssistedHighlight(frame)
	if not frame then return nil end
	local highlight = frame._eqolAssistedHighlight
	if highlight then
		resizeAssistedHighlight(frame)
		return highlight
	end

	highlight = CreateFrame("Frame", nil, frame.overlay or frame)
	highlight:SetAllPoints(frame)
	highlight:EnableMouse(false)
	highlight:SetFrameStrata((frame.overlay and frame.overlay:GetFrameStrata()) or frame:GetFrameStrata())
	highlight:SetFrameLevel(((frame.overlay and frame.overlay:GetFrameLevel()) or frame:GetFrameLevel()) + 8)

	local tex = highlight:CreateTexture(nil, "OVERLAY")
	tex:SetPoint("CENTER", frame, "CENTER", 0, 0)
	if tex.SetBlendMode then tex:SetBlendMode("ADD") end
	local atlasApplied = tex.SetAtlas and tex:SetAtlas(ASSISTED_HIGHLIGHT_CONFIG.atlas, true)
	if not atlasApplied then
		tex:SetTexture(ASSISTED_HIGHLIGHT_CONFIG.fallbackTexture)
		tex:SetVertexColor(0.35, 0.75, 1, 0.95)
	end
	highlight.Texture = tex
	resizeAssistedHighlight(frame)

	local anim = highlight:CreateAnimationGroup()
	anim:SetLooping("REPEAT")
	anim:SetToFinalAlpha(true)
	highlight.Anim = anim

	local alphaAnim = anim:CreateAnimation("Alpha")
	alphaAnim:SetChildKey("Texture")
	alphaAnim:SetFromAlpha(1)
	alphaAnim:SetToAlpha(1)
	alphaAnim:SetDuration(0.001)
	alphaAnim:SetOrder(0)

	local flipAnim
	if anim.CreateAnimation then
		local ok, created = pcall(anim.CreateAnimation, anim, "FlipBook")
		if ok then flipAnim = created end
	end
	if flipAnim and flipAnim.SetFlipBookRows then
		flipAnim:SetChildKey("Texture")
		flipAnim:SetDuration(ASSISTED_HIGHLIGHT_CONFIG.duration)
		flipAnim:SetOrder(0)
		flipAnim:SetFlipBookRows(ASSISTED_HIGHLIGHT_CONFIG.rows)
		flipAnim:SetFlipBookColumns(ASSISTED_HIGHLIGHT_CONFIG.columns)
		flipAnim:SetFlipBookFrames(ASSISTED_HIGHLIGHT_CONFIG.frames)
		flipAnim:SetFlipBookFrameWidth(0)
		flipAnim:SetFlipBookFrameHeight(0)
		highlight.FlipAnim = flipAnim
	end

	highlight:SetAlpha(0)
	highlight:Show()
	frame._eqolAssistedHighlight = highlight
	return highlight
end

local function setAssistedHighlight(frame, enabled)
	if not frame then return end
	if enabled ~= true then
		frame._eqolAssistedHighlightShown = nil
		local existing = frame._eqolAssistedHighlight
		if existing then
			existing:SetAlpha(0)
			if existing.Anim and existing.Anim.IsPlaying and existing.Anim:IsPlaying() then existing.Anim:Stop() end
		end
		return
	end

	local highlight = ensureAssistedHighlight(frame)
	if not highlight then return end
	resizeAssistedHighlight(frame)
	if frame._eqolAssistedHighlightShown == true then
		highlight:SetAlpha(1)
		if highlight.Anim and highlight.Anim.IsPlaying and not highlight.Anim:IsPlaying() then highlight.Anim:Play() end
		return
	end
	frame._eqolAssistedHighlightShown = true
	highlight:SetAlpha(1)
	if highlight.Anim and highlight.Anim.IsPlaying and not highlight.Anim:IsPlaying() then highlight.Anim:Play() end
end

local function setGlow(frame, enabled, glowColor, glowKey, glowCondition, glowAlphaOn, glowAlphaOff, glowStyle, glowInset, glowOptions, layerOptions)
	if not frame then return end
	glowKey = glowKey or "EQOL_SIMPLE"
	local alphaOn = glowAlphaOn == nil and 1 or glowAlphaOn
	local alphaOff = glowAlphaOff == nil and 0 or glowAlphaOff
	frame._eqolGlowState = frame._eqolGlowState or {}
	local state = frame._eqolGlowState[glowKey]
	if not state then
		state = {}
		frame._eqolGlowState[glowKey] = state
	end
	local wasEnabled = state.enabled == true
	if not enabled then
		if not wasEnabled then return end
		state.enabled = false
		state.color = nil
		state.style = nil
		state.inset = nil
		state.requestedColorR = nil
		state.requestedColorG = nil
		state.requestedColorB = nil
		state.requestedColorA = nil
		state.requestedStyle = nil
		state.requestedInset = nil
		state.requestedBorderTintVersion = nil
		state.pixelBorder = nil
		state.pixelCount = nil
		state.pixelSpeed = nil
		state.pixelThickness = nil
		state.shape = nil
		state.hostFrameLevelOffset = nil
		state.frameLevel = nil
		state.condition = nil
		state.alphaOn = nil
		state.alphaOff = nil
		if Glow then Glow.Stop(frame, glowKey, true) end
		return
	end
	local requestedColorR = glowColor and (glowColor[1] or glowColor.r) or nil
	local requestedColorG = glowColor and (glowColor[2] or glowColor.g) or nil
	local requestedColorB = glowColor and (glowColor[3] or glowColor.b) or nil
	local requestedColorA = glowColor and (glowColor[4] or glowColor.a) or nil
	local requestedPixelBorder = type(glowOptions) == "table" and glowOptions.border == true or false
	local requestedPixelCount = Helper.NormalizeGlowPixelCount(type(glowOptions) == "table" and glowOptions.count or nil, Helper.PANEL_LAYOUT_DEFAULTS.glowPixelCount or 8)
	local requestedPixelSpeed = Helper.NormalizeGlowPixelSpeed(type(glowOptions) == "table" and glowOptions.frequency or nil, Helper.PANEL_LAYOUT_DEFAULTS.glowPixelSpeed or 0.25)
	local requestedPixelThickness = Helper.NormalizeGlowPixelThickness(type(glowOptions) == "table" and glowOptions.thickness or nil, Helper.PANEL_LAYOUT_DEFAULTS.glowPixelThickness or 2)
	local requestedHostFrameLevelOffset = type(layerOptions) == "table" and layerOptions.hostFrameLevelOffset or nil
	local requestedFrameLevel = type(layerOptions) == "table" and layerOptions.frameLevel or nil
	local requestedBorderTintVersion = glowStyle == "TINT_BORDER" and frame._eqolGlowBorderVersion or nil
	local issecretvalue = Api and Api.issecretvalue
	local hasSecretCondition = issecretvalue and ((glowCondition ~= nil and issecretvalue(glowCondition)) or (state.condition ~= nil and issecretvalue(state.condition)))
	if
		wasEnabled
		and state.requestedColorR == requestedColorR
		and state.requestedColorG == requestedColorG
		and state.requestedColorB == requestedColorB
		and state.requestedColorA == requestedColorA
		and state.requestedStyle == glowStyle
		and state.requestedInset == glowInset
		and state.requestedBorderTintVersion == requestedBorderTintVersion
		and state.pixelBorder == requestedPixelBorder
		and state.pixelCount == requestedPixelCount
		and state.pixelSpeed == requestedPixelSpeed
		and state.pixelThickness == requestedPixelThickness
		and state.shape == frame._eqolGlowShape
		and state.hostFrameLevelOffset == requestedHostFrameLevelOffset
		and state.frameLevel == requestedFrameLevel
		and not hasSecretCondition
		and state.condition == glowCondition
		and state.alphaOn == alphaOn
		and state.alphaOff == alphaOff
	then
		return
	end
	local fallbackColor = (Helper and Helper.PANEL_LAYOUT_DEFAULTS and Helper.PANEL_LAYOUT_DEFAULTS.readyGlowColor) or { 1, 0.82, 0.2, 1 }
	local normalizedGlowColor = Helper.NormalizeColor(glowColor, fallbackColor)
	local normalizedGlowStyle = Helper.NormalizeGlowStyle(glowStyle, "BLIZZARD")
	local normalizedGlowInset = Helper.NormalizeGlowInset(glowInset, 0)
	local pixelBorder = requestedPixelBorder
	local pixelCount = requestedPixelCount
	local pixelSpeed = requestedPixelSpeed
	local pixelThickness = requestedPixelThickness
	local shapeChanged = state.shape ~= frame._eqolGlowShape
	local colorChanged = false
	local styleChanged = state.style ~= normalizedGlowStyle
	local insetChanged = state.inset ~= normalizedGlowInset
	local pixelChanged = normalizedGlowStyle == "PIXEL"
		and (state.pixelBorder ~= pixelBorder or state.pixelCount ~= pixelCount or state.pixelSpeed ~= pixelSpeed or state.pixelThickness ~= pixelThickness)
	local visualThicknessChanged = (normalizedGlowStyle == "PULSING" or normalizedGlowStyle == "MARCHING_ANTS" or normalizedGlowStyle == "FLASH" or normalizedGlowStyle == "SOLID")
		and state.pixelThickness ~= pixelThickness
	local borderTintChanged = normalizedGlowStyle == "TINT_BORDER" and state.requestedBorderTintVersion ~= requestedBorderTintVersion
	local currentGlowColor = state.color
	colorChanged = not currentGlowColor
		or currentGlowColor[1] ~= normalizedGlowColor[1]
		or currentGlowColor[2] ~= normalizedGlowColor[2]
		or currentGlowColor[3] ~= normalizedGlowColor[3]
		or currentGlowColor[4] ~= normalizedGlowColor[4]
	if Glow and (not wasEnabled or colorChanged or styleChanged or insetChanged or pixelChanged or visualThicknessChanged or borderTintChanged or shapeChanged) then
		if styleChanged or shapeChanged then Glow.Stop(frame, glowKey, true) end
		Glow.Start(frame, glowKey, normalizedGlowStyle, {
			color = normalizedGlowColor,
			cooldown = frame.cooldown,
			inset = normalizedGlowInset,
			border = pixelBorder,
			count = pixelCount,
			frequency = pixelSpeed,
			thickness = pixelThickness,
			shape = frame._eqolGlowShape,
			hostFrameLevelOffset = requestedHostFrameLevelOffset,
			frameLevel = requestedFrameLevel,
		})
	end
	state.enabled = true
	state.style = normalizedGlowStyle
	state.inset = normalizedGlowInset
	state.pixelBorder = pixelBorder
	state.pixelCount = pixelCount
	state.pixelSpeed = pixelSpeed
	state.pixelThickness = pixelThickness
	state.shape = frame._eqolGlowShape
	state.hostFrameLevelOffset = requestedHostFrameLevelOffset
	state.frameLevel = requestedFrameLevel
	state.requestedColorR = requestedColorR
	state.requestedColorG = requestedColorG
	state.requestedColorB = requestedColorB
	state.requestedColorA = requestedColorA
	state.requestedStyle = glowStyle
	state.requestedInset = glowInset
	state.requestedBorderTintVersion = requestedBorderTintVersion
	state.condition = glowCondition
	state.alphaOn = alphaOn
	state.alphaOff = alphaOff
	if normalizedGlowColor then
		state.color = state.color or {}
		state.color[1] = normalizedGlowColor[1]
		state.color[2] = normalizedGlowColor[2]
		state.color[3] = normalizedGlowColor[3]
		state.color[4] = normalizedGlowColor[4]
	else
		state.color = nil
	end
	if Glow then
		if glowCondition ~= nil then
			Glow.SetAlphaFromBoolean(frame, glowKey, glowCondition, alphaOn, alphaOff)
		else
			Glow.SetAlpha(frame, glowKey, alphaOn)
		end
	end
end

local PREVIEW_GLOW_KEY = "EQOL_PREVIEW"

local function stopGlowKeys(frame, ...)
	if not frame then return end
	for i = 1, select("#", ...) do
		local glowKey = select(i, ...)
		if glowKey then setGlow(frame, false, nil, glowKey) end
	end
end

local function setPreviewGlow(frame, enabled, glowColor, glowStyle, glowInset, glowOptions, nativeAuraPreview)
	if not frame then return end
	if not enabled then
		setGlow(frame, false, nil, PREVIEW_GLOW_KEY)
		CooldownPanels.HidePreviewGlowBorder(frame)
		return
	end
	if Glow then
		CooldownPanels.HidePreviewGlowBorder(frame)
		if nativeAuraPreview then
			-- Match the native AuraButton glow at icon level +5: the shared
			-- preview renderer adds another +3, so lift its host by +2.
			setGlow(frame, true, glowColor, PREVIEW_GLOW_KEY, nil, nil, nil, glowStyle, glowInset, glowOptions, {
				hostFrameLevelOffset = 2,
				frameLevel = 3,
			})
		else
			setGlow(frame, true, glowColor, PREVIEW_GLOW_KEY, nil, nil, nil, glowStyle, glowInset, glowOptions)
		end
		return
	end
	setGlow(frame, false, nil, PREVIEW_GLOW_KEY)
	CooldownPanels.ShowPreviewGlowBorder(frame, glowColor)
end

function CooldownPanels.StopAllIconGlows(frame)
	if not frame then return end
	frame._eqolGlowState = nil
	if Glow then Glow.StopAll(frame) end
end

function CooldownPanels.GetReadyGlowPrimedState(runtime)
	if type(runtime) ~= "table" then return nil end
	local primed = runtime.readyGlowPrimed or runtime.itemReadyPrimed
	if type(primed) ~= "table" then primed = {} end
	runtime.readyGlowPrimed = primed
	runtime.itemReadyPrimed = primed
	return primed
end

function CooldownPanels.ClearReadyGlowEntryState(panelId, entryId, clearPrimed)
	if not panelId or not entryId then return end
	local runtime = getRuntime(panelId)
	runtime.readyAt = runtime.readyAt or {}
	runtime.glowTimers = runtime.glowTimers or {}
	runtime.readyAt[entryId] = nil
	local timer = runtime.glowTimers[entryId]
	if timer and timer.Cancel then timer:Cancel() end
	runtime.glowTimers[entryId] = nil
	if clearPrimed then
		local primed = CooldownPanels.GetReadyGlowPrimedState(runtime)
		if primed then primed[entryId] = nil end
	end
end

local function triggerReadyGlow(panelId, entryId, glowDuration)
	if not panelId or not entryId then return end
	local runtime = getRuntime(panelId)
	runtime.readyAt = runtime.readyAt or {}
	runtime.glowTimers = runtime.glowTimers or {}
	CooldownPanels.ClearReadyGlowEntryState(panelId, entryId, false)

	local now = Api.GetTime and Api.GetTime() or 0
	runtime.readyAt[entryId] = now
end

local function shouldArmReadySoundOnCooldownDone(data)
	if type(data) ~= "table" or data.soundReady ~= true or data.cooldownGCD == true then return false end
	if data.spellAuraOverlayActive == true then return false end
	if data.customCooldownDurationActive == true then return false end
	if data.resolvedType == "SPELL" then
		if data.chargesInfo and data.chargesInfo.maxCharges ~= nil then return false end
		return CooldownPanels.IsSpellCooldownInfoActive(data.cooldownIsActive, data.cooldownEnabled, data.cooldownStart, data.cooldownDuration)
	end
	if data.resolvedType == "ITEM" or data.resolvedType == "SLOT" then return CooldownPanels.IsSpellCooldownInfoActive(nil, true, data.cooldownStart, data.cooldownDuration) end
	return false
end

local function updateCooldownDoneContext(cooldown, panelId, entryId, data)
	if not (cooldown and panelId and entryId and type(data) == "table") then return end

	local sameEntry = cooldown._eqolPanelId == panelId and cooldown._eqolEntryId == entryId
	local armReadySound = shouldArmReadySoundOnCooldownDone(data)
	local preserveReadySound = not armReadySound and data.cooldownGCD == true and sameEntry and cooldown._eqolSoundReady == true and cooldown._eqolSoundName ~= nil

	cooldown._eqolPanelId = panelId
	cooldown._eqolEntryId = entryId
	cooldown._eqolCooldownIsGCD = data.cooldownGCD == true
	cooldown._eqolSpellId = data.spellId
	cooldown._eqolBaseSpellId = data.baseSpellId
	cooldown._eqolEffectiveSpellId = data.effectiveSpellId
	cooldown._eqolCustomCooldownKey = data.customCooldownDurationActive == true and data.customCooldownDurationKey or nil
	cooldown._eqolSoundName = data.soundName
	if armReadySound then
		cooldown._eqolSoundReady = true
		cooldown._eqolSoundReadyIgnoreGCD = nil
	elseif preserveReadySound then
		cooldown._eqolSoundReady = true
		cooldown._eqolSoundReadyIgnoreGCD = true
	else
		cooldown._eqolSoundReady = nil
		cooldown._eqolSoundReadyIgnoreGCD = nil
	end
	cooldown._eqolGlowReady = data.glowReady
	cooldown._eqolGlowDuration = data.glowDuration
end

local function clearCooldownDoneState(cooldown)
	if not cooldown then return end
	cooldown._eqolSoundReady = nil
	cooldown._eqolSoundReadyIgnoreGCD = nil
	cooldown._eqolGlowReady = nil
	cooldown._eqolCustomCooldownKey = nil
	if cooldown.SetScript then cooldown:SetScript("OnCooldownDone", nil) end
end

local function isCooldownPanelRuntimeActive(panelId)
	local runtime = CooldownPanels and CooldownPanels.runtime
	local enabledPanels = runtime and runtime.enabledPanels
	if enabledPanels then return panelId and enabledPanels[panelId] == true end
	return true
end

local function onCooldownDone(self)
	if not self then return end
	if not isCooldownPanelRuntimeActive(self._eqolPanelId) then
		clearCooldownDoneState(self)
		return
	end

	-- Never trigger sound/glow for GCD-only cooldowns.
	local isGCD = self._eqolCooldownIsGCD == true
	local allowSoundDuringGCD = self._eqolSoundReadyIgnoreGCD == true

	if not isGCD or allowSoundDuringGCD then
		-- Sound should only fire once per displayed cooldown.
		if self._eqolSoundReady then
			playSoundName(self._eqolSoundName)
			self._eqolSoundReady = nil
			self._eqolSoundReadyIgnoreGCD = nil
		end
	end

	if not isGCD then
		if self._eqolCustomCooldownKey and CooldownPanels and CooldownPanels.ClearEntryCustomCooldownDuration then
			CooldownPanels:ClearEntryCustomCooldownDuration(self._eqolPanelId, self._eqolEntryId, true)
			self._eqolCustomCooldownKey = nil
		end

		if CooldownPanels and CooldownPanels.InvalidateSpellCooldownCachesForAliases then
			CooldownPanels:InvalidateSpellCooldownCachesForAliases(self._eqolSpellId)
			CooldownPanels:InvalidateSpellCooldownCachesForAliases(self._eqolBaseSpellId)
			CooldownPanels:InvalidateSpellCooldownCachesForAliases(self._eqolEffectiveSpellId)
		end

		-- Glow trigger is purely event-driven (robust in secret environments).
		if self._eqolGlowReady then triggerReadyGlow(self._eqolPanelId, self._eqolEntryId, self._eqolGlowDuration) end
	end

	if CooldownPanels and CooldownPanels.RequestPanelRefresh then
		CooldownPanels:RequestPanelRefresh(self._eqolPanelId)
	elseif CooldownPanels and CooldownPanels.RefreshPanel and self._eqolPanelId then
		CooldownPanels:RefreshPanel(self._eqolPanelId)
	end
	-- if CooldownPanels and CooldownPanels.RequestUpdate then CooldownPanels:RequestUpdate() end
end

local function isSafeNumber(value) return type(value) == "number" and (not Api.issecretvalue or not Api.issecretvalue(value)) end

local function isSafeGreaterThan(value, threshold)
	if not isSafeNumber(value) or not isSafeNumber(threshold) then return false end
	return value > threshold
end

local function isSafeLessThan(a, b)
	if not isSafeNumber(a) or not isSafeNumber(b) then return false end
	return a < b
end

local function isSafeNotFalse(value)
	if Api.issecretvalue and Api.issecretvalue(value) then return true end
	return value ~= false
end

local function isCooldownActive(startTime, duration)
	if not isSafeNumber(startTime) or not isSafeNumber(duration) then return false end
	if duration <= 0 or startTime <= 0 then return false end
	if not Api.GetTime then return false end
	return (startTime + duration) > Api.GetTime()
end

function CooldownPanels:GetDurationNow()
	local durationUtil = _G.C_DurationUtil
	if durationUtil and durationUtil.GetCurrentTime then return durationUtil.GetCurrentTime() end
	return (Api.GetTime and Api.GetTime()) or GetTime()
end

function CooldownPanels:SupportsEntryCustomCooldownDuration(entry, resolvedType)
	if not entry then return false end
	if entry.type == "CDM_AURA" or entry.type == "STANCE" then return false end
	local typeKey = resolvedType
	if not typeKey then
		if entry.type == "MACRO" then
			local macro = CooldownPanels.ResolveMacroEntry and CooldownPanels.ResolveMacroEntry(entry) or nil
			typeKey = macro and macro.kind or entry.type
		else
			typeKey = entry.type
		end
	end
	return typeKey == "SPELL" or typeKey == "ITEM" or typeKey == "SLOT"
end

function CooldownPanels:GetAutoCooldownDurationInfoForItemID(itemID)
	itemID = tonumber(itemID)
	if not itemID then return nil end
	local map = self.autoCooldownDurationByItemID
	local info = map and map[itemID] or nil
	local duration = info and tonumber(info.duration) or nil
	if not (duration and duration > 0) then return nil end
	local maxDuration = Helper.CUSTOM_COOLDOWN_DURATION_MAX or 300
	if duration > maxDuration then duration = maxDuration end
	return info, duration
end

function CooldownPanels:GetAutoCooldownDurationInfoForSpellID(spellID)
	spellID = tonumber(spellID)
	if not spellID then return nil end
	local map = self.autoCooldownDurationBySpellID
	local info = map and map[spellID] or nil
	if not info then
		local aliases = self:GetSpellAliasIDs(spellID)
		for i = 1, #aliases do
			info = map and map[aliases[i]] or nil
			if info then break end
		end
	end
	local duration = info and tonumber(info.duration) or nil
	if not (duration and duration > 0) then return nil end
	local maxDuration = Helper.CUSTOM_COOLDOWN_DURATION_MAX or 300
	if duration > maxDuration then duration = maxDuration end
	return info, duration
end

function CooldownPanels:GetEntryAutoCooldownDurationInfo(entry, resolvedType)
	if not entry then return nil end
	local typeKey = resolvedType or entry.type
	if typeKey == "SPELL" then
		local spellID = tonumber(entry.spellID)
		if not spellID and entry.type == "MACRO" then
			local macro = CooldownPanels.ResolveMacroEntry and CooldownPanels.ResolveMacroEntry(entry) or nil
			if macro and macro.kind == "SPELL" then spellID = tonumber(macro.spellID) end
		end
		return self:GetAutoCooldownDurationInfoForSpellID(spellID)
	elseif typeKey == "ITEM" then
		local itemID = tonumber(entry.itemID)
		if itemID and entry.type == "ITEM" then itemID = self.ResolveEntryItemID(entry, itemID) end
		return self:GetAutoCooldownDurationInfoForItemID(itemID)
	elseif typeKey == "SLOT" then
		local slotID = tonumber(entry.slotID)
		local itemID = slotID and Api.GetInventoryItemID and Api.GetInventoryItemID("player", slotID) or nil
		return self:GetAutoCooldownDurationInfoForItemID(itemID)
	end
	return nil
end

function CooldownPanels:GetEntryNativeAuraItemInfo(entry, resolvedType)
	if not (entry and entry.autoCooldownDurationEnabled == true and self.AuraContainers and self.AuraPresets and self.AuraPresets.GetItemSpellIDs) then
		return nil, false, nil
	end
	local typeKey = resolvedType or entry.type
	if typeKey ~= "SLOT" then return nil, false, nil end
	local slotID = tonumber(entry.slotID)
	if slotID ~= 13 and slotID ~= 14 then return nil, false, nil end
	local itemID = Api.GetInventoryItemID and Api.GetInventoryItemID("player", slotID) or nil
	if not itemID then return nil, false, nil end
	local spellIDs, knownItem = self.AuraPresets:GetItemSpellIDs("TRINKET_UPTIME", itemID, entry)
	return spellIDs, knownItem == true, itemID
end

function CooldownPanels:GetActiveProcTriggerInfoForItemID(itemID)
	itemID = tonumber(itemID)
	if not itemID then return nil end
	local map = self.activeProcTriggerByItemID
	local info = map and map[itemID] or nil
	local triggerSpellID
	self:ForEachActiveProcTriggerSpellID(info, function(candidateSpellID)
		if not triggerSpellID then triggerSpellID = candidateSpellID end
	end)
	local duration = self:GetActiveProcTriggerConfiguredDuration(info)
	if not (triggerSpellID and triggerSpellID > 0 and duration and duration > 0) then return nil end
	return info, triggerSpellID, duration
end

function CooldownPanels:IsEntryTrinketSlot(entry, resolvedType)
	if not entry then return false end
	local typeKey = resolvedType or entry.type
	if typeKey ~= "SLOT" then return false end
	local slotID = tonumber(entry.slotID)
	if not slotID then return false end
	return slotID == 13 or slotID == 14
end

function CooldownPanels:SupportsEntryAutoCooldownDuration(entry, resolvedType)
	if self:IsEntryTrinketSlot(entry, resolvedType) then return true end
	if (resolvedType or (entry and entry.type)) == "SLOT" and self.SupportsEntryActiveProcTrigger and self:SupportsEntryActiveProcTrigger(entry, resolvedType) then return true end
	local _, duration = self:GetEntryAutoCooldownDurationInfo(entry, resolvedType)
	return duration ~= nil
end

function CooldownPanels:SupportsEntryActiveProcTrigger(entry, resolvedType)
	if not entry then return false end
	local typeKey = resolvedType or entry.type
	if typeKey == "ITEM" then
		local itemID = tonumber(entry.itemID)
		if itemID and entry.type == "ITEM" then itemID = self.ResolveEntryItemID(entry, itemID) end
		return self:GetActiveProcTriggerInfoForItemID(itemID) ~= nil
	elseif typeKey == "SLOT" then
		local slotID = tonumber(entry.slotID)
		if slotID ~= 13 and slotID ~= 14 then return false end
		local itemID = slotID and Api.GetInventoryItemID and Api.GetInventoryItemID("player", slotID) or nil
		return self:GetActiveProcTriggerInfoForItemID(itemID) ~= nil
	end
	return false
end

function CooldownPanels:SupportsEntryCDMAuraOverlay(entry, resolvedType)
	if not entry then return false end
	local typeKey = resolvedType or entry.type
	if typeKey ~= "SPELL" or entry.type ~= "SPELL" then return false end
	local spellID = tonumber(entry.spellID)
	local cdmAuras = self.CDMAuras
	if not (spellID and cdmAuras and cdmAuras.SupportsSpellAuraOverlay) then return false end
	local candidates = self:GetEntryAuraOverlaySpellIDs(entry, spellID)
	for i = 1, #candidates do
		if cdmAuras:SupportsSpellAuraOverlay(candidates[i]) then return true end
	end
	return false
end

function CooldownPanels:GetEntryAuraOverlaySpellIDs(entry, fallbackSpellID)
	local configured = entry and entry.cdmAuraOverlaySpellIDs
	local source = type(configured) == "table" and #configured > 0 and configured or { fallbackSpellID or entry and entry.spellID }
	local candidates, seen = {}, {}
	for i = 1, #source do
		local spellID = tonumber(source[i])
		if spellID and spellID > 0 then
			candidates, seen = self:GetEntrySpellAliasIDs(entry, spellID, candidates, seen)
			local effectiveSpellID, resolvedSpellID = self:ResolveEntryTrackedSpellID(entry, spellID)
			if effectiveSpellID then candidates, seen = self:GetEntrySpellAliasIDs(entry, effectiveSpellID, candidates, seen) end
			if resolvedSpellID then candidates, seen = self:GetEntrySpellAliasIDs(entry, resolvedSpellID, candidates, seen) end
		end
	end
	return candidates, seen
end

function CooldownPanels:NormalizeEntryAuraOverlaySpellIDs(value)
	local normalized, seen, invalid = {}, {}, {}
	local function add(candidate)
		if type(candidate) == "string" and not candidate:match("^%d+$") then
			invalid[#invalid + 1] = candidate
			return
		end
		local spellID = tonumber(candidate)
		if not spellID or spellID <= 0 or spellID ~= math.floor(spellID) then
			invalid[#invalid + 1] = tostring(candidate or "")
			return
		end
		if seen[spellID] then return end
		seen[spellID] = true
		normalized[#normalized + 1] = spellID
	end
	if type(value) == "table" then
		for _, candidate in ipairs(value) do add(candidate) end
	elseif type(value) == "string" then
		for candidate in value:gmatch("[^,%s;]+") do add(candidate) end
	elseif value ~= nil then
		add(value)
	end
	table.sort(normalized)
	return normalized, invalid
end

function CooldownPanels:FormatEntryAuraOverlaySpellIDs(value)
	local normalized = self:NormalizeEntryAuraOverlaySpellIDs(value)
	local text = {}
	for i = 1, #normalized do text[i] = tostring(normalized[i]) end
	return table.concat(text, ", ")
end

function CooldownPanels:GetEntryAuraUnit(entry, effectiveType)
	if not entry then return "player" end
	if effectiveType == "CDM_AURA" then return Helper.NormalizeAuraUnit(entry.auraUnit) end
	return Helper.NormalizeAuraUnit(entry.cdmAuraOverlayUnit)
end

function CooldownPanels:SetEntryAuraUnit(entry, effectiveType, value)
	if not entry then return false end
	local unitToken = Helper.NormalizeAuraUnit(value)
	if self:GetEntryAuraUnit(entry, effectiveType) == unitToken then return false end
	if effectiveType == "CDM_AURA" then
		entry.auraUnit = unitToken
		entry.auraFilter = unitToken == "target" and "HARMFUL|PLAYER" or Helper.IsAuraGroupUnit(unitToken) and "HELPFUL|PLAYER" or "HELPFUL"
	else
		entry.cdmAuraOverlayUnit = unitToken
	end
	return true
end

function CooldownPanels:SetEntryAuraOverlaySpellIDs(entry, value)
	if type(entry) ~= "table" then return false end
	local normalized, invalid = self:NormalizeEntryAuraOverlaySpellIDs(value)
	if #invalid > 0 then return false, invalid end
	entry.cdmAuraOverlaySpellIDs = #normalized > 0 and normalized or nil
	return true
end

function CooldownPanels:IsEntryCDMAuraOverlayEnabled(layout, entry, resolvedType)
	if not entry then return false end
	local typeKey = resolvedType or entry.type
	if typeKey ~= "SPELL" or entry.type ~= "SPELL" then return false end
	if entry.customCooldownDurationEnabled == true then return false end
	if entry.customCooldownDurationOnCooldownEnabled == true then return false end
	return entry.cdmAuraOverlayEnabled == true or (layout and layout.cdmAuraOverlayEnabled == true)
end

function CooldownPanels:ResolveEntryCDMAuraOverlayColor(layout, entry)
	local panelColor = Helper.NormalizeColor(layout and layout.cdmAuraOverlayColor, Helper.PANEL_LAYOUT_DEFAULTS.cdmAuraOverlayColor or Helper.ACTIVATION_OVERLAY_COLOR_DEFAULT)
	if entry and entry.cdmAuraOverlayColorUseGlobal == false then
		return CooldownPanels.ResolveCachedEntryColor("activationOverlayEntry", entry, entry.activationOverlayColor or entry.cdmAuraOverlayColor, panelColor)
	end
	return panelColor
end

function CooldownPanels:ResolveEntryActivationOverlayReverse(layout, entry)
	if entry and entry.activationOverlayBehaviorUseGlobal == false then return entry.activationOverlayReverse ~= false end
	return not layout or layout.activationOverlayReverse ~= false
end

function CooldownPanels:ResolveEntryActivationOverlayOnly(layout, entry)
	if entry and entry.activationOverlayBehaviorUseGlobal == false then return entry.activationOverlayOnly == true end
	return layout and layout.activationOverlayOnly == true or false
end

function CooldownPanels:ResolveEntryActivationOverlayGlow(layout, entry)
	if entry and entry.activationOverlayBehaviorUseGlobal == false then return entry.activationOverlayGlow == true end
	return layout and layout.activationOverlayGlow == true or false
end

function CooldownPanels:ResolveEntryActivationOverlayGlowColor(layout, entry)
	local _, readyGlowColor = self:ResolveEntryGlowStyle(layout, entry)
	local panelColor = Helper.NormalizeColor(layout and layout.activationOverlayGlowColor, readyGlowColor)
	if entry and entry.activationOverlayBehaviorUseGlobal == false then
		return CooldownPanels.ResolveCachedEntryColor("activationOverlayGlowEntry", entry, entry.activationOverlayGlowColor, panelColor)
	end
	return panelColor
end

function CooldownPanels:ResolveEntryActivationOverlayColor(layout, entry)
	local panelColor = Helper.NormalizeColor(layout and layout.cdmAuraOverlayColor, Helper.PANEL_LAYOUT_DEFAULTS.cdmAuraOverlayColor or Helper.ACTIVATION_OVERLAY_COLOR_DEFAULT)
	if entry and entry.activationOverlayBehaviorUseGlobal == false then
		return CooldownPanels.ResolveCachedEntryColor("activationOverlayEntry", entry, entry.activationOverlayColor, panelColor)
	end
	return panelColor
end

function CooldownPanels:GetEntryCustomCooldownDuration(entry, resolvedType, triggerMode)
	if not self:SupportsEntryCustomCooldownDuration(entry, resolvedType) then return nil end
	if entry.autoCooldownDurationEnabled == true then
		local _, nativeAuraItem = self:GetEntryNativeAuraItemInfo(entry, resolvedType)
		if not nativeAuraItem then
			local autoInfo, autoDuration = self:GetEntryAutoCooldownDurationInfo(entry, resolvedType)
			local autoTriggerMode = autoInfo and autoInfo.triggerMode == "cooldown" and "cooldown" or "activation"
			if autoDuration and (triggerMode == nil or triggerMode == autoTriggerMode) then return autoDuration end
		end
	end
	local enabled = entry.customCooldownDurationEnabled == true or entry.customCooldownDurationOnCooldownEnabled == true
	if triggerMode == "activation" then
		enabled = entry.customCooldownDurationEnabled == true
	elseif triggerMode == "cooldown" then
		enabled = entry.customCooldownDurationOnCooldownEnabled == true
	end
	if enabled ~= true then return nil end
	local duration = tonumber(entry.customCooldownDuration)
	if not duration or duration <= 0 then return nil end
	local maxDuration = Helper.CUSTOM_COOLDOWN_DURATION_MAX or 300
	if duration > maxDuration then duration = maxDuration end
	return duration
end

function CooldownPanels:GetEntryActiveProcTriggerInfo(entry, resolvedType)
	if not entry then return nil end
	local typeKey = resolvedType or entry.type
	if typeKey == "ITEM" then
		local itemID = tonumber(entry.itemID)
		if itemID and entry.type == "ITEM" then itemID = self.ResolveEntryItemID(entry, itemID) end
		local info, triggerSpellID, duration = self:GetActiveProcTriggerInfoForItemID(itemID)
		if info then return info, triggerSpellID, itemID, duration end
	elseif typeKey == "SLOT" then
		local slotID = tonumber(entry.slotID)
		if slotID ~= 13 and slotID ~= 14 then return nil end
		local itemID = slotID and Api.GetInventoryItemID and Api.GetInventoryItemID("player", slotID) or nil
		local info, triggerSpellID, duration = self:GetActiveProcTriggerInfoForItemID(itemID)
		if info then return info, triggerSpellID, itemID, duration end
	end
	return nil
end

function CooldownPanels:GetActiveProcTriggerKind(info, triggerSpellID)
	triggerSpellID = tonumber(triggerSpellID)
	if not (info and triggerSpellID) then return nil end
	if tonumber(info.triggerSpellID) == triggerSpellID then return "trigger" end
	if type(info.triggerSpellIDs) == "table" then
		for i = 1, #info.triggerSpellIDs do
			if tonumber(info.triggerSpellIDs[i]) == triggerSpellID then return "trigger" end
		end
	end
	if tonumber(info.startTriggerSpellID) == triggerSpellID then return "start" end
	if tonumber(info.stackTriggerSpellID) == triggerSpellID then return "stack" end
	return nil
end

function CooldownPanels:GetActiveProcTriggerConfiguredDuration(info, triggerKind)
	if not info then return nil end
	if triggerKind == "start" then return tonumber(info.startDuration or info.duration) end
	if triggerKind == "stack" then return tonumber(info.stackDuration or info.duration) end
	return tonumber(info.duration or info.triggerDuration or info.stackDuration or info.startDuration)
end

function CooldownPanels:ForEachActiveProcTriggerSpellID(info, callback)
	if not (info and callback) then return end
	local function handle(triggerSpellID)
		triggerSpellID = tonumber(triggerSpellID)
		if triggerSpellID and triggerSpellID > 0 then callback(triggerSpellID) end
	end
	handle(info.triggerSpellID)
	if type(info.triggerSpellIDs) == "table" then
		for i = 1, #info.triggerSpellIDs do
			handle(info.triggerSpellIDs[i])
		end
	end
	handle(info.startTriggerSpellID)
	handle(info.stackTriggerSpellID)
end

function CooldownPanels:GetActiveEntryProcTriggerDuration(panelId, entryId, entry, resolvedType)
	if not (entry and entry.autoCooldownDurationEnabled == true) then return nil end
	local _, nativeAuraItem = self:GetEntryNativeAuraItemInfo(entry, resolvedType)
	if nativeAuraItem then return nil end
	local info, triggerSpellID, itemID, duration = self:GetEntryActiveProcTriggerInfo(entry, resolvedType)
	if not info then return nil end
	local runtime = self.runtime
	local store = runtime and runtime.activeProcTriggerDurations
	local key = Helper.GetEntryKey(panelId, entryId)
	local record = store and store[key] or nil
	if not record then return nil end
	self:CleanupActiveProcTriggerRecord(record)
	if record.stackMode == true and (tonumber(record.stackCount) or 0) <= 0 then return nil end
	local startTime = tonumber(record.startTime)
	duration = tonumber(record.duration) or duration
	local endTime = tonumber(record.endTime)
	if not (startTime and duration and duration > 0 and endTime) then
		self:ClearEntryActiveProcTriggerDuration(panelId, entryId, true)
		return nil
	end
	local now = self:GetDurationNow()
	if now >= endTime then
		self:ClearEntryActiveProcTriggerDuration(panelId, entryId, true)
		return nil
	end
	return {
		key = "procTrigger:" .. tostring(itemID or triggerSpellID) .. ":" .. tostring(panelId) .. ":" .. tostring(entryId),
		durationObject = record.durationObject,
		startTime = startTime,
		duration = duration,
		endTime = endTime,
		stackCount = tonumber(record.stackCount),
		rate = 1,
	}
end

function CooldownPanels:GetCustomCooldownDurationStore()
	self.runtime = self.runtime or {}
	local runtime = self.runtime
	runtime.customCooldownDurations = runtime.customCooldownDurations or {}
	runtime.customCooldownDurationTimers = runtime.customCooldownDurationTimers or {}
	runtime.customCooldownDurationStackTimers = runtime.customCooldownDurationStackTimers or {}
	return runtime.customCooldownDurations, runtime.customCooldownDurationTimers
end

function CooldownPanels:ScheduleCustomCooldownStackCleanup(panelId, entryId)
	local runtime = self.runtime
	if not runtime then return end
	local key = Helper.GetEntryKey(panelId, entryId)
	runtime.customCooldownDurationStackTimers = runtime.customCooldownDurationStackTimers or {}
	local timers = runtime.customCooldownDurationStackTimers
	local oldTimer = timers[key]
	if oldTimer and oldTimer.Cancel then oldTimer:Cancel() end
	local store = runtime.customCooldownDurations
	local record = store and store[key] or nil
	if not record then
		timers[key] = nil
		return
	end
	local now = self:GetDurationNow()
	local nextExpiration
	for i = 1, #(record.stackExpirations or {}) do
		local expiration = tonumber(record.stackExpirations[i])
		if expiration and expiration > now and (not nextExpiration or expiration < nextExpiration) then nextExpiration = expiration end
	end
	if not nextExpiration then
		timers[key] = nil
		return
	end
	timers[key] = C_Timer and C_Timer.NewTimer and C_Timer.NewTimer(math.max(nextExpiration - now, 0.01), function()
		local currentStore = CooldownPanels.runtime and CooldownPanels.runtime.customCooldownDurations
		local current = currentStore and currentStore[key] or nil
		if current then
			CooldownPanels:CleanupActiveProcTriggerRecord(current)
			if (tonumber(current.stackCount) or 0) <= 0 then
				CooldownPanels:ClearEntryCustomCooldownDuration(panelId, entryId)
			else
				if CooldownPanels.RequestPanelRefresh then
					CooldownPanels:RequestPanelRefresh(panelId)
				elseif CooldownPanels:GetPanel(panelId) then
					CooldownPanels:RefreshPanel(panelId)
				end
				CooldownPanels:ScheduleCustomCooldownStackCleanup(panelId, entryId)
			end
		end
	end) or nil
end

function CooldownPanels:ClearEntryCustomCooldownDuration(panelId, entryId, suppressRefresh)
	panelId = normalizeId(panelId)
	entryId = normalizeId(entryId)
	if not (panelId and entryId and self.runtime) then return false end
	local key = Helper.GetEntryKey(panelId, entryId)
	local store = self.runtime.customCooldownDurations
	local timers = self.runtime.customCooldownDurationTimers
	local stackTimers = self.runtime.customCooldownDurationStackTimers
	local hadRecord = store and store[key] ~= nil
	if store then store[key] = nil end
	local timer = timers and timers[key] or nil
	if timer and timer.Cancel then timer:Cancel() end
	if timers then timers[key] = nil end
	local stackTimer = stackTimers and stackTimers[key] or nil
	if stackTimer and stackTimer.Cancel then stackTimer:Cancel() end
	if stackTimers then stackTimers[key] = nil end
	if hadRecord and not suppressRefresh then
		if self.RequestPanelRefresh then
			self:RequestPanelRefresh(panelId)
		elseif self:GetPanel(panelId) then
			self:RefreshPanel(panelId)
		end
	end
	return hadRecord
end

function CooldownPanels:ClearPanelCustomCooldownDurations(panelId)
	panelId = normalizeId(panelId)
	if not (panelId and self.runtime) then return false end
	local store = self.runtime.customCooldownDurations
	local timers = self.runtime.customCooldownDurationTimers
	local stackTimers = self.runtime.customCooldownDurationStackTimers
	if not store then return false end
	local prefix = tostring(panelId) .. ":"
	local changed = false
	for key in pairs(store) do
		if tostring(key):sub(1, #prefix) == prefix then
			store[key] = nil
			local timer = timers and timers[key] or nil
			if timer and timer.Cancel then timer:Cancel() end
			if timers then timers[key] = nil end
			local stackTimer = stackTimers and stackTimers[key] or nil
			if stackTimer and stackTimer.Cancel then stackTimer:Cancel() end
			if stackTimers then stackTimers[key] = nil end
			changed = true
		end
	end
	return changed
end

function CooldownPanels:GetActiveEntryCustomCooldownDuration(panelId, entryId, entry, resolvedType)
	local duration = self:GetEntryCustomCooldownDuration(entry, resolvedType)
	if not duration then return nil end
	panelId = normalizeId(panelId)
	entryId = normalizeId(entryId)
	if not (panelId and entryId and self.runtime) then return nil end
	local store = self.runtime.customCooldownDurations
	local key = Helper.GetEntryKey(panelId, entryId)
	local record = store and store[key] or nil
	if not record then return nil end
	local now = self:GetDurationNow()
	if record.stackMode == true then
		self:CleanupActiveProcTriggerRecord(record, now)
		if (tonumber(record.stackCount) or 0) <= 0 then
			self:ClearEntryCustomCooldownDuration(panelId, entryId, true)
			return nil
		end
	end
	local startTime = tonumber(record.startTime)
	local endTime = tonumber(record.endTime)
	local recordDuration = tonumber(record.duration) or duration
	if not (startTime and endTime and recordDuration and recordDuration > 0) or now >= endTime then
		self:ClearEntryCustomCooldownDuration(panelId, entryId, true)
		return nil
	end
	local durationObject = record.durationObject
	if durationObject and durationObject.GetRemainingDuration then
		local remaining = durationObject.GetRemainingDuration(durationObject, Api.DurationModifierRealTime)
		if isSafeNumber(remaining) and remaining <= 0 then
			self:ClearEntryCustomCooldownDuration(panelId, entryId, true)
			return nil
		end
	end
	return {
		key = key,
		durationObject = durationObject,
		startTime = startTime,
		duration = recordDuration,
		endTime = endTime,
		stackCount = tonumber(record.stackCount),
		rate = 1,
	}
end

function CooldownPanels:StartEntryCustomCooldownDuration(panelId, entryId, entry, resolvedType, triggerMode)
	local duration = self:GetEntryCustomCooldownDuration(entry, resolvedType, triggerMode)
	if not duration then return false end
	panelId = normalizeId(panelId)
	entryId = normalizeId(entryId)
	if not (panelId and entryId) then return false end
	local now = self:GetDurationNow()
	local durationObject
	local durationUtil = _G.C_DurationUtil
	if durationUtil and durationUtil.CreateDuration then
		durationObject = durationUtil.CreateDuration()
		if durationObject and durationObject.SetTimeFromStart then durationObject:SetTimeFromStart(now, duration, 1) end
	end
	local store, timers = self:GetCustomCooldownDurationStore()
	local key = Helper.GetEntryKey(panelId, entryId)
	local oldTimer = timers[key]
	if oldTimer and oldTimer.Cancel then oldTimer:Cancel() end
	timers[key] = nil
	if triggerMode == "cooldown" and entry.customCooldownDurationOnCooldownMultipleStacks == true then
		local current = store[key]
		if type(current) ~= "table" then
			current = {
				stackCount = 0,
				stackExpirations = {},
				stackMode = true,
			}
			store[key] = current
		end
		current.stackExpirations = current.stackExpirations or {}
		current.stackExpirations[#current.stackExpirations + 1] = now + duration
		current.durationObject = durationObject
		current.startTime = now
		current.duration = duration
		current.endTime = now + duration
		current.stackMode = true
		self:CleanupActiveProcTriggerRecord(current, now)
		self:ScheduleCustomCooldownStackCleanup(panelId, entryId)
		return true
	end
	store[key] = {
		durationObject = durationObject,
		startTime = now,
		duration = duration,
		endTime = now + duration,
	}
	if C_Timer and C_Timer.NewTimer then
		timers[key] = C_Timer.NewTimer(duration, function()
			local currentStore = CooldownPanels.runtime and CooldownPanels.runtime.customCooldownDurations
			local current = currentStore and currentStore[key] or nil
			if current and current.startTime == now and current.duration == duration then CooldownPanels:ClearEntryCustomCooldownDuration(panelId, entryId) end
		end)
	end
	return true
end

function CooldownPanels:ApplyCustomCooldownDurationState(data, customState)
	if not data then return end
	if not customState then
		data.customCooldownDurationActive = false
		data.customCooldownDurationKey = nil
		data.customCooldownDurationObject = nil
		data.customCooldownStart = nil
		data.customCooldownDuration = nil
		return
	end
	data.customCooldownDurationActive = true
	data.customCooldownDurationKey = customState.key
	data.customCooldownDurationObject = customState.durationObject
	data.customCooldownStart = customState.startTime
	data.customCooldownDuration = customState.duration
	data.cooldownStart = customState.startTime or data.cooldownStart or 0
	data.cooldownDuration = customState.duration or data.cooldownDuration or 0
	data.cooldownEnabled = true
	data.cooldownIsActive = true
	data.cooldownRate = customState.rate or 1
	data.cooldownGCD = false
	data.cooldownDurationObject = customState.durationObject
end

function CooldownPanels:ApplyActivationOverlayVisualState(data, entry)
	if not data then return end
	local active = data.customCooldownDurationActive == true or data.spellAuraOverlayActive == true
	local spellAuraOverlayActive = data.spellAuraOverlayActive == true and data.customCooldownDurationActive ~= true
	data.activationOverlayActive = active
	data.activationOverlayReverse = CooldownPanels:ResolveEntryActivationOverlayReverse(data.layout, entry)
	data.cdmAuraOverlayReverse = entry and entry.cdmAuraOverlayReverse ~= false or true
	data.activationOverlayColor = spellAuraOverlayActive and CooldownPanels:ResolveEntryCDMAuraOverlayColor(data.layout, entry)
		or CooldownPanels:ResolveEntryActivationOverlayColor(data.layout, entry)
	data.activationOverlayOnly = CooldownPanels:ResolveEntryActivationOverlayOnly(data.layout, entry)
	data.activationOverlayGlow = CooldownPanels:ResolveEntryActivationOverlayGlow(data.layout, entry)
	data.activationOverlayGlowColor = active and data.activationOverlayGlow and CooldownPanels:ResolveEntryActivationOverlayGlowColor(data.layout, entry) or nil
	data.cooldownReverse = data.resolvedType == "CDM_AURA"
		or (spellAuraOverlayActive and data.cdmAuraOverlayReverse ~= false)
		or (active == true and not spellAuraOverlayActive and data.activationOverlayReverse ~= false)
end

function CooldownPanels:EntryUsesActivationOverlay(entry, resolvedType)
	if not entry then return false end
	return self:SupportsEntryCustomCooldownDuration(entry, resolvedType) or self:SupportsEntryActiveProcTrigger(entry, resolvedType) or self:SupportsEntryCDMAuraOverlay(entry, resolvedType)
end

function CooldownPanels:ShouldTriggerEntryCustomCooldownDuration(entry, castSpellId)
	local castId = tonumber(castSpellId)
	if not (entry and castId) then return false end
	if entry.customCooldownDurationEnabled ~= true and entry.autoCooldownDurationEnabled ~= true then return false end
	local macro = entry.type == "MACRO" and CooldownPanels.ResolveMacroEntry and CooldownPanels.ResolveMacroEntry(entry) or nil
	local resolvedType = (macro and macro.kind) or entry.type
	if not self:GetEntryCustomCooldownDuration(entry, resolvedType, "activation") then return false end
	if resolvedType == "SPELL" then
		local spellId = tonumber((macro and macro.spellID) or entry.spellID)
		if not spellId then return false end
		local aliases = self:GetSpellAliasIDs(spellId)
		for i = 1, #aliases do
			if aliases[i] == castId then return true end
		end
		return self:AreSpellVariantsEquivalent(spellId, castId)
	elseif resolvedType == "ITEM" then
		local itemId = tonumber((macro and macro.itemID) or entry.itemID)
		if itemId and entry.type == "ITEM" then itemId = self.ResolveEntryItemID(entry, itemId) end
		local itemSpellId = itemId and self:GetItemUseSpellID(itemId) or nil
		return itemSpellId and self:AreSpellVariantsEquivalent(itemSpellId, castId) or false
	elseif resolvedType == "SLOT" then
		local slotId = tonumber(entry.slotID)
		local itemId = slotId and Api.GetInventoryItemID and Api.GetInventoryItemID("player", slotId) or nil
		local itemSpellId = itemId and self:GetItemUseSpellID(itemId) or nil
		return itemSpellId and self:AreSpellVariantsEquivalent(itemSpellId, castId) or false
	end
	return false
end

function CooldownPanels:HandleCustomCooldownActivation(castSpellId)
	local spellId = tonumber(castSpellId)
	if not spellId then return false end
	local root = ensureRoot()
	local runtime = self.runtime
	local enabledPanels = runtime and runtime.enabledPanels
	if not (root and root.panels and enabledPanels and next(enabledPanels)) then return false end
	local panelsToRefresh = {}
	local started = false
	local panelIds = runtime and runtime.enabledPanelIds
	if panelIds and #panelIds > 0 then
		for i = 1, #panelIds do
			local panelId = panelIds[i]
			local panel = enabledPanels[panelId] and root.panels[panelId] or nil
			if panel and panel.entries then
				for _, entryId in ipairs(panel.order or {}) do
					local entry = panel.entries[entryId]
					if self:ShouldTriggerEntryCustomCooldownDuration(entry, spellId) then
						local macro = entry.type == "MACRO" and CooldownPanels.ResolveMacroEntry and CooldownPanels.ResolveMacroEntry(entry) or nil
						local resolvedType = (macro and macro.kind) or entry.type
						if self:StartEntryCustomCooldownDuration(panelId, entryId, entry, resolvedType, "activation") then
							panelsToRefresh[panelId] = true
							started = true
						end
					end
				end
			end
		end
	end
	for panelId in pairs(panelsToRefresh) do
		if self.RequestPanelRefresh then
			self:RequestPanelRefresh(panelId)
		elseif self:GetPanel(panelId) then
			self:RefreshPanel(panelId)
		end
	end
	return started
end

function CooldownPanels:ShouldTriggerEntryCustomCooldownOnCooldown(entry, eventSpellId, eventBaseSpellId)
	if not (entry and (entry.customCooldownDurationOnCooldownEnabled == true or entry.autoCooldownDurationEnabled == true)) then return false end
	local eventId = tonumber(eventSpellId)
	local baseEventId = tonumber(eventBaseSpellId)
	if not (eventId or baseEventId) then return false end
	local macro = entry.type == "MACRO" and CooldownPanels.ResolveMacroEntry and CooldownPanels.ResolveMacroEntry(entry) or nil
	local resolvedType = (macro and macro.kind) or entry.type
	if resolvedType ~= "SPELL" then return false end
	if not self:GetEntryCustomCooldownDuration(entry, resolvedType, "cooldown") then return false end
	local autoInfo = entry.autoCooldownDurationEnabled == true and self:GetEntryAutoCooldownDurationInfo(entry, resolvedType) or nil
	local requiredEventSpellID = autoInfo and tonumber(autoInfo.cooldownEventSpellID) or nil
	if requiredEventSpellID then return eventId == requiredEventSpellID end
	local spellId = tonumber((macro and macro.spellID) or entry.spellID)
	if not spellId then return false end
	local function matches(candidateId)
		candidateId = tonumber(candidateId)
		if not candidateId then return false end
		return self:AreSpellVariantsEquivalent(spellId, candidateId)
	end
	return matches(eventId) or matches(baseEventId)
end

function CooldownPanels:ShouldClearEntryCustomCooldownOnCooldown(entry, eventSpellId)
	if not (entry and entry.autoCooldownDurationEnabled == true) then return false end
	local eventId = tonumber(eventSpellId)
	if not eventId then return false end
	local macro = entry.type == "MACRO" and CooldownPanels.ResolveMacroEntry and CooldownPanels.ResolveMacroEntry(entry) or nil
	local resolvedType = (macro and macro.kind) or entry.type
	if resolvedType ~= "SPELL" then return false end
	local autoInfo = self:GetEntryAutoCooldownDurationInfo(entry, resolvedType)
	local clearEventSpellID = autoInfo and tonumber(autoInfo.cooldownClearEventSpellID) or nil
	return clearEventSpellID and eventId == clearEventSpellID or false
end

function CooldownPanels:HandleCustomCooldownCooldownEvent(eventSpellId, eventBaseSpellId)
	if not (eventSpellId or eventBaseSpellId) then return false end
	local root = ensureRoot()
	local runtime = self.runtime
	local enabledPanels = runtime and runtime.enabledPanels
	if not (root and root.panels and enabledPanels and next(enabledPanels)) then return false end
	local panelsToRefresh = {}
	local started = false
	local panelIds = runtime and runtime.enabledPanelIds
	if panelIds and #panelIds > 0 then
		for i = 1, #panelIds do
			local panelId = panelIds[i]
			local panel = enabledPanels[panelId] and root.panels[panelId] or nil
			if panel and panel.entries then
				for _, entryId in ipairs(panel.order or {}) do
					local entry = panel.entries[entryId]
					if self:ShouldTriggerEntryCustomCooldownOnCooldown(entry, eventSpellId, eventBaseSpellId) then
						local macro = entry.type == "MACRO" and CooldownPanels.ResolveMacroEntry and CooldownPanels.ResolveMacroEntry(entry) or nil
						local resolvedType = (macro and macro.kind) or entry.type
						if self:StartEntryCustomCooldownDuration(panelId, entryId, entry, resolvedType, "cooldown") then
							panelsToRefresh[panelId] = true
							started = true
						end
					elseif self:ShouldClearEntryCustomCooldownOnCooldown(entry, eventSpellId) then
						self:ClearEntryCustomCooldownDuration(panelId, entryId)
					end
				end
			end
		end
	end
	for panelId in pairs(panelsToRefresh) do
		if self.RequestPanelRefresh then
			self:RequestPanelRefresh(panelId)
		elseif self:GetPanel(panelId) then
			self:RefreshPanel(panelId)
		end
	end
	return started
end

function CooldownPanels:GetActiveProcTriggerDurationStore()
	self.runtime = self.runtime or {}
	local runtime = self.runtime
	runtime.activeProcTriggerDurations = runtime.activeProcTriggerDurations or {}
	runtime.activeProcTriggerDurationTimers = runtime.activeProcTriggerDurationTimers or {}
	runtime.activeProcTriggerStackTimers = runtime.activeProcTriggerStackTimers or {}
	return runtime.activeProcTriggerDurations, runtime.activeProcTriggerDurationTimers
end

function CooldownPanels:CleanupActiveProcTriggerRecord(record, now)
	if not record then return 0 end
	now = now or self:GetDurationNow()
	local expirations = record.stackExpirations
	if type(expirations) ~= "table" then
		record.stackCount = tonumber(record.stackCount) or 0
		return record.stackCount
	end
	local writeIndex = 1
	for i = 1, #expirations do
		local expiration = tonumber(expirations[i])
		if expiration and expiration > now then
			expirations[writeIndex] = expiration
			writeIndex = writeIndex + 1
		end
	end
	for i = writeIndex, #expirations do
		expirations[i] = nil
	end
	record.stackCount = writeIndex - 1
	return record.stackCount
end

function CooldownPanels:ScheduleActiveProcTriggerStackCleanup(panelId, entryId)
	local runtime = self.runtime
	if not runtime then return end
	local key = Helper.GetEntryKey(panelId, entryId)
	runtime.activeProcTriggerStackTimers = runtime.activeProcTriggerStackTimers or {}
	local timers = runtime.activeProcTriggerStackTimers
	local oldTimer = timers[key]
	if oldTimer and oldTimer.Cancel then oldTimer:Cancel() end
	local store = runtime.activeProcTriggerDurations
	local record = store and store[key] or nil
	if not record then
		timers[key] = nil
		return
	end
	local now = self:GetDurationNow()
	local nextExpiration
	for i = 1, #(record.stackExpirations or {}) do
		local expiration = tonumber(record.stackExpirations[i])
		if expiration and expiration > now and (not nextExpiration or expiration < nextExpiration) then nextExpiration = expiration end
	end
	if not nextExpiration then
		timers[key] = nil
		return
	end
	timers[key] = C_Timer and C_Timer.NewTimer and C_Timer.NewTimer(math.max(nextExpiration - now, 0.01), function()
		local currentStore = CooldownPanels.runtime and CooldownPanels.runtime.activeProcTriggerDurations
		local current = currentStore and currentStore[key] or nil
		if current then
			CooldownPanels:CleanupActiveProcTriggerRecord(current)
			if (tonumber(current.stackCount) or 0) <= 0 then
				CooldownPanels:ClearEntryActiveProcTriggerDuration(panelId, entryId)
			else
				CooldownPanels:RefreshActiveProcTriggerEntries()
				CooldownPanels:ScheduleActiveProcTriggerStackCleanup(panelId, entryId)
			end
		end
	end) or nil
end

function CooldownPanels:ClearEntryActiveProcTriggerDuration(panelId, entryId, suppressRefresh)
	panelId = normalizeId(panelId)
	entryId = normalizeId(entryId)
	if not (panelId and entryId and self.runtime) then return false end
	local key = Helper.GetEntryKey(panelId, entryId)
	local store = self.runtime.activeProcTriggerDurations
	local timers = self.runtime.activeProcTriggerDurationTimers
	local stackTimers = self.runtime.activeProcTriggerStackTimers
	local hadRecord = store and store[key] ~= nil
	if store then store[key] = nil end
	local timer = timers and timers[key] or nil
	if timer and timer.Cancel then timer:Cancel() end
	if timers then timers[key] = nil end
	local stackTimer = stackTimers and stackTimers[key] or nil
	if stackTimer and stackTimer.Cancel then stackTimer:Cancel() end
	if stackTimers then stackTimers[key] = nil end
	if hadRecord and not suppressRefresh then
		self:RefreshActiveProcTriggerEntries()
	end
	return hadRecord
end

function CooldownPanels:StartEntryActiveProcTriggerDuration(panelId, entryId, entry, resolvedType, info, triggerKind)
	if not (entry and entry.autoCooldownDurationEnabled == true) then return false end
	local _, nativeAuraItem = self:GetEntryNativeAuraItemInfo(entry, resolvedType)
	if nativeAuraItem then return false end
	info = info or self:GetEntryActiveProcTriggerInfo(entry, resolvedType)
	local duration = self:GetActiveProcTriggerConfiguredDuration(info, triggerKind)
	if not (duration and duration > 0) then return false end
	panelId = normalizeId(panelId)
	entryId = normalizeId(entryId)
	if not (panelId and entryId) then return false end
	local now = self:GetDurationNow()
	local durationObject
	local durationUtil = _G.C_DurationUtil
	if durationUtil and durationUtil.CreateDuration then
		durationObject = durationUtil.CreateDuration()
		if durationObject and durationObject.SetTimeFromStart then durationObject:SetTimeFromStart(now, duration, 1) end
	end
	local store, timers = self:GetActiveProcTriggerDurationStore()
	local key = Helper.GetEntryKey(panelId, entryId)
	local oldTimer = timers[key]
	if oldTimer and oldTimer.Cancel then oldTimer:Cancel() end
	if info.mode == "stacked" or info.mode == "stackedAfterStart" then
		local current = store[key]
		if triggerKind == "start" then
			if type(current) ~= "table" then
				current = {
					stackCount = 0,
					stackExpirations = {},
					stackMode = true,
				}
				store[key] = current
			end
			current.armedUntil = now + duration
			current.startDuration = duration
			current.stackMode = true
			current.stackExpirations = current.stackExpirations or {}
			self:CleanupActiveProcTriggerRecord(current, now)
			self:ScheduleActiveProcTriggerStackCleanup(panelId, entryId)
			return true
		end
		if triggerKind ~= "stack" then return false end
		if info.mode == "stackedAfterStart" and not (current and tonumber(current.armedUntil) and tonumber(current.armedUntil) > now) then
			return false
		end
		if type(current) ~= "table" then
			current = {
				stackCount = 0,
				stackExpirations = {},
				stackMode = true,
			}
			store[key] = current
		end
		current.stackExpirations = current.stackExpirations or {}
		current.stackExpirations[#current.stackExpirations + 1] = now + duration
		current.durationObject = durationObject
		current.startTime = now
		current.duration = duration
		current.endTime = now + duration
		current.stackMode = true
		self:CleanupActiveProcTriggerRecord(current, now)
		self:ScheduleActiveProcTriggerStackCleanup(panelId, entryId)
		return true
	end
	store[key] = {
		durationObject = durationObject,
		startTime = now,
		duration = duration,
		endTime = now + duration,
	}
	if C_Timer and C_Timer.NewTimer then
		timers[key] = C_Timer.NewTimer(duration, function()
			local currentStore = CooldownPanels.runtime and CooldownPanels.runtime.activeProcTriggerDurations
			local current = currentStore and currentStore[key] or nil
			if current and current.startTime == now and current.duration == duration then CooldownPanels:ClearEntryActiveProcTriggerDuration(panelId, entryId) end
		end)
	end
	return true
end

function CooldownPanels:RefreshActiveProcTriggerEntries(triggerSpellID)
	local runtime = self.runtime
	local allTargets = runtime and runtime.activeProcTriggerEntryTargets
	if not (allTargets and next(allTargets)) then return false end
	local panelsToRefresh = cdp.ENTRY.GetPanelRefreshScratch and cdp.ENTRY.GetPanelRefreshScratch(runtime, "_eqolActiveProcTriggerEntryRefreshScratch") or {}
	local refreshed = false
	local function refreshPanels(targets)
		for panelId, entries in pairs(targets or {}) do
			local panelNeedsRefresh = false
			for entryId, resolvedType in pairs(entries) do
				local ok = false
				if resolvedType == "ITEM" and cdp.ENTRY.TryRefreshVisibleItemEntry then
					ok = cdp.ENTRY.TryRefreshVisibleItemEntry(panelId, entryId)
				elseif resolvedType == "SLOT" and cdp.ENTRY.TryRefreshVisibleSlotEntry then
					ok = cdp.ENTRY.TryRefreshVisibleSlotEntry(panelId, entryId)
				end
				if ok then
					refreshed = true
				else
					panelNeedsRefresh = true
					refreshed = true
				end
			end
			if panelNeedsRefresh then
				if cdp.ENTRY.QueuePanelRefresh then
					cdp.ENTRY.QueuePanelRefresh(panelsToRefresh, panelId)
				elseif self.RequestPanelRefresh then
					self:RequestPanelRefresh(panelId)
				elseif self.RefreshPanel then
					self:RefreshPanel(panelId)
				end
			end
		end
	end
	if triggerSpellID then
		refreshPanels(allTargets[triggerSpellID])
	else
		for _, targets in pairs(allTargets) do
			refreshPanels(targets)
		end
	end
	if cdp.ENTRY.FlushPanelRefreshes and cdp.ENTRY.FlushPanelRefreshes(panelsToRefresh) then refreshed = true end
	return refreshed
end

function CooldownPanels:UpdateActiveProcTriggerIndex()
	self.runtime = self.runtime or {}
	local runtime = self.runtime
	local root = ensureRoot()
	local enabledPanels = runtime.enabledPanels
	local enabledPanelIds = runtime.enabledPanelIds
	local procMap = self.activeProcTriggerByItemID
	local equipped = {}
	for _, slotID in ipairs({ 13, 14 }) do
		local itemID = Api.GetInventoryItemID and Api.GetInventoryItemID("player", slotID) or nil
		if itemID and procMap and procMap[itemID] then equipped[itemID] = procMap[itemID] end
	end
	local entryTargets = {}
	local hasWatched = false
	if root and root.panels and enabledPanels and next(enabledPanels) and enabledPanelIds and next(equipped) then
		for i = 1, #enabledPanelIds do
			local panelId = enabledPanelIds[i]
			local panel = enabledPanels[panelId] and root.panels[panelId] or nil
			if panel and panel.entries then
				for _, entryId in ipairs(panel.order or {}) do
					local entry = panel.entries[entryId]
					if entry and entry.autoCooldownDurationEnabled == true and entry.showCooldown ~= false then
						local itemID
						if entry.type == "ITEM" then
							itemID = tonumber(entry.itemID)
							if itemID then itemID = self.ResolveEntryItemID(entry, itemID) end
						elseif entry.type == "SLOT" then
							local slotID = tonumber(entry.slotID)
							if slotID == 13 or slotID == 14 then itemID = Api.GetInventoryItemID and Api.GetInventoryItemID("player", slotID) or nil end
						end
						local info = itemID and equipped[itemID] or nil
						local duration = self:GetActiveProcTriggerConfiguredDuration(info)
						if info and duration and duration > 0 then
							self:ForEachActiveProcTriggerSpellID(info, function(triggerSpellID)
								entryTargets[triggerSpellID] = entryTargets[triggerSpellID] or {}
								entryTargets[triggerSpellID][panelId] = entryTargets[triggerSpellID][panelId] or {}
								entryTargets[triggerSpellID][panelId][entryId] = entry.type
								hasWatched = true
							end)
						end
					end
				end
			end
		end
	end
	runtime.activeProcTriggerEntryTargets = hasWatched and entryTargets or nil
end

function CooldownPanels:HandleActiveProcTriggerSpell(triggerSpellID)
	triggerSpellID = tonumber(triggerSpellID)
	if not triggerSpellID then return false end
	local runtime = self.runtime
	local targets = runtime and runtime.activeProcTriggerEntryTargets and runtime.activeProcTriggerEntryTargets[triggerSpellID]
	if not (targets and next(targets)) then
		return false
	end
	local triggeredItems = self.activeProcTriggerBySpellID and self.activeProcTriggerBySpellID[triggerSpellID] or nil
	if not (triggeredItems and next(triggeredItems)) then return false end
	local root = ensureRoot()
	if not (root and root.panels) then return false end
	local started = false
	for panelId, entries in pairs(targets) do
		local panel = root.panels[panelId]
		for entryId, resolvedType in pairs(entries) do
			local entry = panel and panel.entries and panel.entries[entryId] or nil
			local info, _, itemID = self:GetEntryActiveProcTriggerInfo(entry, resolvedType)
			local triggerKind = self:GetActiveProcTriggerKind(info, triggerSpellID)
			if info and triggerKind and itemID and triggeredItems[itemID] then
				if self:StartEntryActiveProcTriggerDuration(panelId, entryId, entry, resolvedType, info, triggerKind) then started = true end
			end
		end
	end
	if started then self:RefreshActiveProcTriggerEntries(triggerSpellID) end
	return started
end

function CooldownPanels:HandleActiveProcTriggerSpellUpdate(spellID, baseSpellID)
	local handled = false
	if spellID then handled = self:HandleActiveProcTriggerSpell(spellID) or handled end
	if baseSpellID and baseSpellID ~= spellID then handled = self:HandleActiveProcTriggerSpell(baseSpellID) or handled end
	return handled
end

function CooldownPanels.IsSpellCooldownInfoActive(cooldownIsActive, cooldownEnabled, startTime, duration)
	if not (Api.issecretvalue and Api.issecretvalue(cooldownIsActive)) and type(cooldownIsActive) == "boolean" then return cooldownIsActive end
	if not isSafeNotFalse(cooldownEnabled) then return false end
	return isCooldownActive(startTime, duration)
end

function CooldownPanels.IsChargeInfoActive(chargesInfo)
	if type(chargesInfo) ~= "table" then return false end
	if not (Api.issecretvalue and Api.issecretvalue(chargesInfo.isActive)) and type(chargesInfo.isActive) == "boolean" then return chargesInfo.isActive end
	if Api.issecretvalue and (Api.issecretvalue(chargesInfo.currentCharges) or Api.issecretvalue(chargesInfo.maxCharges)) then return true end
	return isSafeLessThan(chargesInfo.currentCharges, chargesInfo.maxCharges)
end

function CooldownPanels.ShouldShowSpellChargeCount(chargesInfo)
	if type(chargesInfo) ~= "table" then return false end
	local maxCharges = chargesInfo.maxCharges
	if Api.issecretvalue and Api.issecretvalue(maxCharges) then return false end
	return type(maxCharges) == "number" and maxCharges > 1
end

local function getDurationRemaining(duration)
	if not duration then return nil end
	local remaining = duration.GetRemainingDuration(duration, Api.DurationModifierRealTime)
	if isSafeNumber(remaining) then return remaining end
	return nil
end

local function getSpellCooldownInfo(spellID)
	if not spellID or not Api.GetSpellCooldownInfo then return 0, 0, false, 1, nil, false, false end
	local a, b, c, d = Api.GetSpellCooldownInfo(spellID)
	if type(a) == "table" then
		local startTime = a.startTime or 0
		local duration = a.duration or 0
		local isEnabled = a.isEnabled
		local isOnGCD = type(a.isOnGCD) == "boolean" and a.isOnGCD or nil
		local isActive = type(a.isActive) == "boolean" and a.isActive or CooldownPanels.IsSpellCooldownInfoActive(nil, isEnabled, startTime, duration)
		return startTime, duration, isEnabled, a.modRate or 1, isOnGCD, isActive, a.timeUntilEndOfStartRecovery ~= nil
	end
	local startTime = a or 0
	local duration = b or 0
	local isEnabled = c
	return startTime, duration, isEnabled, d or 1, nil, CooldownPanels.IsSpellCooldownInfoActive(nil, isEnabled, startTime, duration), false
end

local function getGCDStateKey()
	local startTime, duration, enabled, _, isOnGCD, isActive = getSpellCooldownInfo(61304)
	local active = CooldownPanels.IsSpellCooldownInfoActive(isActive, enabled, startTime, duration)
	local comparableStart = isSafeNumber(startTime) and startTime or false
	local comparableDuration = isSafeNumber(duration) and duration or false
	return table.concat({
		tostring(active == true),
		tostring(isOnGCD == true),
		tostring(comparableStart),
		tostring(comparableDuration),
	}, "\031")
end

function CooldownPanels:UpdateGlobalGCDState()
	self.runtime = self.runtime or {}
	local runtime = self.runtime
	local nextKey = getGCDStateKey()
	local changed = runtime._eqolGlobalGCDStateKey == nil or runtime._eqolGlobalGCDStateKey ~= nextKey
	runtime._eqolGlobalGCDStateKey = nextKey
	return changed
end

local getSpellCooldownDurationObject

function CooldownPanels:EnsureSpellQueryCaches()
	self.runtime = self.runtime or {}
	local runtime = self.runtime
	runtime.spellCooldownDurationCache = runtime.spellCooldownDurationCache or {}
	runtime.spellCooldownInfoCache = runtime.spellCooldownInfoCache or {}
	runtime.spellChargesInfoCache = runtime.spellChargesInfoCache or {}
	runtime.spellPassStateCache = runtime.spellPassStateCache or {}
	return runtime
end

function CooldownPanels:BeginSpellQueryBatch()
	local runtime = self:EnsureSpellQueryCaches()
	local depth = (runtime.spellQueryBatchDepth or 0) + 1
	runtime.spellQueryBatchDepth = depth
	if depth == 1 then runtime.spellQueryPass = (runtime.spellQueryPass or 0) + 1 end
	return runtime.spellQueryPass
end

function CooldownPanels:EndSpellQueryBatch()
	local runtime = self.runtime
	if not runtime then return end
	local depth = tonumber(runtime.spellQueryBatchDepth) or 0
	if depth <= 1 then
		runtime.spellQueryBatchDepth = nil
	else
		runtime.spellQueryBatchDepth = depth - 1
	end
end

function CooldownPanels:EnsureSpellQueryPass()
	local runtime = self:EnsureSpellQueryCaches()
	if (runtime.spellQueryBatchDepth or 0) <= 0 then runtime.spellQueryPass = (runtime.spellQueryPass or 0) + 1 end
	return runtime.spellQueryPass
end

function CooldownPanels:BeginSpellQueryPass() return self:EnsureSpellQueryPass() end

function CooldownPanels:GetSpellPassState(spellId)
	if not spellId then return nil end
	local runtime = self:EnsureSpellQueryCaches()
	local pass = runtime.spellQueryPass
	if not pass then return nil end
	local cache = runtime.spellPassStateCache
	local state = cache[spellId]
	if state and state.pass == pass then return state end
	state = state or {}
	state.pass = pass
	state.infoLoaded = nil
	state.durationLoaded = nil
	state.chargesLoaded = nil
	state.chargeDurationLoaded = nil
	state.cooldownStart = nil
	state.cooldownDuration = nil
	state.cooldownEnabled = nil
	state.cooldownRate = nil
	state.cooldownGCD = nil
	state.cooldownIsActive = nil
	state.cooldownDurationObject = nil
	state.chargesInfo = nil
	state.chargeDurationObject = nil
	cache[spellId] = state
	return state
end

function CooldownPanels:BeginRuntimeQueryBatch()
	self:BeginSpellQueryBatch()
	local cdmAuras = self.CDMAuras
	if cdmAuras and cdmAuras.BeginRuntimePass then cdmAuras:BeginRuntimePass() end
end

function CooldownPanels:EndRuntimeQueryBatch()
	local cdmAuras = self.CDMAuras
	if cdmAuras and cdmAuras.EndRuntimePass then cdmAuras:EndRuntimePass() end
	self:EndSpellQueryBatch()
end

function CooldownPanels:IsRuntimeQueryBatchActive()
	local runtime = self.runtime
	return runtime and (runtime.spellQueryBatchDepth or 0) > 0 or false
end

function CooldownPanels:InvalidateSpellQueryCaches(kind, spellId)
	local runtime = self.runtime
	if not runtime then return end
	if kind == nil and spellId == nil then
		runtime.spellAliasIDsCache = nil
		runtime.runtimeCanonicalSpellVariantCache = nil
	end
	if kind == "duration" or kind == nil then
		if spellId ~= nil then
			runtime.spellCooldownDurationCache = runtime.spellCooldownDurationCache or {}
			runtime.spellCooldownDurationCache[spellId] = nil
		else
			runtime.spellCooldownDurationCache = {}
		end
	end
	if kind == "info" or kind == nil then
		if spellId ~= nil then
			runtime.spellCooldownInfoCache = runtime.spellCooldownInfoCache or {}
			runtime.spellCooldownInfoCache[spellId] = nil
		else
			runtime.spellCooldownInfoCache = {}
		end
	end
	if kind == "charges" or kind == nil then
		if spellId ~= nil then
			runtime.spellChargesInfoCache = runtime.spellChargesInfoCache or {}
			runtime.spellChargesInfoCache[spellId] = nil
		else
			runtime.spellChargesInfoCache = {}
		end
	end
	if kind == "chargeDuration" or kind == nil then
		if spellId ~= nil then
			runtime.spellChargeDurationCache = runtime.spellChargeDurationCache or {}
			runtime.spellChargeDurationCache[spellId] = nil
		else
			runtime.spellChargeDurationCache = {}
		end
	end
	if runtime.spellPassStateCache then
		if spellId ~= nil then
			runtime.spellPassStateCache[spellId] = nil
		elseif kind == nil or kind == "info" or kind == "duration" then
			runtime.spellPassStateCache = {}
		end
	end
end

function CooldownPanels:InvalidateSpellCooldownCachesForAliases(spellId)
	local id = tonumber(spellId)
	if not (id and self.runtime) then return false end
	local ids = self:GetSpellAliasIDs(id)
	if not ids or #ids == 0 then return false end
	for i = 1, #ids do
		local aliasId = ids[i]
		self:InvalidateSpellQueryCaches("duration", aliasId)
		self:InvalidateSpellQueryCaches("info", aliasId)
		self:InvalidateSpellQueryCaches("charges", aliasId)
		self:InvalidateSpellQueryCaches("chargeDuration", aliasId)
	end
	return true
end

function CooldownPanels:GetCachedSpellCooldownDurationObject(spellId, ignoreGCD)
	if not spellId then return nil end
	local runtime = self:EnsureSpellQueryCaches()
	local pass = runtime.spellQueryPass
	if not pass then return getSpellCooldownDurationObject(spellId, ignoreGCD) end
	local cache = runtime.spellCooldownDurationCache
	local mode = ignoreGCD == true and "ignoreGCD" or "default"
	local cachedByMode = cache[spellId]
	if type(cachedByMode) ~= "table" then
		cachedByMode = {}
		cache[spellId] = cachedByMode
	end
	local cached = cachedByMode[mode]
	if cached and cached.pass == pass then return cached.value end
	cached = cached or {}
	cachedByMode[mode] = cached
	cached.pass = pass
	cached.value = getSpellCooldownDurationObject(spellId, ignoreGCD)
	return cached.value
end

function CooldownPanels:GetCachedSpellCooldownInfo(spellId, ignoreGCD)
	if not spellId then return 0, 0, false, 1, nil, false, false end
	local runtime = self:EnsureSpellQueryCaches()
	local pass = runtime.spellQueryPass
	if not pass then return getSpellCooldownInfo(spellId) end
	local cache = runtime.spellCooldownInfoCache
	local useIgnoreGCD = ignoreGCD == true
	local mode = useIgnoreGCD == true and "ignoreGCD" or "default"
	local cachedByMode = cache[spellId]
	if type(cachedByMode) ~= "table" then
		cachedByMode = {}
		cache[spellId] = cachedByMode
	end
	local cached = cachedByMode[mode]
	if cached and cached.pass == pass then
		return cached.startTime, cached.duration, cached.enabled, cached.modRate, cached.isOnGCD, cached.isActive, cached.isStartRecovery
	end
	cached = cached or {}
	cachedByMode[mode] = cached
	cached.pass = pass
	if useIgnoreGCD == true then
		cached.startTime, cached.duration, cached.enabled, cached.modRate, cached.isOnGCD, cached.isActive, cached.isStartRecovery =
			self:GetCachedSpellCooldownInfo(spellId, false)
		if cached.isOnGCD == true then
			cached.startTime = 0
			cached.duration = 0
			cached.isActive = false
			cached.isOnGCD = false
		end
	else
		cached.startTime, cached.duration, cached.enabled, cached.modRate, cached.isOnGCD, cached.isActive, cached.isStartRecovery = getSpellCooldownInfo(spellId)
	end
	return cached.startTime, cached.duration, cached.enabled, cached.modRate, cached.isOnGCD, cached.isActive, cached.isStartRecovery
end

function CooldownPanels:GetCachedSpellChargesInfo(spellId)
	if not spellId or not Api.GetSpellChargesInfo then return nil end
	local runtime = self:EnsureSpellQueryCaches()
	local pass = runtime.spellQueryPass
	if not pass then return Api.GetSpellChargesInfo(spellId) end
	local cache = runtime.spellChargesInfoCache
	local cached = cache[spellId]
	if cached and cached.pass == pass then return cached.value end
	cached = cached or {}
	cache[spellId] = cached
	cached.pass = pass
	cached.value = Api.GetSpellChargesInfo(spellId)
	return cached.value
end

function CooldownPanels:GetCachedSpellChargeDurationObject(spellId)
	if not spellId or not (C_Spell and C_Spell.GetSpellChargeDuration) then return nil end
	local runtime = self:EnsureSpellQueryCaches()
	local pass = runtime.spellQueryPass
	if not pass then return C_Spell.GetSpellChargeDuration(spellId) end
	local cache = runtime.spellChargeDurationCache
	if not cache then
		cache = {}
		runtime.spellChargeDurationCache = cache
	end
	local cached = cache[spellId]
	if cached and cached.pass == pass then return cached.value end
	cached = cached or {}
	cache[spellId] = cached
	cached.pass = pass
	cached.value = C_Spell.GetSpellChargeDuration(spellId)
	return cached.value
end

local function getItemCooldownInfo(itemID, slotID)
	local start, duration, enabled
	if slotID and Api.GetInventoryItemCooldown then
		start, duration, enabled = Api.GetInventoryItemCooldown("player", slotID)
		if not (start and duration) then
			start, duration, enabled = nil, nil, nil
		end
	end
	if (start == nil or duration == nil) and itemID and Api.GetItemCooldownFn then
		start, duration, enabled = Api.GetItemCooldownFn(itemID)
	end
	start = start or 0
	duration = duration or 0

	-- Item/slot cooldown queries can briefly collapse to the player's GCD.
	-- If the linked use spell has its own real cooldown running, prefer that timer.
	if itemID and CooldownPanels:IsCooldownMatchingGlobalCooldown(start, duration) then
		local spellId = CooldownPanels:GetItemUseSpellID(itemID)
		if spellId then
			local spellStart, spellDuration = getSpellCooldownInfo(spellId)
			if isCooldownActive(spellStart, spellDuration) and not CooldownPanels:IsCooldownMatchingGlobalCooldown(spellStart, spellDuration) then return spellStart or 0, spellDuration or 0, true end
		end
	end

	return start, duration, enabled
end

function CooldownPanels:GetItemUseSpellID(itemID)
	itemID = tonumber(itemID)
	if not itemID then return nil end
	self.runtime = self.runtime or {}
	local runtime = self.runtime
	runtime.itemUseSpellCache = runtime.itemUseSpellCache or {}
	local cached = runtime.itemUseSpellCache[itemID]
	if cached ~= nil then return cached or nil end
	if not Api.GetItemSpell then return nil end
	local _, spellId = Api.GetItemSpell(itemID)
	spellId = tonumber(spellId)
	if spellId then
		runtime.itemUseSpellCache[itemID] = spellId
	elseif C_Item and C_Item.IsItemDataCachedByID and C_Item.IsItemDataCachedByID(itemID) then
		runtime.itemUseSpellCache[itemID] = false
	elseif C_Item and C_Item.RequestLoadItemDataByID then
		C_Item.RequestLoadItemDataByID(itemID)
	end
	return spellId
end

function CooldownPanels:IsCooldownMatchingGlobalCooldown(cooldownStart, cooldownDuration)
	if not isCooldownActive(cooldownStart, cooldownDuration) then return false end
	local gcdStart, gcdDuration = getSpellCooldownInfo(61304)
	if not isCooldownActive(gcdStart, gcdDuration) then return false end
	return cooldownStart == gcdStart and cooldownDuration == gcdDuration
end

function CooldownPanels:IsItemCooldownOnGCD(itemID, cooldownStart, cooldownDuration)
	if not self:IsCooldownMatchingGlobalCooldown(cooldownStart, cooldownDuration) then return false end
	local spellId = self:GetItemUseSpellID(itemID)
	if not spellId then return true end

	local spellStart, spellDuration = getSpellCooldownInfo(spellId)

	-- A linked use spell being on cooldown is only relevant if its timer is separate from the GCD.
	if isCooldownActive(spellStart, spellDuration) and not self:IsCooldownMatchingGlobalCooldown(spellStart, spellDuration) then return false end

	return true
end

getSpellCooldownDurationObject = function(spellID, ignoreGCD)
	if not spellID or not Api.GetSpellCooldownDuration then return nil end
	if ignoreGCD == true then return Api.GetSpellCooldownDuration(spellID, true) end
	return Api.GetSpellCooldownDuration(spellID)
end

local function hasItem(itemID)
	if not itemID then return false end
	if Api.IsEquippedItem and Api.IsEquippedItem(itemID) then return true end
	local count = Api.GetItemCount(itemID, false, false)
	if count and count > 0 then return true end
	return false
end

local function itemHasUseSpell(itemID) return CooldownPanels.GetItemUseSpellID and CooldownPanels:GetItemUseSpellID(itemID) ~= nil or false end

function CooldownPanels:EntryPassesEditorRuntimeVisibility(entry)
	if not entry or type(entry) ~= "table" then return false end
	if not CooldownPanels.EntryAllowsSpec(entry) then return false end
	local macro = entry.type == "MACRO" and CooldownPanels.ResolveMacroEntry(entry) or nil
	local resolvedType = (macro and macro.kind) or entry.type
	if resolvedType == "SPELL" then
		local baseSpellId = (macro and macro.spellID) or entry.spellID
		if not baseSpellId then return false end
		local effectiveSpellId, resolvedSpellId, _, variantGroup = self:ResolveEntryTrackedSpellID(entry, baseSpellId)
		local spellId = effectiveSpellId or baseSpellId
		if self:IsEntryRacialVariantExcluded(entry, resolvedSpellId or spellId) then return false end
		if resolvedSpellId and not shouldTrackPassiveSpell(entry) and isSpellPassiveSafe(resolvedSpellId, effectiveSpellId) then return false end
		if
			Api.IsSpellKnown
			and not (variantGroup and variantGroup.kind == "talentChoice")
			and not cdp.ENTRY.ShouldTrackUnknownSpell(entry)
			and not Api.IsSpellKnown(spellId, true)
		then
			return false
		end
		return true
	elseif resolvedType == "ITEM" then
		local itemID = CooldownPanels.ResolveEntryItemID(entry, (macro and macro.itemID) or entry.itemID)
		if not itemID then return false end
		if itemHasUseSpell and not itemHasUseSpell(itemID) then return false end
		if entry.showWhenEmpty == true then return true end
		return hasItem(itemID)
	elseif resolvedType == "SLOT" then
		if entry.slotID and Api.GetInventoryItemID then
			local itemId = Api.GetInventoryItemID("player", entry.slotID)
			if not itemId then return entry.showWhenNoCooldown == true end
			if itemHasUseSpell and itemHasUseSpell(itemId) then return true end
			return entry.showWhenNoCooldown == true
		end
		return false
	elseif resolvedType == "STANCE" then
		if self.IsStanceEntryRelevant and not self:IsStanceEntryRelevant(entry) then return false end
		local active = self.IsStanceEntryActive and self:IsStanceEntryActive(entry) or false
		if entry.showWhenMissing == true then return not active end
		return active
	elseif resolvedType == "CDM_AURA" then
		local cdmAuras = self.CDMAuras
		if cdmAuras and cdmAuras.EntryIsAvailableForPreview then return cdmAuras:EntryIsAvailableForPreview(entry) end
		return false
	elseif entry.type == "MACRO" then
		return macro ~= nil
	end
	return true
end

function CooldownPanels:ShouldShowEntryInPanelEditor(panel, entry)
	if not (panel and panel.hideUnavailableEntriesInEditor == true) then return true end
	return self:EntryPassesEditorRuntimeVisibility(entry)
end

function CooldownPanels:SetPanelHideUnavailableEntriesInEditor(panelId, enabled)
	local panel = self:GetPanel(panelId)
	if not panel then return false end
	panel.hideUnavailableEntriesInEditor = enabled == true or nil
	self:RefreshPanel(panelId)
	self:RefreshEditor()
	local blizzardEditor = self.BlizzardEditor
	if blizzardEditor and blizzardEditor.Refresh then blizzardEditor:Refresh() end
	return true
end

local function createPanelFrame(panelId, panel)
	local frame = CreateFrame("Button", "EQOL_CooldownPanel" .. tostring(panelId), UIParent)
	frame:SetRolesets("cooldownViewers")
	frame:SetClampedToScreen(true)
	frame:SetMovable(true)
	frame:EnableMouse(false)
	frame.panelId = panelId
	frame.icons = {}
	frame._eqolPanelFrame = true

	local bg = frame:CreateTexture(nil, "BACKGROUND")
	bg:SetAllPoints(frame)
	bg:SetColorTexture(0.1, 0.6, 0.6, 0.2)
	bg:Hide()
	frame.bg = bg

	local label = frame:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
	label:SetPoint("CENTER")
	label:SetText(panel and panel.name or L["cooldownPanelDefaultName"])
	label:Hide()
	frame.label = label

	local editDropZone = CreateFrame("Button", nil, frame)
	editDropZone:SetAllPoints(frame)
	editDropZone:SetFrameLevel(frame:GetFrameLevel())
	editDropZone:EnableMouse(false)
	editDropZone:RegisterForClicks("LeftButtonUp")
	editDropZone:SetScript("OnReceiveDrag", function(self)
		if not (CooldownPanels and CooldownPanels:IsPanelLayoutEditActive(self.panelId)) then return end
		if CooldownPanels:HandleCursorDrop(self.panelId) then
			CooldownPanels:RefreshPanel(self.panelId)
			if CooldownPanels:IsEditorOpen() then CooldownPanels:RefreshEditor() end
		end
	end)
	editDropZone:SetScript("OnMouseUp", function(self, btn)
		if btn ~= "LeftButton" then return end
		if not (CooldownPanels and CooldownPanels:IsPanelLayoutEditActive(self.panelId)) then return end
		if CooldownPanels:HandleCursorDrop(self.panelId) then
			CooldownPanels:RefreshPanel(self.panelId)
			if CooldownPanels:IsEditorOpen() then CooldownPanels:RefreshEditor() end
			return
		end
		CooldownPanels:SelectPanel(self.panelId)
	end)
	editDropZone:Hide()
	editDropZone.panelId = panelId
	frame.editDropZone = editDropZone

	local editGrid = CreateFrame("Frame", nil, frame)
	editGrid:SetAllPoints(frame)
	editGrid:SetFrameLevel((frame:GetFrameLevel() or 0) + 1)
	editGrid:EnableMouse(false)
	editGrid.cells = {}
	editGrid:Hide()
	frame.editGrid = editGrid

	local editPanelHandle = CreateFrame("Button", nil, frame, "BackdropTemplate")
	editPanelHandle:SetSize(72, 16)
	editPanelHandle:SetPoint("BOTTOM", frame, "TOP", 0, 4)
	editPanelHandle:SetBackdrop({
		bgFile = "Interface\\Buttons\\WHITE8x8",
		edgeFile = "Interface\\Buttons\\WHITE8x8",
		edgeSize = 1,
	})
	editPanelHandle:SetBackdropColor(0, 0, 0, 0.72)
	editPanelHandle:SetBackdropBorderColor(0.95, 0.82, 0.25, 0.95)
	editPanelHandle:RegisterForClicks("LeftButtonUp")
	editPanelHandle:RegisterForDrag("LeftButton")
	editPanelHandle:EnableMouse(false)
	editPanelHandle:Hide()
	editPanelHandle.panelId = panelId
	editPanelHandle.label = editPanelHandle:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
	editPanelHandle.label:SetPoint("CENTER")
	editPanelHandle.label:SetText(L["Panel"] or "Panel")
	editPanelHandle.label:SetTextColor(1, 0.86, 0.24, 1)
	editPanelHandle:SetScript("OnMouseDown", function(self, btn)
		if btn ~= "LeftButton" then return end
		self._eqolDragged = nil
		CooldownPanels:SelectPanel(self.panelId)
	end)
	editPanelHandle:SetScript("OnClick", function(self, btn)
		if btn ~= "LeftButton" then return end
		if self._eqolDragged then
			self._eqolDragged = nil
			return
		end
		if not (CooldownPanels and CooldownPanels:IsPanelLayoutEditActive(self.panelId)) then return end
		CooldownPanels:SelectPanel(self.panelId)
		CooldownPanels:OpenLayoutPanelStandaloneMenu(self.panelId, self)
	end)
	editPanelHandle:SetScript("OnDragStart", function(self)
		if not (CooldownPanels and CooldownPanels:IsPanelLayoutEditActive(self.panelId)) then return end
		self._eqolDragged = CooldownPanels:BeginStandalonePanelDrag(self.panelId) and true or nil
		CooldownPanels:SelectPanel(self.panelId)
	end)
	editPanelHandle:SetScript("OnDragStop", function(self)
		if not (CooldownPanels and CooldownPanels:IsPanelLayoutEditActive(self.panelId)) then return end
		CooldownPanels:FinishStandalonePanelDrag(self.panelId)
	end)
	frame.editPanelHandle = editPanelHandle

	return frame
end

function CooldownPanels.PanelHasUngroupedEntryInRect(panel, column, row, columns, rows)
	if not panel then return false end
	for _, entry in pairs(panel.entries or {}) do
		if entry and Helper.NormalizeFixedGroupId(entry.fixedGroupId) == nil then
			local slotColumn = Helper.NormalizeSlotCoordinate(entry.slotColumn)
			local slotRow = Helper.NormalizeSlotCoordinate(entry.slotRow)
			if CooldownPanels.RectContainsCell(column, row, columns, rows, slotColumn, slotRow) then return true end
		end
	end
	return false
end

function CooldownPanels.ClearFixedGroupDragState(runtime)
	if not runtime then return end
	local frame = runtime.frame
	local grid = frame and frame.editGrid or nil
	if grid and grid:GetScript("OnUpdate") then grid:SetScript("OnUpdate", nil) end
	runtime._eqolFixedGroupDrag = nil
end

function CooldownPanels:GetFixedGroupDragRect(panelId)
	panelId = normalizeId(panelId)
	local panel = panelId and self:GetPanel(panelId) or nil
	local runtime = panelId and getRuntime(panelId) or nil
	local drag = runtime and runtime._eqolFixedGroupDrag or nil
	if not (panel and drag and Helper.IsFixedLayout(panel.layout)) then return nil end
	local currentColumn = Helper.NormalizeSlotCoordinate(drag.currentColumn or drag.startColumn)
	local currentRow = Helper.NormalizeSlotCoordinate(drag.currentRow or drag.startRow)
	if drag.mode == "create" then
		local startColumn = Helper.NormalizeSlotCoordinate(drag.startColumn)
		local startRow = Helper.NormalizeSlotCoordinate(drag.startRow)
		if not (startColumn and startRow and currentColumn and currentRow) then return nil end
		local column = math.min(startColumn, currentColumn)
		local row = math.min(startRow, currentRow)
		local columns = math.abs(currentColumn - startColumn) + 1
		local rows = math.abs(currentRow - startRow) + 1
		return {
			mode = "create",
			column = column,
			row = row,
			columns = columns,
			rows = rows,
			valid = self:CanCreateFixedGroup(panelId, column, row, columns, rows),
		}
	elseif drag.mode == "move" then
		local group = CooldownPanels.GetFixedGroupById(panel, drag.groupId)
		if not (group and currentColumn and currentRow) then return nil end
		local column = currentColumn - ((drag.anchorColumn or 1) - 1)
		local row = currentRow - ((drag.anchorRow or 1) - 1)
		local gridColumns, gridRows = Helper.GetFixedGridBounds(panel, false)
		local valid = column >= 1
			and row >= 1
			and gridColumns > 0
			and gridRows > 0
			and (column + group.columns - 1) <= gridColumns
			and (row + group.rows - 1) <= gridRows
			and not self:DoesFixedGroupRectOverlap(panel, column, row, group.columns, group.rows, group.id)
		if valid and CooldownPanels.PanelHasUngroupedEntryInRect(panel, column, row, group.columns, group.rows) then valid = false end
		return {
			mode = "move",
			groupId = group.id,
			column = column,
			row = row,
			columns = group.columns,
			rows = group.rows,
			valid = valid,
		}
	end
	return nil
end

function CooldownPanels:CancelFixedGroupDrag(panelId)
	panelId = normalizeId(panelId)
	local runtime = panelId and getRuntime(panelId) or nil
	if not runtime or not runtime._eqolFixedGroupDrag then return false end
	CooldownPanels.ClearFixedGroupDragState(runtime)
	local panel = self:GetPanel(panelId)
	local slotCount = panel and Helper.GetFixedSlotCount(panel, false) or 0
	self:UpdateLayoutEditGrid(panelId, slotCount)
	return true
end

function CooldownPanels:EnableFixedGroupDragTracking(panelId)
	panelId = normalizeId(panelId)
	local runtime = panelId and getRuntime(panelId) or nil
	local frame = runtime and runtime.frame or nil
	local grid = frame and frame.editGrid or nil
	if not (runtime and grid) then return false end
	grid:SetScript("OnUpdate", function()
		local activeRuntime = getRuntime(panelId)
		if not (activeRuntime and activeRuntime._eqolFixedGroupDrag) then
			grid:SetScript("OnUpdate", nil)
			return
		end
		local targetSlot = CooldownPanels:GetLayoutEditCursorSlot(panelId)
		if targetSlot then CooldownPanels:UpdateFixedGroupDragTarget(panelId, targetSlot.column, targetSlot.row) end
	end)
	return true
end

function CooldownPanels:StartFixedGroupDraw(panelId, column, row)
	panelId = normalizeId(panelId)
	local panel = panelId and self:GetPanel(panelId) or nil
	local runtime = panelId and getRuntime(panelId) or nil
	column = Helper.NormalizeSlotCoordinate(column)
	row = Helper.NormalizeSlotCoordinate(row)
	if not (panel and runtime and column and row and Helper.IsFixedLayout(panel.layout)) then return false end
	runtime._eqolFixedGroupDrag = {
		mode = "create",
		startColumn = column,
		startRow = row,
		currentColumn = column,
		currentRow = row,
	}
	self:EnableFixedGroupDragTracking(panelId)
	self:UpdateLayoutEditGrid(panelId, Helper.GetFixedSlotCount(panel, false))
	return true
end

function CooldownPanels:StartFixedGroupMove(panelId, groupId, column, row)
	panelId = normalizeId(panelId)
	local panel = panelId and self:GetPanel(panelId) or nil
	local runtime = panelId and getRuntime(panelId) or nil
	column = Helper.NormalizeSlotCoordinate(column)
	row = Helper.NormalizeSlotCoordinate(row)
	local group = panel and CooldownPanels.GetFixedGroupById(panel, groupId) or nil
	if not (panel and runtime and group and column and row and Helper.IsFixedLayout(panel.layout)) then return false end
	local anchorColumn = math.max(1, math.min(group.columns, column - group.column + 1))
	local anchorRow = math.max(1, math.min(group.rows, row - group.row + 1))
	runtime._eqolFixedGroupDrag = {
		mode = "move",
		groupId = group.id,
		startColumn = column,
		startRow = row,
		currentColumn = column,
		currentRow = row,
		anchorColumn = anchorColumn,
		anchorRow = anchorRow,
	}
	self:EnableFixedGroupDragTracking(panelId)
	self:UpdateLayoutEditGrid(panelId, Helper.GetFixedSlotCount(panel, false))
	return true
end

function CooldownPanels:InvalidateLayoutEditGrid(panelId)
	panelId = normalizeId(panelId)
	local runtime = panelId and getRuntime(panelId) or nil
	if not runtime then return end
	runtime._eqolLayoutEditGridCount = nil
	runtime._eqolLayoutEditGridActive = nil
	runtime._eqolLayoutEditGridDirty = true
end

function CooldownPanels:UpdateFixedGroupDragTarget(panelId, column, row)
	panelId = normalizeId(panelId)
	local panel = panelId and self:GetPanel(panelId) or nil
	local runtime = panelId and getRuntime(panelId) or nil
	local drag = runtime and runtime._eqolFixedGroupDrag or nil
	column = Helper.NormalizeSlotCoordinate(column)
	row = Helper.NormalizeSlotCoordinate(row)
	if not (panel and drag and column and row) then return false end
	if drag.currentColumn == column and drag.currentRow == row then return false end
	drag.currentColumn = column
	drag.currentRow = row
	self:UpdateLayoutEditGrid(panelId, Helper.GetFixedSlotCount(panel, false))
	return true
end

function CooldownPanels:FinishFixedGroupDrag(panelId)
	panelId = normalizeId(panelId)
	local panel = panelId and self:GetPanel(panelId) or nil
	local runtime = panelId and getRuntime(panelId) or nil
	local drag = runtime and runtime._eqolFixedGroupDrag or nil
	if not (panel and runtime and drag) then return false end
	local rect = self:GetFixedGroupDragRect(panelId)
	CooldownPanels.ClearFixedGroupDragState(runtime)
	self:UpdateLayoutEditGrid(panelId, Helper.GetFixedSlotCount(panel, false))
	if not (rect and rect.valid) then return false end
	if drag.mode == "create" then
		local groupId = self:CreateFixedGroup(panelId, rect.column, rect.row, rect.columns, rect.rows)
		if groupId then
			clearRuntimeLayoutShapeCache(runtime)
			self:RefreshPanelForCurrentEditContext(panelId, true)
			return true
		end
	elseif drag.mode == "move" then
		local moved, reason = self:MoveFixedGroup(panelId, drag.groupId, rect.column, rect.row)
		if moved then
			clearRuntimeLayoutShapeCache(runtime)
			self:RefreshPanelForCurrentEditContext(panelId, true)
			return true
		end
	end
	return false
end

function CooldownPanels:UpdateLayoutEditGrid(panelId, slotCount)
	local runtime = getRuntime(panelId)
	local frame = runtime and runtime.frame
	local panel = self:GetPanel(panelId)
	local grid = frame and frame.editGrid
	local showGrid = grid and panel and self:IsPanelLayoutEditActive(panelId) and Helper.IsFixedLayout(panel.layout)
	if not grid then return end
	slotCount = tonumber(slotCount) or 0
	if not showGrid or slotCount < 1 then
		grid:Hide()
		for i = 1, #(grid.cells or {}) do
			local cell = grid.cells[i]
			if cell then cell:Hide() end
		end
		return
	end
	grid:Show()
	grid.cells = grid.cells or {}
	local fixedLayoutCache = Helper.GetFixedLayoutCache and Helper.GetFixedLayoutCache(panel) or nil
	local gridColumns = fixedLayoutCache and fixedLayoutCache.boundsColumns or select(1, Helper.GetFixedGridBounds(panel, false))
	local groups = CooldownPanels.GetFixedGroups(panel)
	for i = 1, slotCount do
		local icon = frame.icons and frame.icons[i]
		local cell = grid.cells[i]
		if not cell then
			cell = CreateFrame("Frame", nil, grid, "BackdropTemplate")
			cell:SetBackdrop({
				bgFile = "Interface\\Buttons\\WHITE8x8",
				edgeFile = "Interface\\Buttons\\WHITE8x8",
				edgeSize = 1,
			})
			cell:SetBackdropColor(0.08, 0.2, 0.24, 0.08)
			cell:SetBackdropBorderColor(1, 1, 1, 0.14)
			cell:EnableMouse(false)
			grid.cells[i] = cell
		end
		if icon then
			local cellAnchor = icon.slotAnchor or icon
			local cellColumn = gridColumns and gridColumns > 0 and (((i - 1) % gridColumns) + 1) or i
			local cellRow = gridColumns and gridColumns > 0 and (math.floor((i - 1) / gridColumns) + 1) or 1
			local group = CooldownPanels.GetFixedGroupAtCell(panel, cellColumn, cellRow)
			cell:ClearAllPoints()
			cell:SetPoint("TOPLEFT", cellAnchor, "TOPLEFT", 0, 0)
			cell:SetPoint("BOTTOMRIGHT", cellAnchor, "BOTTOMRIGHT", 0, 0)
			cell._eqolLayoutSlotColumn = cellColumn
			cell._eqolLayoutSlotRow = cellRow
			if group then
				if CooldownPanels.IsFixedGroupStatic(group) then
					cell:SetBackdropColor(0.15, 0.22, 0.34, 0.18)
					cell:SetBackdropBorderColor(0.42, 0.62, 0.92, 0.32)
				else
					cell:SetBackdropColor(0.18, 0.28, 0.34, 0.16)
					cell:SetBackdropBorderColor(0.8, 0.68, 0.22, 0.28)
				end
			else
				cell:SetBackdropColor(0.08, 0.2, 0.24, 0.08)
				cell:SetBackdropBorderColor(1, 1, 1, 0.14)
			end
			cell:Show()
		else
			cell._eqolLayoutSlotColumn = nil
			cell._eqolLayoutSlotRow = nil
			cell:Hide()
		end
	end
	for i = slotCount + 1, #grid.cells do
		local cell = grid.cells[i]
		if cell then
			cell._eqolLayoutSlotColumn = nil
			cell._eqolLayoutSlotRow = nil
			cell:Hide()
		end
	end

	grid.groupOverlays = grid.groupOverlays or {}
	for i = 1, #groups do
		local group = groups[i]
		local overlay = grid.groupOverlays[i]
		if not overlay then
			overlay = CreateFrame("Frame", nil, grid, "BackdropTemplate")
			overlay:SetBackdrop({
				bgFile = "Interface\\Buttons\\WHITE8x8",
				edgeFile = "Interface\\Buttons\\WHITE8x8",
				edgeSize = 1,
			})
			overlay:SetBackdropColor(0.85, 0.72, 0.22, 0.06)
			overlay:SetBackdropBorderColor(0.9, 0.78, 0.24, 0.55)
			overlay:EnableMouse(false)
			overlay.label = overlay:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
			overlay.label:SetPoint("TOPLEFT", overlay, "TOPLEFT", 4, -3)
			overlay.label:SetTextColor(1, 0.88, 0.34, 0.9)
			grid.groupOverlays[i] = overlay
		end
		local startIndex = CooldownPanels.GetFixedGridCellIndex(panel, group.column, group.row)
		local endIndex = CooldownPanels.GetFixedGridCellIndex(panel, group.column + group.columns - 1, group.row + group.rows - 1)
		local startIcon = startIndex and frame.icons and frame.icons[startIndex] or nil
		local endIcon = endIndex and frame.icons and frame.icons[endIndex] or nil
		if startIcon and endIcon then
			local startAnchor = startIcon.slotAnchor or startIcon
			local endAnchor = endIcon.slotAnchor or endIcon
			overlay:ClearAllPoints()
			overlay:SetPoint("TOPLEFT", startAnchor, "TOPLEFT", 1, -1)
			overlay:SetPoint("BOTTOMRIGHT", endAnchor, "BOTTOMRIGHT", -1, 1)
			if CooldownPanels.IsFixedGroupStatic(group) then
				overlay:SetBackdropColor(0.35, 0.52, 0.92, 0.08)
				overlay:SetBackdropBorderColor(0.45, 0.64, 0.95, 0.55)
				overlay.label:SetTextColor(0.78, 0.86, 1, 0.95)
			else
				overlay:SetBackdropColor(0.85, 0.72, 0.22, 0.06)
				overlay:SetBackdropBorderColor(0.9, 0.78, 0.24, 0.55)
				overlay.label:SetTextColor(1, 0.88, 0.34, 0.9)
			end
			overlay.label:SetText(CooldownPanels.GetFixedGroupDisplayLabel(group))
			overlay:Show()
		else
			overlay:Hide()
		end
	end
	for i = #groups + 1, #(grid.groupOverlays or {}) do
		local overlay = grid.groupOverlays[i]
		if overlay then overlay:Hide() end
	end

	if not grid.selectionOverlay then
		local overlay = CreateFrame("Frame", nil, grid, "BackdropTemplate")
		overlay:SetBackdrop({
			bgFile = "Interface\\Buttons\\WHITE8x8",
			edgeFile = "Interface\\Buttons\\WHITE8x8",
			edgeSize = 1,
		})
		overlay:EnableMouse(false)
		overlay:Hide()
		grid.selectionOverlay = overlay
	end
	local dragRect = CooldownPanels:GetFixedGroupDragRect(panelId)
	if dragRect then
		local startIndex = CooldownPanels.GetFixedGridCellIndex(panel, dragRect.column, dragRect.row)
		local endIndex = CooldownPanels.GetFixedGridCellIndex(panel, dragRect.column + dragRect.columns - 1, dragRect.row + dragRect.rows - 1)
		local startIcon = startIndex and frame.icons and frame.icons[startIndex] or nil
		local endIcon = endIndex and frame.icons and frame.icons[endIndex] or nil
		if startIcon and endIcon then
			local startAnchor = startIcon.slotAnchor or startIcon
			local endAnchor = endIcon.slotAnchor or endIcon
			grid.selectionOverlay:ClearAllPoints()
			grid.selectionOverlay:SetPoint("TOPLEFT", startAnchor, "TOPLEFT", 1, -1)
			grid.selectionOverlay:SetPoint("BOTTOMRIGHT", endAnchor, "BOTTOMRIGHT", -1, 1)
			if dragRect.valid then
				grid.selectionOverlay:SetBackdropColor(0.2, 0.7, 0.3, 0.14)
				grid.selectionOverlay:SetBackdropBorderColor(0.2, 0.85, 0.35, 0.9)
			else
				grid.selectionOverlay:SetBackdropColor(0.8, 0.15, 0.15, 0.12)
				grid.selectionOverlay:SetBackdropBorderColor(0.9, 0.2, 0.2, 0.9)
			end
			grid.selectionOverlay:Show()
		else
			grid.selectionOverlay:Hide()
		end
	else
		grid.selectionOverlay:Hide()
	end
end

local function getGridDimensions(count, wrapCount, primaryHorizontal)
	if count < 1 then count = 1 end
	if wrapCount and wrapCount > 0 then
		if primaryHorizontal then
			local cols = math.min(count, wrapCount)
			local rows = math.floor((count + wrapCount - 1) / wrapCount)
			return cols, rows
		end
		local rows = math.min(count, wrapCount)
		local cols = math.floor((count + wrapCount - 1) / wrapCount)
		return cols, rows
	end
	if primaryHorizontal then return count, 1 end
	return 1, count
end

local function getPanelRowCount(panel, layout)
	if not panel or not layout then return 1, true end
	local count
	if Helper.IsFixedLayout(layout) then
		local _, rows = Helper.GetFixedGridBounds(panel, false)
		return rows > 0 and rows or 1, true
	else
		count = panel.order and #panel.order or 0
	end
	if count < 1 then count = 1 end
	local wrapCount = Helper.ClampInt(layout.wrapCount, 0, 40, Helper.PANEL_LAYOUT_DEFAULTS.wrapCount or 0)
	local direction = Helper.NormalizeDirection(layout.direction, Helper.PANEL_LAYOUT_DEFAULTS.direction)
	local primaryHorizontal = direction == "LEFT" or direction == "RIGHT"
	local _, rows = getGridDimensions(count, wrapCount, primaryHorizontal)
	return rows, primaryHorizontal
end

local function containsId(list, id)
	if type(list) ~= "table" then return false end
	for _, value in ipairs(list) do
		if value == id then return true end
	end
	return false
end

local function setCooldownDrawState(cooldown, drawEdge, drawBling, drawSwipe)
	if not cooldown then return end
	local owner = cooldown._eqolOwnerIcon
	local effectiveDrawEdge = drawEdge
	if owner and not cdp.ENTRY.IsIconShapeBackdropBorderCompatible(owner._eqolIconShape) then effectiveDrawEdge = false end
	if cooldown.SetDrawEdge and cooldown._eqolDrawEdge ~= effectiveDrawEdge then
		cooldown:SetDrawEdge(effectiveDrawEdge)
		cooldown._eqolDrawEdge = effectiveDrawEdge
	end
	if cooldown.SetDrawBling and cooldown._eqolDrawBling ~= drawBling then
		cooldown:SetDrawBling(drawBling)
		cooldown._eqolDrawBling = drawBling
	end
	if cooldown.SetDrawSwipe and cooldown._eqolDrawSwipe ~= drawSwipe then
		cooldown:SetDrawSwipe(drawSwipe)
		cooldown._eqolDrawSwipe = drawSwipe
	end
end

function cdp.ENTRY.GetCooldownSwipeColor(data)
	if data and data.cooldownSwipeColor then
		local color = data.cooldownSwipeColor
		return color[1], color[2], color[3], color[4]
	end
	if data and data.activationOverlayActive == true then
		local color = data.activationOverlayColor or Helper.ACTIVATION_OVERLAY_COLOR_DEFAULT
		return color[1], color[2], color[3], color[4]
	end
	if data and data.resolvedType == "CDM_AURA" then return 0, 0, 0, 0.7 end
	local color = Helper.PANEL_LAYOUT_DEFAULTS.cooldownSwipeColor or { 0, 0, 0, 0.8 }
	return color[1], color[2], color[3], color[4]
end

function cdp.ENTRY.GetCooldownSwipeTexture(icon)
	local iconShape = addon.IconShape
	if iconShape and iconShape.GetCooldownSwipeTexture then
		return iconShape.GetCooldownSwipeTexture(icon and icon._eqolIconShape, icon and icon._eqolBlizzardIconBorderEnabled == true and cdp.ICON_BORDER.SWIPE_TEXTURE or nil)
	end
	return cdp.ICON_BORDER.DEFAULT_SWIPE_TEXTURE
end

function cdp.ENTRY.ApplyCooldownSwipeVisual(icon, data)
	if not (icon and icon.cooldown) then return end
	if addon.IconShape and addon.IconShape.ApplyCooldownSwipeVisual then
		addon.IconShape.ApplyCooldownSwipeVisual(icon.cooldown, icon, cdp.ENTRY.GetCooldownSwipeColor, data, {
			blizzardSwipeTexture = icon._eqolBlizzardIconBorderEnabled == true and cdp.ICON_BORDER.SWIPE_TEXTURE or nil,
			customColor = data ~= nil,
		})
	end
end

function cdp.ENTRY.ApplyCooldownSwipeFillState(icon, data, hidden)
	if not (icon and icon.cooldown) then return end
	if hidden == true and icon.cooldown.SetSwipeColor then
		if icon._eqolSwipeColorR ~= 0 or icon._eqolSwipeColorG ~= 0 or icon._eqolSwipeColorB ~= 0 or icon._eqolSwipeColorA ~= 0 then
			icon.cooldown:SetSwipeColor(0, 0, 0, 0)
			icon._eqolSwipeColorR, icon._eqolSwipeColorG, icon._eqolSwipeColorB, icon._eqolSwipeColorA = 0, 0, 0, 0
		end
	else
		cdp.ENTRY.ApplyCooldownSwipeVisual(icon, data)
	end
end

function cdp.ENTRY.ResetCooldownSwipeVisual(icon)
	if not (icon and icon.cooldown) then return end
	if addon.IconShape and addon.IconShape.ResetCooldownSwipeVisual then addon.IconShape.ResetCooldownSwipeVisual(icon.cooldown, icon) end
	icon._eqolBlizzardSwipeTextureApplied = nil
end

function cdp.ENTRY.EnsureBlizzardIconOverlay(icon)
	if not icon then return nil end
	local overlay = icon.blizzardIconOverlay
	if not overlay then
		overlay = icon:CreateTexture(nil, "OVERLAY", nil, 2)
		overlay:SetAtlas(cdp.ICON_BORDER.OVERLAY_ATLAS, false)
		overlay:Hide()
		icon.blizzardIconOverlay = overlay
	end
	return overlay
end

function cdp.ENTRY.ApplyBlizzardCooldownMask(icon, maskTexture)
	local cooldown = icon and icon.cooldown
	if addon.IconShape and addon.IconShape.ApplyCooldownRegionMask then addon.IconShape.ApplyCooldownRegionMask(cooldown, maskTexture, "_eqolBlizzardCooldownMask") end
end

function cdp.ENTRY.ApplyIconTextureAspect(icon, layout, force)
	local texture = icon and icon.texture
	if not (texture and texture.SetTexCoord and icon.GetSize) then return end
	local width, height = icon:GetSize()
	width = tonumber(width) or 0
	height = tonumber(height) or 0
	if width <= 0 or height <= 0 then return end

	local shape = cdp.ENTRY.NormalizeIconShape(layout and layout.iconShape, Helper.PANEL_LAYOUT_DEFAULTS.iconShape)
	local iconZoom = addon.IconShape and addon.IconShape.NormalizeIconZoom and addon.IconShape.NormalizeIconZoom(layout and layout.iconZoom) or Helper.ClampInt(layout and layout.iconZoom, 0, 35, 0)
	local inset
	if icon._eqolUseNativeAuraCrop == true then
		inset = 0.08
	else
		inset = 0
		if addon.IconShape and shape == addon.IconShape.SQUARE then inset = 0.07 end
		inset = inset + ((tonumber(iconZoom) or 0) / 100)
	end
	if inset < 0 then inset = 0 end
	if inset > 0.45 then inset = 0.45 end

	local left, right, top, bottom = inset, 1 - inset, inset, 1 - inset
	if icon._eqolUseNativeAuraCrop ~= true then
		if width > height then
			local crop = ((bottom - top) * (1 - (height / width))) / 2
			top = top + crop
			bottom = bottom - crop
		elseif height > width then
			local crop = ((right - left) * (1 - (width / height))) / 2
			left = left + crop
			right = right - crop
		end
	end

	if not force
		and
		icon._eqolIconTextureAspectLeft == left
		and icon._eqolIconTextureAspectRight == right
		and icon._eqolIconTextureAspectTop == top
		and icon._eqolIconTextureAspectBottom == bottom
	then
		return
	end
	if addon.IconShape and addon.IconShape.StoreTextureTexCoord then addon.IconShape.StoreTextureTexCoord(texture, "_eqolCooldownPanelIconTexCoord") end
	texture:SetTexCoord(left, right, top, bottom)
	icon._eqolIconTextureAspectLeft = left
	icon._eqolIconTextureAspectRight = right
	icon._eqolIconTextureAspectTop = top
	icon._eqolIconTextureAspectBottom = bottom
end

function cdp.ENTRY.ApplyIconShape(icon, layout)
	if not icon then return end
	local shape = cdp.ENTRY.NormalizeIconShape(layout and layout.iconShape, Helper.PANEL_LAYOUT_DEFAULTS.iconShape)
	if addon.IconShape and addon.IconShape.ApplyFrameShape then
		addon.IconShape.ApplyFrameShape(icon, shape, {
			textures = { icon.texture, icon.editorGhostTexture, icon.rangeOverlay, icon.stateTexture, icon.stateTextureSecond },
			cooldown = icon.cooldown,
			textureTexCoordKey = "_eqolCooldownPanelIconTexCoord",
			iconZoom = layout and layout.iconZoom,
			refreshSwipe = function(frame) cdp.ENTRY.ApplyCooldownSwipeVisual(frame, frame._eqolRuntimeData) end,
		})
	end
	cdp.ENTRY.ApplyIconTextureAspect(icon, layout)
end

function CooldownPanels:ApplyNativeAuraIconStyle(button, layout, icon, cooldown, background)
	if not button then return end
	layout = layout or Helper.PANEL_LAYOUT_DEFAULTS
	button.texture = icon
	button.cooldown = cooldown
	cdp.ENTRY.ApplyIconShape(button, layout)

	local shape = cdp.ENTRY.NormalizeIconShape(layout.iconShape, Helper.PANEL_LAYOUT_DEFAULTS.iconShape)
	local borderTexture = normalizeIconBorderTexture(layout.iconBorderTexture, Helper.PANEL_LAYOUT_DEFAULTS.iconBorderTexture, shape)
	-- A hidden icon must not leave an empty panel border behind. The native
	-- cooldown/count regions can remain visible without creating icon chrome.
	if icon and layout.iconBorderEnabled == true then
		if shape == cdp.ICON_SHAPE.DEFAULT and cdp.ENTRY.IsBlizzardIconBorderTexture(borderTexture) then
			cdp.ENTRY.ApplyBlizzardIconSkin(button)
		else
			local edgeSize = Helper.ClampInt(layout.iconBorderSize, 1, 64, Helper.PANEL_LAYOUT_DEFAULTS.iconBorderSize or 1)
			local offset = Helper.ClampInt(layout.iconBorderOffset, -64, 64, Helper.PANEL_LAYOUT_DEFAULTS.iconBorderOffset or 0)
			local color = Helper.NormalizeColor(layout.iconBorderColor, Helper.PANEL_LAYOUT_DEFAULTS.iconBorderColor)
			local shapeBorderApplied = false
			if cdp.ENTRY.IsShapeIconBorderCompatible(borderTexture, shape) and addon.IconShape and addon.IconShape.ApplyBorder then
				shapeBorderApplied = addon.IconShape.ApplyBorder(button, borderTexture, shape, {
					borderSize = edgeSize,
					borderOffset = offset,
					color = color,
					pointFrame = button,
					parent = button,
					texturesKey = "_eqolCooldownPanelNativeAuraShapeBorderTextures",
					drawLayer = "OVERLAY",
					subLevel = 6,
				}) == true
			end
			if not shapeBorderApplied and addon.functions and addon.functions.SetSafeBorder then
				local border = CreateFrame("Frame", nil, button)
				border:EnableMouse(false)
				cdp.PIXEL.SetOutside(border, button, offset)
				border:SetFrameLevel((button:GetFrameLevel() or 0) + 4)
				addon.functions.SetSafeBorder(border, true, borderTexture, edgeSize, color[1], color[2], color[3], color[4], {
					stateKey = "_eqolCooldownPanelNativeAuraSafeBorder",
					defaultTexture = "Interface\\Buttons\\WHITE8x8",
					mediaType = "border",
					drawLayer = "OVERLAY",
					pixelPerfect = true,
				})
				button._eqolNativeAuraBorder = border
			end
		end
	end

	if background then
		background:ClearAllPoints()
		background:SetAllPoints(button.texture or button)
		local mask = button.blizzardIconMask or button._eqolIconShapeMask
		if mask and addon.IconShape and addon.IconShape.ApplyTextureMask then
			addon.IconShape.ApplyTextureMask(background, mask, "_eqolAuraOverlayBackgroundMask")
		end
	end
end

function CooldownPanels:ApplyAuraOverlayIconStyle(button, layout, background)
	if not button then return end
	self:ApplyNativeAuraIconStyle(button, layout, button._eqolOverlayIcon, button._eqolOverlayCooldown, background)
end

function cdp.ENTRY.ClearBlizzardIconSkin(icon)
	if not icon then return end
	icon._eqolBlizzardIconBorderEnabled = nil
	if icon.blizzardIconOverlay then icon.blizzardIconOverlay:Hide() end
	if icon._eqolBlizzardMaskApplied and icon.texture and icon.blizzardIconMask and icon.texture.RemoveMaskTexture then
		pcall(icon.texture.RemoveMaskTexture, icon.texture, icon.blizzardIconMask)
	end
	icon._eqolBlizzardMaskApplied = nil
	if (icon._eqolBlizzardIconTextureInsetApplied or icon._eqolBlizzardIconTextureAnchored) and icon.texture then
		icon.texture:ClearAllPoints()
		icon.texture:SetAllPoints(icon)
	end
	icon._eqolBlizzardIconTextureInsetApplied = nil
	icon._eqolBlizzardIconTextureAnchored = nil
	icon._eqolBlizzardIconBottomInset = nil
	cdp.ENTRY.ApplyBlizzardCooldownMask(icon, nil)
	if (icon._eqolBlizzardCooldownInsetApplied or icon._eqolBlizzardCooldownAnchored) and icon.cooldown then
		icon.cooldown:ClearAllPoints()
		icon.cooldown:SetAllPoints(icon)
	end
	icon._eqolBlizzardCooldownInsetApplied = nil
	icon._eqolBlizzardCooldownAnchored = nil
	icon._eqolBlizzardCooldownInset = nil
	icon._eqolBlizzardCooldownWidth = nil
	icon._eqolBlizzardCooldownHeight = nil
	cdp.ENTRY.ResetCooldownSwipeVisual(icon)
end

function cdp.ENTRY.ApplyBlizzardIconSkin(icon)
	if not icon then return end
	local overlay = cdp.ENTRY.EnsureBlizzardIconOverlay(icon)
	icon._eqolBlizzardIconBorderEnabled = true
	local width = tonumber(icon:GetWidth()) or 0
	local height = tonumber(icon:GetHeight()) or 0
	if width <= 0 then width = tonumber(icon._eqolBaseSlotSize) or Helper.PANEL_LAYOUT_DEFAULTS.iconSize or 36 end
	if height <= 0 then height = width end
	if overlay then
		local offsetX = math.max(1, math.floor((width * cdp.ICON_BORDER.OVERLAY_OFFSET_X_RATIO) + 0.5))
		local offsetY = math.max(1, math.floor((height * cdp.ICON_BORDER.OVERLAY_OFFSET_Y_RATIO) + 0.5))
		local offsetXNudge = cdp.ICON_BORDER.OVERLAY_OFFSET_X_NUDGE or 0
		overlay:ClearAllPoints()
		overlay:SetPoint("TOPLEFT", icon, "TOPLEFT", -offsetX + offsetXNudge, offsetY)
		overlay:SetPoint("BOTTOMRIGHT", icon, "BOTTOMRIGHT", offsetX + offsetXNudge, -offsetY)
		overlay:SetAlpha(1)
		overlay:Show()
	end

	if icon.texture then
		local iconBottomInset = cdp.ICON_BORDER.ICON_BOTTOM_INSET
		if icon._eqolBlizzardIconBottomInset ~= iconBottomInset then
			icon.texture:ClearAllPoints()
			icon.texture:SetPoint("TOPLEFT", icon, "TOPLEFT", 0, 0)
			icon.texture:SetPoint("BOTTOMRIGHT", icon, "BOTTOMRIGHT", 0, iconBottomInset)
			icon._eqolBlizzardIconBottomInset = iconBottomInset
			icon._eqolBlizzardIconTextureInsetApplied = true
			icon._eqolBlizzardIconTextureAnchored = nil
		end
	end

	if icon.texture and icon.texture.AddMaskTexture and icon.CreateMaskTexture then
		if not icon.blizzardIconMask then
			local mask = icon:CreateMaskTexture(nil, "ARTWORK")
			mask:SetAtlas(cdp.ICON_BORDER.MASK_ATLAS, false)
			mask:SetAllPoints(icon)
			icon.blizzardIconMask = mask
		end
		if not icon._eqolBlizzardMaskApplied then
			local ok = pcall(icon.texture.AddMaskTexture, icon.texture, icon.blizzardIconMask)
			icon._eqolBlizzardMaskApplied = ok == true
		end
		cdp.ENTRY.ApplyBlizzardCooldownMask(icon, icon.blizzardIconMask)
	end

	if icon.cooldown then
		if icon._eqolBlizzardCooldownAnchored ~= true or icon._eqolBlizzardCooldownInsetApplied then
			icon.cooldown:ClearAllPoints()
			icon.cooldown:SetAllPoints(icon)
			icon._eqolBlizzardCooldownInset = nil
			icon._eqolBlizzardCooldownInsetApplied = nil
			icon._eqolBlizzardCooldownAnchored = true
			icon._eqolBlizzardCooldownWidth = nil
			icon._eqolBlizzardCooldownHeight = nil
		end
		cdp.ENTRY.ApplyCooldownSwipeVisual(icon, icon._eqolRuntimeData)
	end
end

function cdp.ENTRY.HideIconShapeBorder(border)
	if border and border.shapeBorderTexture then border.shapeBorderTexture:Hide() end
	if border and border.shapeBorderTextures then
		for i = 1, #border.shapeBorderTextures do
			border.shapeBorderTextures[i]:Hide()
		end
	end
end

function cdp.ENTRY.EnsureIconShapeBorderTexture(border, index)
	if not border then return nil end
	border.shapeBorderTextures = border.shapeBorderTextures or {}
	local texture = border.shapeBorderTextures[index]
	if not texture and index == 1 and border.shapeBorderTexture then
		texture = border.shapeBorderTexture
		border.shapeBorderTextures[index] = texture
	end
	if not texture then
		texture = border:CreateTexture(nil, "OVERLAY")
		border.shapeBorderTextures[index] = texture
		if index == 1 then border.shapeBorderTexture = texture end
	end
	return texture
end

function cdp.ENTRY.GetIconShapeBorderLayerOffset(index)
	if index <= 1 then return 0, 0 end
	local remaining = index - 2
	local radius = 1
	while remaining >= radius * 8 do
		remaining = remaining - (radius * 8)
		radius = radius + 1
	end
	local side = math.floor(remaining / (radius * 2))
	local step = remaining % (radius * 2)
	if side == 0 then return -radius + step, -radius end
	if side == 1 then return radius, -radius + step end
	if side == 2 then return radius - step, radius end
	return -radius, radius - step
end

function cdp.ENTRY.ApplyIconShapeBorder(icon, border, textureKey, layout, defaults)
	local info = cdp.ICON_BORDER.SHAPE_ATLASES[textureKey]
	if not (icon and border and info) then return false end
	local color = Helper.NormalizeColor(layout.iconBorderColor, defaults.iconBorderColor)
	local offset = Helper.ClampInt(layout.iconBorderOffset, -64, 64, defaults.iconBorderOffset or 0)
	local edgeSize = Helper.ClampInt(layout.iconBorderSize, 1, 64, defaults.iconBorderSize or 1)
	local resolvedOffset = cdp.PIXEL.Snap(offset, icon)
	if border._eqolBorderOffset ~= offset or border._eqolBorderResolvedOffset ~= resolvedOffset then
		cdp.PIXEL.SetOutside(border, icon, offset)
		border._eqolBorderOffset = offset
		border._eqolBorderResolvedOffset = resolvedOffset
	end
	if border.SetBackdrop then pcall(border.SetBackdrop, border, nil) end
	border._eqolBorderEdgeFile = nil
	border._eqolBorderEdgeSize = nil
	border._eqolBorderResolvedEdgeSize = nil

	if addon.IconShape and addon.IconShape.ApplyBorder then
		local ok = addon.IconShape.ApplyBorder(border, textureKey, layout.iconShape, {
			borderSize = edgeSize,
			borderOffset = 0,
			color = color,
			pixelPerfect = true,
			pointFrame = border,
			parent = border,
			primaryTexture = border.shapeBorderTexture,
			texturesKey = "shapeBorderTextures",
		})
		if not ok then return false end
	else
		local layerCount = info.thicknessMode == "layers" and math.min(edgeSize, 24) or 1
		for i = 1, layerCount do
			local texture = cdp.ENTRY.EnsureIconShapeBorderTexture(border, i)
			if texture then
				if info.atlas then
					local ok = texture.SetAtlas and pcall(texture.SetAtlas, texture, info.atlas, false)
					if not ok then
						texture:Hide()
					end
				elseif info.texture then
					texture:SetTexture(info.texture)
					if texture.SetTexCoord then texture:SetTexCoord(0, 1, 0, 1) end
				end
				local layerX, layerY = cdp.ENTRY.GetIconShapeBorderLayerOffset(i)
				layerX = cdp.PIXEL.SizeFromPixels(layerX, border)
				layerY = cdp.PIXEL.SizeFromPixels(layerY, border)
				texture:ClearAllPoints()
				texture:SetPoint("TOPLEFT", border, "TOPLEFT", layerX, -layerY)
				texture:SetPoint("BOTTOMRIGHT", border, "BOTTOMRIGHT", layerX, -layerY)
				if info.tint == true then
					texture:SetVertexColor(color[1] or 1, color[2] or 1, color[3] or 1, color[4] or 1)
				else
					texture:SetVertexColor(1, 1, 1, color[4] or 1)
				end
				texture:Show()
			end
		end
		for i = layerCount + 1, #(border.shapeBorderTextures or {}) do
			border.shapeBorderTextures[i]:Hide()
		end
	end
	border._eqolShapeBorderAtlas = info.atlas
	border._eqolShapeBorderTexture = info.texture
	border._eqolShapeBorderEdgeSize = edgeSize
	border._eqolIconBorderEnabled = true
	border:Show()
	return true
end

local function applyIconBorder(icon, layout, showIconTexture)
	if not icon or not icon.border then return end
	if showIconTexture ~= nil then icon._eqolResolvedShowIconTexture = showIconTexture ~= false end
	icon._eqolGlowBorderLayout = layout
	icon._eqolGlowBorderTintAdapter = cdp.ENTRY.ApplyGlowBorderTint
	icon._eqolGlowBorderVersion = (icon._eqolGlowBorderVersion or 0) + 1
	local border = icon.border
	local defaults = Helper.PANEL_LAYOUT_DEFAULTS
	local iconTextureVisible = icon._eqolResolvedShowIconTexture ~= false
	if showIconTexture ~= nil then iconTextureVisible = showIconTexture ~= false end
	local enabled = iconTextureVisible and layout and layout.iconBorderEnabled == true
	border._eqolIconBorderEnabled = nil
	if not enabled then
		cdp.ENTRY.ClearBlizzardIconSkin(icon)
		cdp.ENTRY.HideIconShapeBorder(border)
		border:Hide()
		return
	end

	local iconShape = cdp.ENTRY.NormalizeIconShape(layout.iconShape, defaults.iconShape)
	local textureKey = normalizeIconBorderTexture(layout.iconBorderTexture, defaults.iconBorderTexture, iconShape)
	if cdp.ENTRY.IsBlizzardIconBorderTexture(textureKey) then
		cdp.ENTRY.HideIconShapeBorder(border)
		border:Hide()
		if iconShape == cdp.ICON_SHAPE.DEFAULT then
			cdp.ENTRY.ApplyBlizzardIconSkin(icon)
		else
			cdp.ENTRY.ClearBlizzardIconSkin(icon)
		end
		return
	end

	cdp.ENTRY.ClearBlizzardIconSkin(icon)
	if cdp.ENTRY.IsShapeIconBorderCompatible(textureKey, iconShape) then
		if cdp.ENTRY.ApplyIconShapeBorder(icon, border, textureKey, layout, defaults) then return end
	end
	cdp.ENTRY.HideIconShapeBorder(border)
	border._eqolIconBorderEnabled = true
	local edgeSize = Helper.ClampInt(layout.iconBorderSize, 1, 64, defaults.iconBorderSize or 1)
	local offset = Helper.ClampInt(layout.iconBorderOffset, -64, 64, defaults.iconBorderOffset or 0)
	local edgeFile = resolveIconBorderTexture(textureKey)
	local color = Helper.NormalizeColor(layout.iconBorderColor, defaults.iconBorderColor)
	local resolvedEdgeSize = cdp.PIXEL.SizeFromPixels(edgeSize, border)
	local resolvedOffset = cdp.PIXEL.Snap(offset, icon)

	if border._eqolBorderEdgeFile ~= edgeFile or border._eqolBorderEdgeSize ~= edgeSize or border._eqolBorderResolvedEdgeSize ~= resolvedEdgeSize then
		border:SetBackdrop({
			edgeFile = edgeFile,
			edgeSize = resolvedEdgeSize,
			insets = { left = 0, right = 0, top = 0, bottom = 0 },
		})
		border:SetBackdropColor(0, 0, 0, 0)
		border._eqolBorderEdgeFile = edgeFile
		border._eqolBorderEdgeSize = edgeSize
		border._eqolBorderResolvedEdgeSize = resolvedEdgeSize
	end

	if border._eqolBorderOffset ~= offset or border._eqolBorderResolvedOffset ~= resolvedOffset then
		cdp.PIXEL.SetOutside(border, icon, offset)
		border._eqolBorderOffset = offset
		border._eqolBorderResolvedOffset = resolvedOffset
	end

	border:SetBackdropBorderColor(color[1] or 0, color[2] or 0, color[3] or 0, color[4] or 1)
	border:Show()
end

function cdp.ENTRY.ApplyGlowBorderTint(icon, host, opts, enabled)
	if not (icon and host) then return end
	local sourceBorderLevel = icon.border and icon.border.GetFrameLevel and icon.border:GetFrameLevel() or icon:GetFrameLevel() or 0
	host:SetFrameStrata((icon.border and icon.border.GetFrameStrata and icon.border:GetFrameStrata()) or icon:GetFrameStrata())
	host:SetFrameLevel(sourceBorderLevel + 2)
	local proxy = host._eqolBorderTintProxy
	if enabled ~= true then
		if proxy then proxy:Hide() end
		return
	end
	local layout = icon._eqolGlowBorderLayout
	if icon._eqolResolvedShowIconTexture == false or not (layout and layout.iconBorderEnabled == true) then
		if proxy then proxy:Hide() end
		return
	end
	if not proxy then
		proxy = CreateFrame("Frame", nil, host)
		proxy:EnableMouse(false)
		proxy:SetAllPoints(host)
		proxy.border = CreateFrame("Frame", nil, proxy, "BackdropTemplate")
		proxy.border:SetAllPoints(proxy)
		host._eqolBorderTintProxy = proxy
	end
	local tintLayout = proxy._eqolBorderTintLayout or {}
	wipe(tintLayout)
	for key, value in pairs(layout) do
		tintLayout[key] = value
	end
	local tintColor = Helper.NormalizeColor(type(opts) == "table" and opts.color or nil, Helper.PANEL_LAYOUT_DEFAULTS.readyGlowColor)
	tintLayout.iconBorderColor = tintColor
	proxy._eqolBorderTintLayout = tintLayout
	proxy:SetFrameStrata(host:GetFrameStrata())
	proxy:SetFrameLevel((host:GetFrameLevel() or 0) + 1)
	proxy.border:SetFrameStrata(host:GetFrameStrata())
	proxy.border:SetFrameLevel((proxy:GetFrameLevel() or 0) + 1)
	proxy:Show()
	applyIconBorder(proxy, tintLayout)
	if proxy.blizzardIconOverlay then
		proxy.blizzardIconOverlay:SetVertexColor(tintColor[1] or 1, tintColor[2] or 1, tintColor[3] or 1, tintColor[4] or 1)
	end
	if proxy.border and proxy.border.shapeBorderTextures then
		for i = 1, #proxy.border.shapeBorderTextures do
			local texture = proxy.border.shapeBorderTextures[i]
			if texture then texture:SetVertexColor(tintColor[1] or 1, tintColor[2] or 1, tintColor[3] or 1, tintColor[4] or 1) end
		end
	end
end

function cdp.ENTRY.ApplyIconBorderCooldownVisibility(icon, entry, cooldownRunning, resourceInsufficient)
	if not icon or not entry then return end
	local hideBorder = (entry.hideBorderOnCooldown == true and (cooldownRunning == true or resourceInsufficient == true))
		or (entry.hideBorderOffCooldown == true and cooldownRunning ~= true)
	if icon.border and icon.border._eqolIconBorderEnabled == true then icon.border:SetShown(not hideBorder) end
	if icon.blizzardIconOverlay and icon._eqolBlizzardIconBorderEnabled == true then icon.blizzardIconOverlay:SetShown(not hideBorder) end
end

local function applyIconLayout(frame, count, layout)
	if not frame then return end
	local iconSize = Helper.ClampInt(layout.iconSize, 12, 128, Helper.PANEL_LAYOUT_DEFAULTS.iconSize)
	local iconWidth = layout.iconSizeSeparate == true and Helper.ClampInt(layout.iconWidth, 12, 128, iconSize) or iconSize
	local iconHeight = layout.iconSizeSeparate == true and Helper.ClampInt(layout.iconHeight, 12, 128, iconSize) or iconSize
	local spacing = cdp.PIXEL.Snap(Helper.ClampInt(layout.spacing, 0, Helper.SPACING_RANGE or 200, Helper.PANEL_LAYOUT_DEFAULTS.spacing), frame)
	local layoutMode = Helper.NormalizeLayoutMode(layout.layoutMode, Helper.PANEL_LAYOUT_DEFAULTS.layoutMode)
	local direction = Helper.NormalizeDirection(layout.direction, Helper.PANEL_LAYOUT_DEFAULTS.direction)
	local wrapCount = Helper.ClampInt(layout.wrapCount, 0, 40, Helper.PANEL_LAYOUT_DEFAULTS.wrapCount or 0)
	local wrapDirection = Helper.NormalizeDirection(layout.wrapDirection, Helper.PANEL_LAYOUT_DEFAULTS.wrapDirection or "DOWN")
	local growthPoint = Helper.NormalizeGrowthPoint(layout.growthPoint, Helper.PANEL_LAYOUT_DEFAULTS.growthPoint)
	local primaryHorizontal = direction == "LEFT" or direction == "RIGHT"
	local stackAnchor = Helper.NormalizeAnchor(layout.stackAnchor, Helper.PANEL_LAYOUT_DEFAULTS.stackAnchor)
	local stackX = Helper.ClampInt(layout.stackX, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, Helper.PANEL_LAYOUT_DEFAULTS.stackX)
	local stackY = Helper.ClampInt(layout.stackY, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, Helper.PANEL_LAYOUT_DEFAULTS.stackY)
	local chargesAnchor = Helper.NormalizeAnchor(layout.chargesAnchor, Helper.PANEL_LAYOUT_DEFAULTS.chargesAnchor)
	local chargesX = Helper.ClampInt(layout.chargesX, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, Helper.PANEL_LAYOUT_DEFAULTS.chargesX)
	local chargesY = Helper.ClampInt(layout.chargesY, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, Helper.PANEL_LAYOUT_DEFAULTS.chargesY)
	local keybindAnchor = Helper.NormalizeAnchor(layout.keybindAnchor, Helper.PANEL_LAYOUT_DEFAULTS.keybindAnchor)
	local keybindX = Helper.ClampInt(layout.keybindX, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, Helper.PANEL_LAYOUT_DEFAULTS.keybindX)
	local keybindY = Helper.ClampInt(layout.keybindY, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, Helper.PANEL_LAYOUT_DEFAULTS.keybindY)
	local drawEdge = layout.cooldownDrawEdge ~= false
	local drawBling = layout.cooldownDrawBling ~= false
	local drawSwipe = layout.cooldownDrawSwipe ~= false
	local cooldownTextFont = layout.cooldownTextFont
	local cooldownTextSize = layout.cooldownTextSize
	local cooldownTextStyle = layout.cooldownTextStyle
	local cooldownTextColor = Helper.NormalizeColor(layout.cooldownTextColor, Helper.PANEL_LAYOUT_DEFAULTS.cooldownTextColor)
	local cooldownTextX = Helper.ClampInt(layout.cooldownTextX, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, 0)
	local cooldownTextY = Helper.ClampInt(layout.cooldownTextY, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, 0)

	local cols, rows = 1, 1
	local baseIconSize = iconSize
	local resolvedBaseIconSize = cdp.PIXEL.SnapSize(baseIconSize, frame)
	local baseIconWidth = cdp.PIXEL.SnapSize(iconWidth, frame)
	local baseIconHeight = cdp.PIXEL.SnapSize(iconHeight, frame)
	local rowSizes = {}
	local rowOffsets = {}
	local rowWidths = {}
	local width = 0
	local height = 0
	local radialRadius = nil
	local radialRotation = nil
	local radialArcDegrees = nil
	local radialStep = nil
	local radialBaseAngle = nil
	local function getRowIconDimensions(rowSize)
		rowSize = Helper.ClampInt(rowSize, 12, 128, baseIconSize)
		if layout.iconSizeSeparate == true then
			local scale = baseIconSize > 0 and (rowSize / baseIconSize) or 1
			local rowWidth = Helper.ClampInt(iconWidth * scale, 12, 128, iconWidth)
			local rowHeight = Helper.ClampInt(iconHeight * scale, 12, 128, iconHeight)
			return cdp.PIXEL.SnapSize(rowWidth, frame), cdp.PIXEL.SnapSize(rowHeight, frame)
		end
		local resolvedSize = cdp.PIXEL.SnapSize(rowSize, frame)
		return resolvedSize, resolvedSize
	end

	if layoutMode == "RADIAL" then
		radialRadius = cdp.PIXEL.Snap(Helper.ClampInt(layout.radialRadius, 0, Helper.RADIAL_RADIUS_RANGE or 600, Helper.PANEL_LAYOUT_DEFAULTS.radialRadius), frame)
		radialRotation = Helper.ClampNumber(layout.radialRotation, -Helper.RADIAL_ROTATION_RANGE, Helper.RADIAL_ROTATION_RANGE, Helper.PANEL_LAYOUT_DEFAULTS.radialRotation)
		radialArcDegrees = Helper.ClampInt(layout.radialArcDegrees, Helper.RADIAL_ARC_DEGREES_MIN or 15, Helper.RADIAL_ARC_DEGREES_MAX or 360, Helper.PANEL_LAYOUT_DEFAULTS.radialArcDegrees or 360)
		if radialArcDegrees >= (Helper.RADIAL_ARC_DEGREES_MAX or 360) then
			radialStep = count > 0 and ((2 * math.pi) / count) or 0
		else
			radialStep = count > 1 and (math.rad(radialArcDegrees) / (count - 1)) or 0
		end
		radialBaseAngle = (math.pi / 2) - math.rad(radialRotation or 0)
		width = math.max(resolvedBaseIconSize, radialRadius * 2)
		height = width
	else
		cols, rows = getGridDimensions(count, wrapCount, primaryHorizontal)
		if primaryHorizontal then
			local totalHeight = 0
			for rowIndex = 1, rows do
				local rowSize = baseIconSize
				if type(layout.rowSizes) == "table" then
					local override = tonumber(layout.rowSizes[rowIndex])
					if override then rowSize = Helper.ClampInt(override, 12, 128, baseIconSize) end
				end
				rowSizes[rowIndex] = rowSize
				rowOffsets[rowIndex] = totalHeight
				local rowIconWidth, rowIconHeight = getRowIconDimensions(rowSize)
				local rowCols = cols
				if wrapCount and wrapCount > 0 then
					local fillIndex = rowIndex
					if wrapDirection == "UP" then fillIndex = rows - rowIndex + 1 end
					rowCols = math.min(wrapCount, count - ((fillIndex - 1) * wrapCount))
					if rowCols < 1 then rowCols = 1 end
				end
				local rowWidth = (rowCols * rowIconWidth) + ((rowCols - 1) * spacing)
				rowWidths[rowIndex] = rowWidth
				if rowWidth > width then width = rowWidth end
				totalHeight = totalHeight + rowIconHeight + spacing
			end
			if rows > 0 then height = totalHeight - spacing end
		else
			local step = baseIconHeight + spacing
			width = (cols * baseIconWidth) + ((cols - 1) * spacing)
			height = (rows * baseIconHeight) + ((rows - 1) * spacing)
			for rowIndex = 1, rows do
				rowSizes[rowIndex] = baseIconSize
				rowOffsets[rowIndex] = (rowIndex - 1) * step
				rowWidths[rowIndex] = width
			end
		end
	end

	if width <= 0 then width = baseIconWidth end
	if height <= 0 then height = baseIconHeight end

	cdp.PIXEL.SetSize(frame, width, height)
	ensureIconCount(frame, count)
	local fontPath, fontSize, fontStyle = Helper.GetCountFontDefaults(frame)
	local countFontPath = Helper.ResolveFontPath(layout.stackFont, fontPath)
	local countFontSize = Helper.ClampInt(layout.stackFontSize, 6, 64, fontSize or 12)
	local countFontStyle = Helper.NormalizeFontStyle(layout.stackFontStyle, fontStyle)
	local countFontColor = Helper.NormalizeColor(layout.stackColor, Helper.PANEL_LAYOUT_DEFAULTS.stackColor or { 1, 1, 1, 1 })
	local chargesFontPath, chargesFontSize, chargesFontStyle = Helper.GetChargesFontDefaults(frame)
	local chargesPath = Helper.ResolveFontPath(layout.chargesFont, chargesFontPath)
	local chargesSize = Helper.ClampInt(layout.chargesFontSize, 6, 64, chargesFontSize or 12)
	local chargesStyle = Helper.NormalizeFontStyle(layout.chargesFontStyle, chargesFontStyle)
	local chargesFontColor = Helper.NormalizeColor(layout.chargesColor, Helper.PANEL_LAYOUT_DEFAULTS.chargesColor or { 1, 1, 1, 1 })
	local keybindFontPath = Helper.ResolveFontPath(layout.keybindFont, countFontPath)
	local keybindFontSize = Helper.ClampInt(layout.keybindFontSize, 6, 64, Helper.PANEL_LAYOUT_DEFAULTS.keybindFontSize or math.min(countFontSize, 10))
	local keybindFontStyle = Helper.NormalizeFontStyle(layout.keybindFontStyle, countFontStyle)

	local function getAnchorComponents(point)
		local h = "CENTER"
		if point and point:find("LEFT") then
			h = "LEFT"
		elseif point and point:find("RIGHT") then
			h = "RIGHT"
		end
		local v = "CENTER"
		if point and point:find("TOP") then
			v = "TOP"
		elseif point and point:find("BOTTOM") then
			v = "BOTTOM"
		end
		return h, v
	end
	local function getGrowthOffset(point, gridWidth, gridHeight)
		local h, v = getAnchorComponents(point)
		local x = 0
		if h == "CENTER" then x = -(gridWidth / 2) end
		if h == "RIGHT" then x = -gridWidth end
		local y = 0
		if v == "CENTER" then
			y = (gridHeight / 2)
		elseif v == "BOTTOM" then
			y = gridHeight
		end
		return x, y, h, v
	end
	local growthOffsetX, growthOffsetY, anchorH, anchorV = getGrowthOffset(growthPoint, width, height)

	local function applyIconCommon(icon, rowSize)
		local slotAnchor = icon.slotAnchor or icon
		local rowWidth, rowHeight = getRowIconDimensions(rowSize)
		cdp.PIXEL.SetSize(slotAnchor, rowWidth, rowHeight)
		icon._eqolBaseSlotSize = rowSize
		cdp.PIXEL.SetSize(icon, rowWidth, rowHeight)
		if slotAnchor ~= icon then
			icon:ClearAllPoints()
			icon:SetPoint("CENTER", slotAnchor, "CENTER", 0, 0)
		end
		icon._eqolVisualSize = nil
		icon._eqolVisualWidth = nil
		icon._eqolVisualHeight = nil
		icon._eqolVisualShape = nil
		icon._eqolVisualIconZoom = nil
		icon._eqolVisualAnchor = nil
		icon._eqolVisualOffsetX = nil
		icon._eqolVisualOffsetY = nil
		applyIconBorder(icon, layout)
		if icon.count then
			local r = countFontColor[1] or 1
			local g = countFontColor[2] or 1
			local b = countFontColor[3] or 1
			local a = countFontColor[4] or 1
			icon.count:ClearAllPoints()
			icon.count:SetPoint(stackAnchor, icon, stackAnchor, stackX, stackY)
			if Helper.SetFont then
				Helper.SetFont(icon.count, countFontPath, countFontSize, countFontStyle, fontPath)
			else
				icon.count:SetFont(countFontPath, countFontSize, countFontStyle)
			end
			if addon.functions and addon.functions.ApplyFontStyleShadow then
				addon.functions.ApplyFontStyleShadow(icon.count, Helper.NormalizeFontStyleChoice(layout and layout.stackFontStyle, fontStyle), fontStyle)
			end
			icon.count:SetTextColor(r, g, b, a)
			icon.count._eqolStackAnchor = stackAnchor
			icon.count._eqolStackX = stackX
			icon.count._eqolStackY = stackY
			icon.count._eqolStackFont = countFontPath
			icon.count._eqolStackFontSize = countFontSize
			icon.count._eqolStackFontStyle = countFontStyle
			icon.count._eqolStackColorR = r
			icon.count._eqolStackColorG = g
			icon.count._eqolStackColorB = b
			icon.count._eqolStackColorA = a
		end
		if icon.charges then
			local r = chargesFontColor[1] or 1
			local g = chargesFontColor[2] or 1
			local b = chargesFontColor[3] or 1
			local a = chargesFontColor[4] or 1
			icon.charges:ClearAllPoints()
			icon.charges:SetPoint(chargesAnchor, icon, chargesAnchor, chargesX, chargesY)
			if Helper.SetFont then
				Helper.SetFont(icon.charges, chargesPath, chargesSize, chargesStyle, chargesFontPath)
			else
				icon.charges:SetFont(chargesPath, chargesSize, chargesStyle)
			end
			if addon.functions and addon.functions.ApplyFontStyleShadow then
				addon.functions.ApplyFontStyleShadow(icon.charges, Helper.NormalizeFontStyleChoice(layout and layout.chargesFontStyle, chargesFontStyle), chargesFontStyle)
			end
			icon.charges:SetTextColor(r, g, b, a)
			icon.charges._eqolChargesAnchor = chargesAnchor
			icon.charges._eqolChargesX = chargesX
			icon.charges._eqolChargesY = chargesY
			icon.charges._eqolChargesFont = chargesPath
			icon.charges._eqolChargesFontSize = chargesSize
			icon.charges._eqolChargesFontStyle = chargesStyle
			icon.charges._eqolChargesColorR = r
			icon.charges._eqolChargesColorG = g
			icon.charges._eqolChargesColorB = b
			icon.charges._eqolChargesColorA = a
		end
		if icon.keybind then
			icon.keybind:ClearAllPoints()
			icon.keybind:SetPoint(keybindAnchor, icon, keybindAnchor, keybindX, keybindY)
			if Helper.SetFont then
				Helper.SetFont(icon.keybind, keybindFontPath, keybindFontSize, keybindFontStyle, countFontPath)
			else
				icon.keybind:SetFont(keybindFontPath, keybindFontSize, keybindFontStyle)
			end
			if addon.functions and addon.functions.ApplyFontStyleShadow then
				addon.functions.ApplyFontStyleShadow(icon.keybind, Helper.NormalizeFontStyleChoice(layout and layout.keybindFontStyle, countFontStyle), countFontStyle)
			end
		end
		setCooldownDrawState(icon.cooldown, drawEdge, drawBling, drawSwipe)
		if icon.cooldown and icon.cooldown.GetCountdownFontString then
			local fontString = icon.cooldown:GetCountdownFontString()
			if fontString then
				if not icon.cooldown._eqolCooldownTextDefaults then
					local fontPath, fontSize, fontStyle = fontString:GetFont()
					icon.cooldown._eqolCooldownTextDefaults = {
						font = fontPath,
						size = fontSize,
						style = fontStyle,
					}
				end
				local defaults = icon.cooldown._eqolCooldownTextDefaults
				local fontPath = Helper.ResolveFontPath(cooldownTextFont, defaults and defaults.font)
				local fontSize = Helper.ClampInt(cooldownTextSize, 6, 64, defaults and defaults.size or 12)
				local fontStyle = Helper.NormalizeFontStyle(cooldownTextStyle, defaults and defaults.style) or ""
				local r = cooldownTextColor[1] or 1
				local g = cooldownTextColor[2] or 1
				local b = cooldownTextColor[3] or 1
				local a = cooldownTextColor[4] or 1
				if Helper.SetFont then
					Helper.SetFont(fontString, fontPath, fontSize, fontStyle, defaults and defaults.font)
				else
					fontString:SetFont(fontPath, fontSize, fontStyle)
				end
				if addon.functions and addon.functions.ApplyFontStyleShadow then
					addon.functions.ApplyFontStyleShadow(fontString, Helper.NormalizeFontStyleChoice(cooldownTextStyle, defaults and defaults.style), defaults and defaults.style)
				end
				fontString:ClearAllPoints()
				fontString:SetPoint("CENTER", icon.cooldown, "CENTER", cooldownTextX, cooldownTextY)
				fontString:SetTextColor(r, g, b, a)
				fontString._eqolCooldownFont = fontPath
				fontString._eqolCooldownFontSize = fontSize
				fontString._eqolCooldownFontStyle = fontStyle
				fontString._eqolCooldownAnchor = "CENTER"
				fontString._eqolCooldownX = cooldownTextX
				fontString._eqolCooldownY = cooldownTextY
				fontString._eqolCooldownColorR = r
				fontString._eqolCooldownColorG = g
				fontString._eqolCooldownColorB = b
				fontString._eqolCooldownColorA = a
			end
		end
		CooldownPanels.UpdatePreviewGlowBorderLayout(icon, rowSize)
		if icon.previewBling then
			icon.previewBling:ClearAllPoints()
			icon.previewBling:SetPoint("CENTER", icon, "CENTER", 0, 0)
			icon.previewBling:SetSize(rowSize * 1.5, rowSize * 1.5)
		end
		resizeAssistedHighlight(icon)
	end

	if layoutMode == "RADIAL" then
		local centerRadius = (radialRadius or 0) - (resolvedBaseIconSize / 2)
		if centerRadius < 0 then centerRadius = 0 end
		for i = 1, count do
			local icon = frame.icons[i]
			local slotAnchor = icon.slotAnchor or icon
			applyIconCommon(icon, baseIconSize)
			local x, y = 0, 0
			if count > 1 then
				local angle = radialBaseAngle - ((i - 1) * (radialStep or 0))
				x = math.cos(angle) * centerRadius
				y = math.sin(angle) * centerRadius
			end
			slotAnchor:ClearAllPoints()
			slotAnchor:SetPoint("CENTER", frame, "CENTER", x, y)
			if slotAnchor ~= icon then
				icon:ClearAllPoints()
				icon:SetPoint("CENTER", slotAnchor, "CENTER", 0, 0)
			end
		end
		return
	end

	for i = 1, count do
		local icon = frame.icons[i]
		local slotAnchor = icon.slotAnchor or icon
		local primaryIndex = i - 1
		local secondaryIndex = 0
		if wrapCount and wrapCount > 0 then
			primaryIndex = (i - 1) % wrapCount
			secondaryIndex = math.floor((i - 1) / wrapCount)
		end

		local col, row
		if primaryHorizontal then
			col = primaryIndex
			row = secondaryIndex
		else
			local colCount = wrapCount and wrapCount > 0 and math.min(wrapCount, count - (secondaryIndex * wrapCount)) or count
			local rowOffset = anchorV == "CENTER" and ((rows - colCount) / 2) or 0
			row = primaryIndex + rowOffset
			col = secondaryIndex
		end

		if primaryHorizontal and direction == "LEFT" then
			col = (cols - 1) - col
		elseif (not primaryHorizontal) and direction == "UP" then
			row = (rows - 1) - row
		end

		if primaryHorizontal then
			if wrapDirection == "UP" then row = (rows - 1) - row end
		else
			if wrapDirection == "LEFT" then col = (cols - 1) - col end
		end

		local rowIndex = row + 1
		local rowSize = rowSizes[rowIndex] or baseIconSize
		local rowIconWidth, rowHeight = getRowIconDimensions(rowSize)
		local rowOffset = rowOffsets[rowIndex] or (row * (baseIconHeight + spacing))
		local rowWidth = rowWidths[rowIndex] or width
		local rowAlignOffset = 0
		if primaryHorizontal then
			if anchorH == "CENTER" then
				rowAlignOffset = (width - rowWidth) / 2
			elseif anchorH == "RIGHT" then
				rowAlignOffset = width - rowWidth
			end
		end
		local anchorXAdjust = 0
		if anchorH == "CENTER" then
			anchorXAdjust = rowIconWidth / 2
		elseif anchorH == "RIGHT" then
			anchorXAdjust = rowIconWidth
		end
		local anchorYAdjust = 0
		if anchorV == "CENTER" then
			anchorYAdjust = -(rowHeight / 2)
		elseif anchorV == "BOTTOM" then
			anchorYAdjust = -rowHeight
		end
		local stepX = primaryHorizontal and (rowIconWidth + spacing) or (baseIconWidth + spacing)

		applyIconCommon(icon, rowSize)
		slotAnchor:ClearAllPoints()
		slotAnchor:SetPoint(growthPoint, frame, growthPoint, growthOffsetX + anchorXAdjust + rowAlignOffset + (col * stepX), growthOffsetY + anchorYAdjust - rowOffset)
		if slotAnchor ~= icon then
			icon:ClearAllPoints()
			icon:SetPoint("CENTER", slotAnchor, "CENTER", 0, 0)
		end
	end
end

local function applyPanelBorder(frame)
	local borderLayer, borderSubLevel = "BORDER", 0
	local borderPath = "Interface\\AddOns\\EnhanceQoL\\Assets\\PanelBorder_"
	local cornerSize = 70
	local edgeThickness = 70
	local cornerOffsets = 13

	local function makeTex(key, layer, subLevel)
		local tex = frame:CreateTexture(nil, layer or borderLayer, nil, subLevel or borderSubLevel)
		tex:SetTexture(borderPath .. key .. ".tga")
		tex:SetAlpha(0.95)
		return tex
	end

	local tl = makeTex("tl", borderLayer, borderSubLevel + 1)
	tl:SetSize(cornerSize, cornerSize)
	tl:SetPoint("TOPLEFT", frame, "TOPLEFT", -cornerOffsets, cornerOffsets)

	local tr = makeTex("tr", borderLayer, borderSubLevel + 1)
	tr:SetSize(cornerSize, cornerSize)
	tr:SetPoint("TOPRIGHT", frame, "TOPRIGHT", cornerOffsets + 8, cornerOffsets)

	local bl = makeTex("bl", borderLayer, borderSubLevel + 1)
	bl:SetSize(cornerSize, cornerSize)
	bl:SetPoint("BOTTOMLEFT", frame, "BOTTOMLEFT", -cornerOffsets, -cornerOffsets)

	local br = makeTex("br", borderLayer, borderSubLevel + 1)
	br:SetSize(cornerSize, cornerSize)
	br:SetPoint("BOTTOMRIGHT", frame, "BOTTOMRIGHT", cornerOffsets + 8, -cornerOffsets)

	local top = makeTex("t", borderLayer, borderSubLevel)
	top:SetPoint("TOPLEFT", tl, "TOPRIGHT", 0, 0)
	top:SetPoint("TOPRIGHT", tr, "TOPLEFT", 0, 0)
	top:SetHeight(edgeThickness)
	top:SetHorizTile(true)

	local bottom = makeTex("b", borderLayer, borderSubLevel)
	bottom:SetPoint("BOTTOMLEFT", bl, "BOTTOMRIGHT", 0, 0)
	bottom:SetPoint("BOTTOMRIGHT", br, "BOTTOMLEFT", 0, 0)
	bottom:SetHeight(edgeThickness)
	bottom:SetHorizTile(true)

	local left = makeTex("l", borderLayer, borderSubLevel)
	left:SetPoint("TOPLEFT", tl, "BOTTOMLEFT", 0, 0)
	left:SetPoint("BOTTOMLEFT", bl, "TOPLEFT", 0, 0)
	left:SetWidth(edgeThickness)
	left:SetVertTile(true)

	local right = makeTex("r", borderLayer, borderSubLevel)
	right:SetPoint("TOPRIGHT", tr, "BOTTOMRIGHT", 0, 0)
	right:SetPoint("BOTTOMRIGHT", br, "TOPRIGHT", 0, 0)
	right:SetWidth(edgeThickness)
	right:SetVertTile(true)
end

local function applyInsetBorder(frame, offset)
	if not frame then return end
	offset = offset or 10

	local layer, subLevel = "BORDER", 2
	local path = "Interface\\AddOns\\EnhanceQoL\\Assets\\border_round_"
	local cornerSize = 36
	local edgeSize = 36

	frame.eqolInsetParts = frame.eqolInsetParts or {}
	local parts = frame.eqolInsetParts

	local function tex(name)
		if not parts[name] then parts[name] = frame:CreateTexture(nil, layer, nil, subLevel) end
		local t = parts[name]
		t:SetAlpha(0.7)
		t:SetTexture(path .. name .. ".tga")
		t:SetDrawLayer(layer, subLevel)
		return t
	end

	local tl = tex("tl")
	tl:SetSize(cornerSize, cornerSize)
	tl:ClearAllPoints()
	tl:SetPoint("TOPLEFT", frame, "TOPLEFT", offset, -offset)

	local tr = tex("tr")
	tr:SetSize(cornerSize, cornerSize)
	tr:ClearAllPoints()
	tr:SetPoint("TOPRIGHT", frame, "TOPRIGHT", -offset, -offset)

	local bl = tex("bl")
	bl:SetSize(cornerSize, cornerSize)
	bl:ClearAllPoints()
	bl:SetPoint("BOTTOMLEFT", frame, "BOTTOMLEFT", offset, offset)

	local br = tex("br")
	br:SetSize(cornerSize, cornerSize)
	br:ClearAllPoints()
	br:SetPoint("BOTTOMRIGHT", frame, "BOTTOMRIGHT", -offset, offset)

	local top = tex("t")
	top:ClearAllPoints()
	top:SetPoint("TOPLEFT", tl, "TOPRIGHT", 0, 0)
	top:SetPoint("TOPRIGHT", tr, "TOPLEFT", 0, 0)
	top:SetHeight(edgeSize)
	top:SetHorizTile(true)

	local bottom = tex("b")
	bottom:ClearAllPoints()
	bottom:SetPoint("BOTTOMLEFT", bl, "BOTTOMRIGHT", 0, 0)
	bottom:SetPoint("BOTTOMRIGHT", br, "BOTTOMLEFT", 0, 0)
	bottom:SetHeight(edgeSize)
	bottom:SetHorizTile(true)

	local left = tex("l")
	left:ClearAllPoints()
	left:SetPoint("TOPLEFT", tl, "BOTTOMLEFT", 0, 0)
	left:SetPoint("BOTTOMLEFT", bl, "TOPLEFT", 0, 0)
	left:SetWidth(edgeSize)
	left:SetVertTile(true)

	local right = tex("r")
	right:ClearAllPoints()
	right:SetPoint("TOPRIGHT", tr, "BOTTOMRIGHT", 0, 0)
	right:SetPoint("BOTTOMRIGHT", br, "TOPRIGHT", 0, 0)
	right:SetWidth(edgeSize)
	right:SetVertTile(true)
end

local function showEditorDragIcon(editor, texture)
	if not editor then return end
	if not editor.dragIcon then
		local frame = CreateFrame("Frame", nil, UIParent)
		frame:SetSize(34, 34)
		frame:SetFrameStrata("TOOLTIP")
		frame.texture = frame:CreateTexture(nil, "OVERLAY")
		frame.texture:SetAllPoints()
		editor.dragIcon = frame
	end
	editor.dragIcon.texture:SetTexture(texture or Helper.PREVIEW_ICON)
	editor.dragIcon:SetScript("OnUpdate", function(f)
		local x, y = Api.GetCursorPosition()
		local scale = UIParent:GetEffectiveScale()
		f:ClearAllPoints()
		f:SetPoint("CENTER", UIParent, "BOTTOMLEFT", x / scale, y / scale)
	end)
	editor.dragIcon:Show()
end

local function hideEditorDragIcon(editor)
	if not editor or not editor.dragIcon then return end
	editor.dragIcon:SetScript("OnUpdate", nil)
	editor.dragIcon:Hide()
end

function CooldownPanels:GetCursorPositionOnUIParent()
	if not (Api.GetCursorPosition and UIParent and UIParent.GetEffectiveScale) then return nil, nil end
	local x, y = Api.GetCursorPosition()
	local scale = UIParent:GetEffectiveScale()
	if not (x and y and scale and scale > 0) then return nil, nil end
	return x / scale, y / scale
end

function CooldownPanels:GetLayoutEntryCandidatesAtCursor(panelId)
	panelId = normalizeId(panelId)
	if not panelId then return nil end
	local cursorX, cursorY = self:GetCursorPositionOnUIParent()
	if not (cursorX and cursorY) then return nil end
	local runtime = getRuntime(panelId)
	local frame = runtime and runtime.frame or nil
	local icons = frame and frame.icons or nil
	if not icons then return nil end

	local candidates = {}
	local seen = {}
	for i = #icons, 1, -1 do
		local icon = icons[i]
		local candidateEntryId = normalizeId(icon and (icon.entryId or (icon.cooldown and icon.cooldown._eqolEntryId)) or nil)
		if candidateEntryId and not seen[candidateEntryId] and icon and icon.IsShown and icon:IsShown() then
			local left = icon.GetLeft and icon:GetLeft() or nil
			local right = icon.GetRight and icon:GetRight() or nil
			local top = icon.GetTop and icon:GetTop() or nil
			local bottom = icon.GetBottom and icon:GetBottom() or nil
			if left and right and top and bottom and cursorX >= left and cursorX <= right and cursorY <= top and cursorY >= bottom then
				candidates[#candidates + 1] = {
					entryId = candidateEntryId,
					icon = icon,
					anchorFrame = (icon.layoutHandle and icon.layoutHandle.IsShown and icon.layoutHandle:IsShown()) and icon.layoutHandle or icon,
					frameLevel = icon.GetFrameLevel and icon:GetFrameLevel() or 0,
					index = i,
				}
				seen[candidateEntryId] = true
			end
		end
	end

	table.sort(candidates, function(a, b)
		if (a.frameLevel or 0) ~= (b.frameLevel or 0) then return (a.frameLevel or 0) > (b.frameLevel or 0) end
		return (a.index or 0) > (b.index or 0)
	end)

	return candidates
end

function CooldownPanels:ShowLayoutEntryChooserMenu(owner, panelId, candidates)
	if not (owner and panelId and candidates and #candidates > 1 and Api.MenuUtil and Api.MenuUtil.CreateContextMenu) then return false end
	local panel = self:GetPanel(panelId)
	if not panel then return false end

	Api.MenuUtil.CreateContextMenu(owner, function(_, rootDescription)
		rootDescription:SetTag("MENU_EQOL_COOLDOWN_PANEL_LAYOUT_ENTRY_PICKER")
		if rootDescription.SetScrollMode then rootDescription:SetScrollMode(260) end
		rootDescription:CreateTitle("Select entry")
		for _, candidate in ipairs(candidates) do
			local entryId = normalizeId(candidate and candidate.entryId)
			local entry = entryId and panel.entries and panel.entries[entryId] or nil
			if entry then
				local label = CooldownPanels:GetEntryStandaloneTitle(entry)
				local slotColumn = Helper.NormalizeSlotCoordinate(entry.slotColumn)
				local slotRow = Helper.NormalizeSlotCoordinate(entry.slotRow)
				local iconToken = getEntryIcon(entry)
				local iconType = type(iconToken)
				if slotColumn and slotRow then label = string.format("%s [%d,%d]", label, slotColumn, slotRow) end
				if (iconType == "string" and iconToken ~= "") or iconType == "number" then label = string.format("|T%s:14:14:0:0:64:64:4:60:4:60|t %s", tostring(iconToken), label) end
				rootDescription:CreateButton(label, function()
					CooldownPanels:SelectPanel(panelId)
					CooldownPanels:SelectEntry(entryId)
					CooldownPanels:OpenLayoutEntryStandaloneMenu(panelId, entryId, candidate.anchorFrame or candidate.icon or owner)
				end)
			end
		end
	end)

	return true
end

function CooldownPanels:ShowEntryQuickSetupMenu(owner, panelId, entryId)
	panelId = normalizeId(panelId)
	entryId = normalizeId(entryId)
	if not (owner and panelId and entryId and Api.MenuUtil and Api.MenuUtil.CreateContextMenu) then return false end
	local panel = self:GetPanel(panelId)
	local entry = panel and panel.entries and panel.entries[entryId] or nil
	if not entry then return false end
	Api.MenuUtil.CreateContextMenu(owner, function(_, rootDescription)
		rootDescription:SetTag("MENU_EQOL_COOLDOWN_PANEL_ENTRY_QUICK_SETUP")
		rootDescription:CreateTitle(L["CooldownPanelQuickSetups"] or "Quick setups")
		local bars = self.Bars
		if bars and bars.IsBarDisplayModeValue and bars.IsBarDisplayModeValue(entry.displayMode) then
			if bars.AppendQuickSetupMenu then bars.AppendQuickSetupMenu(rootDescription, panelId, entryId) end
			return
		end
		local effectiveType = CooldownPanels:GetLayoutEntryStandaloneEffectiveType(entry)
		local supportsStacksOnly = effectiveType == "SPELL" or effectiveType == "CDM_AURA"
		if effectiveType == "SLOT" then
			local slotID = tonumber(entry.slotID)
			supportsStacksOnly = slotID == 13 or slotID == 14
		end
		if supportsStacksOnly then
			rootDescription:CreateButton(L["CooldownPanelQuickSetupStacksOnly"] or "Stack count only", function()
				CooldownPanels:ApplyStacksOnlyQuickSetup(panelId, entryId, true)
			end)
		end
		local textInfoMenu = rootDescription:CreateButton(L["CooldownPanelQuickSetupTextInfoOnCooldown"] or "Text info on cooldown")
		for _, layoutKey in ipairs(cdp.ENTRY.TEXT_INFO_LAYOUT_ORDER) do
			local layout = cdp.ENTRY.TEXT_INFO_LAYOUTS[layoutKey]
			if layout then
				textInfoMenu:CreateButton(L[layout.labelKey] or layout.fallback, function()
					CooldownPanels:ApplyTextInfoOnCooldownQuickSetup(panelId, entryId, true, layoutKey)
				end)
			end
		end
		local textAlwaysMenu = rootDescription:CreateButton(L["CooldownPanelQuickSetupTextAlwaysWithCooldown"] or "Text always with cooldown")
		for _, layoutKey in ipairs(cdp.ENTRY.TEXT_INFO_LAYOUT_ORDER) do
			local layout = cdp.ENTRY.TEXT_INFO_LAYOUTS[layoutKey]
			if layout then
				textAlwaysMenu:CreateButton(L[layout.labelKey] or layout.fallback, function()
					CooldownPanels:ApplyTextAlwaysWithCooldownQuickSetup(panelId, entryId, true, layoutKey)
				end)
			end
		end
		if entry.type ~= "CDM_AURA" then
			rootDescription:CreateButton(L["CooldownPanelQuickSetupTextInfoWhenReady"] or "Text info when ready", function()
				CooldownPanels:ApplyTextInfoWhenReadyQuickSetup(panelId, entryId, true)
			end)
		end
	end)
	return true
end

function cdp.ENTRY.EnsureAddByIDPopup()
	if StaticPopupDialogs["EQOL_COOLDOWN_PANEL_ADD_BY_ID"] then return end
	StaticPopupDialogs["EQOL_COOLDOWN_PANEL_ADD_BY_ID"] = {
		text = "%s",
		button1 = _G.ADD or OKAY,
		button2 = CANCEL,
		hasEditBox = true,
		editBoxWidth = 160,
		timeout = 0,
		whileDead = true,
		hideOnEscape = true,
		preferredIndex = 3,
		OnShow = function(self)
			self:SetFrameStrata("TOOLTIP")
			local editBox = self.editBox or self:GetEditBox()
			if editBox then
				editBox:SetText("")
				editBox:SetNumeric(true)
				editBox:SetFocus()
			end
		end,
		EditBoxOnEnterPressed = function(editBox)
			local parent = editBox:GetParent()
			if parent and parent.button1 then parent.button1:Click() end
		end,
		OnAccept = function(self, data)
			local panelId = data and data.panelId
			local entryType = data and data.entryType
			local editBox = self.editBox or self:GetEditBox()
			local value = editBox and tonumber(editBox:GetText()) or nil
			if not (panelId and entryType and value) then return end
			local entryId = CooldownPanels:AddEntrySafe(panelId, entryType, value)
			if entryId then
				CooldownPanels:RefreshEditor()
				if CooldownPanels.BlizzardEditor and CooldownPanels.BlizzardEditor.Refresh then CooldownPanels.BlizzardEditor:Refresh() end
			end
		end,
	}
end

function cdp.ENTRY.ShowAddByIDPopup(panelId, entryType)
	panelId = normalizeId(panelId)
	if not panelId then return false end
	entryType = entryType and tostring(entryType):upper() or nil
	if entryType ~= "SPELL" and entryType ~= "ITEM" and entryType ~= "CDM_AURA" then return false end
	cdp.ENTRY.EnsureAddByIDPopup()
	local label
	if entryType == "ITEM" then
		label = L["CooldownPanelAddItemID"] or "Add Item ID"
	elseif entryType == "CDM_AURA" then
		label = L["CooldownPanelAddAuraSpellID"] or "Add Aura Spell ID"
	else
		label = L["CooldownPanelAddSpellID"] or "Add Spell ID"
	end
	StaticPopup_Show("EQOL_COOLDOWN_PANEL_ADD_BY_ID", label, nil, {
		panelId = panelId,
		entryType = entryType,
		label = label,
	})
	return true
end

local function showSlotMenu(owner, panelId)
	if not panelId or not Api.MenuUtil or not Api.MenuUtil.CreateContextMenu then return end
	local slotEntries = getSlotMenuEntries()
	local stanceEntries = CooldownPanels.GetStanceMenuEntries and CooldownPanels:GetStanceMenuEntries() or nil
	local racialEntries = CooldownPanels.GetPlayerRacialSpellEntries and CooldownPanels:GetPlayerRacialSpellEntries() or nil
	local cdmAuras = CooldownPanels.CDMAuras
	local hasCDMMenu = cdmAuras and cdmAuras.AppendAddMenu
	local auraPresets = CooldownPanels.AuraPresets
	local hasAuraPresetMenu = auraPresets and auraPresets.HasAvailablePresets and auraPresets:HasAvailablePresets(panelId)
	local hasOtherEntries = slotEntries and #slotEntries > 0 or stanceEntries and #stanceEntries > 0 or racialEntries and #racialEntries > 0 or hasCDMMenu or hasAuraPresetMenu
	Api.MenuUtil.CreateContextMenu(owner, function(_, rootDescription)
		rootDescription:SetTag("MENU_EQOL_COOLDOWN_PANEL_ENTRY_ADD")
		rootDescription:CreateTitle(L["CooldownPanelAddSlot"] or "Add more")
		rootDescription:CreateButton(L["CooldownPanelAddSpellID"] or "Add Spell ID", function()
			cdp.ENTRY.ShowAddByIDPopup(panelId, "SPELL")
		end)
		if CooldownPanels.AuraContainers then
			rootDescription:CreateButton(L["CooldownPanelAddAuraSpellID"] or "Add Aura Spell ID", function()
				cdp.ENTRY.ShowAddByIDPopup(panelId, "CDM_AURA")
			end)
		end
		rootDescription:CreateButton(L["CooldownPanelAddItemID"] or "Add Item ID", function()
			cdp.ENTRY.ShowAddByIDPopup(panelId, "ITEM")
		end)
		if hasOtherEntries then rootDescription:CreateDivider() end
		if hasAuraPresetMenu then auraPresets:AppendAddMenu(rootDescription, panelId) end
		if slotEntries and #slotEntries > 0 then
			local slotMenu = rootDescription:CreateButton(L["CooldownPanelSlotType"] or _G.SLOT or "Slot")
			for _, slot in ipairs(slotEntries) do
				slotMenu:CreateButton(slot.label, function()
					CooldownPanels:AddEntrySafe(panelId, "SLOT", slot.id)
					CooldownPanels:RefreshEditor()
				end)
			end
		end
		if stanceEntries and #stanceEntries > 0 then
			local stanceMenu = rootDescription:CreateButton((CooldownPanels.GetStanceTypeLabel and CooldownPanels:GetStanceTypeLabel()) or (_G.STANCE or "Stance"))
			for _, classData in ipairs(stanceEntries) do
				local classMenu = stanceMenu:CreateButton(classData.label or tostring(classData.classTag or "Class"))
				for _, stance in ipairs(classData.entries or {}) do
					local menuLabel = stance.label or (_G.STEALTH or "Stealth")
					local iconToken = stance.icon
					local iconType = type(iconToken)
					if (iconType == "string" and iconToken ~= "") or iconType == "number" then menuLabel = string.format("|T%s:14:14:0:0:64:64:4:60:4:60|t %s", tostring(iconToken), menuLabel) end
					classMenu:CreateButton(menuLabel, function()
						local overrides = CooldownPanels.GetStanceDefaultOverrides and CooldownPanels:GetStanceDefaultOverrides() or nil
						CooldownPanels:AddEntrySafe(panelId, "STANCE", stance.id, overrides)
						CooldownPanels:RefreshEditor()
					end)
				end
			end
		end
		if racialEntries and #racialEntries > 0 then
			local racialMenu = rootDescription:CreateButton(L["CooldownPanelAddRacials"] or "Racials")
			if #racialEntries > 1 then
				racialMenu:CreateButton(string.format("%s: %s", _G.ADD or "Add", _G.ALL or "All"), function()
					CooldownPanels:AddPlayerRacialEntries(panelId)
				end)
				racialMenu:CreateDivider()
			end
			for _, racial in ipairs(racialEntries) do
				local label = L["CooldownPanelAddRacial"] or "Racial"
				if #racialEntries > 1 then label = string.format("%s %d", label, _) end
				local iconToken = racial.icon or Helper.PREVIEW_ICON
				local iconType = type(iconToken)
				if (iconType == "string" and iconToken ~= "") or iconType == "number" then label = string.format("|T%s:14:14:0:0:64:64:4:60:4:60|t %s", tostring(iconToken), label) end
				racialMenu:CreateButton(label, function()
					CooldownPanels:AddPlayerRacialEntry(panelId, racial.spellID, racial.racialSlot)
					CooldownPanels:RefreshEditor()
				end)
			end
		end
		if hasCDMMenu then cdmAuras:AppendAddMenu(rootDescription, panelId) end
	end)
end

function CooldownPanels:ShowRacialExclusionsMenu(owner, panelId, entryId)
	if not (owner and panelId and entryId and Api.MenuUtil and Api.MenuUtil.CreateContextMenu) then return end
	local panel = CooldownPanels:GetPanel(panelId)
	local entry = panel and panel.entries and panel.entries[entryId] or nil
	if not CooldownPanels:IsRacialSpellEntry(entry) then return end
	Api.MenuUtil.CreateContextMenu(owner, function(_, rootDescription)
		rootDescription:SetTag("MENU_EQOL_COOLDOWN_PANEL_RACIAL_EXCLUSIONS")
		rootDescription:CreateTitle(L["CooldownPanelRacialExclusions"] or "Excluded racials")
		for _, definition in ipairs(CooldownPanels:GetRacialExclusionDefinitions()) do
			local spellId = tonumber(definition and definition.spellID)
			if spellId then
				local label = getSpellName(spellId) or tostring(spellId)
				local iconToken = C_Spell and C_Spell.GetSpellTexture and C_Spell.GetSpellTexture(spellId) or nil
				local iconType = type(iconToken)
				if (iconType == "string" and iconToken ~= "") or iconType == "number" then label = string.format("|T%s:14:14:0:0:64:64:4:60:4:60|t %s", tostring(iconToken), label) end
				rootDescription:CreateCheckbox(label, function()
					return type(entry.racialVariantExclusions) == "table" and entry.racialVariantExclusions[spellId] == true or false
				end, function()
					entry.racialVariantExclusions = entry.racialVariantExclusions or {}
					if entry.racialVariantExclusions[spellId] == true then
						entry.racialVariantExclusions[spellId] = nil
					else
						entry.racialVariantExclusions[spellId] = true
					end
					if not next(entry.racialVariantExclusions) then entry.racialVariantExclusions = nil end
					CooldownPanels:RebuildSpellIndex()
					CooldownPanels:RefreshPanel(panelId)
					CooldownPanels:RefreshEditor()
				end)
			end
		end
	end)
end

function CooldownPanels:GetSpellIdFromCooldownManagerInfo(cooldownInfo)
	return Helper.GetPlainPositiveSpellId(cooldownInfo and cooldownInfo.spellID)
end

function CooldownPanels:GetCooldownManagerChildCooldownID(child)
	if type(child) ~= "table" then return nil end
	local cooldownID = Helper.GetPlainPositiveSpellId(child.cooldownID)
	if not cooldownID and type(child.GetCooldownID) == "function" then
		local ok, value = pcall(child.GetCooldownID, child)
		if ok then cooldownID = Helper.GetPlainPositiveSpellId(value) end
	end
	return cooldownID
end

local function getSpellIdFromCooldownManagerChild(child)
	if not child then return nil end
	local spellId
	local cooldownID = CooldownPanels:GetCooldownManagerChildCooldownID(child)
	if type(child.GetBaseSpellID) == "function" then
		local ok, value = pcall(child.GetBaseSpellID, child)
		if ok then spellId = Helper.GetPlainPositiveSpellId(value) end
	end
	if not spellId and type(child.GetCooldownInfo) == "function" then
		local ok, cooldownInfo = pcall(child.GetCooldownInfo, child)
		if ok then spellId = CooldownPanels:GetSpellIdFromCooldownManagerInfo(cooldownInfo) end
	end
	if not spellId and type(child.cooldownInfo) == "table" then spellId = CooldownPanels:GetSpellIdFromCooldownManagerInfo(child.cooldownInfo) end
	if not spellId and cooldownID and C_CooldownViewer and C_CooldownViewer.GetCooldownViewerCooldownInfo then
		local cooldownInfo = C_CooldownViewer.GetCooldownViewerCooldownInfo(cooldownID)
		spellId = CooldownPanels:GetSpellIdFromCooldownManagerInfo(cooldownInfo)
	end
	if not spellId and type(child.GetSpellID) == "function" then
		local ok, value = pcall(child.GetSpellID, child)
		if ok then spellId = Helper.GetPlainPositiveSpellId(value) end
	end
	if not spellId and type(child.GetSpellId) == "function" then
		local ok, value = pcall(child.GetSpellId, child)
		if ok then spellId = Helper.GetPlainPositiveSpellId(value) end
	end
	if not spellId and type(child.GetSpell) == "function" then
		local ok, value = pcall(child.GetSpell, child)
		if ok then spellId = Helper.GetPlainPositiveSpellId(value) end
	end
	if not spellId and type(child.GetData) == "function" then
		local ok, data = pcall(child.GetData, child)
		if ok and type(data) == "table" then
			spellId = Helper.GetPlainPositiveSpellId(data.spellID)
			if not spellId then spellId = Helper.GetPlainPositiveSpellId(data.spellId) end
			if not spellId then spellId = Helper.GetPlainPositiveSpellId(data.spell) end
		end
	end
	if not spellId and type(child) == "table" then
		spellId = Helper.GetPlainPositiveSpellId(child.spellID)
		if not spellId then spellId = Helper.GetPlainPositiveSpellId(child.spellId) end
		if not spellId then spellId = Helper.GetPlainPositiveSpellId(child.spell) end
	end
	return spellId, cooldownID
end

local ensureImportCDMPopup

local function getCooldownManagerSourceLabel(sourceKind)
	local cdmAuras = CooldownPanels.CDMAuras
	if cdmAuras and cdmAuras.GetImportSourceLabel then
		local label = cdmAuras:GetImportSourceLabel(sourceKind)
		if label then return label end
	end
	if sourceKind == "UTILITY" then return L["CooldownPanelImportCDMUtility"] or "Utility Cooldowns" end
	return L["CooldownPanelImportCDMEssential"] or COOLDOWN_VIEWER_SETTINGS_CATEGORY_ESSENTIAL
end

local function getCooldownManagerLayoutChildren(sourceKind)
	local viewerName = sourceKind == "UTILITY" and "UtilityCooldownViewer" or "EssentialCooldownViewer"
	local sourceLabel = getCooldownManagerSourceLabel(sourceKind)
	local viewer = _G[viewerName]
	if type(viewer) ~= "table" then return nil, sourceLabel, "SOURCE_NOT_FOUND" end
	local containers = {
		viewer.oldGridSettings,
		viewer.gridSettings,
		viewer.currentGridSettings,
		viewer.settings,
		viewer,
	}
	for i = 1, #containers do
		local container = containers[i]
		local layoutChildren = container and container.layoutChildren
		if type(layoutChildren) == "table" then return layoutChildren, sourceLabel end
	end
	return nil, sourceLabel, "SOURCE_NOT_FOUND"
end

cdp.IMPORT = cdp.IMPORT or {}

function cdp.IMPORT.GetCooldownManagerSpellIdsFromAPI(sourceKind)
	if not (C_CooldownViewer and C_CooldownViewer.GetCooldownViewerCategorySet and C_CooldownViewer.GetCooldownViewerCooldownInfo) then return nil end
	local category
	if sourceKind == "UTILITY" then
		category = Enum and Enum.CooldownViewerCategory and Enum.CooldownViewerCategory.Utility
	else
		category = Enum and Enum.CooldownViewerCategory and Enum.CooldownViewerCategory.Essential
	end
	if not category then return nil end
	local cooldownIDs = C_CooldownViewer.GetCooldownViewerCategorySet(category, false)
	if type(cooldownIDs) ~= "table" or #cooldownIDs == 0 then return nil end
	local spellIds = {}
	for i = 1, #cooldownIDs do
		local cooldownID = cooldownIDs[i]
		local cooldownInfo = C_CooldownViewer.GetCooldownViewerCooldownInfo(cooldownID)
		local spellId = cooldownInfo and cooldownInfo.isKnown == true and CooldownPanels:GetSpellIdFromCooldownManagerInfo(cooldownInfo) or nil
		if spellId then spellIds[#spellIds + 1] = { spellID = spellId, cooldownID = cooldownID } end
	end
	return spellIds
end

function cdp.IMPORT.GetCooldownManagerSpellIdsFromSource(sourceKind)
	sourceKind = type(sourceKind) == "string" and sourceKind:upper() or "ESSENTIAL"
	if sourceKind ~= "UTILITY" then sourceKind = "ESSENTIAL" end
	local sourceLabel = getCooldownManagerSourceLabel(sourceKind)

	local layoutChildren, fallbackLabel, sourceErr = getCooldownManagerLayoutChildren(sourceKind)
	sourceLabel = fallbackLabel or sourceLabel
	if not sourceErr then
		local spellIds = {}
		local function collect(child)
			local spellId, cooldownID = getSpellIdFromCooldownManagerChild(child)
			if spellId then spellIds[#spellIds + 1] = { spellID = spellId, cooldownID = cooldownID } end
		end
		if #layoutChildren > 0 then
			for i = 1, #layoutChildren do
				collect(layoutChildren[i])
			end
		else
			local numericKeys = {}
			for key in pairs(layoutChildren) do
				if type(key) == "number" then numericKeys[#numericKeys + 1] = key end
			end
			table.sort(numericKeys)
			for _, key in ipairs(numericKeys) do
				collect(layoutChildren[key])
			end
		end
		if #spellIds > 0 then return spellIds, sourceLabel end
	end

	local spellIds = cdp.IMPORT.GetCooldownManagerSpellIdsFromAPI(sourceKind)
	if spellIds then return spellIds, sourceLabel end
	return nil, sourceLabel, sourceErr or "SOURCE_NOT_FOUND"
end

local function importCooldownManagerSpells(panelId, sourceKind)
	panelId = normalizeId(panelId)
	local panel = CooldownPanels:GetPanel(panelId)
	if not panel then return nil, "PANEL_NOT_FOUND" end
	local spellIds, sourceLabel, sourceErr = cdp.IMPORT.GetCooldownManagerSpellIdsFromSource(sourceKind)
	if sourceErr then return nil, sourceErr, sourceLabel end
	local root = ensureRoot()
	if not root then return nil, "NO_DB" end
	panel.entries = panel.entries or {}
	panel.order = panel.order or {}

	local existingBySpellId = {}
	for _, entry in pairs(panel.entries) do
		if entry and entry.type == "SPELL" and entry.spellID then
			local canonicalSpellID = CooldownPanels:NormalizePersistentSpellID(entry.spellID, { allowTalentChoiceCanonical = true }) or tonumber(entry.spellID)
			if canonicalSpellID then existingBySpellId[canonicalSpellID] = true end
		end
	end

	local function importChild(child, stats)
		local spellId
		if type(child) == "table" then
			spellId = getSpellIdFromCooldownManagerChild(child)
		else
			spellId = Helper.GetPlainPositiveSpellId(child)
		end
		if not spellId then
			stats.invalid = stats.invalid + 1
			return
		end
		local baseSpellId = getBaseSpellId(spellId) or spellId
		if not spellExistsSafe(baseSpellId) then
			stats.invalid = stats.invalid + 1
			return
		end
		local resolvedSpellId = CooldownPanels:NormalizePersistentSpellID(spellId, { allowTalentChoiceCanonical = true }) or baseSpellId
		local canonicalSpellID = CooldownPanels:NormalizePersistentSpellID(resolvedSpellId, { allowTalentChoiceCanonical = true }) or resolvedSpellId
		if existingBySpellId[canonicalSpellID] then
			stats.duplicates = stats.duplicates + 1
			return
		end
		if CooldownPanels:GetFixedEntryAddError(panel, nil) then
			stats.invalid = stats.invalid + 1
			return
		end
		local entryId = Helper.GetNextNumericId(panel.entries)
		local entry = Helper.CreateEntry("SPELL", resolvedSpellId, root.defaults)
		entry.id = entryId
		panel.entries[entryId] = entry
		panel.order[#panel.order + 1] = entryId
		existingBySpellId[canonicalSpellID] = true
		stats.added = stats.added + 1
	end

	local stats = { added = 0, duplicates = 0, invalid = 0, seen = 0 }
	for i = 1, #spellIds do
		stats.seen = stats.seen + 1
		importChild(spellIds[i], stats)
	end

	if stats.added > 0 then
		Helper.SyncOrder(panel.order, panel.entries)
		CooldownPanels:RebuildSpellIndex()
		CooldownPanels:RefreshPanel(panelId)
	end
	stats.sourceLabel = sourceLabel
	return stats
end

