		{ buttonPrefix = "MultiBarLeftButton", label = _G.BINDING_HEADER_ACTIONBAR5 or "Action Bar 5", firstSlot = 37 },
		{ buttonPrefix = "MultiBar5Button", label = _G.BINDING_HEADER_ACTIONBAR6 or "Action Bar 6", firstSlot = 145 },
		{ buttonPrefix = "MultiBar6Button", label = _G.BINDING_HEADER_ACTIONBAR7 or "Action Bar 7", firstSlot = 157 },
