	}

function cdp.IMPORT.GetImportLabel()
	return _G.IMPORT or L["Import"] or "Import"
end

function cdp.IMPORT.GetActionBarsLabel()
	return L["ProfileImportProtectionActionBars"] or "Action Bars"
end

function cdp.IMPORT.GetButtonActionSlot(button)
	if not button then return nil end
	local slot = tonumber(button.action)
	if not slot and button.GetAttribute then
		local ok, value = pcall(button.GetAttribute, button, "action")
		if ok then slot = tonumber(value) end
	end
	return slot
end

function cdp.IMPORT.GetActionBarSlots(definition)
	local slots = {}
	local buttonCount = _G.NUM_ACTIONBAR_BUTTONS or 12
	for index = 1, buttonCount do
		local button = definition.buttonPrefix and _G[definition.buttonPrefix .. index] or nil
		local slot = cdp.IMPORT.GetButtonActionSlot(button)
		if not slot and definition.firstSlot then slot = definition.firstSlot + index - 1 end
		if slot then slots[#slots + 1] = slot end
	end
	return slots
end

function cdp.IMPORT.GetActionEntryInfo(slot)
	if not (slot and Api.GetActionInfo) then return nil end
	local actionType, actionId = Api.GetActionInfo(slot)
	if actionType == "spell" and actionId then return "SPELL", actionId end
	if actionType == "item" and actionId then return "ITEM", actionId end
	if actionType == "macro" then
		local macroID = tonumber(actionId)
		local macroName = Api.GetActionText and CooldownPanels.NormalizeMacroName(Api.GetActionText(slot)) or nil
		if macroName and Api.GetMacroIndexByName then
			local byName = Api.GetMacroIndexByName(macroName)
			if type(byName) == "number" and byName > 0 then macroID = byName end
		end
		if not macroName and macroID and Api.GetMacroInfo then macroName = CooldownPanels.NormalizeMacroName(Api.GetMacroInfo(macroID)) end
		if macroID or macroName then return "MACRO", macroID or macroName, { macroName = macroName } end
	end
	return nil
end

function cdp.IMPORT.IsDuplicateEntry(panelId, entryType, idValue, overrides)
	local typeKey = entryType and tostring(entryType):upper() or nil
	if typeKey == "SPELL" then
		local numericValue = tonumber(idValue)
		if numericValue then
			local baseValue = getBaseSpellId(numericValue) or numericValue
			local normalized = CooldownPanels:NormalizePersistentSpellID(numericValue, { allowTalentChoiceCanonical = true }) or baseValue
			return CooldownPanels:FindEntryByValue(panelId, typeKey, normalized) ~= nil
		end
	elseif typeKey == "MACRO" then
		local macroName = type(overrides) == "table" and CooldownPanels.NormalizeMacroName(overrides.macroName) or nil
		if not macroName then macroName = CooldownPanels.NormalizeMacroName(type(idValue) == "string" and idValue or nil) end
		if not macroName and tonumber(idValue) and Api.GetMacroInfo then macroName = CooldownPanels.NormalizeMacroName(Api.GetMacroInfo(tonumber(idValue))) end
		if not tonumber(idValue) and macroName and Api.GetMacroIndexByName then
			local macroId = Api.GetMacroIndexByName(macroName)
			if type(macroId) == "number" and macroId > 0 then idValue = macroId end
		end
		return CooldownPanels:FindEntryByValue(panelId, typeKey, tonumber(idValue) or macroName or idValue) ~= nil
	end
	return CooldownPanels:FindEntryByValue(panelId, typeKey, tonumber(idValue) or idValue) ~= nil
end

function cdp.IMPORT.ImportActionBar(panelId, definition)
	panelId = normalizeId(panelId)
	local panel = CooldownPanels:GetPanel(panelId)
	if not panel then return nil, "PANEL_NOT_FOUND" end
	local stats = { added = 0, duplicates = 0, invalid = 0, seen = 0, sourceLabel = definition and definition.label or cdp.IMPORT.GetActionBarsLabel() }
	for _, slot in ipairs(cdp.IMPORT.GetActionBarSlots(definition or {})) do
		local entryType, idValue, overrides = cdp.IMPORT.GetActionEntryInfo(slot)
		if entryType and idValue then
			stats.seen = stats.seen + 1
			if cdp.IMPORT.IsDuplicateEntry(panelId, entryType, idValue, overrides) then
				stats.duplicates = stats.duplicates + 1
			elseif CooldownPanels:GetFixedEntryAddError(panel, nil) then
				stats.invalid = stats.invalid + 1
			elseif CooldownPanels:AddEntrySafe(panelId, entryType, idValue, overrides) then
				stats.added = stats.added + 1
			else
				stats.invalid = stats.invalid + 1
			end
		end
	end
	if stats.added > 0 then
		CooldownPanels:RefreshEditor()
		CooldownPanels:RefreshPanel(panelId)
		if CooldownPanels.BlizzardEditor and CooldownPanels.BlizzardEditor.Refresh then CooldownPanels.BlizzardEditor:Refresh() end
	end
	return stats
end

function cdp.IMPORT.PrintImportResult(result, sourceLabel)
	print(
		string.format(
			"[EnhanceQoL] " .. (L["CooldownPanelImportCDMResult"] or "Imported %d entries from %s (%d duplicates, %d skipped)."),
			result and result.added or 0,
			tostring(result and result.sourceLabel or sourceLabel),
			result and result.duplicates or 0,
			result and result.invalid or 0
		)
	)
end

