function CooldownPanels:NormalizeStandaloneSettingsOrder(settings, sectionOrder)
	if type(settings) ~= "table" or type(sectionOrder) ~= "table" then return settings end
	local order = {}
	for index, id in ipairs(sectionOrder) do
		order[id] = index
	end
	local sections, children, loose = {}, {}, {}
	for _, setting in ipairs(settings) do
		local id = setting and setting.id
		local parentId = setting and setting.parentId
		if id and order[id] then
			sections[id] = setting
		elseif parentId and order[parentId] then
			children[parentId] = children[parentId] or {}
			children[parentId][#children[parentId] + 1] = setting
		else
			loose[#loose + 1] = setting
		end
	end
	local sorted = {}
	for _, id in ipairs(sectionOrder) do
		if sections[id] then sorted[#sorted + 1] = sections[id] end
		if children[id] then
			for _, child in ipairs(children[id]) do
				sorted[#sorted + 1] = child
			end
		end
	end
	for _, setting in ipairs(loose) do
		sorted[#sorted + 1] = setting
	end
	return sorted
end

function CooldownPanels:GetLayoutEntryStandaloneMenuState(create)
	CooldownPanels.runtime = CooldownPanels.runtime or {}
	local state = CooldownPanels.runtime.layoutEntryStandaloneMenu
	if state == nil and create ~= false then
		state = {}
		CooldownPanels.runtime.layoutEntryStandaloneMenu = state
	end
	return state
end

function CooldownPanels:ClearLayoutEntryStandaloneMenuState()
	local state = self:GetLayoutEntryStandaloneMenuState(false)
	if not state then return end
	for key in pairs(state) do
		state[key] = nil
	end
end

function CooldownPanels:GetLayoutEntryStandaloneDialogEntry(panelId, entryId)
	panelId = normalizeId(panelId)
	entryId = normalizeId(entryId)
	local panel = self:GetPanel(panelId)
	local entry = panel and panel.entries and panel.entries[entryId] or nil
	return panel, entry
end

function CooldownPanels:GetLayoutEntryStandaloneEffectiveType(entry)
	local effectiveType = entry and entry.type or nil
	if effectiveType == "MACRO" then
		local macro = CooldownPanels.ResolveMacroEntry(entry)
		effectiveType = (macro and macro.kind) or "MACRO"
	end
	return effectiveType
end

function CooldownPanels:HideLayoutEntryStandaloneMenu(panelId, keepLayoutEdit)
	local lib = addon.EditModeLib
	local state = self:GetLayoutEntryStandaloneMenuState(false)
	local trackedPanelId = normalizeId(state and state.panelId)
	if panelId and trackedPanelId and trackedPanelId ~= normalizeId(panelId) then return false end
	local hostFrame = state and state.hostFrame or (trackedPanelId and getRuntime(trackedPanelId).frame) or nil
	local hidden = false
	local editor = keepLayoutEdit and state and state.blizzardEditorLayoutEdit == true and getEditor() or nil
	local restoreSuppress = editor and editor._eqolSuppressBlizzardEditorLayoutEditEnd ~= true
	if editor then editor._eqolSuppressBlizzardEditorLayoutEditEnd = true end
	if lib and lib.HideStandaloneSettingsDialog then hidden = lib:HideStandaloneSettingsDialog(hostFrame) end
	if restoreSuppress then editor._eqolSuppressBlizzardEditorLayoutEditEnd = nil end
	self:ClearLayoutEntryStandaloneMenuState()
	return hidden
end

function CooldownPanels:RefreshLayoutEntryStandaloneMenu(rebuild)
	local lib = addon.EditModeLib
	local state = self:GetLayoutEntryStandaloneMenuState(false)
	if not state or not state.hostFrame then return end
	if not (lib and lib.IsStandaloneSettingsDialogShown and lib:IsStandaloneSettingsDialogShown(state.hostFrame)) then
		self:ClearLayoutEntryStandaloneMenuState()
		return
	end
	local panelId = normalizeId(state.panelId)
	local entryId = normalizeId(state.entryId)
	local panel, entry = self:GetLayoutEntryStandaloneDialogEntry(panelId, entryId)
	local allowOutsideLayoutEdit = state.allowOutsideLayoutEdit == true
	local editor = not allowOutsideLayoutEdit and getEditor() or nil
	local selectedPanelId = normalizeId(editor and editor.selectedPanelId)
	local selectedEntryId = normalizeId(editor and editor.selectedEntryId)
	if not panel or not entry or (not allowOutsideLayoutEdit and (not self:IsPanelLayoutEditActive(panelId) or selectedPanelId ~= panelId or selectedEntryId ~= entryId)) then
		self:HideLayoutEntryStandaloneMenu(panelId)
		return
	end
	if rebuild == true then self:OpenLayoutEntryStandaloneMenu(panelId, entryId, state.anchorFrame or state.dialog or state.hostFrame, allowOutsideLayoutEdit) end
end

function CooldownPanels:FocusLayoutEntryStandaloneSettingsGroup(panelId, entryId, targetGroupId)
	panelId = normalizeId(panelId)
	entryId = normalizeId(entryId)
	local lib = addon.EditModeLib
	local focusGroup = lib and lib.internal and lib.internal.FocusSettingGroup or nil
	local state = self:GetLayoutEntryStandaloneMenuState(false)
	if not (panelId and targetGroupId and focusGroup and state and normalizeId(state.panelId) == panelId and state.hostFrame) then return false end
	if entryId and normalizeId(state.entryId) ~= entryId then return false end
	return focusGroup(lib.internal, state.hostFrame, targetGroupId)
end

function CooldownPanels:FocusEntryStaticTextStandaloneSettings(panelId)
	return self:FocusLayoutEntryStandaloneSettingsGroup(panelId, nil, "cooldownPanelStandaloneStaticText")
end

function CooldownPanels:FocusEntryStacksStandaloneSettings(panelId, entryId)
	return self:FocusLayoutEntryStandaloneSettingsGroup(panelId, entryId, "cooldownPanelStandaloneStacks")
end

function CooldownPanels:GetEditorStandaloneDialogAnchor()
	local blizzardEditor = self.BlizzardEditor
	local blizzardFrame = blizzardEditor and blizzardEditor.frame or nil
	if blizzardFrame and blizzardFrame.IsShown and blizzardFrame:IsShown() then return blizzardFrame end
	local editor = getEditor()
	local frame = editor and editor.frame or nil
	if frame and frame.IsShown and frame:IsShown() then return frame end
	return nil
end

function CooldownPanels:GetEditorStandaloneDialogSpawnPosition()
	local frame = self:GetEditorStandaloneDialogAnchor()
	if not frame then return nil end
	return {
		point = "TOPLEFT",
		relativePoint = "TOPRIGHT",
		relativeTo = frame,
		x = 54,
		y = 0,
	}
end

function CooldownPanels:DockStandaloneDialogToEditor(dialog)
	local frame = self:GetEditorStandaloneDialogAnchor()
	if not dialog then return false end
	if not frame then
		if dialog.SetMovable then dialog:SetMovable(true) end
		if dialog.RegisterForDrag then dialog:RegisterForDrag("LeftButton") end
		return false
	end
	if dialog.SetClampedToScreen then dialog:SetClampedToScreen(false) end
	if dialog.SetMovable then dialog:SetMovable(true) end
	if dialog.RegisterForDrag then dialog:RegisterForDrag("LeftButton") end
	if dialog.StopMovingOrSizing then dialog:StopMovingOrSizing() end
	dialog:ClearAllPoints()
	dialog:SetPoint("TOPLEFT", frame, "TOPRIGHT", 54, 0)
	return true
end

function CooldownPanels:GetStandaloneDialogSpawnPosition(anchorFrame, fallbackFrame, offsetX, offsetY)
	local editorSpawnPosition = self:GetEditorStandaloneDialogSpawnPosition()
	if editorSpawnPosition then return editorSpawnPosition end

	local source = anchorFrame or fallbackFrame or UIParent
	local xOffset = tonumber(offsetX) or 0
	local yOffset = tonumber(offsetY) or 0
	if not source then return {
		point = "TOPLEFT",
		relativePoint = "TOPLEFT",
		relativeTo = UIParent,
		x = xOffset,
		y = yOffset,
	} end

	local right = source.GetRight and source:GetRight() or nil
	local top = source.GetTop and source:GetTop() or nil
	local sourceScale = (source.GetEffectiveScale and source:GetEffectiveScale()) or 1
	local parentScale = (UIParent and UIParent.GetEffectiveScale and UIParent:GetEffectiveScale()) or 1

	if right and top then
		return {
			point = "TOPLEFT",
			relativePoint = "BOTTOMLEFT",
			relativeTo = UIParent,
			x = (right * sourceScale / parentScale) + xOffset,
			y = (top * sourceScale / parentScale) + yOffset,
		}
	end

	return {
		point = "TOPLEFT",
		relativePoint = "TOPRIGHT",
		relativeTo = source,
		x = xOffset,
		y = yOffset,
	}
end

function CooldownPanels:OpenLayoutEntryStandaloneMenu(panelId, entryId, anchorFrame, allowOutsideLayoutEdit)
	local lib = addon.EditModeLib
	if not (lib and lib.ShowStandaloneSettingsDialog and SettingType) then return end
	panelId = normalizeId(panelId)
	entryId = normalizeId(entryId)
	if not (panelId and entryId) then return end
	allowOutsideLayoutEdit = allowOutsideLayoutEdit == true
	if not allowOutsideLayoutEdit and not self:IsPanelLayoutEditActive(panelId) then return end
	local editor = getEditor()
	local suppressBlizzardEditorLayoutEnd = editor and editor._eqolBlizzardEditorLayoutEdit == true
	if suppressBlizzardEditorLayoutEnd then editor._eqolSuppressBlizzardEditorLayoutEditEnd = true end
	self:HideLayoutPanelStandaloneMenu(panelId)
	self:HideLayoutFixedGroupStandaloneMenu(panelId)

	local panel, entry = self:GetLayoutEntryStandaloneDialogEntry(panelId, entryId)
	local runtime = getRuntime(panelId)
	local hostFrame = runtime and runtime.frame or (self.EnsurePanelFrame and self:EnsurePanelFrame(panelId)) or nil
	if not (panel and entry and hostFrame) then
		if suppressBlizzardEditorLayoutEnd then editor._eqolSuppressBlizzardEditorLayoutEditEnd = nil end
		return
	end
	local spawnPosition = self:GetStandaloneDialogSpawnPosition(anchorFrame, hostFrame, 12, 0)
	local defaultStaticFontPath, defaultStaticFontSize, defaultStaticFontStyle = Helper.GetCountFontDefaults(hostFrame)
	local defaultCooldownFontPath, defaultCooldownFontSize, defaultCooldownFontStyle = self:GetCooldownFontDefaults(hostFrame)
	local defaultCountFontPath, defaultCountFontSize, defaultCountFontStyle = defaultStaticFontPath, defaultStaticFontSize, defaultStaticFontStyle
	local defaultChargesFontPath, defaultChargesFontSize, defaultChargesFontStyle = Helper.GetChargesFontDefaults(hostFrame)

	local function allowsStandaloneEntryReadySound(effectiveType) return effectiveType and effectiveType ~= "MACRO" and effectiveType ~= "STANCE" and effectiveType ~= "CDM_AURA" end

	local function getPanel() return CooldownPanels:GetPanel(panelId) end

	local function getLayout()
		local currentPanel = getPanel()
		return currentPanel and currentPanel.layout or nil
	end

	local function getEntry()
		local currentPanel, currentEntry = CooldownPanels:GetLayoutEntryStandaloneDialogEntry(panelId, entryId)
		return currentPanel, currentEntry
	end

	local function getEffectiveType()
		local _, currentEntry = getEntry()
		return CooldownPanels:GetLayoutEntryStandaloneEffectiveType(currentEntry)
	end

	local function allowsStandaloneEntryAuraSound(effectiveType)
		local layout = getLayout()
		local _, currentEntry = getEntry()
		return effectiveType == "CDM_AURA"
			or (effectiveType == "SPELL" and CooldownPanels:IsEntryCDMAuraOverlayEnabled(layout, currentEntry, effectiveType))
	end

	local refreshEntryDialogPending = false

	local function isStandaloneDialogDragActive()
		if type(IsMouseButtonDown) ~= "function" then return false end
		return IsMouseButtonDown("LeftButton") == true
	end

	local function updateEntryDialog()
		local state = CooldownPanels:GetLayoutEntryStandaloneMenuState(false)
		local activeDialog = state and state.dialog
		if state and normalizeId(state.panelId) == panelId and normalizeId(state.entryId) == entryId and activeDialog then
			local _, currentEntry = getEntry()
			local title = currentEntry and CooldownPanels:GetEntryStandaloneTitle(currentEntry) or nil
			if activeDialog.context then activeDialog.context.title = title end
			if activeDialog.Title and title then activeDialog.Title:SetText(title) end
			if activeDialog.UpdateSettings then activeDialog:UpdateSettings() end
			if activeDialog.UpdateButtons then activeDialog:UpdateButtons() end
			if activeDialog.Layout then activeDialog:Layout() end
		end
	end

	local function scheduleEntryDialogRefresh()
		if refreshEntryDialogPending then return end
		refreshEntryDialogPending = true
		RunNextFrame(function()
			refreshEntryDialogPending = false
			local state = CooldownPanels:GetLayoutEntryStandaloneMenuState(false)
			if not state or normalizeId(state.panelId) ~= panelId or normalizeId(state.entryId) ~= entryId then return end
			if isStandaloneDialogDragActive() then
				scheduleEntryDialogRefresh()
				return
			end
			updateEntryDialog()
		end)
	end

	local function refreshEntryViews()
		CooldownPanels:RefreshPanel(panelId)
		if CooldownPanels.IsEditorOpen and CooldownPanels:IsEditorOpen() then CooldownPanels:RefreshEditor() end
		if CooldownPanels.BlizzardEditor and CooldownPanels.BlizzardEditor.RefreshPanel then CooldownPanels.BlizzardEditor:RefreshPanel(panelId) end
		if isStandaloneDialogDragActive() then
			scheduleEntryDialogRefresh()
			return
		end
		updateEntryDialog()
	end

	local function refreshEntryPreview()
		CooldownPanels:RefreshPanel(panelId)
		if CooldownPanels.IsEditorOpen and CooldownPanels:IsEditorOpen() then CooldownPanels:RefreshEditor() end
		if CooldownPanels.BlizzardEditor and CooldownPanels.BlizzardEditor.RefreshPanel then CooldownPanels.BlizzardEditor:RefreshPanel(panelId) end
	end

	local function refreshEntryGlowPreview(refreshEditorAlert)
		if not CooldownPanels:TryRefreshEntryGlowPreview(panelId, entryId) then CooldownPanels:UpdateRuntimeIcons(panelId) end
		if
			refreshEditorAlert == true
			and CooldownPanels.BlizzardEditor
			and CooldownPanels.BlizzardEditor.RefreshEntryAlert
		then
			CooldownPanels.BlizzardEditor:RefreshEntryAlert(panelId, entryId)
		end
	end

	local function setEntryField(field, value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		if currentEntry[field] == value then return end
		currentEntry[field] = value
		refreshEntryViews()
	end

	local function setEntryBoolean(field, value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local normalized = value == true
		if (currentEntry[field] == true) == normalized then return end
		currentEntry[field] = normalized and true or false
		if field == "showCharges" then currentEntry.showChargesUseGlobal = false end
		if field == "showStacks" then currentEntry.showStacksUseGlobal = false end
		if field == "showCooldownText" then currentEntry.showCooldownTextUseGlobal = false end
		CooldownPanels:HandleEntryBooleanMutation(panelId, entryId, currentEntry, field)
		refreshEntryViews()
	end

	local function setEntryGlowBoolean(field, value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local normalized = value == true
		if (currentEntry[field] == true) == normalized then return end
		currentEntry[field] = normalized and true or false
		CooldownPanels:HandleEntryBooleanMutation(panelId, entryId, currentEntry, field)
		refreshEntryGlowPreview(field == "glowReady")
	end

	local function setAlwaysShowLike(value)
		local layout = getLayout()
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local normalized = value == true
		if currentEntry.type == "STANCE" then
			if (currentEntry.showWhenMissing == true) == normalized then return end
			currentEntry.showWhenMissing = normalized and true or false
		elseif currentEntry.type == "CDM_AURA" then
			local mode = normalized and (CooldownPanels.CDM_AURA_ALWAYS_SHOW_MODE and CooldownPanels.CDM_AURA_ALWAYS_SHOW_MODE.SHOW or "SHOW")
				or (CooldownPanels.CDM_AURA_ALWAYS_SHOW_MODE and CooldownPanels.CDM_AURA_ALWAYS_SHOW_MODE.HIDE or "HIDE")
			local resolvedMode = CooldownPanels:ResolveEntryCDMAuraAlwaysShowMode(layout, currentEntry)
			if currentEntry.cdmAuraAlwaysShowUseGlobal == false and resolvedMode == mode then return end
			currentEntry.cdmAuraAlwaysShowUseGlobal = false
			currentEntry.cdmAuraAlwaysShowMode = mode
			currentEntry.alwaysShow = normalized and true or false
		else
			if (currentEntry.alwaysShow == true) == normalized then return end
			currentEntry.alwaysShow = normalized and true or false
		end
		refreshEntryViews()
	end

	local function refreshReadyGlowState(currentEntry)
		if not currentEntry then return end
		local runtimeState = getRuntime(panelId)
		local hadReady = runtimeState and runtimeState.readyAt and runtimeState.readyAt[entryId] ~= nil
		CooldownPanels.ClearReadyGlowEntryState(panelId, entryId, false)
		local primed = CooldownPanels.GetReadyGlowPrimedState(runtimeState)
		if primed then primed[entryId] = nil end
		if currentEntry.glowReady and hadReady then
			local resolvedDuration = CooldownPanels:ResolveEntryGlowStyle(getLayout(), currentEntry)
			triggerReadyGlow(panelId, entryId, resolvedDuration)
			if primed then primed[entryId] = true end
		end
	end

	local function setGlowOverrideEnabled(value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local useGlobal = value ~= true
		local resolvedGlowReady = CooldownPanels:ResolveEntryGlowReady(getLayout(), currentEntry)
		local resolvedReadyGlowCheckPower = CooldownPanels:ResolveEntryReadyGlowCheckPower(getLayout(), currentEntry)
		if
			currentEntry.glowUseGlobal == useGlobal
			and currentEntry.glowReadyUseGlobal == useGlobal
			and currentEntry.readyGlowCheckPowerUseGlobal == useGlobal
		then
			return
		end
		currentEntry.glowUseGlobal = useGlobal
		currentEntry.glowReadyUseGlobal = useGlobal
		currentEntry.readyGlowCheckPowerUseGlobal = useGlobal
		if not useGlobal then
			currentEntry.glowReady = resolvedGlowReady
			currentEntry.readyGlowCheckPower = resolvedReadyGlowCheckPower
		end
		CooldownPanels:RebuildPowerIndex()
		refreshReadyGlowState(currentEntry)
		refreshEntryGlowPreview(true)
	end

	local function setReadyGlowCheckPower(value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local normalized = value == true
		if currentEntry.readyGlowCheckPowerUseGlobal == false and currentEntry.readyGlowCheckPower == normalized then return end
		currentEntry.readyGlowCheckPowerUseGlobal = false
		currentEntry.readyGlowCheckPower = normalized
		CooldownPanels:HandleEntryBooleanMutation(panelId, entryId, currentEntry, "readyGlowCheckPower")
		refreshEntryGlowPreview()
	end

	local function setProcGlowOverrideEnabled(value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local useGlobal = value ~= true
		if currentEntry.procGlowUseGlobal == useGlobal then return end
		currentEntry.procGlowUseGlobal = useGlobal
		refreshEntryGlowPreview()
	end

	local function setProcGlowEnabled(_, value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local normalized = value == true
		if currentEntry.procGlowEnabled == normalized then return end
		currentEntry.procGlowEnabled = normalized
		refreshEntryGlowPreview()
	end

	local function setProcGlowStyle(_, value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local layout = getLayout()
		local panelStyle = CooldownPanels:ResolveEntryProcGlowVisual(layout, nil)
		local normalized = Helper.NormalizeGlowStyle(value, panelStyle)
		normalized = cdp.ENTRY.NormalizeGlowStyleForEntryDisplayMode(normalized, currentEntry)
		local stored = normalized == panelStyle and nil or normalized
		if currentEntry.procGlowStyle == stored then return end
		currentEntry.procGlowStyle = stored
		refreshEntryGlowPreview()
		refreshStandaloneSettings()
	end

	local function setProcGlowInset(_, value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local layout = getLayout()
		local _, panelInset = CooldownPanels:ResolveEntryProcGlowVisual(layout, nil)
		local normalized = Helper.NormalizeGlowInset(value, panelInset)
		local stored = normalized == panelInset and nil or normalized
		if currentEntry.procGlowInset == stored then return end
		currentEntry.procGlowInset = stored
		refreshEntryGlowPreview()
	end

	local function setGlowStyle(_, value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local layout = getLayout()
		local _, _, panelStyle = CooldownPanels:ResolveEntryGlowStyle(layout, nil)
		local normalized = Helper.NormalizeGlowStyle(value, panelStyle)
		normalized = cdp.ENTRY.NormalizeGlowStyleForEntryDisplayMode(normalized, currentEntry)
		local stored = normalized == panelStyle and nil or normalized
		if currentEntry.glowStyle == stored then return end
		currentEntry.glowStyle = stored
		refreshEntryGlowPreview()
		refreshStandaloneSettings()
	end

	local function setPandemicGlowStyle(_, value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local layout = getLayout()
		local _, panelStyle = CooldownPanels:ResolveEntryPandemicGlowVisual(layout, nil)
		local normalized = Helper.NormalizeGlowStyle(value, panelStyle)
		normalized = cdp.ENTRY.NormalizeGlowStyleForEntryDisplayMode(normalized, currentEntry)
		local stored = normalized == panelStyle and nil or normalized
		if currentEntry.pandemicGlowStyle == stored then return end
		currentEntry.pandemicGlowStyle = stored
		refreshEntryGlowPreview()
		refreshStandaloneSettings()
	end

	local function setGlowInset(_, value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local layout = getLayout()
		local _, _, _, panelInset = CooldownPanels:ResolveEntryGlowStyle(layout, nil)
		local normalized = Helper.NormalizeGlowInset(value, panelInset)
		local stored = normalized == panelInset and nil or normalized
		if currentEntry.glowInset == stored then return end
		currentEntry.glowInset = stored
		refreshEntryGlowPreview()
	end

	local function setGlowPixelOption(field, value)
		local _, currentEntry = getEntry()
		if not currentEntry or not (currentEntry.glowUseGlobal == false or currentEntry.procGlowUseGlobal == false) then return end
		if CooldownPanels:SetEntryGlowPixelOption(currentEntry, getLayout(), field, value) then refreshEntryGlowPreview() end
	end

	local function setPandemicGlowInset(_, value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local layout = getLayout()
		local _, _, panelInset = CooldownPanels:ResolveEntryPandemicGlowVisual(layout, nil)
		local normalized = Helper.NormalizeGlowInset(value, panelInset)
		local stored = normalized == panelInset and nil or normalized
		if currentEntry.pandemicGlowInset == stored then return end
		currentEntry.pandemicGlowInset = stored
		refreshEntryGlowPreview()
	end

	local function setGlowColor(_, value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local normalized = Helper.NormalizeColor(value, Helper.PANEL_LAYOUT_DEFAULTS.readyGlowColor)
		local previous = Helper.NormalizeColor(currentEntry.glowColor, Helper.PANEL_LAYOUT_DEFAULTS.readyGlowColor)
		if normalized[1] == previous[1] and normalized[2] == previous[2] and normalized[3] == previous[3] and normalized[4] == previous[4] then return end
		currentEntry.glowColor = normalized
		refreshEntryGlowPreview()
	end

	local function setActivationOverlayColor(_, value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		currentEntry.activationOverlayBehaviorUseGlobal = false
		currentEntry.activationOverlayColor = Helper.NormalizeColor(value, Helper.ACTIVATION_OVERLAY_COLOR_DEFAULT)
		CooldownPanels:RefreshEntryActivationOverlayColor(panelId, entryId)
	end

	local function setActivationOverlayGlowColor(_, value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local layout = getLayout()
		local panelColor = CooldownPanels:ResolveEntryActivationOverlayGlowColor(layout, nil)
		currentEntry.activationOverlayBehaviorUseGlobal = false
		currentEntry.activationOverlayGlowColor = Helper.NormalizeColor(value, panelColor)
		refreshEntryGlowPreview()
	end

	local function setGlowOtherAura(_, value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		if value == nil or value == "" then
			if currentEntry.glowOtherAura == nil then return end
			currentEntry.glowOtherAura = nil
			refreshEntryGlowPreview()
			refreshStandaloneSettings()
			return
		end
		for _, option in ipairs(CooldownPanels:GetCDMAuraGlowOtherAuraOptions(panelId, currentEntry)) do
			if option.value == tostring(value) then
				currentEntry.glowOtherAura = option.info
				refreshEntryGlowPreview()
				refreshStandaloneSettings()
				return
			end
		end
	end

	local function setStaticText(_, value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local text = value or ""
		if currentEntry.staticText == text then return end
		currentEntry.staticText = text
		refreshEntryViews()
	end

	local function isStateTextureSupported()
		local effectiveType = getEffectiveType()
		return effectiveType == "SPELL" or effectiveType == "CDM_AURA"
	end

	local function entryHasStateTexture()
		local _, currentEntry = getEntry()
		return CooldownPanels:HasConfiguredStateTexture(currentEntry)
	end

	local function entryUsesDoubleStateTexture()
		local _, currentEntry = getEntry()
		return currentEntry and currentEntry.stateTextureDouble == true or false
	end

	local function setStateTextureInput(_, value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local ok, err = CooldownPanels:ApplyEntryStateTextureInput(currentEntry, value)
		if not ok then
			showErrorMessage(err)
			refreshEntryViews()
			refreshStandaloneSettingValues()
			return
		end
		refreshEntryPreview()
		refreshStandaloneSettingValues()
	end

	local function setStateTextureField(field, value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		if currentEntry[field] == value then return end
		currentEntry[field] = value
		refreshEntryPreview()
	end

	local function setCooldownTextOverrideEnabled(value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local useGlobal = value ~= true
		if currentEntry.cooldownTextUseGlobal == useGlobal then return end
		currentEntry.cooldownTextUseGlobal = useGlobal
		refreshEntryViews()
	end

	local function setShowCooldownTextOverrideEnabled(value)
		local layout = getLayout()
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local useGlobal = value ~= true
		if currentEntry.showCooldownTextUseGlobal == useGlobal then return end
		if not useGlobal then currentEntry.showCooldownText = CooldownPanels:ShouldShowEntryCooldownText(layout, currentEntry) end
		currentEntry.showCooldownTextUseGlobal = useGlobal
		refreshEntryViews()
	end

	local function setStaticTextOverrideEnabled(value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local useGlobal = value ~= true
		if currentEntry.staticTextUseGlobal == useGlobal then return end
		currentEntry.staticTextUseGlobal = useGlobal
		refreshEntryViews()
	end

	local function setShowIconOverrideEnabled(value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local useGlobal = value ~= true
		if currentEntry.showIconTextureUseGlobal == useGlobal then return end
		currentEntry.showIconTextureUseGlobal = useGlobal
		refreshEntryViews()
	end

	local function setCooldownVisualsOverrideEnabled(value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local useGlobal = value ~= true
		if currentEntry.cooldownVisualsUseGlobal == useGlobal then return end
		currentEntry.cooldownVisualsUseGlobal = useGlobal
		refreshEntryViews()
	end

	local function setCustomCooldownDurationEnabled(value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local normalized = value == true
		if normalized and not ((tonumber(currentEntry.customCooldownDuration) or 0) > 0) then
			currentEntry.customCooldownDuration = 60
		end
		if currentEntry.customCooldownDurationEnabled == normalized then return end
		currentEntry.customCooldownDurationEnabled = normalized
		if normalized then currentEntry.autoCooldownDurationEnabled = false end
		if normalized then currentEntry.cdmAuraOverlayEnabled = false end
		if normalized then currentEntry.customCooldownDurationOnCooldownEnabled = false end
		if normalized then currentEntry.customCooldownDurationOnCooldownMultipleStacks = false end
		CooldownPanels:ClearEntryCustomCooldownDuration(panelId, entryId, true)
		refreshEntryViews()
	end

	local function setCustomCooldownDurationOnCooldownEnabled(value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local normalized = value == true
		if normalized and not ((tonumber(currentEntry.customCooldownDuration) or 0) > 0) then
			currentEntry.customCooldownDuration = 60
		end
		if currentEntry.customCooldownDurationOnCooldownEnabled == normalized then return end
		currentEntry.customCooldownDurationOnCooldownEnabled = normalized
		if normalized then currentEntry.autoCooldownDurationEnabled = false end
		if normalized then currentEntry.cdmAuraOverlayEnabled = false end
		if normalized then currentEntry.customCooldownDurationEnabled = false end
		if not normalized then currentEntry.customCooldownDurationOnCooldownMultipleStacks = false end
		CooldownPanels:ClearEntryCustomCooldownDuration(panelId, entryId, true)
		refreshEntryViews()
	end

	local function setCustomCooldownDurationOnCooldownMultipleStacks(value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local normalized = value == true
		if normalized and (getEffectiveType() ~= "SPELL" or currentEntry.customCooldownDurationOnCooldownEnabled ~= true) then return end
		if currentEntry.customCooldownDurationOnCooldownMultipleStacks == normalized then return end
		currentEntry.customCooldownDurationOnCooldownMultipleStacks = normalized
		CooldownPanels:ClearEntryCustomCooldownDuration(panelId, entryId, true)
		refreshEntryViews()
	end

	local function setCDMAuraOverlayEnabled(value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local normalized = value == true
		if normalized and not CooldownPanels:SupportsEntryCDMAuraOverlay(currentEntry, getEffectiveType()) then return end
		if currentEntry.cdmAuraOverlayEnabled == normalized then return end
		currentEntry.cdmAuraOverlayEnabled = normalized
		if normalized then
			currentEntry.customCooldownDurationEnabled = false
			currentEntry.customCooldownDurationOnCooldownEnabled = false
			currentEntry.autoCooldownDurationEnabled = false
		end
		CooldownPanels:ClearEntryCustomCooldownDuration(panelId, entryId, true)
		CooldownPanels:RebuildSpellIndex()
		refreshEntryViews()
	end

	local function setCDMAuraOverlaySpellIDs(_, value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local previous = CooldownPanels:FormatEntryAuraOverlaySpellIDs(currentEntry.cdmAuraOverlaySpellIDs)
		local updated = CooldownPanels:SetEntryAuraOverlaySpellIDs(currentEntry, value)
		if not updated then
			if UIErrorsFrame and UIErrorsFrame.AddMessage then UIErrorsFrame:AddMessage(L["CooldownPanelCDMAuraOverlaySpellIDsInvalid"] or "Enter positive Spell IDs separated by commas.", 1, 0.2, 0.2) end
			refreshEntryViews()
			return
		end
		if previous == CooldownPanels:FormatEntryAuraOverlaySpellIDs(currentEntry.cdmAuraOverlaySpellIDs) then return end
		CooldownPanels:RebuildSpellIndex()
		refreshEntryViews()
	end

	local function setTrackedAuraUnit(value)
		local _, currentEntry = getEntry()
		if not (currentEntry and getEffectiveType() == "CDM_AURA") then return end
		if not CooldownPanels:SetEntryAuraUnit(currentEntry, "CDM_AURA", value) then return end
		refreshEntryViews()
	end

	local function setCDMAuraOverlayUnit(value)
		local _, currentEntry = getEntry()
		local effectiveType = getEffectiveType()
		if not (currentEntry and CooldownPanels:SupportsEntryCDMAuraOverlay(currentEntry, effectiveType)) then return end
		if not CooldownPanels:SetEntryAuraUnit(currentEntry, effectiveType, value) then return end
		refreshEntryViews()
	end

	local function setTrackedAuraOnlyMine(value)
		local _, currentEntry = getEntry()
		if not (currentEntry and getEffectiveType() == "CDM_AURA" and currentEntry.auraUnit == "target") then return end
		local nextFilter = value == true and "HARMFUL|PLAYER" or "HARMFUL"
		if currentEntry.auraFilter == nextFilter then return end
		currentEntry.auraFilter = nextFilter
		refreshEntryViews()
	end

	local function setCDMAuraOverlayColorOverrideEnabled(value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local useGlobal = value ~= true
		if currentEntry.cdmAuraOverlayColorUseGlobal == useGlobal then return end
		currentEntry.cdmAuraOverlayColorUseGlobal = useGlobal
		refreshEntryViews()
	end

	local function setActivationOverlayBehaviorOverrideEnabled(value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local useGlobal = value ~= true
		if currentEntry.activationOverlayBehaviorUseGlobal == useGlobal then return end
		if not useGlobal then
			local layout = getLayout()
			currentEntry.activationOverlayReverse = CooldownPanels:ResolveEntryActivationOverlayReverse(layout, currentEntry)
			currentEntry.activationOverlayOnly = CooldownPanels:ResolveEntryActivationOverlayOnly(layout, currentEntry)
			currentEntry.activationOverlayGlow = CooldownPanels:ResolveEntryActivationOverlayGlow(layout, currentEntry)
			currentEntry.activationOverlayColor = CooldownPanels:ResolveEntryActivationOverlayColor(layout, currentEntry)
			currentEntry.activationOverlayGlowColor = CooldownPanels:ResolveEntryActivationOverlayGlowColor(layout, currentEntry)
		end
		currentEntry.activationOverlayBehaviorUseGlobal = useGlobal
		refreshEntryViews()
	end

	local function setActivationOverlayBehaviorField(field, value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		currentEntry.activationOverlayBehaviorUseGlobal = false
		if currentEntry[field] == value then return end
		currentEntry[field] = value
		if field == "activationOverlayGlow" then
			refreshEntryGlowPreview()
		else
			refreshEntryViews()
		end
	end

	local function setAutoCooldownDurationEnabled(value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local normalized = value == true
		if normalized and not CooldownPanels:SupportsEntryAutoCooldownDuration(currentEntry, getEffectiveType()) then return end
		if currentEntry.autoCooldownDurationEnabled == normalized then return end
		currentEntry.autoCooldownDurationEnabled = normalized
		if normalized then currentEntry.customCooldownDurationEnabled = false end
		if normalized then currentEntry.customCooldownDurationOnCooldownEnabled = false end
		if normalized then currentEntry.customCooldownDurationOnCooldownMultipleStacks = false end
		if normalized then currentEntry.cdmAuraOverlayEnabled = false end
		CooldownPanels:ClearEntryCustomCooldownDuration(panelId, entryId, true)
		refreshEntryViews()
	end

	local function setCustomCooldownDuration(value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local duration = Helper.ClampNumber(value, 0, Helper.CUSTOM_COOLDOWN_DURATION_MAX or 300, currentEntry.customCooldownDuration or 0) or 0
		local enabledChanged = false
		if duration <= 0 then
			duration = 0
			if currentEntry.customCooldownDurationEnabled ~= false then
				currentEntry.customCooldownDurationEnabled = false
				enabledChanged = true
			end
			if currentEntry.customCooldownDurationOnCooldownEnabled ~= false then
				currentEntry.customCooldownDurationOnCooldownEnabled = false
				enabledChanged = true
			end
			if currentEntry.customCooldownDurationOnCooldownMultipleStacks ~= false then
				currentEntry.customCooldownDurationOnCooldownMultipleStacks = false
				enabledChanged = true
			end
		end
		if currentEntry.customCooldownDuration == duration and not enabledChanged then return end
		currentEntry.customCooldownDuration = duration
		CooldownPanels:ClearEntryCustomCooldownDuration(panelId, entryId, true)
		refreshEntryViews()
	end

	local function setCooldownVisibilityOverrideEnabled(value)
		local layout = getLayout()
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local useGlobal = value ~= true
		if currentEntry.cooldownVisibilityUseGlobal == useGlobal then return end
		if not useGlobal then
			currentEntry.hideOnCooldown, currentEntry.showOnCooldown = CooldownPanels:ResolveEntryCooldownVisibility(layout, currentEntry)
		end
		currentEntry.cooldownVisibilityUseGlobal = useGlobal
		refreshEntryViews()
	end

	local function setCooldownVisibility(field, value)
		local _, currentEntry = getEntry()
		if not currentEntry then return end
		local hideOnCooldown = currentEntry.hideOnCooldown == true
		local showOnCooldown = currentEntry.showOnCooldown == true
		if field == "hideOnCooldown" then
			hideOnCooldown = value == true
			if hideOnCooldown then showOnCooldown = false end
		elseif field == "showOnCooldown" then
			showOnCooldown = value == true
			if showOnCooldown then hideOnCooldown = false end
		else
			return
		end
		if currentEntry.hideOnCooldown == hideOnCooldown and currentEntry.showOnCooldown == showOnCooldown then return end
		currentEntry.hideOnCooldown = hideOnCooldown
