	panelEnabled:SetScript("OnClick", function(self)
		local panelId = editor.selectedPanelId
		local panel = panelId and CooldownPanels:GetPanel(panelId)
		if panel then
			panel.enabled = self:GetChecked() and true or false
			CooldownPanels:RebuildSpellIndex()
			Keybinds.MarkPanelsDirty()
			CooldownPanels:RefreshPanel(panelId)
			CooldownPanels:UpdateCursorAnchorState()
			CooldownPanels:RefreshEditor()
		end
	end)

	panelSpecButton:SetScript("OnClick", function(self) showSpecMenu(self, editor.selectedPanelId) end)

	entryIdBox:SetScript("OnEnterPressed", function(self)
		local panelId = editor.selectedPanelId
		local entryId = editor.selectedEntryId
		local panel = panelId and CooldownPanels:GetPanel(panelId)
		local entry = panel and panel.entries and panel.entries[entryId]
		local value = tonumber(self:GetText())
		if not panel or not entry then
			self:ClearFocus()
			CooldownPanels:RefreshEditor()
			return
		end
		if entry.type == "STANCE" or (entry.type == "CDM_AURA" and not CooldownPanels.AuraContainers) then
			self:ClearFocus()
			CooldownPanels:RefreshEditor()
			return
		end
		if not value then
			self:ClearFocus()
			CooldownPanels:RefreshEditor()
			return
		end
		local newValue = value
		local enableHighestRank = false
		local exactTalentChoice = entry.type == "SPELL" and CooldownPanels:IsEntryTalentChoiceExact(entry)
		if entry.type == "SPELL" then
			local baseValue = getBaseSpellId(value) or value
			if not spellExistsSafe(value) and not spellExistsSafe(baseValue) then
				showErrorMessage(L["CooldownPanelSpellInvalid"] or "Spell does not exist.")
				self:ClearFocus()
				CooldownPanels:RefreshEditor()
				return
			end
			exactTalentChoice = exactTalentChoice and CooldownPanels:IsTalentChoiceSpellID(value)
			newValue = exactTalentChoice and value or (CooldownPanels:NormalizePersistentSpellID(value, { allowTalentChoiceCanonical = true }) or baseValue)
		elseif entry.type == "CDM_AURA" then
			if not spellExistsSafe(value) then
				showErrorMessage(L["CooldownPanelSpellInvalid"] or "Spell does not exist.")
				self:ClearFocus()
				CooldownPanels:RefreshEditor()
				return
			end
			newValue = value
		elseif entry.type == "ITEM" then
			local canonicalItemID, wasHigherRank = CooldownPanels:GetCanonicalItemRankID(newValue)
			if canonicalItemID then newValue = canonicalItemID end
			enableHighestRank = wasHigherRank == true
		end
		local existingId = CooldownPanels:FindEntryByValue(panelId, entry.type, newValue, exactTalentChoice and { talentChoiceExact = true } or nil)
		if existingId and existingId ~= entryId then
			showErrorMessage("Entry already exists.")
			self:ClearFocus()
			CooldownPanels:RefreshEditor()
			return
		end
		if entry.type == "SPELL" then
			entry.spellID = newValue
			entry.talentChoiceExact = exactTalentChoice and true or nil
		elseif entry.type == "CDM_AURA" then
			entry.spellID = newValue
			entry.auraSpellID = newValue
			entry.auraBackend = "AURA_CONTAINER"
			entry.auraUnit = Helper.NormalizeAuraUnit(entry.auraUnit)
			if entry.auraUnit == "target" then
				entry.auraFilter = entry.auraFilter == "HARMFUL" and "HARMFUL" or "HARMFUL|PLAYER"
			else
				entry.auraFilter = "HELPFUL"
			end
			entry.buffName = C_Spell and C_Spell.GetSpellName and C_Spell.GetSpellName(newValue) or entry.buffName
			entry.iconTextureID = C_Spell and C_Spell.GetSpellTexture and C_Spell.GetSpellTexture(newValue) or entry.iconTextureID
		elseif entry.type == "ITEM" then
			entry.itemID = newValue
			if enableHighestRank then entry.useHighestRank = true end
		elseif entry.type == "SLOT" then
			entry.slotID = newValue
		elseif entry.type == "MACRO" then
			entry.macroID = newValue
			local macroName = Api.GetMacroInfo and Api.GetMacroInfo(newValue) or nil
			entry.macroName = CooldownPanels.NormalizeMacroName(macroName) or entry.macroName
		end
		self:ClearFocus()
		CooldownPanels:ClearEntryCustomCooldownDuration(panelId, entryId, true)
		CooldownPanels:RebuildSpellIndex()
		CooldownPanels:RefreshPanel(panelId)
		CooldownPanels:RefreshEditor()
	end)
	entryIdBox:SetScript("OnEscapePressed", function(self)
		self:ClearFocus()
		CooldownPanels:RefreshEditor()
	end)

	local function bindEntryToggle(cb, field)
		cb:SetScript("OnClick", function(self)
			local panelId = editor.selectedPanelId
			local entryId = editor.selectedEntryId
			local panel = panelId and CooldownPanels:GetPanel(panelId)
			local entry = panel and panel.entries and panel.entries[entryId]
			if not entry then return end
			entry[field] = self:GetChecked() and true or false
			if field == "showCharges" then entry.showChargesUseGlobal = false end
			if field == "showStacks" then entry.showStacksUseGlobal = false end
			if field == "showCooldownText" then entry.showCooldownTextUseGlobal = false end
			CooldownPanels:HandleEntryBooleanMutation(panelId, entryId, entry, field)
			CooldownPanels:RefreshPanel(panelId)
			CooldownPanels:RefreshEditor()
		end)
	end

	bindEntryToggle(cbCharges, "showCharges")
	bindEntryToggle(cbStacks, "showStacks")
	bindEntryToggle(cbCooldownText, "showCooldownText")
	bindEntryToggle(cbTrackPassiveSpell, "trackPassiveSpell")
	bindEntryToggle(cbTrackUnknownSpell, "trackUnknownSpell")
	auraUnitButton:SetScript("OnClick", function(self) CooldownPanels:ShowEntryAuraUnitMenu(self, editor.selectedPanelId, editor.selectedEntryId) end)
	cbCDMAuraOverlayOnlyMine:SetScript("OnClick", function(self)
		local panelId = editor.selectedPanelId
		local entryId = editor.selectedEntryId
		local panel = panelId and CooldownPanels:GetPanel(panelId)
		local entry = panel and panel.entries and panel.entries[entryId]
		if not entry then return end
		local checked = self:GetChecked() and true or false
		if entry.type == "CDM_AURA" then
			if entry.auraUnit ~= "target" then return end
			entry.auraFilter = checked and "HARMFUL|PLAYER" or "HARMFUL"
		else
			entry.cdmAuraOverlayTargetPlayerOnly = checked
		end
		CooldownPanels:RefreshPanel(panelId)
		CooldownPanels:RefreshEditor()
	end)
	cbAlwaysShow:SetScript("OnClick", function(self)
		local panelId = editor.selectedPanelId
		local entryId = editor.selectedEntryId
		local panel = panelId and CooldownPanels:GetPanel(panelId)
		local entry = panel and panel.entries and panel.entries[entryId]
		if not entry then return end
		if entry.type == "STANCE" then
			entry.showWhenMissing = self:GetChecked() and true or false
		elseif entry.type == "CDM_AURA" then
			local layout = panel and panel.layout or nil
			local mode = self:GetChecked() and (CooldownPanels.CDM_AURA_ALWAYS_SHOW_MODE and CooldownPanels.CDM_AURA_ALWAYS_SHOW_MODE.SHOW or "SHOW")
				or (CooldownPanels.CDM_AURA_ALWAYS_SHOW_MODE and CooldownPanels.CDM_AURA_ALWAYS_SHOW_MODE.HIDE or "HIDE")
			local resolvedMode = CooldownPanels:ResolveEntryCDMAuraAlwaysShowMode(layout, entry)
			if entry.cdmAuraAlwaysShowUseGlobal == false and resolvedMode == mode then return end
			entry.cdmAuraAlwaysShowUseGlobal = false
			entry.cdmAuraAlwaysShowMode = mode
			entry.alwaysShow = self:GetChecked() and true or false
		else
			entry.alwaysShow = self:GetChecked() and true or false
		end
		CooldownPanels:RefreshPanel(panelId)
		CooldownPanels:RefreshEditor()
	end)
	bindEntryToggle(cbItemCount, "showItemCount")
	bindEntryToggle(cbItemUses, "showItemUses")
	bindEntryToggle(cbUseHighestRank, "useHighestRank")
	bindEntryToggle(cbShowWhenEmpty, "showWhenEmpty")
	bindEntryToggle(cbShowWhenNoCooldown, "showWhenNoCooldown")
	cbCDMAuraOverlay:SetScript("OnClick", function(self)
		local panelId = editor.selectedPanelId
		local entryId = editor.selectedEntryId
		local panel = panelId and CooldownPanels:GetPanel(panelId)
		local entry = panel and panel.entries and panel.entries[entryId]
		if not entry then return end
		local enabled = self:GetChecked() == true
		if enabled and not CooldownPanels:SupportsEntryCDMAuraOverlay(entry, entry.type) then
			self:SetChecked(false)
			return
		end
			entry.cdmAuraOverlayEnabled = enabled
			if enabled then
				entry.customCooldownDurationEnabled = false
				entry.customCooldownDurationOnCooldownEnabled = false
				entry.customCooldownDurationOnCooldownMultipleStacks = false
				entry.autoCooldownDurationEnabled = false
			end
		CooldownPanels:ClearEntryCustomCooldownDuration(panelId, entryId, true)
		CooldownPanels:RebuildSpellIndex()
		CooldownPanels:RefreshPanel(panelId)
		CooldownPanels:RefreshEditor()
	end)
	local function commitAuraOverlaySpellIDs(box)
		if box._eqolUpdating then return end
		local panelId = editor.selectedPanelId
		local entryId = editor.selectedEntryId
		local panel = panelId and CooldownPanels:GetPanel(panelId)
		local entry = panel and panel.entries and panel.entries[entryId]
		if not entry then return end
		local previous = CooldownPanels:FormatEntryAuraOverlaySpellIDs(entry.cdmAuraOverlaySpellIDs)
		local updated = CooldownPanels:SetEntryAuraOverlaySpellIDs(entry, box:GetText() or "")
		if not updated then
			if UIErrorsFrame and UIErrorsFrame.AddMessage then UIErrorsFrame:AddMessage(L["CooldownPanelCDMAuraOverlaySpellIDsInvalid"] or "Enter positive Spell IDs separated by commas.", 1, 0.2, 0.2) end
			box._eqolUpdating = true
			box:SetText(previous)
			box._eqolUpdating = nil
			return
		end
		local current = CooldownPanels:FormatEntryAuraOverlaySpellIDs(entry.cdmAuraOverlaySpellIDs)
		box._eqolUpdating = true
		box:SetText(current)
		box._eqolUpdating = nil
		if current == previous then return end
		CooldownPanels:RebuildSpellIndex()
		CooldownPanels:RefreshPanel(panelId)
		CooldownPanels:RefreshEditor()
	end
	auraOverlaySpellIDsBox:SetScript("OnEnterPressed", function(self)
		commitAuraOverlaySpellIDs(self)
		self:ClearFocus()
	end)
	auraOverlaySpellIDsBox:SetScript("OnEscapePressed", function(self)
		local panelId = editor.selectedPanelId
		local panel = panelId and CooldownPanels:GetPanel(panelId)
		local entry = panel and panel.entries and panel.entries[editor.selectedEntryId]
		self._eqolUpdating = true
		self:SetText(CooldownPanels:FormatEntryAuraOverlaySpellIDs(entry and entry.cdmAuraOverlaySpellIDs))
		self._eqolUpdating = nil
		self:ClearFocus()
	end)
	auraOverlaySpellIDsBox:SetScript("OnEditFocusLost", function(self) commitAuraOverlaySpellIDs(self) end)
