	local function applyStaticTextValue(self)
		local panelId = editor.selectedPanelId
		local entryId = editor.selectedEntryId
		local panel = panelId and CooldownPanels:GetPanel(panelId)
		local entry = panel and panel.entries and panel.entries[entryId]
		if not entry then
			self:ClearFocus()
			return
		end
		local text = self:GetText() or ""
		if entry.staticText == text then
			self:ClearFocus()
			return
		end
		entry.staticText = text
		self:ClearFocus()
		CooldownPanels:RefreshPanel(panelId)
		CooldownPanels:RefreshEditor()
	end

	staticTextBox:SetScript("OnEnterPressed", applyStaticTextValue)
	staticTextBox:SetScript("OnEditFocusLost", applyStaticTextValue)
	staticTextBox:SetScript("OnEscapePressed", function(self)
		self:ClearFocus()
		CooldownPanels:RefreshEditor()
	end)

	local function applyCustomDurationValue(self)
		local panelId = editor.selectedPanelId
		local entryId = editor.selectedEntryId
		local panel = panelId and CooldownPanels:GetPanel(panelId)
		local entry = panel and panel.entries and panel.entries[entryId]
		if not entry then
			self:ClearFocus()
			return
		end
		local duration = Helper.ClampNumber(tonumber(self:GetText()), 0, Helper.CUSTOM_COOLDOWN_DURATION_MAX or 300, entry.customCooldownDuration or 0) or 0
		if duration <= 0 then
			duration = 0
			entry.customCooldownDurationEnabled = false
			entry.customCooldownDurationOnCooldownEnabled = false
			entry.customCooldownDurationOnCooldownMultipleStacks = false
		end
		entry.customCooldownDuration = duration
		CooldownPanels:ClearEntryCustomCooldownDuration(panelId, entryId, true)
		self:ClearFocus()
		CooldownPanels:RefreshPanel(panelId)
		CooldownPanels:RefreshEditor()
	end

	customDurationBox:SetScript("OnEnterPressed", applyCustomDurationValue)
	customDurationBox:SetScript("OnEditFocusLost", applyCustomDurationValue)
	customDurationBox:SetScript("OnEscapePressed", function(self)
		self:ClearFocus()
		CooldownPanels:RefreshEditor()
	end)

	soundButton:SetScript("OnClick", function(self)
		local panelId = editor.selectedPanelId
		local entryId = editor.selectedEntryId
		if panelId and entryId then showSoundMenu(self, panelId, entryId) end
	end)

	removeEntry:SetScript("OnClick", function()
		local panelId = editor.selectedPanelId
		local entryId = editor.selectedEntryId
		if panelId and entryId then
			CooldownPanels:RemoveEntry(panelId, entryId)
			editor.selectedEntryId = nil
			CooldownPanels:RefreshEditor()
		end
	end)

	local cdmAuras = CooldownPanels.CDMAuras
	if cdmAuras and cdmAuras.AttachEditor then cdmAuras:AttachEditor(runtime.editor) end

	return runtime.editor
end

	function CooldownPanels:OpenBlizzardEditorEntrySettings(panelId, entryId, anchorFrame)
		local editor = ensureEditor()
		panelId = normalizeId(panelId)
		entryId = normalizeId(entryId)
		local panel = panelId and self:GetPanel(panelId) or nil
		local entry = panel and panel.entries and panel.entries[entryId] or nil
		if not (editor and panel and entry) then return false end
		editor._eqolBlizzardEditorLayoutEdit = true
		editor._eqolSuppressBlizzardEditorLayoutEditEnd = true
		if self.SelectPanel then self:SelectPanel(panelId) end
		editor._eqolSuppressLayoutPanelDialog = true
		if self.SetEditorLayoutEditEnabled then self:SetEditorLayoutEditEnabled(true) end
		editor._eqolSuppressLayoutPanelDialog = nil
		editor._eqolSuppressBlizzardEditorLayoutEditEnd = nil
		if self.SelectEntry then self:SelectEntry(entryId) end
		if self.OpenLayoutEntryStandaloneMenu then self:OpenLayoutEntryStandaloneMenu(panelId, entryId, anchorFrame) end
		return true
	end

function CooldownPanels:OpenBlizzardEditorPanelSettings(panelId, anchorFrame)
	local editor = ensureEditor()
		panelId = normalizeId(panelId)
		local panel = panelId and self:GetPanel(panelId) or nil
		if not (editor and panel) then return false end
		editor._eqolBlizzardEditorLayoutEdit = true
		editor._eqolSuppressBlizzardEditorLayoutEditEnd = true
		editor._eqolSuppressLayoutPanelDialog = true
		if self.SelectPanel then self:SelectPanel(panelId) end
		if self.SetEditorLayoutEditEnabled then self:SetEditorLayoutEditEnabled(true) end
		editor._eqolSuppressLayoutPanelDialog = nil
		editor._eqolSuppressBlizzardEditorLayoutEditEnd = nil
		if self.OpenLayoutPanelStandaloneMenu then self:OpenLayoutPanelStandaloneMenu(panelId, anchorFrame) end
		return true
	end

