	if not code then
		showErrorMessage(L["DataExportFailed"] or "Export failed.")
		return false
	end
	cdp.EXPORT.ShowDialog(title or (L["CooldownPanelExportView"] or "Export View"), code)
	return true
end

ensureDeletePopup = function()
	if not StaticPopupDialogs["EQOL_COOLDOWN_PANEL_DELETE"] then
		StaticPopupDialogs["EQOL_COOLDOWN_PANEL_DELETE"] = {
			text = L["CooldownPanelDeletePanel"] or "Delete Panel?",
			button1 = YES,
			button2 = CANCEL,
			timeout = 0,
			whileDead = true,
			hideOnEscape = true,
			preferredIndex = 3,
			OnAccept = function(self, data)
				if not data or not data.panelId then return end
				CooldownPanels:DeletePanel(data.panelId)
				CooldownPanels:RefreshEditor()
				if CooldownPanels.BlizzardEditor and CooldownPanels.BlizzardEditor.Refresh then CooldownPanels.BlizzardEditor:Refresh() end
			end,
		}
	end
	if not StaticPopupDialogs["EQOL_COOLDOWN_PANEL_REMOVE_ALL_ENTRIES"] then
		StaticPopupDialogs["EQOL_COOLDOWN_PANEL_REMOVE_ALL_ENTRIES"] = {
			text = L["CooldownPanelRemoveAllEntriesPrompt"] or 'Remove all entries from "%s"? This cannot be undone.',
			button1 = YES,
			button2 = CANCEL,
			timeout = 0,
			whileDead = true,
			hideOnEscape = true,
			preferredIndex = 3,
			OnAccept = function(self, data)
				if not data or not data.panelId then return end
				CooldownPanels:RemoveAllEntries(data.panelId)
			end,
		}
	end
end

function cdp.EXPORT.ImportErrorMessage(reason)
	if reason == "NO_INPUT" then return L["ProfileImportEmpty"] or "Please paste a code to import." end
	if reason == "INVALID" or reason == "DECODE" or reason == "DECOMPRESS" or reason == "DESERIALIZE" then return L["The code could not be read."] or "The code could not be read." end
	return L["CooldownPanelImportFailed"] or "Cooldown panel import failed."
end

function cdp.EXPORT.ShowDialog(title, code)
	CooldownPanels.EnsureExportPanelPopup()
	local dialog = StaticPopupDialogs["EQOL_COOLDOWN_PANEL_EXPORT"]
	dialog.text = title or (L["CooldownPanelExportPanel"] or "Export Panel")
	dialog._eqolExportCode = code or ""
	StaticPopup_Show("EQOL_COOLDOWN_PANEL_EXPORT")
end

function CooldownPanels.EnsureExportPanelPopup()
