		text = L["CooldownPanelFixedGroupIconSizePrompt"] or "Set group icon size (leave empty for panel size)",
		button1 = OKAY,
		button2 = CANCEL,
		hasEditBox = true,
		editBoxWidth = 180,
		enterClicksFirstButton = true,
		timeout = 0,
