	glowPixelSpeed = true,
	glowPixelThickness = true,
	glowReady = true,
	hideGlowOutOfCombat = true,
	pandemicGlowColor = true,
	pandemicGlowInset = true,
	pandemicGlowStyle = true,
	procGlowEnabled = true,
	procGlowInset = true,
	procGlowStyle = true,
	readyGlowCheckPower = true,
	readyGlowColor = true,
	readyGlowInset = true,
	readyGlowStyle = true,
}

function CooldownPanels:TryRefreshPanelGlowPreview(panelId, fixedGroupId)
	panelId = normalizeId(panelId)
	fixedGroupId = Helper.NormalizeFixedGroupId(fixedGroupId)
	if not (panelId and self:IsPanelLayoutEditActive(panelId)) then return false end

	local panel = self:GetPanel(panelId)
	local runtime = panel and getRuntime(panelId) or nil
	local entryToIcon = runtime and runtime.entryToIcon or nil
	if not (panel and panel.entries and runtime and runtime.frame and entryToIcon) then return false end

	-- Validate the complete target set before applying anything so an inconsistent
	-- editor mapping falls back to one regular refresh instead of a partial preview.
	for entryId, icon in pairs(entryToIcon) do
		local entry = panel.entries[entryId]
		if not entry then return false end
		if entry.displayMode ~= "BAR" and (not fixedGroupId or Helper.NormalizeFixedGroupId(entry.fixedGroupId) == fixedGroupId) then
			local data = icon and icon._eqolRuntimeData or nil
			if not (data and normalizeId(data.entryId) == normalizeId(entryId)) then return false end
		end
	end

	local effectiveLayoutCache = runtime._eqolPanelGlowEffectiveLayoutCache
	if not effectiveLayoutCache then
		effectiveLayoutCache = {}
		runtime._eqolPanelGlowEffectiveLayoutCache = effectiveLayoutCache
	else
		for key in pairs(effectiveLayoutCache) do
			effectiveLayoutCache[key] = nil
		end
	end

	for entryId, icon in pairs(entryToIcon) do
		local entry = panel.entries[entryId]
		if entry and entry.displayMode ~= "BAR" and (not fixedGroupId or Helper.NormalizeFixedGroupId(entry.fixedGroupId) == fixedGroupId) then
			local data = icon._eqolRuntimeData
			data.layout = self:GetEntryEffectiveLayout(panelId, entry, effectiveLayoutCache, panel) or panel.layout
			if not self:TryRefreshEntryGlowPreview(panelId, entryId) then return false end
		end
	end
	return true
end

function cdp.RUNTIME.NormalizeCDMAuraCooldownID(value)
	local valueType = type(value)
	if valueType == "number" then return value > 0 and value or nil end
	if valueType == "string" then return value ~= "" and value or nil end
	return nil
end

function cdp.RUNTIME.CDMAuraCooldownIDsEqual(a, b)
	local left = cdp.RUNTIME.NormalizeCDMAuraCooldownID(a)
	local right = cdp.RUNTIME.NormalizeCDMAuraCooldownID(b)
	if left == nil or right == nil then return false end
	return tostring(left) == tostring(right)
end

function CooldownPanels:NormalizeCDMAuraGlowOtherAura(value)
	if type(value) ~= "table" then value = { cooldownID = value } end
	local cooldownID = cdp.RUNTIME.NormalizeCDMAuraCooldownID(value.cooldownID)
	if not cooldownID then return nil end
	return {
		cooldownID = cooldownID,
		spellID = tonumber(value.spellID),
		buffName = type(value.buffName) == "string" and value.buffName or nil,
		iconTextureID = value.iconTextureID,
		sourceType = value.sourceType,
		sourceViewer = value.sourceViewer,
	}
end

function CooldownPanels:GetCDMAuraGlowOtherAuraOptions(panelId, currentEntry)
	local cdmAuras = self.CDMAuras
	local options = {}
	if not (cdmAuras and cdmAuras.ScanTrackedBuffs) then return options end
	local buffs = cdmAuras:ScanTrackedBuffs(true)
	if type(buffs) ~= "table" then return options end
	for i = 1, #buffs do
		local info = buffs[i]
		local cooldownID = cdp.RUNTIME.NormalizeCDMAuraCooldownID(info and info.cooldownID)
		if cooldownID and not cdp.RUNTIME.CDMAuraCooldownIDsEqual(cooldownID, currentEntry and currentEntry.cooldownID) then
			local icon = tostring(info.iconTextureID or Helper.PREVIEW_ICON)
			local nameText = tostring(info.buffName or cooldownID)
			options[#options + 1] = {
				value = tostring(cooldownID),
				label = string.format("|T%s:14:14:0:0:64:64:4:60:4:60|t %s", icon, nameText),
				info = self:NormalizeCDMAuraGlowOtherAura(info),
			}
		end
	end
	return options
end

function CooldownPanels:IsCDMAuraGlowOtherAuraActive(panelId, entryId, entry, entryLayout)
	local cdmAuras = self.CDMAuras
	local config = self:NormalizeCDMAuraGlowOtherAura(entry and entry.glowOtherAura)
	if not (cdmAuras and cdmAuras.BuildRuntimeData and config) then return false end
	if cdp.RUNTIME.CDMAuraCooldownIDsEqual(config.cooldownID, entry and entry.cooldownID) then return false end
	local otherEntry = {
		type = "CDM_AURA",
		cooldownID = config.cooldownID,
		spellID = config.spellID,
		buffName = config.buffName,
		iconTextureID = config.iconTextureID,
		sourceType = config.sourceType or entry.sourceType,
		sourceViewer = config.sourceViewer,
	}
	local otherData = cdmAuras:BuildRuntimeData(panelId, tostring(entryId or "") .. ":glowOtherAura", otherEntry, entryLayout, "HIDE")
	return otherData and otherData.active == true or false
end

CooldownPanels.SetIconDesaturatedRuntime = function(texture, enabled, skipDesaturation)
	if skipDesaturation then
		texture:SetDesaturated(false)
	else
		texture:SetDesaturated(enabled == true)
	end
end

CooldownPanels.SetIconDesaturationRuntime = function(texture, value, skipDesaturation)
	if skipDesaturation then
		texture:SetDesaturation(0)
	else
		texture:SetDesaturation(value or 0)
	end
end

CooldownPanels.IsAssistedSuggestedSpell = function(assistedSuggestedSpellId, assistedSuggestedBaseId, assistedSuggestedEffectiveId, baseSpellId, effectiveSpellId)
	if not (assistedSuggestedSpellId and baseSpellId) then return false end
	if baseSpellId == assistedSuggestedSpellId or baseSpellId == assistedSuggestedBaseId or baseSpellId == assistedSuggestedEffectiveId then return true end
	if effectiveSpellId and (effectiveSpellId == assistedSuggestedSpellId or effectiveSpellId == assistedSuggestedBaseId or effectiveSpellId == assistedSuggestedEffectiveId) then return true end
	return false
end

local function updateItemCountCache(usesOnly)
	CooldownPanels.runtime = CooldownPanels.runtime or {}
	local runtime = CooldownPanels.runtime
	runtime.itemCountCache = runtime.itemCountCache or {}
	local cache = runtime.itemCountCache
	local trackedIds = usesOnly == true and runtime.itemUsesTrackedIds or runtime.itemTrackedIds
	local trackedUsesIds = runtime.itemUsesTrackedIds
	if not trackedIds or not next(trackedIds) then
		if usesOnly == true then return false end
		for id in pairs(cache) do
			cache[id] = nil
		end
		return false
	end
	for id in pairs(cache) do
		if not runtime.itemTrackedIds[id] then cache[id] = nil end
	end
	for id in pairs(trackedIds) do
		local slot = cache[id] or {}
		if usesOnly ~= true then slot.count = Api.GetItemCount(id, false, false) or 0 end
		if trackedUsesIds and trackedUsesIds[id] then
			slot.uses = Api.GetItemCount(id, false, true) or 0
		elseif usesOnly ~= true then
			slot.uses = nil
		end
		cache[id] = slot
	end
	return true
end

updateItemCountCacheForItem = function(itemID, includeUses)
	if not itemID then return end
	CooldownPanels.runtime = CooldownPanels.runtime or {}
	local runtime = CooldownPanels.runtime
	runtime.itemCountCache = runtime.itemCountCache or {}
	local slot = runtime.itemCountCache[itemID] or {}
	slot.count = Api.GetItemCount(itemID, false, false) or 0
	if includeUses == nil then includeUses = runtime.itemUsesTrackedIds and runtime.itemUsesTrackedIds[itemID] end
	if includeUses then
		slot.uses = Api.GetItemCount(itemID, false, true) or 0
	else
		slot.uses = nil
	end
	runtime.itemCountCache[itemID] = slot
end

function CooldownPanels:HandleEntryBooleanMutation(panelId, entryId, entry, field)
	if not (panelId and entry and field) then return end
	if field == "glowReady" then CooldownPanels.ClearReadyGlowEntryState(panelId, entryId, true) end
	if field == "trackPassiveSpell" or field == "trackUnknownSpell" then self:RebuildSpellIndex() end
	if field == "interruptGlow" then self:RebuildSpellIndex() end
	if field == "glowReady" or field == "checkPower" or field == "hideWhenNoResource" or field == "readyGlowCheckPower" then self:RebuildPowerIndex() end
	if field == "showCharges" or field == "showChargesUseGlobal" then self:RebuildChargesIndex() end
	if field == "showItemUses" or field == "useHighestRank" then
		self:RebuildSpellIndex()
		updateItemCountCache()
		if entry.type == "ITEM" then
			local resolvedItemId = CooldownPanels.ResolveEntryItemID(entry, entry.itemID)
			if resolvedItemId then updateItemCountCacheForItem(resolvedItemId, entry.showItemUses == true) end
		elseif entry.type == "MACRO" then
			local macro = CooldownPanels.ResolveMacroEntry(entry)
			if macro and macro.kind == "ITEM" and macro.itemID then updateItemCountCacheForItem(macro.itemID, entry.showItemUses == true) end
		end
	end
end

function CooldownPanels:RefreshEntryStyleMutation(panelId, entryId, entry, refreshDialog)
	panelId = normalizeId(panelId)
	entryId = normalizeId(entryId)
	if not (panelId and entry) then return end
	local root = ensureRoot()
	if root and Helper.NormalizeEntry then Helper.NormalizeEntry(entry, root.defaults) end
	self:ClearEntryCustomCooldownDuration(panelId, entryId, true)
	self:RebuildSpellIndex()
	self:RebuildChargesIndex()
	self:RebuildPowerIndex()
	updateItemCountCache()
	self:RefreshPanel(panelId)
	if self.IsEditorOpen and self:IsEditorOpen() then self:RefreshEditor() end
	if self.BlizzardEditor and self.BlizzardEditor.RefreshPanel then self.BlizzardEditor:RefreshPanel(panelId) end
	if refreshDialog and self.RefreshLayoutEntryStandaloneMenu then self:RefreshLayoutEntryStandaloneMenu(true) end
end

function CooldownPanels:DisableEntryGlowForQuickSetup(panelId, entryId, entry)
	if not entry then return end
	entry.glowUseGlobal = false
	entry.glowReady = false
	entry.interruptGlow = false
	entry.pandemicGlow = false
	entry.glowOtherAura = nil
	entry.glowOtherAuraColor = nil
	entry.procGlowUseGlobal = false
	entry.procGlowEnabled = false
	entry.activationOverlayBehaviorUseGlobal = false
	entry.activationOverlayGlow = false
	self.ClearReadyGlowEntryState(panelId, entryId, true)
end

function CooldownPanels:DisableEntryCountersForQuickSetup(entry)
	if not entry then return end
	entry.showCharges = false
	entry.showChargesCooldown = false
	entry.showStacks = false
	if entry.type == "ITEM" then
		entry.showItemCount = false
		entry.showItemUses = false
	end
end

function CooldownPanels:SetEntryAlwaysShowForQuickSetup(entry)
	if not entry then return end
	entry.alwaysShow = true
	if entry.type == "CDM_AURA" then
		entry.cdmAuraAlwaysShowUseGlobal = false
		entry.cdmAuraAlwaysShowMode = CooldownPanels.CDM_AURA_ALWAYS_SHOW_MODE and CooldownPanels.CDM_AURA_ALWAYS_SHOW_MODE.SHOW or "SHOW"
	end
end

function CooldownPanels:ApplyStacksOnlyQuickSetup(panelId, entryId, refreshDialog)
	panelId = normalizeId(panelId)
	entryId = normalizeId(entryId)
	local panel = panelId and self:GetPanel(panelId) or nil
	local entry = panel and panel.entries and panel.entries[entryId] or nil
	if not entry then return false end
	local effectiveType = self:GetLayoutEntryStandaloneEffectiveType(entry)
	local supportsStacks = effectiveType == "SPELL" or effectiveType == "CDM_AURA"
	if effectiveType == "SLOT" then
		local slotID = tonumber(entry.slotID)
		supportsStacks = slotID == 13 or slotID == 14
	end
	if not supportsStacks then return false end
	if refreshDialog then self:FocusEntryStacksStandaloneSettings(panelId, entryId) end

	entry.hideIcon = true
	entry.showCooldownTextUseGlobal = false
	entry.showCooldownText = false
	entry.cooldownTextUseGlobal = false
	entry.cooldownVisualsUseGlobal = false
	entry.showChargesCooldown = false
	entry.cooldownDrawEdge = false
	entry.cooldownDrawBling = false
	entry.cooldownDrawSwipe = false
	entry.cooldownGcdDrawEdge = false
	entry.cooldownGcdDrawBling = false
	entry.cooldownGcdDrawSwipe = false
	self:DisableEntryCountersForQuickSetup(entry)
	entry.showChargesUseGlobal = false
	entry.chargesStyleUseGlobal = false
	entry.showStacksUseGlobal = false
	entry.showStacks = true
	entry.stackStyleUseGlobal = false
	entry.stackAnchor = "CENTER"
	entry.stackX = 0
	entry.stackY = 0
	entry.stackFontSize = 20
	self:DisableEntryGlowForQuickSetup(panelId, entryId, entry)
	entry.staticText = ""
	entry.staticTextShowOnCooldown = false

	self:RefreshEntryStyleMutation(panelId, entryId, entry, refreshDialog)
	return true
end

