				icon.cooldown:Clear()
				if icon.cooldown.SetScript then icon.cooldown:SetScript("OnCooldownDone", nil) end
			end
			if layoutEditActive and data.showCooldown then
				hidden = false
				if icon.cooldown.SetScript then icon.cooldown:SetScript("OnCooldownDone", nil) end
				local auraPreview = CooldownPanels.AuraContainers ~= nil and data.resolvedType == "CDM_AURA"
				if auraPreview and icon.cooldown.SetDrawEdge then icon.cooldown:SetDrawEdge(false) end
				cooldownTextDurationObject = setExampleCooldown(icon.cooldown, auraPreview)
				cooldownTextIsGCD = false
				icon:SetAlpha(1)
			end
			if data.resolvedType == "CDM_AURA" and data.cdmAuraActiveDesaturate == true and cdmAuraActive then
				desaturate = true
				CooldownPanels.SetIconDesaturatedRuntime(icon.texture, true, entryNoDesaturation)
			end
			local cooldownDefaultFontPath, cooldownDefaultFontSize, cooldownDefaultFontStyle = cdp.RUNTIME.EnsureCooldownTextDefaults(icon)
			if
				data._eqolRuntimePlacementDirty
				or cdp.RUNTIME.HasCooldownTextStyleChange(icon._eqolRuntimeSnapshot, data, cooldownDefaultFontPath, cooldownDefaultFontSize, cooldownDefaultFontStyle)
			then
				CooldownPanels:ApplyEntryCooldownTextStyle(icon, data.layout, data.entry)
				cdp.RUNTIME.WriteCooldownTextStyleSnapshot(icon._eqolRuntimeSnapshot, data, cooldownDefaultFontPath, cooldownDefaultFontSize, cooldownDefaultFontStyle)
			end
			CooldownPanels:ApplyRuntimeCooldownTextBinding(icon, data, cooldownTextDurationObject, cooldownTextIsGCD, data.hideChargeCooldownText == true and hideChargeCooldownVisuals)
			if data.spellUnusable then
				icon.texture:SetVertexColor(unusableTintR or 0.6, unusableTintG or 0.6, unusableTintB or 0.6)
			elseif data.powerInsufficient then
				icon.texture:SetVertexColor(powerTintR or 0.5, powerTintG or 0.5, powerTintB or 1)
			elseif
				((data.resolvedType == "ITEM" or data.resolvedType == "SLOT") and not cooldownEnabledOk and isSafeGreaterThan(cooldownDuration, 0))
				or (data.resolvedType == "SPELL" and data.cooldownEnabled == false and data.cooldownIsActive == false and data.cooldownGCD ~= true)
			then
				icon.texture:SetVertexColor(0.4, 0.4, 0.4)
			else
				icon.texture:SetVertexColor(1, 1, 1)
			end

			if data.showItemCount and data.itemCount ~= nil then
				icon.count:SetText(data.itemCount)
				icon.count:Show()
			elseif data.showStacks and data.stackCount then
				icon.count:SetText(data.stackCount)
				icon.count:Show()
			else
				icon.count:Hide()
			end
			if layoutEditActive and not (icon.count and icon.count.IsShown and icon.count:IsShown()) then
				if data.resolvedType == "ITEM" and data.showItemCount then
					icon.count:SetText("20")
					icon.count:Show()
				elseif data.showStacks then
					icon.count:SetText(data.resolvedType == "CDM_AURA" and "2" or "3")
					icon.count:Show()
				end
			end
			if data._eqolRuntimeBaseDecorDirty and icon.keybind then
				if data.showKeybinds and data.keybindText then
					icon.keybind:SetText(data.keybindText)
					icon.keybind:Show()
				else
					icon.keybind:Hide()
				end
				cdp.RUNTIME.WriteBaseDecorSnapshot(icon._eqolRuntimeSnapshot, data, showTooltips)
			end
			local staticTextCooldown = false
			if data.entry and data.entry.staticTextShowOnCooldown == true then
				staticTextCooldown = layoutEditActive == true or data.stanceActive == true or cdmAuraActive or durationActive or (cooldownEnabledOk and isCooldownActive(cooldownStart, cooldownDuration))
			end
			if data._eqolRuntimeBaseDecorDirty and not icon.keybind then cdp.RUNTIME.WriteBaseDecorSnapshot(icon._eqolRuntimeSnapshot, data, showTooltips) end
			if data._eqolRuntimePlacementDirty or cdp.RUNTIME.HasStaticTextChange(icon._eqolRuntimeSnapshot, data, staticFontPath, staticFontSize, staticFontStyle, staticTextCooldown) then
				applyStaticText(icon, data.layout, data.entry, staticFontPath, staticFontSize, staticFontStyle, staticTextCooldown)
				cdp.RUNTIME.WriteStaticTextSnapshot(icon._eqolRuntimeSnapshot, data, staticFontPath, staticFontSize, staticFontStyle, staticTextCooldown)
			end
			if durationActive and showOnCooldown and data.entry.staticTextShowOnCooldown == true and staticTextCooldown then
				if data.entry.spellID then
					icon.staticText:SetAlpha(cooldownDurationObject:EvaluateRemainingDuration(Helper.FakeCurve))
					icon.cooldown:SetAlpha(cooldownDurationObject:EvaluateRemainingDuration(Helper.FakeCurve))
					if icon.cooldownText then icon.cooldownText:SetAlpha(cooldownDurationObject:EvaluateRemainingDuration(Helper.FakeCurve)) end
				end
			end

			data.stateTextureDesaturated = data.stateTextureShown == true and desaturate == true and entryNoDesaturation ~= true
			if data._eqolRuntimePlacementDirty or cdp.RUNTIME.HasStateTextureChange(icon._eqolRuntimeSnapshot, data) then
				applyStateTexture(icon, data)
				cdp.RUNTIME.WriteStateTextureSnapshot(icon._eqolRuntimeSnapshot, data)
			end
			if layoutEditActive and icon.previewSoundBorder and data.previewSound then icon.previewSoundBorder:Show() end
			if icon.rangeOverlay then
				if data.rangeOverlay then
					icon.rangeOverlay:SetColorTexture(rangeOverlayR or 1, rangeOverlayG or 0.1, rangeOverlayB or 0.1, rangeOverlayA or 0.35)
					icon.rangeOverlay:Show()
				else
					icon.rangeOverlay:Hide()
				end
			end
			setAssistedHighlight(icon, data.assistedSuggested == true)

			local readyGlowCooldownRunning
			local useSecretReadyGlow = data.resolvedType == "SPELL" and data.spellReadyCondition ~= nil and data.glowReady and data.showCooldown and data.canTriggerReadyGlow
			local secretReadyGlowAllowed = useSecretReadyGlow and data.readyGlowResourceBlocked ~= true
			if useSecretReadyGlow then
				if data.readyAt or (readyGlowPrimed and readyGlowPrimed[data.entryId]) then
					CooldownPanels.ClearReadyGlowEntryState(panelId, data.entryId, true)
					data.readyAt = nil
				end
			elseif data.canTriggerReadyGlow then
				readyGlowCooldownRunning = durationActive or usingCooldown or (cooldownEnabledOk and isCooldownActive(cooldownStart, cooldownDuration))
				if readyGlowCooldownRunning then
					CooldownPanels.ClearReadyGlowEntryState(panelId, data.entryId, true)
					data.readyAt = nil
				end
			end
			if readyGlowCooldownRunning == nil then readyGlowCooldownRunning = durationActive or usingCooldown or (cooldownEnabledOk and isCooldownActive(cooldownStart, cooldownDuration)) end
			cdp.ENTRY.ApplyIconBorderCooldownVisibility(icon, data.entry, readyGlowCooldownRunning == true, data.powerInsufficient == true)
			if not useSecretReadyGlow and data.glowReady and data.showCooldown and data.canTriggerReadyGlow then
				if data.readyAt then
					if readyGlowPrimed then readyGlowPrimed[data.entryId] = true end
				elseif not readyGlowCooldownRunning and not data.cooldownGCD and readyGlowPrimed and not readyGlowPrimed[data.entryId] then
					triggerReadyGlow(panelId, data.entryId, data.glowDuration)
					readyGlowPrimed[data.entryId] = true
					data.readyAt = runtime.readyAt[data.entryId]
				end
			end

			local overlayGlow = data.overlayGlow == true
			local overlayGlowColor = overlayGlow and data.overlayGlowColor or nil
			local simpleGlowEnabled = overlayGlow
			local simpleGlowColor = overlayGlowColor
			local simpleGlowStyle = data.overlayGlowStyle or data.readyGlowStyle
			local simpleGlowInset = data.overlayGlowInset or data.readyGlowInset
			if data.glowReady and not useSecretReadyGlow then
				local ready = data.readyAt ~= nil
				if ready and data.readyGlowCheckPower == true and data.readyGlowResourceBlocked == true then ready = false end

				simpleGlowEnabled = overlayGlow or ready
				simpleGlowColor = ready and data.readyGlowColor or overlayGlowColor
				simpleGlowStyle = ready and data.readyGlowStyle or (data.overlayGlowStyle or data.readyGlowStyle)
				simpleGlowInset = ready and data.readyGlowInset or (data.overlayGlowInset or data.readyGlowInset)
			end
			if data.activationOverlayActive == true and data.activationOverlayGlow == true then
				simpleGlowEnabled = true
				simpleGlowColor = data.activationOverlayGlowColor or data.readyGlowColor or overlayGlowColor
				simpleGlowStyle = data.readyGlowStyle or simpleGlowStyle
				simpleGlowInset = data.readyGlowInset or simpleGlowInset
			end
			if layoutEditActive then
				cdp.RUNTIME.ApplyLayoutEditEntryGlowPreview(icon, data)
			else
				setPreviewGlow(icon, false)
				if data.liveGlowAllowed == false then
					setGlow(icon, false, nil, "EQOL_SIMPLE")
					setGlow(icon, false, nil, "EQOL_OVERLAY")
					setGlow(icon, false, nil, "EQOL_READY")
					setGlow(icon, false, nil, "EQOL_INTERRUPT")
				elseif useSecretReadyGlow then
					setGlow(icon, false, nil, "EQOL_SIMPLE")
					if secretReadyGlowAllowed then
						setGlow(
							icon,
							overlayGlow,
							overlayGlowColor,
							"EQOL_OVERLAY",
							data.spellReadyCondition,
							0,
							1,
							data.overlayGlowStyle or data.readyGlowStyle,
							data.overlayGlowInset or data.readyGlowInset,
							data.glowPixelOptions
						)
						setGlow(icon, true, data.readyGlowColor, "EQOL_READY", data.spellReadyCondition, 1, 0, data.readyGlowStyle, data.readyGlowInset, data.glowPixelOptions)
					else
						setGlow(
							icon,
							overlayGlow,
							overlayGlowColor,
							"EQOL_OVERLAY",
							nil,
							nil,
							nil,
							data.overlayGlowStyle or data.readyGlowStyle,
							data.overlayGlowInset or data.readyGlowInset,
							data.glowPixelOptions
						)
						setGlow(icon, false, nil, "EQOL_READY")
					end
					setGlow(icon, data.interruptGlow == true, data.readyGlowColor, "EQOL_INTERRUPT", data.interruptGlowCondition, 0, 1, data.readyGlowStyle, data.readyGlowInset, data.glowPixelOptions)
				else
					setGlow(icon, false, nil, "EQOL_OVERLAY")
					setGlow(icon, false, nil, "EQOL_READY")
					setGlow(icon, simpleGlowEnabled, simpleGlowColor, "EQOL_SIMPLE", nil, nil, nil, simpleGlowStyle, simpleGlowInset, data.glowPixelOptions)
					setGlow(icon, data.interruptGlow == true, data.readyGlowColor, "EQOL_INTERRUPT", data.interruptGlowCondition, 0, 1, data.readyGlowStyle, data.readyGlowInset, data.glowPixelOptions)
				end
			end
			self:SuppressBarNativeIconPresentation(icon, data)
			if showGhostIcon then
				icon:SetAlpha(1)
				CooldownPanels:ApplyEditorGhostIcon(icon)
			end
			cdp.RUNTIME.UpdateCooldownPingReceiver(icon, not layoutEditActive)
		end
	end

	if sparseFixedRuntime and visibleSlotIndices then
		for listIndex = 1, visibleSlotCount do
			updateRuntimeIconAtIndex(visibleSlotIndices[listIndex])
		end
		if previousOccupiedSlotIndices and previousOccupiedSlots then
			for listIndex = 1, #previousOccupiedSlotIndices do
				local slotIndex = previousOccupiedSlotIndices[listIndex]
				if slotIndex and not visibleSlotsUsed[slotIndex] and previousOccupiedSlots[slotIndex] then updateRuntimeIconAtIndex(slotIndex) end
			end
		end
	else
		for i = 1, count do
			updateRuntimeIconAtIndex(i)
		end
	end

	for i = count + 1, #frame.icons do
		local icon = frame.icons[i]
		if icon then
			cdp.RUNTIME.ClearIconSnapshot(icon)
			self:ConfigureLayoutEditPanelIcon(panelId, icon, nil, nil, nil)
			icon.entryId = nil
			icon._eqolRuntimeData = nil
			cdp.RUNTIME.UpdateCooldownPingReceiver(icon, false)
			clearPreviewCooldown(icon.cooldown)
			icon.cooldown:Clear()
			icon.cooldown._eqolSoundReady = nil
			icon.cooldown._eqolSoundReadyIgnoreGCD = nil
			icon.cooldown._eqolSoundName = nil
			if icon.cooldown.SetScript then icon.cooldown:SetScript("OnCooldownDone", nil) end
			if icon.cooldown.Resume then icon.cooldown:Resume() end
			icon.count:Hide()
			icon.charges:Hide()
			if icon.rangeOverlay then icon.rangeOverlay:Hide() end
			if icon.keybind then icon.keybind:Hide() end
			if icon.staticText then icon.staticText:Hide() end
			if icon.stateTexture then icon.stateTexture:Hide() end
			if icon.stateTextureSecond then icon.stateTextureSecond:Hide() end
			CooldownPanels:HideEditorGhostIcon(icon)
			CooldownPanels.HidePreviewGlowBorder(icon)
			if icon.previewBling then icon.previewBling:Hide() end
			if icon.previewSoundBorder then icon.previewSoundBorder:Hide() end
			icon._eqolLayoutDragRangePreview = nil
			icon.texture:SetDesaturated(false)
			icon.texture:SetAlpha(1)
			setAssistedHighlight(icon, false)
			CooldownPanels.StopAllIconGlows(icon)
		end
	end

	if fixedLayout then
		local nextScratchOccupiedSlots = previousOccupiedSlots or {}
		local nextScratchOccupiedSlotIndices = previousOccupiedSlotIndices or {}
		for i = visibleSlotCount + 1, #(visibleSlotIndices or {}) do
			visibleSlotIndices[i] = nil
		end
		runtime._eqolScratchOccupiedSlots = nextScratchOccupiedSlots
		runtime._eqolScratchOccupiedSlotIndices = nextScratchOccupiedSlotIndices
		runtime._eqolOccupiedSlots = visibleSlotsUsed
		runtime._eqolOccupiedSlotIndices = visibleSlotIndices
	end
	runtime._eqolLastLayoutEditActive = layoutEditActive == true
	runtime.visibleCount = visibleCount
	runtime.initialized = true
end

function CooldownPanels:ApplyPanelPosition(panelId)
	local panel = self:GetPanel(panelId)
	if not panel then return end
	local runtime = getRuntime(panelId)
	local frame = runtime.frame
	if not frame then return end
	local anchor = ensurePanelAnchor(panel)
	local panelKey = normalizeId(panelId)
	local dynamicResult
	if panel.dynamicAnchor and panel.dynamicAnchor.enabled == true and addon.DynamicAnchors then dynamicResult = addon.DynamicAnchors:ResolveConsumer(self:GetDynamicAnchorId(panelId), { mode = "LIVE" }) end
	local dynamicWinner = dynamicResult and dynamicResult.winner
	if not dynamicWinner and panelKey then CooldownPanels.ValidateRelativeFrameChoice(panel, panelKey, runtime) end
	local placement = dynamicWinner and dynamicWinner.placement or anchor
	local point = Helper.NormalizeAnchor(placement and placement.point, panel.point or "CENTER")
	local relativePoint = Helper.NormalizeAnchor(placement and placement.relativePoint, point)
	local x = tonumber(placement and placement.x) or 0
	local y = tonumber(placement and placement.y) or 0
	local relativeFrame = dynamicWinner and dynamicWinner.frame or resolveAnchorFrame(anchor)
	if relativeFrame == frame then
		if not dynamicWinner then
			anchor.relativeFrame = "UIParent"
			CooldownPanels.MarkRelativeFrameEntriesDirty()
		end
		relativeFrame = UIParent
	end
	if dynamicWinner and InCombatLockdown and InCombatLockdown() and frame.IsProtected and frame:IsProtected() then
		runtime._eqolDynamicAnchorDeferred = true
		return
	end
	runtime._eqolDynamicAnchorDeferred = nil
	if
		runtime._eqolAnchorAppliedFrame == frame
		and runtime._eqolAnchorPoint == point
		and runtime._eqolAnchorRelativePoint == relativePoint
		and runtime._eqolAnchorRelativeFrame == relativeFrame
		and runtime._eqolAnchorX == x
		and runtime._eqolAnchorY == y
	then
		local _, hostOutcome = cdp.PIXEL.AlignHostToPixelGrid(frame)
		if hostOutcome ~= "noOp" then cdp.PIXEL.AlignPanelContent(frame) end
		return
	end
	runtime._eqolAnchorAppliedFrame = frame
	runtime._eqolAnchorPoint = point
	runtime._eqolAnchorRelativePoint = relativePoint
	runtime._eqolAnchorRelativeFrame = relativeFrame
	runtime._eqolAnchorX = x
	runtime._eqolAnchorY = y
	frame:ClearAllPoints()
	cdp.PIXEL.SetPoint(frame, point, relativeFrame, relativePoint, x, y)
	cdp.PIXEL.AlignHostToPixelGrid(frame)
	cdp.PIXEL.AlignPanelContent(frame)

	local mythicPlus = addon and addon.MythicPlus
	local reapplyTrackerAnchorsForTarget = mythicPlus and mythicPlus.functions and mythicPlus.functions.ReapplyTrackerAnchorsForTarget
	if reapplyTrackerAnchorsForTarget and frame.GetName then reapplyTrackerAnchorsForTarget(frame:GetName()) end
end

function CooldownPanels:HandlePositionChanged(panelId, data)
	local panel = self:GetPanel(panelId)
	if not panel or type(data) ~= "table" then return end
	local runtime = getRuntime(panelId)
	local anchor = ensurePanelAnchor(panel)
	if not anchor or not anchorUsesUIParent(anchor) then return end
	anchor.point = data.point or anchor.point or "CENTER"
	anchor.relativePoint = data.relativePoint or anchor.relativePoint or anchor.point
	if data.x ~= nil then anchor.x = data.x end
	if data.y ~= nil then anchor.y = data.y end
	panel.point = anchor.point or panel.point or "CENTER"
	panel.x = anchor.x or panel.x or 0
	panel.y = anchor.y or panel.y or 0
end

local function playerHasVehicleUI()
	if UnitHasVehicleUI then return UnitHasVehicleUI("player") == true end
	if UnitInVehicle then return UnitInVehicle("player") == true end
	return false
end

function CooldownPanels:BuildVisibilityDriverSignature(layout)
	local source = layout and layout.visibility
	local signature = 0
	local weight = 1
	if layout and layout.hideInPetBattle == true then signature = signature + weight end
	weight = weight * 2
	if layout and layout.hideInVehicle == true then signature = signature + weight end
	weight = weight * 2
	if addon.variables and addon.variables.unitClass == "DRUID" then signature = signature + weight end
	weight = weight * 2
	if addon.functions and addon.functions.GetDruidTravelStanceIndexes then signature = signature + weight end
	weight = weight * 2
	if addon.functions and addon.functions.BuildUnitFrameDriverExpression then signature = signature + weight end
	weight = weight * 2
	if addon.functions and addon.functions.VisibilityConfigUsesManualEvaluation then signature = signature + weight end
	weight = weight * 2
	if type(source) == "table" then
		signature = signature + weight
		weight = weight * 2
		if source.MOUSEOVER then signature = signature + weight end
		weight = weight * 2
		if source.ALWAYS_IN_COMBAT then signature = signature + weight end
		weight = weight * 2
		if source.ALWAYS_OUT_OF_COMBAT then signature = signature + weight end
		weight = weight * 2
		if source.PLAYER_CASTING then signature = signature + weight end
		weight = weight * 2
		if source.PLAYER_MOUNTED then signature = signature + weight end
		weight = weight * 2
		if source.PLAYER_NOT_MOUNTED then signature = signature + weight end
		weight = weight * 2
		if source.PLAYER_HAS_TARGET then signature = signature + weight end
		weight = weight * 2
		if source.PLAYER_IN_GROUP then signature = signature + weight end
		weight = weight * 2
		if source.SHOW_IN_INSTANCE then signature = signature + weight end
		weight = weight * 2
		if source.SKYRIDING_ACTIVE then signature = signature + weight end
		weight = weight * 2
		if source.SKYRIDING_INACTIVE then signature = signature + weight end
		weight = weight * 2
		if source.FLYING_ACTIVE then signature = signature + weight end
		weight = weight * 2
		if source.FLYING_INACTIVE then signature = signature + weight end
		weight = weight * 2
		if source.ALWAYS_HIDDEN then signature = signature + weight end
		return signature, nil
	else
		return signature, source
	end
end

local function isPetBattleActive() return C_PetBattles and C_PetBattles.IsInBattle and C_PetBattles.IsInBattle() == true end
local function isClientSceneActive()
	local runtime = CooldownPanels.runtime
	return runtime and runtime.clientSceneActive == true
end

function CooldownPanels:EnsureVisibilityDriverWatcher()
	self.runtime = self.runtime or {}
	if self.runtime.visibilityDriverWatcher then return end
	local watcher = CreateFrame("Frame")
	watcher:RegisterEvent("PLAYER_REGEN_ENABLED")
	watcher:SetScript("OnEvent", function()
		local runtime = CooldownPanels.runtime
		local pending = runtime and runtime.pendingVisibilityDriverUpdates
		if not pending then return end
		runtime.pendingVisibilityDriverUpdates = nil
		for frame, expr in pairs(pending) do
			if frame then
				local desired = expr
				if desired == false then desired = nil end
				CooldownPanels:ApplyVisibilityDriverToFrame(frame, desired)
				local panelId = frame.panelId
				if panelId and CooldownPanels.GetPanel and CooldownPanels:GetPanel(panelId) then CooldownPanels:UpdateVisibility(panelId) end
			end
		end
	end)
	self.runtime.visibilityDriverWatcher = watcher
end

function CooldownPanels:ApplyVisibilityDriverToFrame(frame, expression)
	self.runtime = self.runtime or {}
	if not frame then return false end
	if InCombatLockdown and InCombatLockdown() then
		self.runtime.pendingVisibilityDriverUpdates = self.runtime.pendingVisibilityDriverUpdates or {}
		self.runtime.pendingVisibilityDriverUpdates[frame] = expression == nil and false or expression
		self:EnsureVisibilityDriverWatcher()
		return false
	end
	if not expression then
		if frame._eqolVisibilityDriver then
			if UnregisterStateDriver then pcall(UnregisterStateDriver, frame, "visibility") end
			frame._eqolVisibilityDriver = nil
		end
		return true
	end
	if frame._eqolVisibilityDriver == expression then return true end
	if RegisterStateDriver then
		if frame._eqolVisibilityDriver and UnregisterStateDriver then
			pcall(UnregisterStateDriver, frame, "visibility")
			frame._eqolVisibilityDriver = nil
		end
		local ok = pcall(RegisterStateDriver, frame, "visibility", expression)
		if ok then
			frame._eqolVisibilityDriver = expression
			return true
		end
	end
	return false
end

function CooldownPanels:BuildVisibilityDriver(panel, panelId)
	if not panel then return nil, false, nil end
	panel.layout = panel.layout or Helper.CopyTableShallow(Helper.PANEL_LAYOUT_DEFAULTS)
	local layout = panel.layout
	local signature, signatureSource = self:BuildVisibilityDriverSignature(layout)
	panelId = panelId or panel.id
	local runtime = panelId and getRuntime(panelId) or nil
	local cache = runtime and runtime.visibilityDriverCache
	if cache and cache.signature == signature and cache.signatureSource == signatureSource then return cache.expression, cache.usesManualVisibility, cache.visibilityCfg end

	local visibilityCfg = PanelVisibility.NormalizeConfig(layout.visibility)
	local hideInPetBattle = layout.hideInPetBattle == true
	local hideInVehicle = layout.hideInVehicle == true
	local expression
	local usesManual = false
	if visibilityCfg and visibilityCfg.ALWAYS_HIDDEN then
		expression = "hide"
		if runtime then runtime.visibilityDriverCache = { signature = signature, signatureSource = signatureSource, expression = expression, usesManualVisibility = false, visibilityCfg = visibilityCfg } end
		return expression, false, visibilityCfg
	end
	local usesManualVisibility = addon.functions and addon.functions.VisibilityConfigUsesManualEvaluation
	if usesManualVisibility and usesManualVisibility(visibilityCfg, { allowMouseover = false }) then
		usesManual = true
		if runtime then runtime.visibilityDriverCache = { signature = signature, signatureSource = signatureSource, expression = nil, usesManualVisibility = true, visibilityCfg = visibilityCfg } end
		return nil, true, visibilityCfg
	end
	if not visibilityCfg and not hideInPetBattle and not hideInVehicle then
		if runtime then runtime.visibilityDriverCache = { signature = signature, signatureSource = signatureSource, expression = nil, usesManualVisibility = false, visibilityCfg = nil } end
		return nil, false, nil
	end

	local prependHideClauses = {}
	if hideInPetBattle then prependHideClauses[#prependHideClauses + 1] = "petbattle" end
	if hideInVehicle then prependHideClauses[#prependHideClauses + 1] = "vehicleui" end

	local buildDriverExpression = addon.functions and addon.functions.BuildUnitFrameDriverExpression
	if visibilityCfg and next(visibilityCfg) and buildDriverExpression then expression = buildDriverExpression(visibilityCfg, { prependHideClauses = prependHideClauses }) end
	if not expression and #prependHideClauses > 0 then
		local clauses = {}
		for i = 1, #prependHideClauses do
			clauses[#clauses + 1] = ("[%s] hide"):format(prependHideClauses[i])
		end
		clauses[#clauses + 1] = "show"
		expression = table.concat(clauses, "; ")
	end
	if runtime then runtime.visibilityDriverCache = { signature = signature, signatureSource = signatureSource, expression = expression, usesManualVisibility = usesManual, visibilityCfg = visibilityCfg } end
	return expression, usesManual, visibilityCfg
end

function CooldownPanels:ShouldShowPanel(panelId)
	local panel = self:GetPanel(panelId)
	if not panel then return false end
	if self:IsPanelLayoutEditActive(panelId) then return true end
	if panel.enabled == false then return false end
	if not panelAllowsSpec(panel) then return false end
	panel.layout = panel.layout or Helper.CopyTableShallow(Helper.PANEL_LAYOUT_DEFAULTS)
	if panel.layout.hideInPetBattle == true and isPetBattleActive() then return false end
	if panel.layout.hideInVehicle == true and playerHasVehicleUI() then return false end
	local hideInClientScene = panel.layout.hideInClientScene
	if hideInClientScene == nil then hideInClientScene = Helper.PANEL_LAYOUT_DEFAULTS.hideInClientScene == true end
	if hideInClientScene and isClientSceneActive() then return false end
	if not PanelVisibility.ShouldShow(panel.layout.visibility) then return false end
	local runtime = getRuntime(panelId)
	return runtime.visibleCount and runtime.visibleCount > 0
end

function CooldownPanels:UpdatePanelOpacity(panelId, forcedAlpha)
	local panel = self:GetPanel(panelId)
	if not panel then return end
	local runtime = getRuntime(panelId)
	local frame = runtime.frame
	if not frame then return end
	panel.layout = panel.layout or Helper.CopyTableShallow(Helper.PANEL_LAYOUT_DEFAULTS)
	local layout = panel.layout
	local fallbackOut = Helper.PANEL_LAYOUT_DEFAULTS.opacityOutOfCombat
	local fallbackIn = Helper.PANEL_LAYOUT_DEFAULTS.opacityInCombat
	local outAlpha = Helper.NormalizeOpacity(layout.opacityOutOfCombat, fallbackOut)
	local inAlpha = Helper.NormalizeOpacity(layout.opacityInCombat, fallbackIn)
	local alpha
	if forcedAlpha ~= nil then
		alpha = forcedAlpha
	elseif self:IsPanelLayoutEditActive(panelId) then
		alpha = 1
	else
		local inCombat = (InCombatLockdown and InCombatLockdown()) or (UnitAffectingCombat and UnitAffectingCombat("player")) or false
		alpha = inCombat and inAlpha or outAlpha
	end
	if alpha == nil then alpha = 1 end
	if frame._eqolAlpha ~= alpha then
		frame._eqolAlpha = alpha
		frame:SetAlpha(alpha)
	end
end

function CooldownPanels:UpdateVisibility(panelId)
	local panel = self:GetPanel(panelId)
	local runtime = getRuntime(panelId)
	local frame = runtime.frame
	if not frame or not panel then return end
	panel.layout = panel.layout or Helper.CopyTableShallow(Helper.PANEL_LAYOUT_DEFAULTS)
	local layout = panel.layout
	local layoutEditActive = self:IsPanelLayoutEditActive(panelId)
	local visibleCount = runtime.visibleCount or 0
	local contentVisible = layoutEditActive or visibleCount > 0
	local hideInClientScene = layout.hideInClientScene
	if hideInClientScene == nil then hideInClientScene = Helper.PANEL_LAYOUT_DEFAULTS.hideInClientScene == true end
	local clientSceneHidden = not layoutEditActive and hideInClientScene and isClientSceneActive()
	local canUseDriver = not layoutEditActive and panel.enabled ~= false and panelAllowsSpec(panel) and contentVisible and not clientSceneHidden
	local shouldShow = self:ShouldShowPanel(panelId)
	local driverExpression
	local usesManualVisibility = false
	if canUseDriver then
		driverExpression, usesManualVisibility = self:BuildVisibilityDriver(panel, panelId)
	end
	if canUseDriver and driverExpression and not usesManualVisibility then
		if self:ApplyVisibilityDriverToFrame(frame, driverExpression) then
			self:UpdatePanelOpacity(panelId, nil)
			self:UpdatePanelMouseState(panelId)
			self:NotifyDynamicAnchorTargetStateChanged(panelId, shouldShow)
			return
		end
	end
	self:ApplyVisibilityDriverToFrame(frame, nil)
	local forceAlphaHidden = false
	local pendingVisibilityUpdates = self.runtime and self.runtime.pendingVisibilityDriverUpdates
	local driverDetachPending = pendingVisibilityUpdates and pendingVisibilityUpdates[frame] == false
	local driverStillControlsVisibility = frame._eqolVisibilityDriver ~= nil or driverDetachPending
	if frame:IsShown() ~= shouldShow then
		local inCombat = (InCombatLockdown and InCombatLockdown()) or false
		local isProtected = frame.IsProtected and frame:IsProtected()
		if not shouldShow and inCombat and driverStillControlsVisibility then
			forceAlphaHidden = true
		elseif not (inCombat and isProtected) then
			frame:SetShown(shouldShow)
		elseif not shouldShow then
			-- Protected frames cannot be shown/hidden in combat; use alpha fallback.
			forceAlphaHidden = true
		end
	elseif not shouldShow then
		local inCombat = (InCombatLockdown and InCombatLockdown()) or false
		local isProtected = frame.IsProtected and frame:IsProtected()
		if inCombat and (isProtected or driverStillControlsVisibility) then forceAlphaHidden = true end
	end
	self:UpdatePanelOpacity(panelId, forceAlphaHidden and 0 or nil)
	self:UpdatePanelMouseState(panelId)
	self:NotifyDynamicAnchorTargetStateChanged(panelId, shouldShow)
end

function CooldownPanels:UpdatePanelMouseState(panelId)
	local runtime = getRuntime(panelId)
	local frame = runtime.frame
	if not frame then return end
	local layoutEditActive = self:IsPanelLayoutEditActive(panelId)
	if frame._mouseEnabled ~= false then
		frame._mouseEnabled = false
		frame:EnableMouse(false)
	end
	if frame.Selection and frame.Selection.EnableMouse then
		local enableSelection = false
		if frame._eqolSelectionMouseEnabled ~= enableSelection then
			frame._eqolSelectionMouseEnabled = enableSelection
			frame.Selection:EnableMouse(enableSelection)
		end
	end
	if frame.editDropZone then
		local showDropZone = layoutEditActive
		frame.editDropZone:SetShown(showDropZone)
		if frame._eqolDropZoneMouseEnabled ~= showDropZone then
			frame._eqolDropZoneMouseEnabled = showDropZone
			frame.editDropZone:EnableMouse(showDropZone)
		end
	end
	local showMoveHandle = false
	local showPanelHandle = layoutEditActive and self:IsLayoutPanelStandaloneMenuAvailable(panelId)
	local handleLayoutKey
	if showMoveHandle then
		handleLayoutKey = "MOVE"
	elseif showPanelHandle then
		handleLayoutKey = "PANEL"
	else
		handleLayoutKey = "NONE"
	end
	if frame._eqolPanelHandleLayout ~= handleLayoutKey then
		frame._eqolPanelHandleLayout = handleLayoutKey
		if frame.editMoveHandle then
			frame.editMoveHandle:ClearAllPoints()
			frame.editMoveHandle:SetPoint("BOTTOM", frame, "TOP", 0, 4)
		end
		if frame.editPanelHandle then
			frame.editPanelHandle:ClearAllPoints()
			frame.editPanelHandle:SetPoint("BOTTOM", frame, "TOP", 0, 4)
		end
	end
	if frame.editMoveHandle then
		frame.editMoveHandle:SetShown(showMoveHandle == true)
		if frame._eqolMoveHandleMouseEnabled ~= showMoveHandle then
			frame._eqolMoveHandleMouseEnabled = showMoveHandle
			frame.editMoveHandle:EnableMouse(showMoveHandle == true)
		end
	end
	if frame.editPanelHandle then
		frame.editPanelHandle:SetShown(showPanelHandle == true)
		if frame._eqolPanelHandleMouseEnabled ~= showPanelHandle then
			frame._eqolPanelHandleMouseEnabled = showPanelHandle
			frame.editPanelHandle:EnableMouse(showPanelHandle == true)
		end
	end
end

function CooldownPanels:ShowLayoutEditHint(panelId, show)
	local runtime = getRuntime(panelId)
	local frame = runtime.frame
	if not frame then return end
	if show then
		if frame.bg then frame.bg:Show() end
		if frame.label then frame.label:Show() end
	else
		if frame.bg then frame.bg:Hide() end
		if frame.label then frame.label:Hide() end
	end
end

function CooldownPanels:PrepareStaticCDMAuraRuntimeEntry(panelId, entryId, entry, runtime, frame)
	local function fail()
		return false
	end
	local function done()
		return true
	end

	if not (panelId and entryId and entry and runtime and frame) then return fail("missingContext") end
	if entry.type ~= "CDM_AURA" then return fail("notCDMAura") end
	if self:IsPanelLayoutEditActive(panelId) then return fail("layoutEdit") end
	if runtime.initialized ~= true then return fail("notInitialized") end
	local panel = self:GetPanel(panelId)
	if not (panel and type(panel.layout) == "table" and Helper.IsFixedLayout and Helper.IsFixedLayout(panel.layout)) then return fail("notFixedLayout") end
	local fixedLayoutCache = Helper.GetFixedLayoutCache and Helper.GetFixedLayoutCache(panel) or nil
	local targetIndex = fixedLayoutCache and fixedLayoutCache.staticTargetIndexByEntryId and fixedLayoutCache.staticTargetIndexByEntryId[entryId] or nil
	local fixedSlotCount = fixedLayoutCache and fixedLayoutCache.slotCount or 0
	local fixedGridColumns = fixedLayoutCache and fixedLayoutCache.boundsColumns or 0
	if not (targetIndex and targetIndex > 0 and fixedSlotCount > 0 and fixedGridColumns > 0 and targetIndex <= fixedSlotCount) then return fail("notStaticSlot") end
	if fixedLayoutCache.slotEntryIds and fixedLayoutCache.slotEntryIds[targetIndex] ~= entryId then return fail("slotMismatch") end
	if not (frame.icons and frame.icons[targetIndex]) then return fail("missingSlotIcon") end
	local visible = runtime.visibleEntries
	if not visible then
		visible = {}
		runtime.visibleEntries = visible
	end
	local existingData = visible[targetIndex]
	if existingData and existingData.entryId ~= entryId then return fail("slotOccupied") end

	local layout = panel.layout
	local fixedGroupById = fixedLayoutCache.groupById
	local entryLayout = layout
	local groupId = entry.fixedGroupId
	local fixedGroup = groupId and fixedGroupById and fixedGroupById[groupId] or nil
	if fixedGroup and Helper.FixedGroupUsesStaticSlots and Helper.FixedGroupUsesStaticSlots(fixedGroup) ~= true then return fail("dynamicGroup") end
	if fixedGroup and fixedGroup.layoutOverrides then entryLayout = self:GetFixedGroupEffectiveLayout(panelId, fixedGroup, {}, panel, layout, fixedLayoutCache) or layout end

	local cdmAuras = CooldownPanels.CDMAuras
	if not (cdmAuras and cdmAuras.BuildRuntimeData) then return fail("missingBuilder") end
	local cdmAuraAlwaysShowMode = self:ResolveEntryCDMAuraAlwaysShowMode(entryLayout, entry)
	local cdmAuraData = cdmAuras:BuildRuntimeData(panelId, entryId, entry, entryLayout, cdmAuraAlwaysShowMode)
	if not cdmAuraData then return fail("missingAuraData") end
	if cdmAuraData.show ~= true then return done("hidden") end

	local icon = frame.icons[targetIndex]
	local slotColumn = ((targetIndex - 1) % fixedGridColumns) + 1
	local slotRow = math.floor((targetIndex - 1) / fixedGridColumns) + 1
	local showCooldown = entry.showCooldown ~= false
	local showCooldownText = self:ShouldShowEntryCooldownText(entryLayout, entry)
	local showStacks = shouldShowEntryStacks(entryLayout, entry, "CDM_AURA")
	local showEntryIconTexture = self:ResolveEntryShowIconTexture(entryLayout, entry)
	local entryNoDesaturation = self:ResolveEntryNoDesaturation(entryLayout, entry)
	local _, entryDrawEdge, entryDrawBling, entryDrawSwipe, entryGcdDrawEdge, entryGcdDrawBling, entryGcdDrawSwipe = self:ResolveEntryCooldownVisuals(entryLayout, entry)
	local glowDuration, glowColor, glowStyle, glowInset = self:ResolveEntryGlowStyle(entryLayout, entry)
	local pandemicGlowColor, pandemicGlowStyle, pandemicGlowInset = self:ResolveEntryPandemicGlowVisual(entryLayout, entry)
	local otherAuraGlowColor = self.ResolveCachedEntryColor and self.ResolveCachedEntryColor("otherAuraGlowEntry", entry, entry.glowOtherAuraColor, glowColor) or glowColor
	local activeGlowConfigured
	if CooldownPanels.AuraContainers then
		activeGlowConfigured = self:ResolveEntryGlowReady(entryLayout, entry) == true
	else
		activeGlowConfigured = entry.glowReady == true
	end
	local stateTextureType, stateTextureValue, stateTextureWidth, stateTextureHeight, stateTextureScale, stateTextureAngle, stateTextureDouble, stateTextureMirror, stateTextureMirrorSecond, stateTextureMirrorVertical, stateTextureMirrorVerticalSecond, stateTextureSpacingX, stateTextureSpacingY =
		self:ResolveEntryStateTexture(entry)
	local data = existingData or {}
	visible[targetIndex] = data
	data.icon = cdmAuraData.iconTextureID or getEntryIcon(entry) or Helper.PREVIEW_ICON
	data.showCooldown = showCooldown
	data.showCooldownText = showCooldownText
	data.showIconTexture = showEntryIconTexture
	data.showGhostIcon = false
	data.showCharges = false
	data.showChargesCooldown = false
	data.hideChargeCooldownText = false
	data.showStacks = showStacks
	data.showItemCount = false
	data.showItemUses = false
	data.chargesHideWhenZero = entryLayout.chargesHideWhenZero == true
	data.showKeybinds = entryLayout.keybindsEnabled == true
	data.keybindText = data.showKeybinds and Keybinds.GetEntryKeybindText(entry, entryLayout) or nil
	data.layout = entryLayout
	data.liveGlowAllowed = entryLayout.hideGlowOutOfCombat ~= true or ((InCombatLockdown and InCombatLockdown()) or (UnitAffectingCombat and UnitAffectingCombat("player"))) == true
	data.entry = entry
	data.entryId = entryId
	data.nativeAuraTooltipOwner = cdmAuraData.nativeAuraTooltipOwner == true
	data.fixedContext = nil
	data.hideOnCooldown = false
	data.showOnCooldown = false
	data.resolvedType = "CDM_AURA"
	data.spellId = nil
	data.baseSpellId = nil
	data.effectiveSpellId = nil
	data.resolvedSpellId = nil
	data.variantGroupKind = nil
	data.variantGroupKey = nil
	data.overlayGlow = false
	data.overlayGlowColor = nil
	data.overlayGlowStyle = glowStyle
	data.overlayGlowInset = glowInset
	data.stateTextureShown = stateTextureType and true or false
	data.stateTextureType = stateTextureType
	data.stateTextureValue = stateTextureValue
	data.stateTextureWidth = stateTextureWidth
	data.stateTextureHeight = stateTextureHeight
	data.stateTextureScale = stateTextureScale
	data.stateTextureAngle = stateTextureAngle
	data.stateTextureDouble = stateTextureDouble
	data.stateTextureMirror = stateTextureMirror
	data.stateTextureMirrorSecond = stateTextureMirrorSecond
	data.stateTextureMirrorVertical = stateTextureMirrorVertical
	data.stateTextureMirrorVerticalSecond = stateTextureMirrorVerticalSecond
	data.stateTextureSpacingX = stateTextureSpacingX
	data.stateTextureSpacingY = stateTextureSpacingY
	if entry.pandemicGlow == true and cdmAuraData.pandemicActive == true then
		data.overlayGlow = true
		data.overlayGlowColor = pandemicGlowColor
		data.overlayGlowStyle = pandemicGlowStyle
		data.overlayGlowInset = pandemicGlowInset
	elseif entry.glowOtherAura ~= nil and self:IsCDMAuraGlowOtherAuraActive(panelId, entryId, entry, entryLayout) then
		data.overlayGlow = true
		data.overlayGlowColor = otherAuraGlowColor
	elseif activeGlowConfigured and cdmAuraData.active == true then
		data.overlayGlow = true
		data.overlayGlowColor = glowColor
	end
	data.powerInsufficient = false
	data.spellUnusable = false
	data.rangeOverlay = false
	data.assistedSuggested = false
	data.noDesaturation = entryNoDesaturation
	data.cooldownDrawEdge = entryDrawEdge
	data.cooldownDrawBling = entryDrawBling
	data.cooldownDrawSwipe = entryDrawSwipe
	data.cooldownSwipeColor = self:GetCustomCooldownSwipeColor(entryLayout, entry)
	data.cooldownGcdDrawEdge = entryGcdDrawEdge
	data.cooldownGcdDrawBling = entryGcdDrawBling
	data.cooldownGcdDrawSwipe = entryGcdDrawSwipe
	data.glowReady = false
	data.glowDuration = glowDuration
	data.readyGlowColor = glowColor
	data.readyGlowStyle = glowStyle
	data.readyGlowInset = glowInset
	data.glowPixelOptions = self:ResolveGlowPixelOptions(entryLayout, entry)
	data.readyGlowCheckPower = false
	data.readyGlowResourceBlocked = false
	data.interruptGlow = false
	data.interruptGlowCondition = nil
	data.spellReadyCondition = nil
	data.canTriggerReadyGlow = false
	data.soundReady = false
	data.soundName = normalizeSoundName(nil)
	data.previewSound = false
	data.readyAt = nil
	data.stanceActive = false
	data.stackCount = CooldownPanels.NormalizePositiveDisplayCount(cdmAuraData.stackCount)
	data.itemCount = nil
	data.itemUses = nil
	data.emptyItem = false
	data.chargesInfo = nil
	data.chargeDurationObject = nil
	data.cooldownDurationObject = cdmAuraData.cooldownDurationObject
	data.customCooldownDurationActive = false
	data.customCooldownDurationKey = nil
	data.customCooldownDurationObject = nil
	data.customCooldownStart = nil
	data.customCooldownDuration = nil
	data.spellAuraOverlayActive = false
	data.spellAuraOverlayDurationObject = nil
	data.spellAuraOverlayLabel = nil
	data.cooldownIgnoreGCD = false
	data.cooldownStart = cdmAuraData.cooldownStart or 0
	data.cooldownDuration = cdmAuraData.cooldownDuration or 0
	data.cooldownEnabled = cdmAuraData.cooldownEnabled
	data.cooldownIsActive = false
	data.cooldownRate = cdmAuraData.cooldownRate or 1
	data.cooldownGCD = false
	data.cdmAuraLabel = cdmAuraData.buffName
	data.cdmAuraRawApplications = cdmAuraData.rawApplications
	data.cdmAuraActive = cdmAuraData.active == true
	data.cdmAuraInactiveDesaturate = cdmAuraData.inactiveDesaturate == true
		or cdmAuraAlwaysShowMode == (CooldownPanels.CDM_AURA_ALWAYS_SHOW_MODE and CooldownPanels.CDM_AURA_ALWAYS_SHOW_MODE.DESATURATE or "DESATURATE")
	data.cdmAuraActiveDesaturate = cdmAuraData.activeDesaturate == true
		or cdmAuraAlwaysShowMode == (CooldownPanels.CDM_AURA_ALWAYS_SHOW_MODE and CooldownPanels.CDM_AURA_ALWAYS_SHOW_MODE.DESATURATE_ACTIVE or "DESATURATE_ACTIVE")
		or cdmAuraAlwaysShowMode == (CooldownPanels.CDM_AURA_ALWAYS_SHOW_MODE and CooldownPanels.CDM_AURA_ALWAYS_SHOW_MODE.HIDE_DESATURATE_ACTIVE or "HIDE_DESATURATE_ACTIVE")
	data.cdmAuraDurationObject = cdmAuraData.cooldownDurationObject
	self:ApplyActivationOverlayVisualState(data, entry)

	icon._eqolRuntimeEmpty = nil
	icon:Show()
	icon.entryId = entryId
	icon._eqolRuntimeData = data
	icon._eqolPreviewCellColumn = slotColumn
	icon._eqolPreviewCellRow = slotRow
	cdp.RUNTIME.EnsureIconSnapshot(icon)
	self:ApplyEntryIconVisualLayout(icon, entryLayout, entry, panel, fixedGridColumns, slotColumn, slotRow, nil, fixedLayoutCache)
	cdp.RUNTIME.WritePlacementSnapshot(icon, icon._eqolRuntimeSnapshot, data, fixedLayoutCache, fixedGridColumns, slotColumn, slotRow, false)
	icon.texture:SetTexture(data.icon)
	icon.texture:SetShown(showEntryIconTexture ~= false)
	applyIconBorder(icon, entryLayout, showEntryIconTexture ~= false)
	icon.texture:SetAlpha(1)
	cdp.RUNTIME.WriteTextureSnapshot(icon._eqolRuntimeSnapshot, data)
	cdp.ENTRY.ApplyIconTextureAspect(icon, entryLayout, true)
	self:ApplyEntryStackTextStyle(icon, entryLayout, entry)
	self:ApplyEntryChargesTextStyle(icon, entryLayout, entry)
	self:ApplyEntryCooldownTextStyle(icon, entryLayout, entry)
	if data.showStacks and data.stackCount ~= nil then
		icon.count:SetText(data.stackCount)
		icon.count:Show()
	else
		icon.count:Hide()
	end
	applyStaticText(icon, entryLayout, entry, nil, nil, nil, false)
	CooldownPanels.ApplyIconTooltip(icon, entry, entryLayout.showTooltips == true, data.nativeAuraTooltipOwner)
	self:SuppressBarNativeIconPresentation(icon, data)
	runtime.entryToIcon = runtime.entryToIcon or {}
	runtime.entryToIcon[entryId] = icon
	runtime.visibleCount = (tonumber(runtime.visibleCount) or 0) + 1
	runtime._eqolOccupiedSlots = runtime._eqolOccupiedSlots or {}
	runtime._eqolOccupiedSlotIndices = runtime._eqolOccupiedSlotIndices or {}
	if runtime._eqolOccupiedSlots[targetIndex] ~= true then
		runtime._eqolOccupiedSlots[targetIndex] = true
		runtime._eqolOccupiedSlotIndices[#runtime._eqolOccupiedSlotIndices + 1] = targetIndex
	end
	return done("success")
end


function CooldownPanels:ClearStaticCDMAuraRuntimeEntry(panelId, entryId, entry, runtime, frame)
	local function fail()
		return false
	end
	local function done()
		return true
	end

	if not (panelId and entryId and entry and runtime and frame) then return fail() end
	if entry.type ~= "CDM_AURA" then return fail() end
	if self:IsPanelLayoutEditActive(panelId) then return fail() end
	if runtime.initialized ~= true then return fail() end
	local panel = self:GetPanel(panelId)
	if not (panel and type(panel.layout) == "table" and Helper.IsFixedLayout and Helper.IsFixedLayout(panel.layout)) then return fail() end
	local fixedLayoutCache = Helper.GetFixedLayoutCache and Helper.GetFixedLayoutCache(panel) or nil
	local targetIndex = fixedLayoutCache and fixedLayoutCache.staticTargetIndexByEntryId and fixedLayoutCache.staticTargetIndexByEntryId[entryId] or nil
	local fixedSlotCount = fixedLayoutCache and fixedLayoutCache.slotCount or 0
	if not (targetIndex and targetIndex > 0 and fixedSlotCount > 0 and targetIndex <= fixedSlotCount) then return fail() end
	if fixedLayoutCache.slotEntryIds and fixedLayoutCache.slotEntryIds[targetIndex] ~= entryId then return fail() end
	local fixedGroupById = fixedLayoutCache.groupById
	local groupId = entry.fixedGroupId
	local fixedGroup = groupId and fixedGroupById and fixedGroupById[groupId] or nil
	if fixedGroup and Helper.FixedGroupUsesStaticSlots and Helper.FixedGroupUsesStaticSlots(fixedGroup) ~= true then return fail() end

	local icon = runtime.entryToIcon and runtime.entryToIcon[entryId] or nil
	if not icon then icon = frame.icons and frame.icons[targetIndex] or nil end
	if not icon then return fail() end
	local visible = runtime.visibleEntries
	local visibleData = visible and visible[targetIndex] or nil
	if visibleData and visibleData.entryId ~= entryId then return fail() end
	if icon.entryId and icon.entryId ~= entryId then return fail() end
	if icon._eqolRuntimeData and icon._eqolRuntimeData.entryId ~= entryId then return fail() end

	if visible then visible[targetIndex] = nil end
	if runtime.entryToIcon then runtime.entryToIcon[entryId] = nil end
	local occupiedSlots = runtime._eqolOccupiedSlots
	if occupiedSlots then occupiedSlots[targetIndex] = nil end
	local occupiedSlotIndices = runtime._eqolOccupiedSlotIndices
	if occupiedSlotIndices then
		for i = #occupiedSlotIndices, 1, -1 do
			if occupiedSlotIndices[i] == targetIndex then table.remove(occupiedSlotIndices, i) end
		end
	end

	cdp.RUNTIME.ClearIconSnapshot(icon)
	icon.entryId = nil
	icon._eqolRuntimeData = nil
	self:HideEditorGhostIcon(icon)
	clearPreviewCooldown(icon.cooldown)
	icon.cooldown:Clear()
	icon.cooldown._eqolPanelId = nil
	icon.cooldown._eqolEntryId = nil
	icon.cooldown._eqolCooldownIsGCD = nil
	icon.cooldown._eqolSoundReady = nil
	icon.cooldown._eqolSoundReadyIgnoreGCD = nil
	icon.cooldown._eqolSoundName = nil
	icon.cooldown._eqolGlowReady = nil
	icon.cooldown._eqolGlowDuration = nil
	icon.cooldown._eqolSpellId = nil
	icon.cooldown._eqolBaseSpellId = nil
	icon.cooldown._eqolEffectiveSpellId = nil
	icon.cooldown._eqolCustomCooldownKey = nil
	if icon.cooldown.SetScript then icon.cooldown:SetScript("OnCooldownDone", nil) end
	if icon.cooldown.Resume then icon.cooldown:Resume() end
	icon.count:Hide()
	icon.charges:Hide()
	if icon.rangeOverlay then icon.rangeOverlay:Hide() end
	if icon.keybind then icon.keybind:Hide() end
	if icon.staticText then icon.staticText:Hide() end
	if icon.stateTexture then icon.stateTexture:Hide() end
	if icon.stateTextureSecond then icon.stateTextureSecond:Hide() end
	CooldownPanels.HidePreviewGlowBorder(icon)
	if icon.previewBling then icon.previewBling:Hide() end
	if icon.previewSoundBorder then icon.previewSoundBorder:Hide() end
	icon._eqolLayoutDragRangePreview = nil
	icon.texture:SetDesaturated(false)
	icon.texture:SetAlpha(1)
	CooldownPanels.ApplyIconTooltip(icon, nil, false)
	setAssistedHighlight(icon, false)
	CooldownPanels.StopAllIconGlows(icon)
	icon:Hide()
	icon._eqolRuntimeEmpty = true

	local visibleCount = 0
	if visible then
		for i = 1, fixedSlotCount do
			if visible[i] then visibleCount = visibleCount + 1 end
		end
	end
	runtime.visibleCount = visibleCount
	self:UpdateVisibility(panelId)
	return done()
end

function CooldownPanels:RefreshRuntimeEntry(panelId, entryId)
	local function fallback()
		return false
	end

	panelId = normalizeId(panelId)
	entryId = normalizeId(entryId)
	if not (panelId and entryId) then return fallback() end
	if self:IsPanelLayoutEditActive(panelId) then return fallback() end
	local panel = self:GetPanel(panelId)
	local entry = panel and panel.entries and panel.entries[entryId] or nil
	if not entry then return fallback() end
	if entry.type ~= "CDM_AURA" then return fallback() end
	local usesBarDisplay = entry.displayMode == "BAR"
	local runtime = getRuntime(panelId)
	local frame = runtime and runtime.frame or nil
	local icon = runtime and runtime.entryToIcon and runtime.entryToIcon[entryId] or nil
	local data = icon and icon._eqolRuntimeData or nil
	if not (frame and icon and data and data.entryId == entryId) then
		if frame and self.PrepareStaticCDMAuraRuntimeEntry and self:PrepareStaticCDMAuraRuntimeEntry(panelId, entryId, entry, runtime, frame) then
			icon = runtime.entryToIcon and runtime.entryToIcon[entryId] or nil
			data = icon and icon._eqolRuntimeData or nil
			if not data then return true end
		end
		if not (frame and icon and data and data.entryId == entryId) then return fallback() end
	end

	local cdmAuras = CooldownPanels.CDMAuras
	if not (cdmAuras and cdmAuras.BuildRuntimeData) then return fallback() end
	local cdmAuraAlwaysShowMode = CooldownPanels.AuraContainers and self:ResolveEntryCDMAuraAlwaysShowMode(data.layout, entry) or nil
	local cdmAuraData = cdmAuras:BuildRuntimeData(panelId, entryId, entry, data.layout, cdmAuraAlwaysShowMode)
	if not cdmAuraData then return fallback() end
	if cdmAuraData.show ~= true then
		if frame and self.ClearStaticCDMAuraRuntimeEntry and self:ClearStaticCDMAuraRuntimeEntry(panelId, entryId, entry, runtime, frame) then
			if usesBarDisplay and self.RequestPanelRefresh then self:RequestPanelRefresh(panelId) end
			return true
		end
		return fallback()
	end

	local hasStateTexture = entry.stateTextureType ~= nil or (type(entry.stateTextureInput) == "string" and entry.stateTextureInput ~= "")
	if entry.pandemicGlow == true then return fallback() end
	if entry.glowOtherAura ~= nil then return fallback() end
	if hasStateTexture then return fallback() end

	local activeGlowConfigured
	if CooldownPanels.AuraContainers then
		activeGlowConfigured = CooldownPanels:ResolveEntryGlowReady(data.layout, entry) == true
	else
		activeGlowConfigured = entry.glowReady == true
	end
	local glowColor, glowStyle, glowInset
	if activeGlowConfigured then
		local _
		_, glowColor, glowStyle, glowInset = CooldownPanels:ResolveEntryGlowStyle(data.layout, entry)
	end

	data.icon = cdmAuraData.iconTextureID or getEntryIcon(entry) or Helper.PREVIEW_ICON
	icon.texture:SetTexture(data.icon)
	cdp.RUNTIME.WriteTextureSnapshot(icon._eqolRuntimeSnapshot, data)
	data.stackCount = CooldownPanels.NormalizePositiveDisplayCount(cdmAuraData.stackCount)
	data.cdmAuraLabel = cdmAuraData.buffName
	data.cdmAuraRawApplications = cdmAuraData.rawApplications
	data.cdmAuraActive = cdmAuraData.active == true
	data.cdmAuraDurationObject = cdmAuraData.cooldownDurationObject
	data.cooldownStart = cdmAuraData.cooldownStart or 0
	data.cooldownDuration = cdmAuraData.cooldownDuration or 0
	data.cooldownEnabled = cdmAuraData.cooldownEnabled
	data.cooldownRate = cdmAuraData.cooldownRate or 1

	local entryNoDesaturation = data.noDesaturation == true
	local hideOnCooldown = data.hideOnCooldown == true
	local showOnCooldown = data.showOnCooldown == true
	local cdmAuraActive = data.cdmAuraActive == true
	local cdmAuraDurationObject = data.cdmAuraDurationObject
	local cdmAuraDurationActive = cdmAuraDurationObject ~= nil
	local desaturate = false
	if data.cdmAuraInactiveDesaturate == true and not cdmAuraActive and not cdmAuraDurationActive then desaturate = true end
	if data.cdmAuraActiveDesaturate == true and cdmAuraActive then desaturate = true end

	clearPreviewCooldown(icon.cooldown)
	setCooldownDrawState(icon.cooldown, data.cooldownDrawEdge ~= false, data.cooldownDrawBling ~= false, data.cooldownDrawSwipe ~= false)
	if data.showCooldown then
		if cdmAuraActive then
			icon.cooldown:Clear()
			if cdmAuraDurationActive and icon.cooldown.SetCooldownFromDurationObject then
				icon.cooldown:SetCooldownFromDurationObject(cdmAuraDurationObject)
				if icon.cooldown.SetScript then icon.cooldown:SetScript("OnCooldownDone", onCooldownDone) end
			else
				if icon.cooldown.SetScript then icon.cooldown:SetScript("OnCooldownDone", nil) end
			end
			if hideOnCooldown then
				icon:SetAlpha(0)
			elseif showOnCooldown then
				icon:SetAlpha(1)
			end
		else
			icon.cooldown:Clear()
			if icon.cooldown.SetScript then icon.cooldown:SetScript("OnCooldownDone", nil) end
			if hideOnCooldown then
				icon:SetAlpha(1)
			elseif showOnCooldown then
				icon:SetAlpha(0)
			end
		end
	else
		icon.cooldown:Clear()
		if icon.cooldown.SetScript then icon.cooldown:SetScript("OnCooldownDone", nil) end
	end
	self:ApplyRuntimeCooldownDurationTextProfile(icon, data.layout)
	self:ApplyRuntimeCooldownTextBinding(icon, data, data.showCooldown and cdmAuraActive and cdmAuraDurationObject or nil)
	CooldownPanels.SetIconDesaturatedRuntime(icon.texture, desaturate, entryNoDesaturation)

	if activeGlowConfigured then
		local playerInCombat = (InCombatLockdown and InCombatLockdown()) or (UnitAffectingCombat and UnitAffectingCombat("player")) or false
		local liveGlowAllowed = not (data.layout and data.layout.hideGlowOutOfCombat == true and playerInCombat ~= true)
		local activeGlow = cdmAuraData.active == true
		data.liveGlowAllowed = liveGlowAllowed
		data.overlayGlow = activeGlow
		data.overlayGlowColor = activeGlow and glowColor or nil
		data.overlayGlowStyle = glowStyle
		data.overlayGlowInset = glowInset
		data.readyGlowColor = glowColor
		data.readyGlowStyle = glowStyle
		data.readyGlowInset = glowInset
		data.glowReady = false
		setPreviewGlow(icon, false)
		setGlow(icon, false, nil, "EQOL_OVERLAY")
		setGlow(icon, false, nil, "EQOL_READY")
		setGlow(icon, false, nil, "EQOL_INTERRUPT")
		if liveGlowAllowed then
			setGlow(icon, activeGlow, activeGlow and glowColor or nil, "EQOL_SIMPLE", nil, nil, nil, glowStyle, glowInset, data.glowPixelOptions)
		else
			setGlow(icon, false, nil, "EQOL_SIMPLE")
		end
	end

	if data.showStacks and data.stackCount ~= nil then
		icon.count:SetText(data.stackCount)
		icon.count:Show()
	elseif data.showItemCount and data.itemCount ~= nil then
		icon.count:SetText(data.itemCount)
		icon.count:Show()
	else
		icon.count:Hide()
	end
	local staticFontPath, staticFontSize, staticFontStyle = Helper.GetCountFontDefaults(frame)
	local staticTextCooldown = entry.staticTextShowOnCooldown == true and (cdmAuraActive or cdmAuraDurationActive) or false
	if cdp.RUNTIME.HasStaticTextChange(icon._eqolRuntimeSnapshot, data, staticFontPath, staticFontSize, staticFontStyle, staticTextCooldown) then
		applyStaticText(icon, data.layout, entry, staticFontPath, staticFontSize, staticFontStyle, staticTextCooldown)
		cdp.RUNTIME.WriteStaticTextSnapshot(icon._eqolRuntimeSnapshot, data, staticFontPath, staticFontSize, staticFontStyle, staticTextCooldown)
	end
	if icon.cooldown.Resume then icon.cooldown:Resume() end
	updateCooldownDoneContext(icon.cooldown, panelId, entryId, data)
	self:SuppressBarNativeIconPresentation(icon, data)
	self:UpdateVisibility(panelId)
	if usesBarDisplay and self.RequestPanelRefresh then self:RequestPanelRefresh(panelId) end
	return true
end

function CooldownPanels:RefreshPanel(panelId, framePrepared)
	local panel = self:GetPanel(panelId)
	if not panel then return end
	local layoutEditActive = self:IsPanelLayoutEditActive(panelId)
	if panel.enabled == false and not layoutEditActive then
		local runtime = self.runtime and self.runtime[panelId]
		local frame = runtime and runtime.frame
		if runtime then runtime.visibleCount = 0 end
		if frame then
			if frame.icons then
				for i = 1, #frame.icons do
					local cooldown = frame.icons[i] and frame.icons[i].cooldown
					if cooldown then clearCooldownDoneState(cooldown) end
				end
			end
			self:ApplyVisibilityDriverToFrame(frame, nil)
			if InCombatLockdown and InCombatLockdown() then
				self:UpdatePanelOpacity(panelId, 0)
			else
				frame:Hide()
				self:UpdatePanelOpacity(panelId, nil)
			end
		end
		self:NotifyDynamicAnchorTargetStateChanged(panelId, false)
		return
	end
	local startedRuntimeQueryBatch = false
	if not self:IsRuntimeQueryBatchActive() then
		self:BeginRuntimeQueryBatch()
		startedRuntimeQueryBatch = true
	end
	if framePrepared ~= true then
		self:EnsurePanelFrame(panelId)
		self:ApplyPanelPosition(panelId)
	end
	local runtime = getRuntime(panelId)
	if layoutEditActive then
		clearRuntimeLayoutShapeCache(runtime)
		self:UpdateRuntimeIcons(panelId)
	else
		if ensureAssistedHighlightHook then ensureAssistedHighlightHook() end
		self:UpdateRuntimeIcons(panelId)
	end
	self:UpdateVisibility(panelId)
	self:ShowLayoutEditHint(panelId, layoutEditActive)
	if startedRuntimeQueryBatch then self:EndRuntimeQueryBatch() end
end

function CooldownPanels:HideAllRuntimePanels()
	local root = ensureRoot()
	if not root or not root.panels then return end
	local allRuntime = self.runtime
	if not allRuntime then return end
	for panelId in pairs(root.panels) do
		local runtime = allRuntime[panelId]
		if runtime then
			runtime.visibleCount = 0
			runtime.visiblePowerSpellCount = 0
			runtime._eqolHiddenByEligibility = true
			if runtime.visibleEntries then
				for i = 1, #runtime.visibleEntries do
					runtime.visibleEntries[i] = nil
				end
			end
			if runtime.visiblePowerSpells then
				for i = 1, #runtime.visiblePowerSpells do
					runtime.visiblePowerSpells[i] = nil
				end
			end
			if runtime.frame then self:UpdateVisibility(panelId) end
		end
	end
end

CooldownPanels.GetLoadedPanelIdsForRefresh = function(root, runtime)
	if runtime then
		local enabledPanels = runtime.enabledPanels
		if enabledPanels then
			if not next(enabledPanels) then return {} end
			local enabledPanelIds = runtime.enabledPanelIds
			if enabledPanelIds and #enabledPanelIds > 0 then return enabledPanelIds end
			local panelIds = {}
			for _, panelId in ipairs(CooldownPanels.GetCachedPanelIds(root)) do
				if enabledPanels[panelId] then panelIds[#panelIds + 1] = panelId end
			end
			return panelIds
		end
	end
	return CooldownPanels.GetCachedPanelIds(root)
end

CooldownPanels.HideDisabledPanelRuntime = function(panelId)
	local panel = CooldownPanels:GetPanel(panelId)
	if not panel then return end
	local runtime = getRuntime(panelId)
	if not runtime then return end
	runtime.visibleCount = 0
	runtime.visiblePowerSpellCount = 0
	if not runtime.frame then
		runtime._eqolHiddenByEligibility = true
		return
	end
	runtime._eqolHiddenByEligibility = nil
	CooldownPanels:UpdateRuntimeIcons(panelId)
	CooldownPanels:UpdateVisibility(panelId)
	CooldownPanels:ShowLayoutEditHint(panelId, false)
end

function CooldownPanels:RefreshAllPanels(forceAll, explicitPanelIds)
	local root = ensureRoot()
	if not root then return end
	local runtime = self.runtime
	local layoutEditActive = self:IsAnyPanelLayoutEditActive()
	local panelIds = explicitPanelIds
	if runtime and runtime.disabledPanelIds then
		for i = 1, #runtime.disabledPanelIds do
			local panelId = runtime.disabledPanelIds[i]
			if panelId and root.panels and root.panels[panelId] then
				if layoutEditActive then
					CooldownPanels.HideDisabledPanelRuntime(panelId)
				else
					self:RefreshPanel(panelId)
				end
			end
		end
		for i = 1, #runtime.disabledPanelIds do
			runtime.disabledPanelIds[i] = nil
		end
	end
	if runtime and runtime.enabledPanels and not next(runtime.enabledPanels) then
		self:HideAllRuntimePanels()
		self:UpdateCursorAnchorState()
		return
	end
	if panelIds == nil and forceAll ~= true and not layoutEditActive then
		local enabledPanels = runtime and runtime.enabledPanels
		if not enabledPanels or not next(enabledPanels) then
			self:HideAllRuntimePanels()
			self:UpdateCursorAnchorState()
			return
		end
		panelIds = runtime and runtime.enabledPanelIds or nil
	end
	syncRootOrderIfDirty(root)
	panelIds = panelIds or CooldownPanels.GetLoadedPanelIdsForRefresh(root, runtime)
	self:BeginRuntimeQueryBatch()
	for _, panelId in ipairs(panelIds) do
		self:EnsurePanelFrame(panelId)
	end
	for _, panelId in ipairs(panelIds) do
		self:ApplyPanelPosition(panelId)
	end
	for _, panelId in ipairs(panelIds) do
		self:RefreshPanel(panelId, true)
	end
	self:EndRuntimeQueryBatch()
	self:UpdateCursorAnchorState()
	local unitFrames = addon and addon.Aura and addon.Aura.UF
	if unitFrames and unitFrames.ReanchorFramesAttachedToCooldownPanels then unitFrames.ReanchorFramesAttachedToCooldownPanels(panelIds) end
	local resourceBars = addon and addon.Aura and addon.Aura.ResourceBars
	if resourceBars and resourceBars.ReanchorAll then
		resourceBars.ReanchorAll()
		if resourceBars.SyncRelativeFrameWidths then resourceBars.SyncRelativeFrameWidths() end
	end
end

function CooldownPanels:RefreshPanelForCurrentEditContext(panelId, refreshEditor)
	local runtime = getRuntime(panelId)
	if CooldownPanels:IsPanelLayoutEditActive(panelId) then
		if runtime then clearRuntimeLayoutShapeCache(runtime) end
		CooldownPanels:UpdateRuntimeIcons(panelId)
		CooldownPanels:UpdateVisibility(panelId)
	elseif CooldownPanels:IsEditorOpen() then
		if runtime then clearRuntimeLayoutShapeCache(runtime) end
		CooldownPanels:ApplyLayout(panelId)
		CooldownPanels:ApplyPanelPosition(panelId)
		CooldownPanels:UpdateVisibility(panelId)
	else
		CooldownPanels:RefreshPanel(panelId)
	end
	if refreshEditor and CooldownPanels:IsEditorOpen() then CooldownPanels:RefreshEditor() end
end

function CooldownPanels:RefreshPanelIconZoom(panelId)
	local panel = self:GetPanel(panelId)
	local layout = panel and panel.layout
	local runtime = getRuntime(panelId)
	local frame = runtime and runtime.frame
	local icons = frame and frame.icons
	if not (layout and icons) then return false end
	local iconZoom = addon.IconShape and addon.IconShape.NormalizeIconZoom and addon.IconShape.NormalizeIconZoom(layout.iconZoom) or Helper.ClampInt(layout.iconZoom, 0, 35, 0)
	for i = 1, #icons do
		local icon = icons[i]
		if icon then
			cdp.ENTRY.ApplyIconShape(icon, layout)
			icon._eqolVisualIconZoom = iconZoom
		end
	end
	return true
end

function CooldownPanels:RefreshPanelCDMAuraOverlayColor(panelId)
	local panel = self:GetPanel(panelId)
	local runtime = panel and getRuntime(panelId)
	local icons = runtime and runtime.frame and runtime.frame.icons
	if not (panel and icons) then return false end
	local refreshed = false
	for i = 1, #icons do
		local icon = icons[i]
		local data = icon and icon._eqolRuntimeData
		local entry = data and data.entry
		if
			data
			and data.spellAuraOverlayActive == true
			and data.customCooldownDurationActive ~= true
			and data.resolvedType == "SPELL"
			and entry
			and entry.cdmAuraOverlayColorUseGlobal ~= false
		then
			data.activationOverlayColor = self:ResolveEntryCDMAuraOverlayColor(panel.layout, entry)
			cdp.ENTRY.ApplyCooldownSwipeVisual(icon, data)
			if icon._eqolRuntimeSnapshot then cdp.RUNTIME.WriteCooldownWidgetConfigSnapshot(icon._eqolRuntimeSnapshot, data, true) end
			refreshed = true
		elseif
			data
			and data.activationOverlayActive == true
			and data.spellAuraOverlayActive ~= true
			and entry
			and entry.activationOverlayBehaviorUseGlobal ~= false
		then
			data.activationOverlayColor = self:ResolveEntryActivationOverlayColor(panel.layout, entry)
			cdp.ENTRY.ApplyCooldownSwipeVisual(icon, data)
			if icon._eqolRuntimeSnapshot then cdp.RUNTIME.WriteCooldownWidgetConfigSnapshot(icon._eqolRuntimeSnapshot, data, true) end
			refreshed = true
		end
	end
	return refreshed
end

function CooldownPanels:RefreshEntryActivationOverlayColor(panelId, entryId)
	local panel = self:GetPanel(panelId)
	local runtime = panel and getRuntime(panelId)
	local icon = runtime and runtime.entryToIcon and runtime.entryToIcon[entryId] or nil
	local data = icon and icon._eqolRuntimeData
	local entry = data and data.entry
	if not (icon and data and entry) then return false end
	if data.activationOverlayActive ~= true then return false end
	self:ApplyActivationOverlayVisualState(data, entry)
	cdp.ENTRY.ApplyCooldownSwipeVisual(icon, data)
	if icon._eqolRuntimeSnapshot then
		local cooldownUsesAuraDisplay = data.resolvedType == "CDM_AURA" or data.customCooldownDurationActive == true or data.spellAuraOverlayActive == true
		cdp.RUNTIME.WriteCooldownWidgetConfigSnapshot(icon._eqolRuntimeSnapshot, data, cooldownUsesAuraDisplay)
	end
	return true
end

applyEditLayout = function(panelId, field, value, skipRefresh)
	local panel = CooldownPanels:GetPanel(panelId)
	if not panel then return end
	panel.layout = panel.layout or {}
	local layout = panel.layout
	local rowSizeIndex = field and field:match("^rowSize(%d+)$")

	if field == "iconSize" then
		layout.iconSize = Helper.ClampInt(value, 12, 128, layout.iconSize)
	elseif field == "iconSizeSeparate" then
		layout.iconSizeSeparate = value == true
		if layout.iconSizeSeparate then
			layout.iconWidth = Helper.ClampInt(layout.iconWidth, 12, 128, layout.iconSize or Helper.PANEL_LAYOUT_DEFAULTS.iconSize)
			layout.iconHeight = Helper.ClampInt(layout.iconHeight, 12, 128, layout.iconSize or Helper.PANEL_LAYOUT_DEFAULTS.iconSize)
		end
	elseif field == "iconWidth" then
		layout.iconWidth = Helper.ClampInt(value, 12, 128, layout.iconWidth or layout.iconSize or Helper.PANEL_LAYOUT_DEFAULTS.iconWidth)
	elseif field == "iconHeight" then
		layout.iconHeight = Helper.ClampInt(value, 12, 128, layout.iconHeight or layout.iconSize or Helper.PANEL_LAYOUT_DEFAULTS.iconHeight)
	elseif field == "spacing" then
		layout.spacing = Helper.ClampInt(value, 0, Helper.SPACING_RANGE or 200, layout.spacing)
	elseif field == "layoutMode" then
		layout.layoutMode = Helper.NormalizeLayoutMode(value, layout.layoutMode or Helper.PANEL_LAYOUT_DEFAULTS.layoutMode)
		Helper.InvalidateFixedLayoutCache(panel)
		if Helper.IsFixedLayout(layout) then
			local maxColumn, maxRow = Helper.EnsureFixedSlotAssignments(panel)
			if Helper.NormalizeFixedGridSize(layout.fixedGridColumns, 0) <= 0 then layout.fixedGridColumns = math.max(maxColumn or 0, 1) end
			if Helper.NormalizeFixedGridSize(layout.fixedGridRows, 0) <= 0 then layout.fixedGridRows = math.max(maxRow or 0, 1) end
		end
	elseif field == "fixedSlotCount" then
		local minimum = 0
		Helper.InvalidateFixedLayoutCache(panel)
		if Helper.IsFixedLayout(layout) then
			local maxColumn = Helper.EnsureFixedSlotAssignments(panel)
			minimum = maxColumn or 0
		end
		layout.fixedGridColumns = math.max(Helper.NormalizeFixedGridSize(value, layout.fixedGridColumns or Helper.PANEL_LAYOUT_DEFAULTS.fixedGridColumns or 0), minimum)
	elseif field == "fixedGridRows" then
		local minimum = 0
		Helper.InvalidateFixedLayoutCache(panel)
		if Helper.IsFixedLayout(layout) then
			local _, maxRow = Helper.EnsureFixedSlotAssignments(panel)
			minimum = maxRow or 0
		end
		layout.fixedGridRows = math.max(Helper.NormalizeFixedGridSize(value, layout.fixedGridRows or Helper.PANEL_LAYOUT_DEFAULTS.fixedGridRows or 0), minimum)
	elseif field == "direction" then
		layout.direction = Helper.NormalizeDirection(value, layout.direction)
	elseif field == "wrapCount" then
		layout.wrapCount = Helper.ClampInt(value, 0, 40, layout.wrapCount)
		if Helper.IsFixedLayout(layout) then Helper.InvalidateFixedLayoutCache(panel) end
	elseif field == "wrapDirection" then
		layout.wrapDirection = Helper.NormalizeDirection(value, layout.wrapDirection)
	elseif field == "growthPoint" then
		layout.growthPoint = Helper.NormalizeGrowthPoint(value, layout.growthPoint or Helper.PANEL_LAYOUT_DEFAULTS.growthPoint)
	elseif field == "radialRadius" then
		layout.radialRadius = Helper.ClampInt(value, 0, Helper.RADIAL_RADIUS_RANGE or 600, layout.radialRadius or Helper.PANEL_LAYOUT_DEFAULTS.radialRadius)
	elseif field == "radialRotation" then
		layout.radialRotation =
			Helper.ClampNumber(value, -(Helper.RADIAL_ROTATION_RANGE or 360), Helper.RADIAL_ROTATION_RANGE or 360, layout.radialRotation or Helper.PANEL_LAYOUT_DEFAULTS.radialRotation)
	elseif field == "radialArcDegrees" then
		layout.radialArcDegrees =
			Helper.ClampInt(value, Helper.RADIAL_ARC_DEGREES_MIN or 15, Helper.RADIAL_ARC_DEGREES_MAX or 360, layout.radialArcDegrees or Helper.PANEL_LAYOUT_DEFAULTS.radialArcDegrees or 360)
	elseif field == "rangeOverlayEnabled" then
		layout.rangeOverlayEnabled = value == true
		if updateRangeCheckSpells then updateRangeCheckSpells() end
	elseif field == "rangeOverlayColor" then
		layout.rangeOverlayColor = Helper.NormalizeColor(value, Helper.PANEL_LAYOUT_DEFAULTS.rangeOverlayColor)
	elseif field == "procGlowEnabled" then
		layout.procGlowEnabled = value ~= false
	elseif field == "glowReady" then
		layout.glowReady = value == true
		CooldownPanels:RebuildPowerIndex()
	elseif field == "hideGlowOutOfCombat" then
		layout.hideGlowOutOfCombat = value == true
	elseif field == "procGlowStyle" then
		layout.procGlowStyle = Helper.NormalizeGlowStyle(value, layout.procGlowStyle or layout.readyGlowStyle or Helper.PANEL_LAYOUT_DEFAULTS.readyGlowStyle)
	elseif field == "procGlowInset" then
		layout.procGlowInset = Helper.NormalizeGlowInset(value, layout.procGlowInset or layout.readyGlowInset or Helper.PANEL_LAYOUT_DEFAULTS.readyGlowInset or 0)
	elseif field == "readyGlowStyle" then
		layout.readyGlowStyle = Helper.NormalizeGlowStyle(value, layout.readyGlowStyle or Helper.PANEL_LAYOUT_DEFAULTS.readyGlowStyle)
	elseif field == "pandemicGlowStyle" then
		layout.pandemicGlowStyle = Helper.NormalizeGlowStyle(value, layout.pandemicGlowStyle or layout.readyGlowStyle or Helper.PANEL_LAYOUT_DEFAULTS.readyGlowStyle)
	elseif field == "readyGlowInset" then
		layout.readyGlowInset = Helper.NormalizeGlowInset(value, layout.readyGlowInset or Helper.PANEL_LAYOUT_DEFAULTS.readyGlowInset or 0)
	elseif field == "glowPixelBorder" then
		layout.glowPixelBorder = value == true
	elseif field == "glowPixelCount" then
		layout.glowPixelCount = Helper.NormalizeGlowPixelCount(value, layout.glowPixelCount or Helper.PANEL_LAYOUT_DEFAULTS.glowPixelCount or 8)
	elseif field == "glowPixelSpeed" then
		layout.glowPixelSpeed = Helper.NormalizeGlowPixelSpeed(value, layout.glowPixelSpeed or Helper.PANEL_LAYOUT_DEFAULTS.glowPixelSpeed or 0.25)
	elseif field == "glowPixelThickness" then
		layout.glowPixelThickness = Helper.NormalizeGlowPixelThickness(value, layout.glowPixelThickness or Helper.PANEL_LAYOUT_DEFAULTS.glowPixelThickness or 2)
	elseif field == "readyGlowColor" then
		layout.readyGlowColor = Helper.NormalizeColor(value, Helper.PANEL_LAYOUT_DEFAULTS.readyGlowColor)
	elseif field == "pandemicGlowInset" then
		layout.pandemicGlowInset = Helper.NormalizeGlowInset(value, layout.pandemicGlowInset or layout.readyGlowInset or Helper.PANEL_LAYOUT_DEFAULTS.readyGlowInset or 0)
	elseif field == "pandemicGlowColor" then
		layout.pandemicGlowColor = Helper.NormalizeColor(value, layout.readyGlowColor or Helper.PANEL_LAYOUT_DEFAULTS.pandemicGlowColor or Helper.PANEL_LAYOUT_DEFAULTS.readyGlowColor)
	elseif field == "readyGlowDuration" then
		layout.readyGlowDuration = 0
	elseif field == "readyGlowCheckPower" then
		layout.readyGlowCheckPower = value == true
		CooldownPanels:RebuildPowerIndex()
	elseif field == "noDesaturation" then
		layout.noDesaturation = value == true
	elseif field == "hideWhenNoResource" then
		layout.hideWhenNoResource = value == true
		CooldownPanels:RebuildPowerIndex()
	elseif field == "cdmAuraAlwaysShowMode" then
		layout.cdmAuraAlwaysShowMode = CooldownPanels:NormalizeCDMAuraAlwaysShowMode(value, layout.cdmAuraAlwaysShowMode or Helper.PANEL_LAYOUT_DEFAULTS.cdmAuraAlwaysShowMode)
	elseif field == "cdmAuraOverlayEnabled" then
		layout.cdmAuraOverlayEnabled = value == true
		CooldownPanels:RebuildSpellIndex()
	elseif field == "cdmAuraOverlayColor" then
		layout.cdmAuraOverlayColor = Helper.NormalizeColor(value, Helper.PANEL_LAYOUT_DEFAULTS.cdmAuraOverlayColor or Helper.ACTIVATION_OVERLAY_COLOR_DEFAULT)
	elseif field == "activationOverlayReverse" then
		layout.activationOverlayReverse = value == true
	elseif field == "activationOverlayOnly" then
		layout.activationOverlayOnly = value == true
	elseif field == "activationOverlayGlow" then
		layout.activationOverlayGlow = value == true
	elseif field == "activationOverlayGlowColor" then
		layout.activationOverlayGlowColor = Helper.NormalizeColor(value, layout.readyGlowColor or Helper.PANEL_LAYOUT_DEFAULTS.activationOverlayGlowColor)
	elseif field == "checkPower" then
		layout.checkPower = value == true
		CooldownPanels:RebuildPowerIndex()
	elseif field == "powerTintColor" then
		layout.powerTintColor = Helper.NormalizeColor(value, Helper.PANEL_LAYOUT_DEFAULTS.powerTintColor)
	elseif field == "strata" then
		layout.strata = Helper.NormalizeStrata(value, layout.strata)
	elseif field == "stackAnchor" then
		layout.stackAnchor = Helper.NormalizeAnchor(value, layout.stackAnchor or Helper.PANEL_LAYOUT_DEFAULTS.stackAnchor)
	elseif field == "stackX" then
		layout.stackX = Helper.ClampInt(value, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, layout.stackX or Helper.PANEL_LAYOUT_DEFAULTS.stackX)
	elseif field == "stackY" then
		layout.stackY = Helper.ClampInt(value, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, layout.stackY or Helper.PANEL_LAYOUT_DEFAULTS.stackY)
	elseif field == "stackFont" then
		if type(value) == "string" and value ~= "" then layout.stackFont = value end
	elseif field == "stackFontSize" then
		layout.stackFontSize = Helper.ClampInt(value, 6, 64, layout.stackFontSize or Helper.PANEL_LAYOUT_DEFAULTS.stackFontSize)
	elseif field == "stackFontStyle" then
		layout.stackFontStyle = Helper.NormalizeFontStyleChoice(value, layout.stackFontStyle or Helper.PANEL_LAYOUT_DEFAULTS.stackFontStyle)
	elseif field == "stackColor" then
		layout.stackColor = Helper.NormalizeColor(value, Helper.PANEL_LAYOUT_DEFAULTS.stackColor or { 1, 1, 1, 1 })
	elseif field == "showStacks" then
		layout.showStacks = value == true
	elseif field == "chargesAnchor" then
		layout.chargesAnchor = Helper.NormalizeAnchor(value, layout.chargesAnchor or Helper.PANEL_LAYOUT_DEFAULTS.chargesAnchor)
	elseif field == "chargesX" then
		layout.chargesX = Helper.ClampInt(value, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, layout.chargesX or Helper.PANEL_LAYOUT_DEFAULTS.chargesX)
	elseif field == "chargesY" then
		layout.chargesY = Helper.ClampInt(value, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, layout.chargesY or Helper.PANEL_LAYOUT_DEFAULTS.chargesY)
	elseif field == "chargesFont" then
		if type(value) == "string" and value ~= "" then layout.chargesFont = value end
	elseif field == "chargesFontSize" then
		layout.chargesFontSize = Helper.ClampInt(value, 6, 64, layout.chargesFontSize or Helper.PANEL_LAYOUT_DEFAULTS.chargesFontSize)
	elseif field == "chargesFontStyle" then
		layout.chargesFontStyle = Helper.NormalizeFontStyleChoice(value, layout.chargesFontStyle or Helper.PANEL_LAYOUT_DEFAULTS.chargesFontStyle)
	elseif field == "chargesColor" then
		layout.chargesColor = Helper.NormalizeColor(value, Helper.PANEL_LAYOUT_DEFAULTS.chargesColor or { 1, 1, 1, 1 })
	elseif field == "showCharges" then
		layout.showCharges = value == true
		CooldownPanels:RebuildChargesIndex()
	elseif field == "chargesHideWhenZero" then
		layout.chargesHideWhenZero = value == true
	elseif field == "keybindsEnabled" then
		layout.keybindsEnabled = value == true
		Keybinds.MarkPanelsDirty()
	elseif field == "keybindsIgnoreItems" then
		layout.keybindsIgnoreItems = value == true
	elseif field == "keybindAnchor" then
		layout.keybindAnchor = Helper.NormalizeAnchor(value, layout.keybindAnchor or Helper.PANEL_LAYOUT_DEFAULTS.keybindAnchor)
	elseif field == "keybindX" then
		layout.keybindX = Helper.ClampInt(value, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, layout.keybindX or Helper.PANEL_LAYOUT_DEFAULTS.keybindX)
	elseif field == "keybindY" then
		layout.keybindY = Helper.ClampInt(value, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, layout.keybindY or Helper.PANEL_LAYOUT_DEFAULTS.keybindY)
	elseif field == "keybindFont" then
		if type(value) == "string" and value ~= "" then layout.keybindFont = value end
	elseif field == "keybindFontSize" then
		layout.keybindFontSize = Helper.ClampInt(value, 6, 64, layout.keybindFontSize or Helper.PANEL_LAYOUT_DEFAULTS.keybindFontSize)
	elseif field == "keybindFontStyle" then
		layout.keybindFontStyle = Helper.NormalizeFontStyleChoice(value, layout.keybindFontStyle or Helper.PANEL_LAYOUT_DEFAULTS.keybindFontStyle)
	elseif field == "cooldownDrawEdge" then
		layout.cooldownDrawEdge = value ~= false
	elseif field == "cooldownDrawBling" then
		layout.cooldownDrawBling = value ~= false
	elseif field == "cooldownDrawSwipe" then
		layout.cooldownDrawSwipe = value ~= false
	elseif field == "cooldownSwipeColor" then
		layout.cooldownSwipeColor = Helper.NormalizeColor(value, Helper.PANEL_LAYOUT_DEFAULTS.cooldownSwipeColor)
	elseif field == "showChargesCooldown" then
		layout.showChargesCooldown = value == true
	elseif field == "hideChargeCooldownText" then
		layout.hideChargeCooldownText = value == true
	elseif field == "cooldownGcdDrawEdge" then
		layout.cooldownGcdDrawEdge = value == true
	elseif field == "cooldownGcdDrawBling" then
		layout.cooldownGcdDrawBling = value == true
	elseif field == "cooldownGcdDrawSwipe" then
		layout.cooldownGcdDrawSwipe = value == true
	elseif field == "showTooltips" then
		layout.showTooltips = value == true
	elseif field == "showIconTexture" then
		layout.showIconTexture = value ~= false
	elseif field == "iconShape" then
		layout.iconShape = cdp.ENTRY.NormalizeIconShape(value, Helper.PANEL_LAYOUT_DEFAULTS.iconShape)
	elseif field == "iconZoom" then
		local iconZoom = addon.IconShape and addon.IconShape.NormalizeIconZoom and addon.IconShape.NormalizeIconZoom(value) or Helper.ClampInt(value, 0, 35, layout.iconZoom or 0)
		if layout.iconZoom == iconZoom then return end
		layout.iconZoom = iconZoom
	elseif field == "iconBorderEnabled" then
		layout.iconBorderEnabled = value == true
	elseif field == "iconBorderTexture" then
		layout.iconBorderTexture = normalizeIconBorderTexture(value, layout.iconBorderTexture or Helper.PANEL_LAYOUT_DEFAULTS.iconBorderTexture, layout.iconShape)
	elseif field == "iconBorderSize" then
		layout.iconBorderSize = Helper.ClampInt(value, 1, 64, layout.iconBorderSize or Helper.PANEL_LAYOUT_DEFAULTS.iconBorderSize)
	elseif field == "iconBorderOffset" then
		layout.iconBorderOffset = Helper.ClampInt(value, -64, 64, layout.iconBorderOffset or Helper.PANEL_LAYOUT_DEFAULTS.iconBorderOffset)
	elseif field == "iconBorderColor" then
		layout.iconBorderColor = Helper.NormalizeColor(value, Helper.PANEL_LAYOUT_DEFAULTS.iconBorderColor)
	elseif field == "hideOnCooldown" then
		layout.hideOnCooldown = value == true
		if layout.hideOnCooldown then layout.showOnCooldown = false end
	elseif field == "showOnCooldown" then
		layout.showOnCooldown = value == true
		if layout.showOnCooldown then layout.hideOnCooldown = false end
	elseif field == "hideInVehicle" then
		layout.hideInVehicle = value == true
	elseif field == "hideInPetBattle" then
		layout.hideInPetBattle = value == true
	elseif field == "hideInClientScene" then
		layout.hideInClientScene = value == true
	elseif field == "visibility" then
		layout.visibility = PanelVisibility.NormalizeConfig(value)
		if CooldownPanels.UpdateEventRegistration then CooldownPanels:UpdateEventRegistration() end
	elseif field == "showCooldownText" then
		layout.showCooldownText = value ~= false
	elseif field == "cooldownTextFont" then
		if type(value) == "string" and value ~= "" then layout.cooldownTextFont = value end
	elseif field == "cooldownTextSize" then
		layout.cooldownTextSize = Helper.ClampInt(value, 6, 64, layout.cooldownTextSize or 12)
	elseif field == "cooldownTextStyle" then
		layout.cooldownTextStyle = Helper.NormalizeFontStyleChoice(value, layout.cooldownTextStyle or Helper.PANEL_LAYOUT_DEFAULTS.cooldownTextStyle)
	elseif field == "cooldownTextColor" then
		layout.cooldownTextColor = Helper.NormalizeColor(value, Helper.PANEL_LAYOUT_DEFAULTS.cooldownTextColor)
	elseif field == "cooldownTextX" then
		layout.cooldownTextX = Helper.ClampInt(value, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, layout.cooldownTextX or 0)
	elseif field == "cooldownTextY" then
		layout.cooldownTextY = Helper.ClampInt(value, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, layout.cooldownTextY or 0)
	elseif field == "staticTextFont" then
		if type(value) == "string" then layout.staticTextFont = value end
	elseif field == "staticTextSize" then
		layout.staticTextSize = Helper.ClampInt(value, 6, 64, layout.staticTextSize or Helper.PANEL_LAYOUT_DEFAULTS.staticTextSize or 12)
	elseif field == "staticTextStyle" then
		layout.staticTextStyle = Helper.NormalizeFontStyleChoice(value, layout.staticTextStyle or Helper.PANEL_LAYOUT_DEFAULTS.staticTextStyle or "OUTLINE")
	elseif field == "staticTextColor" then
		layout.staticTextColor = Helper.NormalizeColor(value, Helper.PANEL_LAYOUT_DEFAULTS.staticTextColor or { 1, 1, 1, 1 })
	elseif field == "staticTextAnchor" then
		layout.staticTextAnchor = Helper.NormalizeAnchor(value, layout.staticTextAnchor or Helper.PANEL_LAYOUT_DEFAULTS.staticTextAnchor or "CENTER")
	elseif field == "staticTextX" then
		layout.staticTextX = Helper.ClampInt(value, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, layout.staticTextX or Helper.PANEL_LAYOUT_DEFAULTS.staticTextX or 0)
	elseif field == "staticTextY" then
		layout.staticTextY = Helper.ClampInt(value, -Helper.OFFSET_RANGE, Helper.OFFSET_RANGE, layout.staticTextY or Helper.PANEL_LAYOUT_DEFAULTS.staticTextY or 0)
	elseif field == "opacityOutOfCombat" then
		layout.opacityOutOfCombat = Helper.NormalizeOpacity(value, layout.opacityOutOfCombat or Helper.PANEL_LAYOUT_DEFAULTS.opacityOutOfCombat)
	elseif field == "opacityInCombat" then
		layout.opacityInCombat = Helper.NormalizeOpacity(value, layout.opacityInCombat or Helper.PANEL_LAYOUT_DEFAULTS.opacityInCombat)
	elseif rowSizeIndex then
		local index = tonumber(rowSizeIndex)
		local base = Helper.ClampInt(layout.iconSize, 12, 128, Helper.PANEL_LAYOUT_DEFAULTS.iconSize)
		local newSize = Helper.ClampInt(value, 12, 128, base)
		layout.rowSizes = layout.rowSizes or {}
		if newSize == base then
			layout.rowSizes[index] = nil
		else
			layout.rowSizes[index] = newSize
		end
		if not next(layout.rowSizes) then layout.rowSizes = nil end
	end

	if Helper.IsFixedLayout(layout) then CooldownPanels.BumpFixedGroupEffectiveLayoutVersion(panel) end

	if field == "iconZoom" and not skipRefresh then
		CooldownPanels:RefreshPanelIconZoom(panelId)
		return
	end
	if field == "cdmAuraOverlayColor" and not skipRefresh then
		CooldownPanels:RefreshPanelCDMAuraOverlayColor(panelId)
		return
	end
	if not skipRefresh then
		-- The open layout editor already owns the current icon mapping. Glow-only
		-- changes do not need layout, aura-container, text, or bar reconstruction.
		local usedGlowPreview = cdp.RUNTIME.PANEL_GLOW_PREVIEW_FIELDS[field] == true and CooldownPanels:TryRefreshPanelGlowPreview(panelId)
		if not usedGlowPreview then CooldownPanels:RefreshPanelForCurrentEditContext(panelId, false) end
	end
	if field == "layoutMode" and not skipRefresh then refreshStandaloneSettings() end
	if (field == "iconShape" or field == "procGlowStyle" or field == "readyGlowStyle" or field == "pandemicGlowStyle") and not skipRefresh then
		CooldownPanels:RefreshLayoutPanelStandaloneMenu()
		refreshStandaloneSettings()
	end
end

local function getCopySettingsEntries(panelKey)
	local root = CooldownPanels:GetRoot()
	if not root or not root.panels then return {} end
	local entries = {}
	local seen = {}
	if type(root.order) == "table" then
		for _, id in ipairs(root.order) do
			local otherId = normalizeId(id)
			if otherId ~= panelKey then
				local other = root.panels[otherId]
				if other then
						local label = (L["cooldownPanelReferenceLabel"]):format(tostring(otherId), other.name or L["cooldownPanelDefaultName"])
					entries[#entries + 1] = { id = otherId, label = label }
					seen[otherId] = true
				end
			end
		end
	end
	for id, other in pairs(root.panels) do
		local otherId = normalizeId(id)
		if other and otherId ~= panelKey and not seen[otherId] then
				local label = (L["cooldownPanelReferenceLabel"]):format(tostring(otherId), other.name or L["cooldownPanelDefaultName"])
			entries[#entries + 1] = { id = otherId, label = label }
		end
	end
	return entries
end

function CooldownPanels:PrepareLayoutPanelStandaloneSettings(panelId)
	local panel = self:GetPanel(panelId)
	if not panel then return end
	local runtime = getRuntime(panelId)

	local frame = self:EnsurePanelFrame(panelId)
	if not frame then return end

	panel.layout = panel.layout or Helper.CopyTableShallow(Helper.PANEL_LAYOUT_DEFAULTS)
	local layout = panel.layout
	local baseIconSize = Helper.ClampInt(layout.iconSize, 12, 128, Helper.PANEL_LAYOUT_DEFAULTS.iconSize)
	local anchor = ensurePanelAnchor(panel)
	local panelKey = normalizeId(panelId)
	local countFontPath, countFontSize, countFontStyle = Helper.GetCountFontDefaults(frame)
	local chargesFontPath, chargesFontSize, chargesFontStyle = Helper.GetChargesFontDefaults(frame)
	local function fontOptions() return Helper.GetFontOptions(countFontPath) end
	local function chargesFontOptions() return Helper.GetFontOptions(chargesFontPath) end
	local function hasStaticTextEntries() return panel and panel.entries and next(panel.entries) ~= nil end
	local function hasCDMAuraEntries()
		if not (panel and panel.entries) then return false end
		for _, entry in pairs(panel.entries) do
			if entry and entry.type == "CDM_AURA" then return true end
		end
		return false
	end
	local function usesPixelGlowStyle()
		if Helper.NormalizeGlowStyle(layout.readyGlowStyle, Helper.PANEL_LAYOUT_DEFAULTS.readyGlowStyle) == "PIXEL" then return true end
		if Helper.NormalizeGlowStyle(select(1, CooldownPanels:ResolveEntryProcGlowVisual(layout, nil)), layout.readyGlowStyle or Helper.PANEL_LAYOUT_DEFAULTS.readyGlowStyle) == "PIXEL" then
			return true
		end
		if Helper.NormalizeGlowStyle(layout.pandemicGlowStyle, layout.readyGlowStyle or Helper.PANEL_LAYOUT_DEFAULTS.readyGlowStyle) == "PIXEL" then return true end
		return false
	end

	local function glowStyleUsesThickness(style)
		style = Helper.NormalizeGlowStyle(style, Helper.PANEL_LAYOUT_DEFAULTS.readyGlowStyle)
		return style == "PIXEL" or style == "PULSING" or style == "MARCHING_ANTS" or style == "FLASH"
	end

	local function usesGlowThicknessStyle()
		if glowStyleUsesThickness(layout.readyGlowStyle) then return true end
		if glowStyleUsesThickness(select(1, CooldownPanels:ResolveEntryProcGlowVisual(layout, nil))) then return true end
		if glowStyleUsesThickness(Helper.NormalizeGlowStyle(layout.pandemicGlowStyle, layout.readyGlowStyle or Helper.PANEL_LAYOUT_DEFAULTS.readyGlowStyle)) then return true end
		return false
	end
	local function setStaticTextEntryId(entryId)
		local runtimePanel = getRuntime(panelId)
		if runtimePanel then runtimePanel.layoutEditEntryId = normalizeId(entryId) end
	end
	local function getStaticTextEntryId()
		if not hasStaticTextEntries() then return nil end
		local editor = getEditor()
		if editor and editor.selectedPanelId == panelId then
			local selected = normalizeId(editor.selectedEntryId)
			if selected and panel.entries and panel.entries[selected] then
				setStaticTextEntryId(selected)
				return selected
			end
		end
		local runtimePanel = getRuntime(panelId)
		local entryId = normalizeId(runtimePanel and runtimePanel.layoutEditEntryId)
		if entryId and panel.entries and panel.entries[entryId] then return entryId end
		local order = panel.order or {}
		for _, id in ipairs(order) do
			if panel.entries and panel.entries[id] then
				setStaticTextEntryId(id)
				return id
			end
		end
		for id in pairs(panel.entries) do
			if panel.entries[id] then
				setStaticTextEntryId(id)
				return id
			end
		end
		return nil
	end
	local function getStaticTextEntry()
		local entryId = getStaticTextEntryId()
		return entryId and panel.entries and panel.entries[entryId] or nil, entryId
	end
	local staticTextSharedFields = {
		staticTextFont = true,
		staticTextSize = true,
		staticTextStyle = true,
		staticTextColor = true,
		staticTextAnchor = true,
		staticTextX = true,
		staticTextY = true,
	}
	local function updateStaticTextEntry(entry, field, value)
		if not entry then return end
		local changed = false
		if staticTextSharedFields[field] then
			for _, other in pairs(panel.entries or {}) do
				if other then
					if other.staticTextUseGlobal ~= false then
						other.staticTextUseGlobal = false
						changed = true
					end
					if other[field] ~= value then
						other[field] = value
						changed = true
					end
				end
			end
		else
			if entry[field] == value then return end
			entry[field] = value
			changed = true
		end
		if not changed then return end
		CooldownPanels:RefreshPanel(panelId)
		CooldownPanels:RefreshEditor()
	end
	local function ensureAnchorTable() return ensurePanelAnchor(panel) end
	local function syncPanelPositionFromAnchor()
		local a = ensureAnchorTable()
		if not a then return end
		panel.point = a.point or panel.point or "CENTER"
		panel.x = a.x or panel.x or 0
		panel.y = a.y or panel.y or 0
	end
	local function applyAnchorPosition(skipFrameRefresh, skipSettingValuesRefresh)
		syncPanelPositionFromAnchor()
		CooldownPanels:ApplyPanelPosition(panelId)
		CooldownPanels:UpdateVisibility(panelId)
		if skipFrameRefresh ~= true then refreshLayoutPanelFrame(panelId) end
		if skipSettingValuesRefresh ~= true then refreshStandaloneSettingValues() end
	end
	local function applyAnchorDefaults(a, target)
		if not a then return end
		if target == "UIParent" then
			a.point = "CENTER"
			a.relativePoint = "CENTER"
			a.x = 0
			a.y = 0
		else
			a.point = "TOPLEFT"
			a.relativePoint = "BOTTOMLEFT"
			a.x = 0
			a.y = 0
		end
	end
	local function getRowSizeValue(index)
		local base = Helper.ClampInt(layout.iconSize, 12, 128, Helper.PANEL_LAYOUT_DEFAULTS.iconSize)
		local rowSizes = layout.rowSizes
		local value = rowSizes and tonumber(rowSizes[index]) or nil
		return Helper.ClampInt(value, 12, 128, base)
	end
	local function isRadialLayout() return Helper.NormalizeLayoutMode(layout.layoutMode, Helper.PANEL_LAYOUT_DEFAULTS.layoutMode) == "RADIAL" end
	local function isFixedLayout() return Helper.NormalizeLayoutMode(layout.layoutMode, Helper.PANEL_LAYOUT_DEFAULTS.layoutMode) == "FIXED" end
	local function usesSeparateIconSize() return layout.iconSizeSeparate == true end
	local function shouldShowRowSize(index)
		if isRadialLayout() then return false end
		local rows, primaryHorizontal = getPanelRowCount(panel, layout)
		return primaryHorizontal and rows >= index
	end
	local visibilityRuleOptions = PanelVisibility.GetRuleOptions()
	local settings
	if SettingType then
		settings = {
			{
				name = _G.GENERAL or "General",
				kind = SettingType.Collapsible,
				id = "cooldownPanelGeneral",
				defaultCollapsed = false,
			},
			{
				name = L["CooldownPanelPanelName"] or "Panel name",
				kind = SettingType.Input,
				parentId = "cooldownPanelGeneral",
				labelWidth = 100,
				inputWidth = 220,
				get = function()
					local currentPanel = CooldownPanels:GetPanel(panelId)
					return currentPanel and currentPanel.name or ""
				end,
				set = function(_, value) CooldownPanels:SetPanelEditorName(panelId, value) end,
				default = "",
				maxChars = 64,
			},
			{
				name = L["Enabled"] or "Enabled",
				kind = SettingType.Checkbox,
				parentId = "cooldownPanelGeneral",
				get = function()
					local currentPanel = CooldownPanels:GetPanel(panelId)
					return currentPanel and currentPanel.enabled ~= false or false
				end,
				set = function(_, value) CooldownPanels:SetPanelEditorEnabled(panelId, value) end,
			},
			{
				name = L["durationTextProfile"] or "Duration text profile",
				kind = SettingType.Dropdown,
				parentId = "cooldownPanelGeneral",
				height = 140,
				get = function()
					local currentPanel = CooldownPanels:GetPanel(panelId)
					return CooldownPanels:GetPanelDurationTextProfile(currentPanel)
				end,
				set = function(_, value)
					local currentPanel = CooldownPanels:GetPanel(panelId)
					if not currentPanel then return end
					currentPanel.layout = currentPanel.layout or Helper.CopyTableShallow(Helper.PANEL_LAYOUT_DEFAULTS)
					local profileKey = CooldownPanels:NormalizeDurationTextProfile(value, "MINIMAL")
					currentPanel.layout.durationTextProfile = profileKey
					currentPanel.barDurationTextProfile = profileKey
					CooldownPanels:RefreshPanel(panelId)
					CooldownPanels:RefreshEditor()
				end,
				generator = function(_, root)
					local durationText = addon.DurationText
					local options = durationText and durationText.GetProfileOptions and durationText:GetProfileOptions() or {}
					for _, option in ipairs(options) do
						root:CreateRadio(option.label, function()
							local currentPanel = CooldownPanels:GetPanel(panelId)
							return CooldownPanels:GetPanelDurationTextProfile(currentPanel) == option.value
						end, function()
							local currentPanel = CooldownPanels:GetPanel(panelId)
							if not currentPanel then return end
							currentPanel.layout = currentPanel.layout or Helper.CopyTableShallow(Helper.PANEL_LAYOUT_DEFAULTS)
							local profileKey = CooldownPanels:NormalizeDurationTextProfile(option.value, "MINIMAL")
							currentPanel.layout.durationTextProfile = profileKey
							currentPanel.barDurationTextProfile = profileKey
							CooldownPanels:RefreshPanel(panelId)
							CooldownPanels:RefreshEditor()
						end)
					end
				end,
			},
			{
				name = L["CooldownPanelSpecFilter"] or "Show only for spec",
				kind = SettingType.MultiDropdown,
				parentId = "cooldownPanelGeneral",
				customText = L["CooldownPanelSpecAny"] or "All specs",
				height = 260,
				get = function() return nil end,
				set = function() end,
				optionfunc = function() return CooldownPanels:GetPanelSpecFilterOptions() end,
				isSelected = function(_, value) return CooldownPanels:IsPanelSpecFilterOptionSelected(panelId, value) end,
				setSelected = function(_, value, selected) CooldownPanels:SetPanelSpecFilterOptionSelected(panelId, value, selected) end,
			},
			{
				name = L["Copy Settings"] or "Copy Settings",
				kind = SettingType.Collapsible,
				id = "cooldownPanelCopySettings",
				defaultCollapsed = true,
			},
			{
				name = L["Copy Settings"] or "Copy Settings",
				tooltip = L["CooldownPanelCopySettingsTooltip"],
				kind = SettingType.Dropdown,
				field = "copySettingsFrom",
				parentId = "cooldownPanelCopySettings",
				height = 140,
				get = function() return nil end,
				set = function() end,
				generator = function(_, root)
					local entries = getCopySettingsEntries(panelKey)
					if not entries or #entries == 0 then
						if root.CreateTitle then root:CreateTitle(L["CooldownPanelCopySettingsNone"] or "No other panels") end
						return
					end
					for _, entry in ipairs(entries) do
						root:CreateRadio(entry.label, function() return false end, function()
							ensureCopyPopup()
							StaticPopup_Show("EQOL_COOLDOWN_PANEL_COPY_SETTINGS", entry.label, nil, { targetPanelId = panelId, sourcePanelId = entry.id })
						end)
					end
				end,
			},
			{
				name = "Anchor",
				kind = SettingType.Collapsible,
				id = "cooldownPanelAnchor",
				defaultCollapsed = true,
			},
			{
				name = "Relative frame",
				kind = SettingType.Dropdown,
				field = "anchorRelativeFrame",
				parentId = "cooldownPanelAnchor",
				height = 200,
				get = function() return CooldownPanels.ValidateRelativeFrameChoice(panel, panelKey, runtime) end,
				set = function(_, value)
					local a = ensureAnchorTable()
					if not a then return end
					local target = Helper.NormalizeRelativeFrameName(value)
					local cache = CooldownPanels.GetRelativeFrameCache(runtime, panel, panelKey)
					if not (cache.valid and cache.valid[target]) then target = "UIParent" end
					if target == cdp.FAKE_CURSOR.FRAME_NAME then
						CooldownPanels:AttachFakeCursor(panelId)
						return
					end
					if a.relativeFrame ~= target then CooldownPanels.MarkRelativeFrameEntriesDirty() end
					a.relativeFrame = target
					applyAnchorDefaults(a, target)
					applyAnchorPosition()
					CooldownPanels:UpdateCursorAnchorState()
					local anchorHelper = CooldownPanels.AnchorHelper
					if anchorHelper and anchorHelper.MaybeScheduleRefresh then anchorHelper:MaybeScheduleRefresh(target) end
				end,
				generator = function(_, root)
					local entries = CooldownPanels.GetRelativeFrameCache(runtime, panel, panelKey).entries
					local current = CooldownPanels.ValidateRelativeFrameChoice(panel, panelKey, runtime)
					for _, entry in ipairs(entries) do
						root:CreateRadio(entry.label, function() return current == entry.key end, function()
							local a = ensureAnchorTable()
							if not a then return end
							local target = entry.key
							local cache = CooldownPanels.GetRelativeFrameCache(runtime, panel, panelKey)
							if not (cache.valid and cache.valid[target]) then target = "UIParent" end
							if target == cdp.FAKE_CURSOR.FRAME_NAME then
								CooldownPanels:AttachFakeCursor(panelId)
								return
							end
							if a.relativeFrame ~= target then CooldownPanels.MarkRelativeFrameEntriesDirty() end
							a.relativeFrame = target
							applyAnchorDefaults(a, target)
							applyAnchorPosition()
							CooldownPanels:UpdateCursorAnchorState()
							local anchorHelper = CooldownPanels.AnchorHelper
							if anchorHelper and anchorHelper.MaybeScheduleRefresh then anchorHelper:MaybeScheduleRefresh(target) end
						end)
					end
				end,
				default = "UIParent",
			},
			{
				name = "Anchor point",
				kind = SettingType.Dropdown,
				field = "anchorPoint",
				parentId = "cooldownPanelAnchor",
				height = 160,
				get = function()
					local a = ensureAnchorTable()
					return Helper.NormalizeAnchor(a and a.point, "CENTER")
				end,
				set = function(_, value)
					local a = ensureAnchorTable()
					if not a then return end
					a.point = Helper.NormalizeAnchor(value, a.point or "CENTER")
					if not a.relativePoint then a.relativePoint = a.point end
					applyAnchorPosition(true, true)
				end,
				generator = function(_, root)
					for _, option in ipairs(Helper.AnchorOptions) do
						root:CreateRadio(option.label, function()
							local a = ensureAnchorTable()
							return Helper.NormalizeAnchor(a and a.point, "CENTER") == option.value
						end, function()
							local a = ensureAnchorTable()
							if not a then return end
							a.point = option.value
							if not a.relativePoint then a.relativePoint = option.value end
							applyAnchorPosition(true, true)
						end)
					end
				end,
			},
			{
				name = "Relative point",
