		"cooldownPanelCharges",
		"cooldownPanelGlow",
		"cooldownPanelKeybinds",
		"cooldownPanelCopySettings",
	})
	runtime.layoutPanelSettings = settings
	runtime.layoutPanelSettingsMaxHeight = 620
	self:UpdateVisibility(panelId)
end

function CooldownPanels:AttachFakeCursor(panelId)
	if not panelId then return end
	local panel = self:GetPanel(panelId)
	if not panel then return end
	local anchor = ensurePanelAnchor(panel)
	if not anchor then return end

	anchor.point = "CENTER"
	anchor.relativePoint = "CENTER"
	CooldownPanels.MarkRelativeFrameEntriesDirty()
	anchor.relativeFrame = cdp.FAKE_CURSOR.FRAME_NAME
	anchor.x = 0
	anchor.y = 0
	panel.point = anchor.point or panel.point or "CENTER"
	panel.x = anchor.x or panel.x or 0
	panel.y = anchor.y or panel.y or 0
	self:ApplyPanelPosition(panelId)
	refreshStandaloneSettingValues()
	resetFakeCursorFrame()
	self:UpdateCursorAnchorState()
end

local function isSlashCommandRegistered(command)
	if addon.functions and addon.functions.IsSlashCommandRegistered then return addon.functions.IsSlashCommandRegistered(command) end
	if not command then return false end
	command = command:lower()
	for key, value in pairs(_G) do
		if type(key) == "string" and key:match("^SLASH_") and type(value) == "string" then
			if value:lower() == command then return true end
		end
	end
	return false
end

local function setSlashCommandAlias(slot, command)
	if addon.functions and addon.functions.SetSlashCommandAlias then
		return addon.functions.SetSlashCommandAlias("EQOLCP", slot, command)
	end
	command = type(command) == "string" and command:lower() or nil
	_G["SLASH_EQOLCP" .. slot] = command
	return command
end

local function registerCooldownPanelsSlashCommand()
	if not SlashCmdList then return end
	local commands = { "/ecd", "/cpe" }
	local assigned = false
	local slot = 1
	for _, command in ipairs(commands) do
		local lower = command:lower()
		if isSlashCommandRegistered(lower) then
			local owned = false
			if SlashCmdList["EQOLCP"] then
				for i = 1, #commands do
					local key = _G["SLASH_EQOLCP" .. i]
					if type(key) == "string" and key:lower() == lower then
						owned = true
						break
					end
				end
			end
			if not owned then command = nil end
		end
		if command then
			setSlashCommandAlias(slot, lower)
			slot = slot + 1
			assigned = true
		end
	end
	for clearSlot = slot, #commands do
		setSlashCommandAlias(clearSlot, nil)
	end
	if not assigned then return end
	SlashCmdList["EQOLCP"] = function()
		local panels = addon.Aura and addon.Aura.CooldownPanels
		if not panels then return end
		if panels.TogglePreferredEditor then
			panels:TogglePreferredEditor()
		elseif panels.ToggleBlizzardEditor then
			panels:ToggleBlizzardEditor()
		end
	end
end

function cdp.ENTRY.GetSpellTargets(runtime, spellId, baseSpellId)
	local index = runtime and runtime.spellEntryIndex
	if not index then return nil end
	runtime._eqolSpellEntryTargets = runtime._eqolSpellEntryTargets or {}
	local targets = runtime._eqolSpellEntryTargets
	for panelId, entries in pairs(targets) do
		if entries then
			for entryId in pairs(entries) do
				entries[entryId] = nil
			end
		end
		targets[panelId] = nil
	end

	local function collect(id)
		local numericId = tonumber(id)
		if not numericId then return end
		local panels = index[numericId]
		if not panels then return end
		for panelId, entries in pairs(panels) do
			targets[panelId] = targets[panelId] or {}
			for entryId, meta in pairs(entries) do
				targets[panelId][entryId] = meta
			end
		end
	end

	local seenIDs = {}
	for _, sourceId in ipairs({ spellId, baseSpellId }) do
		if sourceId then
			local aliasIDs = CooldownPanels:GetSpellAliasIDs(sourceId)
			for i = 1, #aliasIDs do
				local aliasId = aliasIDs[i]
				if not seenIDs[aliasId] then
					seenIDs[aliasId] = true
					collect(aliasId)
				end
			end
		end
	end

	return next(targets) and targets or nil
end

function cdp.ENTRY.GetItemTargets(runtime, itemId)
	local index = runtime and runtime.itemEntryIndex
	if not index then return nil end
	runtime._eqolItemEntryTargets = runtime._eqolItemEntryTargets or {}
	local targets = runtime._eqolItemEntryTargets
	for panelId, entries in pairs(targets) do
		if entries then
			for entryId in pairs(entries) do
				entries[entryId] = nil
			end
		end
		targets[panelId] = nil
	end

	local numericItemId = tonumber(itemId)
	if not numericItemId then return nil end
	local panels = index[numericItemId]
	if not panels then return nil end
	for panelId, entries in pairs(panels) do
		targets[panelId] = targets[panelId] or {}
		for entryId, meta in pairs(entries) do
			targets[panelId][entryId] = meta
		end
	end

	return next(targets) and targets or nil
end

function cdp.ENTRY.QueuePanelRefresh(panelsToRefresh, panelId)
	if not (panelsToRefresh and panelId) then return end
	panelsToRefresh[panelId] = true
end

function cdp.ENTRY.GetPanelRefreshScratch(runtime, scratchKey)
	if not runtime then return nil end
	scratchKey = scratchKey or "_eqolEntryPanelRefreshScratch"
	local scratch = runtime[scratchKey]
	if not scratch then
		scratch = {}
		runtime[scratchKey] = scratch
	else
		for panelId in pairs(scratch) do
			scratch[panelId] = nil
		end
	end
	return scratch
end

function cdp.ENTRY.FlushPanelRefreshes(panelsToRefresh)
	if not panelsToRefresh then return false end
	local refreshed = false
	for panelId in pairs(panelsToRefresh) do
		panelsToRefresh[panelId] = nil
		if CooldownPanels.RequestPanelRefresh then
			CooldownPanels:RequestPanelRefresh(panelId)
			refreshed = true
		elseif CooldownPanels:GetPanel(panelId) then
			CooldownPanels:RefreshPanel(panelId)
			refreshed = true
		end
	end
	return refreshed
end

function cdp.ENTRY.ApplyVisibleSpellRuntime(panelId, runtime, icon, data, resolvedLayout)
	if not (runtime and icon and data) then return false end
	local staticFontPath = resolvedLayout and resolvedLayout.staticFontPath
	local staticFontSize = resolvedLayout and resolvedLayout.staticFontSize
	local staticFontStyle = resolvedLayout and resolvedLayout.staticFontStyle
	local powerTintR = resolvedLayout and resolvedLayout.powerTintR
	local powerTintG = resolvedLayout and resolvedLayout.powerTintG
	local powerTintB = resolvedLayout and resolvedLayout.powerTintB
	local unusableTintR = resolvedLayout and resolvedLayout.unusableTintR
	local unusableTintG = resolvedLayout and resolvedLayout.unusableTintG
	local unusableTintB = resolvedLayout and resolvedLayout.unusableTintB
	local readyGlowPrimed = CooldownPanels.GetReadyGlowPrimedState(runtime)

	icon:Show()
	updateCooldownDoneContext(icon.cooldown, panelId, data.entryId, data)
	if icon.cooldown.Resume then icon.cooldown:Resume() end
	if icon.cooldown.SetAlpha then icon.cooldown:SetAlpha(1) end
	icon.cooldown:SetHideCountdownNumbers(not data.showCooldownText)
	local auraDisplayActive = data.customCooldownDurationActive == true or data.spellAuraOverlayActive == true
	if icon.cooldown.SetUseAuraDisplayTime then icon.cooldown:SetUseAuraDisplayTime(auraDisplayActive) end
	if icon.cooldown.SetReverse then icon.cooldown:SetReverse(data.cooldownReverse == true) end
	cdp.ENTRY.ApplyCooldownSwipeVisual(icon, data)

	local cooldownStart = data.cooldownStart or 0
	local cooldownDuration = data.cooldownDuration or 0
	local cooldownRate = data.cooldownRate or 1
	local chargeDurationObject = data.chargeDurationObject
	local cooldownDurationObject = data.cooldownDurationObject
	local cooldownTextDurationObject
	local cooldownTextIsGCD = false
	local cooldownEnabledOk = isSafeNotFalse(data.cooldownEnabled)
	local spellCooldownActive = CooldownPanels.IsSpellCooldownInfoActive(data.cooldownIsActive, data.cooldownEnabled, cooldownStart, cooldownDuration)
	local durationActive = cooldownDurationObject ~= nil and spellCooldownActive
	local cooldownActive = data.showCooldown and (durationActive or spellCooldownActive)
	local usingCooldown = false
	local desaturate = false
	local hidden = false
	local chargeCooldownHasAvailableCharge = false
	local chargeInfoActive = false
	local entryNoDesaturation = data.noDesaturation == true
	local entryDrawEdge = data.cooldownDrawEdge ~= false
	local entryDrawBling = data.cooldownDrawBling ~= false
	local entryDrawSwipe = data.cooldownDrawSwipe ~= false
	local entryGcdDrawEdge = data.cooldownGcdDrawEdge == true
	local entryGcdDrawBling = data.cooldownGcdDrawBling == true
	local entryGcdDrawSwipe = data.cooldownGcdDrawSwipe == true
	local hideOnCooldown = data.hideOnCooldown == true
	local showOnCooldown = data.showOnCooldown == true

	local chargesAlpha = 1
	if data.showCharges and data.chargesInfo and data.chargesInfo.maxCharges ~= nil then
		if CooldownPanels.ShouldShowSpellChargeCount(data.chargesInfo) and data.chargesInfo.currentCharges ~= nil then
			icon.charges:SetText(data.chargesInfo.currentCharges)
			if data.chargesHideWhenZero == true then chargesAlpha = data.chargesInfo.currentCharges end
			icon.charges:SetAlpha(chargesAlpha)
			icon.charges:Show()
		else
			icon.charges:SetAlpha(1)
			icon.charges:Hide()
		end
		if data.showCooldown then
			chargeInfoActive = CooldownPanels.IsChargeInfoActive(data.chargesInfo)
			if chargeInfoActive then
				cooldownStart = data.chargesInfo.cooldownStartTime or cooldownStart
				cooldownDuration = data.chargesInfo.cooldownDuration or cooldownDuration
				cooldownRate = data.chargesInfo.chargeModRate or cooldownRate
				cooldownActive = true
				usingCooldown = true
			end
		end
		if usingCooldown and isSafeNumber(data.chargesInfo.currentCharges) then
			chargeCooldownHasAvailableCharge = data.chargesInfo.currentCharges > 0 and isSafeLessThan(data.chargesInfo.currentCharges, data.chargesInfo.maxCharges)
			desaturate = data.chargesInfo.currentCharges == 0
			if hideOnCooldown or showOnCooldown then hidden = desaturate end
		end
	else
		icon.charges:SetAlpha(1)
		icon.charges:Hide()
	end

	if data.customCooldownDurationActive == true then
		usingCooldown = false
		chargeCooldownHasAvailableCharge = false
		chargeInfoActive = false
		cooldownStart = data.customCooldownStart or cooldownStart
		cooldownDuration = data.customCooldownDuration or cooldownDuration
		cooldownRate = 1
		cooldownEnabledOk = true
		spellCooldownActive = true
		durationActive = cooldownDurationObject ~= nil
		cooldownActive = data.showCooldown == true
		desaturate = false
		if hideOnCooldown or showOnCooldown then hidden = true end
	end
	if data.spellAuraOverlayActive == true then
		usingCooldown = false
		chargeCooldownHasAvailableCharge = false
		chargeInfoActive = false
		cooldownEnabledOk = true
		spellCooldownActive = true
		durationActive = cooldownDurationObject ~= nil
		cooldownActive = data.showCooldown == true
		desaturate = false
		if hideOnCooldown or showOnCooldown then hidden = true end
	end
	-- Cooldown activity remains inspectable when charge counts are secret, so it
	-- can safely distinguish a recharge-only timer from the zero-charge cooldown.
	local hideChargeCooldownVisuals = usingCooldown and not spellCooldownActive
	cdp.ENTRY.ApplyCooldownSwipeFillState(icon, data, hideChargeCooldownVisuals)

	CooldownPanels.SetIconDesaturatedRuntime(icon.texture, desaturate, entryNoDesaturation)
	if hideOnCooldown then
		icon:SetAlphaFromBoolean(hidden, 0, 1)
	elseif showOnCooldown then
		icon:SetAlphaFromBoolean(hidden, 1, 0)
	else
		icon:SetAlpha(1)
	end

	if data.showCooldown then
		if usingCooldown then
			setCooldownDrawState(icon.cooldown, entryDrawEdge, entryDrawBling, entryDrawSwipe)
			if chargeCooldownHasAvailableCharge then
				if data.showChargesCooldown then
					if chargeDurationObject and icon.cooldown.SetCooldownFromDurationObject then
						icon.cooldown:Clear()
						icon.cooldown:SetCooldownFromDurationObject(chargeDurationObject)
						cooldownTextDurationObject = chargeDurationObject
					elseif isSafeNumber(cooldownStart) and isSafeNumber(cooldownDuration) then
						icon.cooldown:Clear()
						icon.cooldown:SetCooldown(cooldownStart, cooldownDuration, cooldownRate)
						cooldownTextDurationObject = CooldownPanels:ConfigureNumericCooldownTextDuration(icon, cooldownStart, cooldownDuration, cooldownRate)
					else
						icon.cooldown:Clear()
					end
					if icon.cooldown.SetScript then icon.cooldown:SetScript("OnCooldownDone", onCooldownDone) end
				else
					icon.cooldown:Clear()
					if icon.cooldown.SetScript then icon.cooldown:SetScript("OnCooldownDone", nil) end
				end
			else
				if data.showChargesCooldown then
					if chargeDurationObject and icon.cooldown.SetCooldownFromDurationObject then
						icon.cooldown:Clear()
						icon.cooldown:SetCooldownFromDurationObject(chargeDurationObject)
						cooldownTextDurationObject = chargeDurationObject
					elseif isSafeNumber(cooldownStart) and isSafeNumber(cooldownDuration) then
						icon.cooldown:Clear()
						icon.cooldown:SetCooldown(cooldownStart, cooldownDuration, cooldownRate)
						cooldownTextDurationObject = CooldownPanels:ConfigureNumericCooldownTextDuration(icon, cooldownStart, cooldownDuration, cooldownRate)
					else
						icon.cooldown:Clear()
					end
					if not data.cooldownGCD and icon.cooldown.SetScript then icon.cooldown:SetScript("OnCooldownDone", onCooldownDone) end
				else
					icon.cooldown:Clear()
					if icon.cooldown.SetScript then icon.cooldown:SetScript("OnCooldownDone", nil) end
				end

				if cooldownDurationObject then
					if data.cooldownGCD then
					else
						if icon.cooldown.SetScript then icon.cooldown:SetScript("OnCooldownDone", onCooldownDone) end
						setCooldownDrawState(icon.cooldown, entryDrawEdge, entryDrawBling, entryDrawSwipe)
						CooldownPanels.SetIconDesaturationRuntime(icon.texture, cooldownDurationObject:EvaluateRemainingDuration(curveDesat), entryNoDesaturation)
						if hideOnCooldown then
							icon:SetAlpha(cooldownDurationObject:EvaluateRemainingDuration(curveAlpha))
						elseif showOnCooldown then
							icon:SetAlpha(cooldownDurationObject:EvaluateRemainingDuration(curveDesat))
						end
						if data.showChargesCooldown and chargeDurationObject then
							icon.cooldown:SetCooldownFromDurationObject(chargeDurationObject)
							cooldownTextDurationObject = chargeDurationObject
						else
							icon.cooldown:SetCooldownFromDurationObject(cooldownDurationObject)
							cooldownTextDurationObject = cooldownDurationObject
						end
					end
				end
			end
		elseif durationActive then
			icon.cooldown:SetCooldownFromDurationObject(cooldownDurationObject)
			cooldownTextDurationObject = cooldownDurationObject
			cooldownTextIsGCD = data.cooldownGCD == true
			if data.cooldownGCD then
				CooldownPanels.SetIconDesaturationRuntime(icon.texture, 0, entryNoDesaturation)
				if hideOnCooldown then
					icon:SetAlpha(1)
				elseif showOnCooldown then
					icon:SetAlpha(0)
				end
				setCooldownDrawState(icon.cooldown, entryGcdDrawEdge, entryGcdDrawBling, entryGcdDrawSwipe)
			else
				setCooldownDrawState(icon.cooldown, entryDrawEdge, entryDrawBling, entryDrawSwipe)
				local auraDisplayDurationActive = data.customCooldownDurationActive == true or data.spellAuraOverlayActive == true
				local desat = auraDisplayDurationActive and 0 or cooldownDurationObject:EvaluateRemainingDuration(curveDesat)
				CooldownPanels.SetIconDesaturationRuntime(icon.texture, desat, entryNoDesaturation)
				if hideOnCooldown then
					icon:SetAlpha(cooldownDurationObject:EvaluateRemainingDuration(curveAlpha))
				elseif showOnCooldown then
					icon:SetAlpha(auraDisplayDurationActive and 1 or cooldownDurationObject:EvaluateRemainingDuration(curveDesat))
				end
				if icon.cooldown.SetScript then icon.cooldown:SetScript("OnCooldownDone", onCooldownDone) end
			end
		elseif cooldownActive then
			if isSafeNumber(cooldownStart) and isSafeNumber(cooldownDuration) then
				icon.cooldown:SetCooldown(cooldownStart, cooldownDuration, cooldownRate)
				cooldownTextDurationObject = CooldownPanels:ConfigureNumericCooldownTextDuration(icon, cooldownStart, cooldownDuration, cooldownRate)
				cooldownTextIsGCD = data.cooldownGCD == true
			else
				icon.cooldown:Clear()
			end
			if data.cooldownGCD then
				CooldownPanels.SetIconDesaturationRuntime(icon.texture, 0, entryNoDesaturation)
				if hideOnCooldown then
					icon:SetAlpha(1)
				elseif showOnCooldown then
					icon:SetAlpha(0)
				end
				setCooldownDrawState(icon.cooldown, entryGcdDrawEdge, entryGcdDrawBling, entryGcdDrawSwipe)
				if icon.cooldown.SetScript then icon.cooldown:SetScript("OnCooldownDone", nil) end
			else
				CooldownPanels.SetIconDesaturatedRuntime(icon.texture, true, entryNoDesaturation)
				if hideOnCooldown then
					icon:SetAlpha(0)
				elseif showOnCooldown then
					icon:SetAlpha(1)
				end
				setCooldownDrawState(icon.cooldown, entryDrawEdge, entryDrawBling, entryDrawSwipe)
				if icon.cooldown.SetScript then icon.cooldown:SetScript("OnCooldownDone", onCooldownDone) end
			end
		else
			setCooldownDrawState(icon.cooldown, entryDrawEdge, entryDrawBling, entryDrawSwipe)
			icon.cooldown:Clear()
			if icon.cooldown.SetScript then icon.cooldown:SetScript("OnCooldownDone", nil) end
		end
	else
		setCooldownDrawState(icon.cooldown, entryDrawEdge, entryDrawBling, entryDrawSwipe)
		icon.cooldown:Clear()
		if icon.cooldown.SetScript then icon.cooldown:SetScript("OnCooldownDone", nil) end
	end

	if data.spellUnusable then
		icon.texture:SetVertexColor(unusableTintR or 0.6, unusableTintG or 0.6, unusableTintB or 0.6)
	elseif data.powerInsufficient then
		icon.texture:SetVertexColor(powerTintR or 0.5, powerTintG or 0.5, powerTintB or 1)
	elseif data.cooldownEnabled == false and data.cooldownIsActive == false and data.cooldownGCD ~= true then
		icon.texture:SetVertexColor(0.4, 0.4, 0.4)
	else
		icon.texture:SetVertexColor(1, 1, 1)
	end

	CooldownPanels:ApplyRuntimeCooldownDurationTextProfile(icon, data.layout)
	CooldownPanels:ApplyRuntimeCooldownTextBinding(icon, data, cooldownTextDurationObject, cooldownTextIsGCD, data.hideChargeCooldownText == true and hideChargeCooldownVisuals)

	local staticTextCooldown = false
	if data.entry and data.entry.staticTextShowOnCooldown == true then staticTextCooldown = durationActive or (cooldownEnabledOk and isCooldownActive(cooldownStart, cooldownDuration)) end
	applyStaticText(icon, data.layout, data.entry, staticFontPath, staticFontSize, staticFontStyle, staticTextCooldown)
	if durationActive and showOnCooldown and data.entry and data.entry.staticTextShowOnCooldown == true and staticTextCooldown and data.entry.spellID then
		icon.staticText:SetAlpha(cooldownDurationObject:EvaluateRemainingDuration(Helper.FakeCurve))
		icon.cooldown:SetAlpha(cooldownDurationObject:EvaluateRemainingDuration(Helper.FakeCurve))
		if icon.cooldownText then icon.cooldownText:SetAlpha(cooldownDurationObject:EvaluateRemainingDuration(Helper.FakeCurve)) end
	end

	data.readyAt = runtime.readyAt and runtime.readyAt[data.entryId] or nil
	local readyGlowCooldownRunning
	local useSecretReadyGlow = data.spellReadyCondition ~= nil and data.glowReady and data.showCooldown and data.canTriggerReadyGlow
	local secretReadyGlowAllowed = useSecretReadyGlow and data.readyGlowResourceBlocked ~= true
	if useSecretReadyGlow then
		if data.readyAt or (readyGlowPrimed and readyGlowPrimed[data.entryId]) then
			CooldownPanels.ClearReadyGlowEntryState(panelId, data.entryId, true)
			data.readyAt = nil
		end
	elseif data.canTriggerReadyGlow then
		readyGlowCooldownRunning = durationActive or usingCooldown or (cooldownEnabledOk and isCooldownActive(cooldownStart, cooldownDuration))
		if readyGlowCooldownRunning then
			CooldownPanels.ClearReadyGlowEntryState(panelId, data.entryId, true)
			data.readyAt = nil
		end
	end
	if readyGlowCooldownRunning == nil then readyGlowCooldownRunning = durationActive or usingCooldown or (cooldownEnabledOk and isCooldownActive(cooldownStart, cooldownDuration)) end
	cdp.ENTRY.ApplyIconBorderCooldownVisibility(icon, data.entry, readyGlowCooldownRunning == true, data.powerInsufficient == true)
	if not useSecretReadyGlow and data.glowReady and data.showCooldown and data.canTriggerReadyGlow then
		if data.readyAt then
			if readyGlowPrimed then readyGlowPrimed[data.entryId] = true end
		elseif not readyGlowCooldownRunning and not data.cooldownGCD and readyGlowPrimed and not readyGlowPrimed[data.entryId] then
			triggerReadyGlow(panelId, data.entryId, data.glowDuration)
			readyGlowPrimed[data.entryId] = true
			data.readyAt = runtime.readyAt[data.entryId]
		end
	end

	local overlayGlow = data.overlayGlow == true
	local overlayGlowColor = overlayGlow and data.overlayGlowColor or nil
	local simpleGlowEnabled = overlayGlow
	local simpleGlowColor = overlayGlowColor
	local simpleGlowStyle = data.overlayGlowStyle or data.readyGlowStyle
	local simpleGlowInset = data.overlayGlowInset or data.readyGlowInset
	if data.glowReady and not useSecretReadyGlow then
		local ready = data.readyAt ~= nil
		if ready and data.readyGlowCheckPower == true and data.readyGlowResourceBlocked == true then ready = false end
		simpleGlowEnabled = overlayGlow or ready
		simpleGlowColor = ready and data.readyGlowColor or overlayGlowColor
		simpleGlowStyle = ready and data.readyGlowStyle or (data.overlayGlowStyle or data.readyGlowStyle)
		simpleGlowInset = ready and data.readyGlowInset or (data.overlayGlowInset or data.readyGlowInset)
	end
	setPreviewGlow(icon, false)
	if data.liveGlowAllowed == false then
		setGlow(icon, false, nil, "EQOL_SIMPLE")
		setGlow(icon, false, nil, "EQOL_OVERLAY")
		setGlow(icon, false, nil, "EQOL_READY")
		setGlow(icon, false, nil, "EQOL_INTERRUPT")
	elseif useSecretReadyGlow then
		setGlow(icon, false, nil, "EQOL_SIMPLE")
		if secretReadyGlowAllowed then
			setGlow(
				icon,
				overlayGlow,
				overlayGlowColor,
				"EQOL_OVERLAY",
				data.spellReadyCondition,
				0,
				1,
				data.overlayGlowStyle or data.readyGlowStyle,
				data.overlayGlowInset or data.readyGlowInset,
				data.glowPixelOptions
			)
			setGlow(icon, true, data.readyGlowColor, "EQOL_READY", data.spellReadyCondition, 1, 0, data.readyGlowStyle, data.readyGlowInset, data.glowPixelOptions)
		else
			setGlow(icon, overlayGlow, overlayGlowColor, "EQOL_OVERLAY", nil, nil, nil, data.overlayGlowStyle or data.readyGlowStyle, data.overlayGlowInset or data.readyGlowInset, data.glowPixelOptions)
			setGlow(icon, false, nil, "EQOL_READY")
		end
		setGlow(icon, data.interruptGlow == true, data.readyGlowColor, "EQOL_INTERRUPT", data.interruptGlowCondition, 0, 1, data.readyGlowStyle, data.readyGlowInset, data.glowPixelOptions)
	else
		setGlow(icon, false, nil, "EQOL_OVERLAY")
		setGlow(icon, false, nil, "EQOL_READY")
		setGlow(icon, simpleGlowEnabled, simpleGlowColor, "EQOL_SIMPLE", nil, nil, nil, simpleGlowStyle, simpleGlowInset, data.glowPixelOptions)
		setGlow(icon, data.interruptGlow == true, data.readyGlowColor, "EQOL_INTERRUPT", data.interruptGlowCondition, 0, 1, data.readyGlowStyle, data.readyGlowInset, data.glowPixelOptions)
	end

	return true
end

function cdp.ENTRY.ApplyVisibleItemRuntime(panelId, runtime, icon, data, resolvedLayout)
	if not (runtime and icon and data) then return false end
	local staticFontPath = resolvedLayout and resolvedLayout.staticFontPath
	local staticFontSize = resolvedLayout and resolvedLayout.staticFontSize
	local staticFontStyle = resolvedLayout and resolvedLayout.staticFontStyle
	local readyGlowPrimed = CooldownPanels.GetReadyGlowPrimedState(runtime)
	local cooldownStart = data.cooldownStart or 0
	local cooldownDuration = data.cooldownDuration or 0
	local cooldownEnabledOk = data.cooldownEnabled ~= false and data.cooldownEnabled ~= 0
	local cooldownDurationObject = data.cooldownDurationObject
	local cooldownTextDurationObject
	local customCooldownActive = data.customCooldownDurationActive == true
	if customCooldownActive then
		cooldownStart = data.customCooldownStart or cooldownStart
		cooldownDuration = data.customCooldownDuration or cooldownDuration
		cooldownEnabledOk = true
	end
	local cooldownRunning = (customCooldownActive and (cooldownDurationObject ~= nil or isCooldownActive(cooldownStart, cooldownDuration))) or (cooldownEnabledOk and isCooldownActive(cooldownStart, cooldownDuration))
	local cooldownActive = data.showCooldown and cooldownRunning
	local entryNoDesaturation = data.noDesaturation == true and data.emptyItem ~= true
	local entryDrawEdge = data.cooldownDrawEdge ~= false
	local entryDrawBling = data.cooldownDrawBling ~= false
	local entryDrawSwipe = data.cooldownDrawSwipe ~= false
	local hidden = false
	local desaturate = data.emptyItem == true

	icon:Show()
	updateCooldownDoneContext(icon.cooldown, panelId, data.entryId, data)
	if icon.cooldown.Resume then icon.cooldown:Resume() end
	if icon.cooldown.SetAlpha then icon.cooldown:SetAlpha(1) end
	icon.cooldown:SetHideCountdownNumbers(not data.showCooldownText)
	if icon.cooldown.SetUseAuraDisplayTime then icon.cooldown:SetUseAuraDisplayTime(customCooldownActive) end
	if icon.cooldown.SetReverse then icon.cooldown:SetReverse(data.cooldownReverse == true) end
	cdp.ENTRY.ApplyCooldownSwipeVisual(icon, data)

	if data.showItemUses then
		if data.itemUses ~= nil then
			icon.charges:SetText(data.itemUses)
			icon.charges:SetAlpha(1)
			icon.charges:Show()
		else
			icon.charges:SetAlpha(1)
			icon.charges:Hide()
		end
	else
		icon.charges:SetAlpha(1)
		icon.charges:Hide()
	end

	if data.showCooldown and cooldownActive then
		if cooldownDurationObject and icon.cooldown.SetCooldownFromDurationObject then
			icon.cooldown:Clear()
			icon.cooldown:SetCooldownFromDurationObject(cooldownDurationObject)
			cooldownTextDurationObject = cooldownDurationObject
		else
			icon.cooldown:SetCooldown(cooldownStart, cooldownDuration, 1)
			cooldownTextDurationObject = CooldownPanels:ConfigureNumericCooldownTextDuration(icon, cooldownStart, cooldownDuration, 1)
		end
		setCooldownDrawState(icon.cooldown, entryDrawEdge, entryDrawBling, entryDrawSwipe)
		if icon.cooldown.SetScript then icon.cooldown:SetScript("OnCooldownDone", onCooldownDone) end
		desaturate = customCooldownActive ~= true
		if data.hideOnCooldown == true then
			icon:SetAlpha(0)
			hidden = true
		elseif data.showOnCooldown == true then
			icon:SetAlpha(1)
		end
	else
		setCooldownDrawState(icon.cooldown, entryDrawEdge, entryDrawBling, entryDrawSwipe)
		icon.cooldown:Clear()
		if icon.cooldown.SetScript then icon.cooldown:SetScript("OnCooldownDone", nil) end
		if data.hideOnCooldown == true then
			icon:SetAlpha(1)
		elseif data.showOnCooldown == true then
			icon:SetAlpha(0)
			hidden = true
		else
			icon:SetAlpha(1)
		end
	end

	CooldownPanels.SetIconDesaturatedRuntime(icon.texture, desaturate, entryNoDesaturation)
	if not hidden and data.showOnCooldown ~= true and data.hideOnCooldown ~= true then icon:SetAlpha(1) end

	if (data.resolvedType == "ITEM" or data.resolvedType == "SLOT") and not cooldownEnabledOk and isSafeGreaterThan(cooldownDuration, 0) then
		icon.texture:SetVertexColor(0.4, 0.4, 0.4)
	else
		icon.texture:SetVertexColor(1, 1, 1)
	end

	CooldownPanels:ApplyRuntimeCooldownDurationTextProfile(icon, data.layout)
	CooldownPanels:ApplyRuntimeCooldownTextBinding(icon, data, cooldownTextDurationObject)

	if data.showItemCount and data.itemCount ~= nil then
		icon.count:SetText(data.itemCount)
		icon.count:Show()
	elseif data.showStacks and data.stackCount ~= nil then
		icon.count:SetText(data.stackCount)
		icon.count:Show()
	else
		icon.count:Hide()
	end

	local staticTextCooldown = false
	if data.entry and data.entry.staticTextShowOnCooldown == true then staticTextCooldown = cooldownRunning == true end
	applyStaticText(icon, data.layout, data.entry, staticFontPath, staticFontSize, staticFontStyle, staticTextCooldown)

	data.readyAt = runtime.readyAt and runtime.readyAt[data.entryId] or nil
	local readyGlowCooldownRunning = cooldownRunning == true
	if data.canTriggerReadyGlow then
		if readyGlowCooldownRunning then
			CooldownPanels.ClearReadyGlowEntryState(panelId, data.entryId, true)
			data.readyAt = nil
		end
	end
	cdp.ENTRY.ApplyIconBorderCooldownVisibility(icon, data.entry, readyGlowCooldownRunning == true, data.powerInsufficient == true)
	if data.glowReady and data.showCooldown and data.canTriggerReadyGlow then
		if data.readyAt then
			if readyGlowPrimed then readyGlowPrimed[data.entryId] = true end
		elseif not readyGlowCooldownRunning and not data.cooldownGCD and readyGlowPrimed and not readyGlowPrimed[data.entryId] then
			triggerReadyGlow(panelId, data.entryId, data.glowDuration)
			readyGlowPrimed[data.entryId] = true
			data.readyAt = runtime.readyAt[data.entryId]
		end
	end

	local overlayGlow = data.overlayGlow == true
	local overlayGlowColor = overlayGlow and data.overlayGlowColor or nil
	local simpleGlowEnabled = overlayGlow
	local simpleGlowColor = overlayGlowColor
	local simpleGlowStyle = data.overlayGlowStyle or data.readyGlowStyle
	local simpleGlowInset = data.overlayGlowInset or data.readyGlowInset
	if data.glowReady then
		local ready = data.readyAt ~= nil
		if ready and data.readyGlowCheckPower == true and data.readyGlowResourceBlocked == true then ready = false end
		simpleGlowEnabled = overlayGlow or ready
		simpleGlowColor = ready and data.readyGlowColor or overlayGlowColor
		simpleGlowStyle = ready and data.readyGlowStyle or (data.overlayGlowStyle or data.readyGlowStyle)
		simpleGlowInset = ready and data.readyGlowInset or (data.overlayGlowInset or data.readyGlowInset)
	end
	if data.activationOverlayActive == true and data.activationOverlayGlow == true then
		simpleGlowEnabled = true
		simpleGlowColor = data.activationOverlayGlowColor or data.readyGlowColor or overlayGlowColor
		simpleGlowStyle = data.readyGlowStyle or simpleGlowStyle
		simpleGlowInset = data.readyGlowInset or simpleGlowInset
	end
	setPreviewGlow(icon, false)
	if data.liveGlowAllowed == false then
		setGlow(icon, false, nil, "EQOL_SIMPLE")
		setGlow(icon, false, nil, "EQOL_OVERLAY")
		setGlow(icon, false, nil, "EQOL_READY")
		setGlow(icon, false, nil, "EQOL_INTERRUPT")
	else
		setGlow(icon, false, nil, "EQOL_OVERLAY")
		setGlow(icon, false, nil, "EQOL_READY")
		setGlow(icon, false, nil, "EQOL_INTERRUPT")
		setGlow(icon, simpleGlowEnabled, simpleGlowColor, "EQOL_SIMPLE", nil, nil, nil, simpleGlowStyle, simpleGlowInset, data.glowPixelOptions)
	end

	return true
end

function cdp.ENTRY.GetVisibleSpellEntryRefreshBlockReason(panelId, entryId, mode)
	local panel = CooldownPanels:GetPanel(panelId)
	local runtime = panel and getRuntime(panelId) or nil
	if not (panel and runtime and runtime.frame) then return "missingPanelRuntime" end
	if CooldownPanels:IsPanelLayoutEditActive(panelId) then return "layoutEditActive" end

	local metaByPanel = CooldownPanels.runtime and CooldownPanels.runtime.spellEntryMeta
	local meta = metaByPanel and metaByPanel[panelId] and metaByPanel[panelId][entryId] or nil
	if not meta then return "missingMeta" end
	local entry = panel.entries and panel.entries[entryId] or nil
	if not entry then return "missingEntry" end
	local macro = entry.type == "MACRO" and CooldownPanels.ResolveMacroEntry(entry) or nil
	local baseSpellId = entry.type == "SPELL" and tonumber(entry.spellID) or (macro and macro.kind == "SPELL" and tonumber(macro.spellID)) or nil
	if not baseSpellId then return "missingSpellId" end
	local effectiveSpellId, resolvedSpellId, _, variantGroup = CooldownPanels:ResolveEntryTrackedSpellID(entry, baseSpellId)
	effectiveSpellId = effectiveSpellId or getEffectiveSpellId(baseSpellId) or baseSpellId
	local spellId = effectiveSpellId or baseSpellId
	local spellPassive = not shouldTrackPassiveSpell(entry) and isSpellPassiveSafe(resolvedSpellId or baseSpellId, effectiveSpellId) or false
	local talentChoiceResolved = variantGroup and variantGroup.kind == "talentChoice"
	if spellPassive then return "passiveSpell" end
	if Api.IsSpellKnown and not talentChoiceResolved and not cdp.ENTRY.ShouldTrackUnknownSpell(entry) and not Api.IsSpellKnown(spellId, true) then return "unknownSpell" end

	if mode == "charges" then
		if meta.localChargesSafe ~= true then return "localChargesUnsafe" end
	elseif mode == "power" then
		if meta.localPowerSafe ~= true then return "localPowerUnsafe" end
	else
		if meta.localCooldownSafe ~= true then return "localCooldownUnsafe" end
	end

	if entry.displayMode == "BAR" then return "barDisplay" end
	local icon = runtime.entryToIcon and runtime.entryToIcon[entryId] or nil
	local data = icon and icon._eqolRuntimeData or nil
	local entryLayout = data and data.layout or panel.layout
	if mode == "event" then
		if CooldownPanels:HasConfiguredStateTexture(entry) then return "stateTexture" end
		if entry.pandemicGlow == true then return "pandemicGlow" end
		if entry.glowOtherAura ~= nil then return "otherAuraGlow" end
		if entry.alwaysShow == false and CooldownPanels:ShouldShowEntryCharges(entryLayout, entry, "SPELL") then return "chargeVisibility" end
		if shouldShowEntryStacks(entryLayout, entry, "SPELL") then return "stackDisplay" end
		if CooldownPanels:ResolveEntryHideWhenNoResource(entryLayout, entry) then return "resourceVisibility" end
		if CooldownPanels:ResolveEntryActivationOverlayGlow(entryLayout, entry) and CooldownPanels:EntryUsesActivationOverlay(entry, "SPELL") then return "activationOverlayGlow" end
	end
	if CooldownPanels:IsEntryCDMAuraOverlayEnabled(entryLayout, entry, "SPELL") then return "cdmAuraOverlay" end
	if CooldownPanels:ResolveEntryActivationOverlayOnly(entryLayout, entry) and CooldownPanels:EntryUsesActivationOverlay(entry, "SPELL") then return "activationOverlayOnly" end
	if not (icon and data and data.entryId == entryId and data.resolvedType == "SPELL") then return "missingIconData" end
	return nil
end

function cdp.ENTRY.TryRefreshVisibleSpellEntry(panelId, entryId, mode)
	local blockReason = cdp.ENTRY.GetVisibleSpellEntryRefreshBlockReason(panelId, entryId, mode)
	if blockReason == "barDisplay" and mode ~= "power" then
		local bars = CooldownPanels.Bars
		if bars and bars.TryRefreshRuntimeChargeBarEntry and bars.TryRefreshRuntimeChargeBarEntry(panelId, entryId, mode) then return true end
	end
	if blockReason then return false end

	local panel = CooldownPanels:GetPanel(panelId)
	local runtime = panel and getRuntime(panelId) or nil
	local icon = runtime.entryToIcon and runtime.entryToIcon[entryId] or nil
	local data = icon and icon._eqolRuntimeData or nil
	local entry = panel.entries and panel.entries[entryId] or nil
	local macro = entry.type == "MACRO" and CooldownPanels.ResolveMacroEntry(entry) or nil
	local baseSpellId = entry.type == "SPELL" and tonumber(entry.spellID) or (macro and macro.kind == "SPELL" and tonumber(macro.spellID)) or nil
	local effectiveSpellId, resolvedSpellId, _, variantGroup = CooldownPanels:ResolveEntryTrackedSpellID(entry, baseSpellId)
	effectiveSpellId = effectiveSpellId or getEffectiveSpellId(baseSpellId) or baseSpellId
	local spellId = effectiveSpellId or baseSpellId

	local showCooldown = entry.showCooldown ~= false
	local staticTextShowOnCooldown = entry.staticTextShowOnCooldown == true
	local trackCooldown = showCooldown or staticTextShowOnCooldown
	local showCharges = CooldownPanels:ShouldShowEntryCharges(data.layout, entry, "SPELL")
	local entryCheckPower = CooldownPanels:ResolveEntryCheckPower(data.layout, entry)
	local readyGlowCheckPower = data.glowReady and CooldownPanels:ResolveEntryReadyGlowCheckPower(data.layout, entry)
	local powerInsufficientSpells = CooldownPanels.runtime and CooldownPanels.runtime.powerInsufficient
	local spellUnusableSpells = CooldownPanels.runtime and CooldownPanels.runtime.spellUnusable
	local resourceInsufficient = isSpellFlagged(powerInsufficientSpells, baseSpellId, effectiveSpellId)
	local unusableForReadyGlow = isSpellFlagged(spellUnusableSpells, baseSpellId, effectiveSpellId)
	local spellPassState = CooldownPanels:GetSpellPassState(spellId)
	local ignoreCooldownGCD = CooldownPanels:ShouldIgnoreEntryCooldownGCD(data.layout, entry)
	local chargesInfo
	local chargesInfoActive = false
	local chargeDurationObject
	local cooldownDurationObject
	local cooldownStart, cooldownDuration, cooldownEnabled, cooldownRate, cooldownGCD, cooldownIsActive

	if mode ~= "power" and showCharges then
		if spellPassState and spellPassState.chargesLoaded == nil then
			spellPassState.chargesInfo = CooldownPanels:GetCachedSpellChargesInfo(spellId)
			spellPassState.chargesLoaded = true
		end
		chargesInfo = spellPassState and spellPassState.chargesInfo or CooldownPanels:GetCachedSpellChargesInfo(spellId)
		chargesInfoActive = CooldownPanels.IsChargeInfoActive(chargesInfo)
	end
	if mode ~= "power" and (trackCooldown or (showCooldown and chargesInfoActive)) then
		cooldownStart, cooldownDuration, cooldownEnabled, cooldownRate, cooldownGCD, cooldownIsActive =
			CooldownPanels:GetCachedSpellCooldownInfo(spellId, ignoreCooldownGCD)
	end
	cooldownIsActive = mode == "power" and data.cooldownIsActive or CooldownPanels.IsSpellCooldownInfoActive(cooldownIsActive, cooldownEnabled, cooldownStart, cooldownDuration)
	if mode ~= "power" and showCooldown and data.showChargesCooldown and chargesInfoActive then
		if spellPassState and spellPassState.chargeDurationLoaded == nil then
			spellPassState.chargeDurationObject = CooldownPanels:GetCachedSpellChargeDurationObject(spellId)
			spellPassState.chargeDurationLoaded = true
		end
		chargeDurationObject = spellPassState and spellPassState.chargeDurationObject or CooldownPanels:GetCachedSpellChargeDurationObject(spellId)
	end
	if mode ~= "power" and trackCooldown and cooldownIsActive then
		cooldownDurationObject = CooldownPanels:GetCachedSpellCooldownDurationObject(spellId, ignoreCooldownGCD)
	end

	if mode ~= "power" then
		data.cooldownStart = cooldownStart or 0
		data.cooldownDuration = cooldownDuration or 0
		data.cooldownEnabled = cooldownEnabled
		data.cooldownIsActive = cooldownIsActive
		data.cooldownRate = cooldownRate or 1
		data.cooldownGCD = cooldownGCD == true
		data.chargesInfo = chargesInfo
		data.chargeDurationObject = chargeDurationObject
		data.cooldownDurationObject = cooldownDurationObject
	end
	data.cooldownIgnoreGCD = ignoreCooldownGCD == true
	data.spellId = spellId
	data.baseSpellId = baseSpellId
	data.effectiveSpellId = effectiveSpellId
	data.resolvedSpellId = resolvedSpellId
	data.variantGroupKind = variantGroup and variantGroup.kind or nil
	data.variantGroupKey = variantGroup and variantGroup.key or nil
	if data.stateTextureType then
		local overlayGlowSpells = CooldownPanels.runtime and CooldownPanels.runtime.overlayGlowSpells
		data.stateTextureShown = entry.stateTextureShowWithoutProc == true or isSpellFlagged(overlayGlowSpells, baseSpellId, effectiveSpellId) == true
	end
	local customCooldownState = CooldownPanels:GetActiveEntryCustomCooldownDuration(panelId, entryId, entry, "SPELL")
	CooldownPanels:ApplyCustomCooldownDurationState(data, customCooldownState)
	CooldownPanels:ApplyActivationOverlayVisualState(data, entry)
	if customCooldownState then
		cooldownGCD = false
		cooldownIsActive = true
	end
	data.powerInsufficient = entryCheckPower and resourceInsufficient
	data.spellUnusable = entryCheckPower and isSpellFlagged(spellUnusableSpells, baseSpellId, effectiveSpellId)
	data.readyGlowCheckPower = readyGlowCheckPower == true
	data.readyGlowResourceBlocked = readyGlowCheckPower and (resourceInsufficient or unusableForReadyGlow) or false
	if data.glowReady and showCooldown then
		if data.cooldownGCD then
			data.spellReadyCondition = true
		elseif type(data.cooldownIsActive) == "boolean" then
			data.spellReadyCondition = not data.cooldownIsActive
		else
			data.spellReadyCondition = nil
		end
	else
		data.spellReadyCondition = nil
	end
	data.interruptGlow = false
	data.interruptGlowCondition = nil
	if entry.interruptGlow == true and CooldownPanels:IsInterruptGlowSupported(entry) then
		data.interruptGlow, data.interruptGlowCondition = CooldownPanels:GetInterruptGlowTargetCondition(effectiveSpellId or baseSpellId)
	end

	local resolvedLayout = CooldownPanels.ResolveRuntimeLayout(runtime, runtime.frame, panel.layout)
	return cdp.ENTRY.ApplyVisibleSpellRuntime(panelId, runtime, icon, data, resolvedLayout)
end

function cdp.ENTRY.TryRefreshVisibleItemEntry(panelId, entryId)
	local panel = CooldownPanels:GetPanel(panelId)
	local runtime = panel and getRuntime(panelId) or nil
	if not (panel and runtime and runtime.frame) then return false end
	if CooldownPanels:IsPanelLayoutEditActive(panelId) then return false end

	local icon = runtime.entryToIcon and runtime.entryToIcon[entryId] or nil
	local data = icon and icon._eqolRuntimeData or nil
	local entry = panel.entries and panel.entries[entryId] or nil
	if not entry then return false end
	if entry.displayMode == "BAR" then return false end
	local macro = entry.type == "MACRO" and CooldownPanels.ResolveMacroEntry(entry) or nil
	local resolvedType = (macro and macro.kind) or entry.type
	if resolvedType ~= "ITEM" then return false end

	local baseItemId = tonumber((macro and macro.itemID) or entry.itemID)
	if not baseItemId then return false end
	local resolvedItemId = CooldownPanels.ResolveEntryItemID(entry, baseItemId)
	if not (resolvedItemId and itemHasUseSpell(resolvedItemId)) then return false end

	local showCooldown = entry.showCooldown ~= false
	local showWhenEmpty = entry.showWhenEmpty == true
	local showItemCount = entry.showItemCount ~= false
	local showItemUses = entry.showItemUses == true
	local alwaysShow = entry.alwaysShow ~= false
	local itemCache = CooldownPanels.runtime and CooldownPanels.runtime.itemCountCache or nil
	local cached = itemCache and itemCache[resolvedItemId] or nil
	if not cached then
		updateItemCountCacheForItem(resolvedItemId, showItemUses)
		itemCache = CooldownPanels.runtime and CooldownPanels.runtime.itemCountCache or nil
		cached = itemCache and itemCache[resolvedItemId] or nil
	end

	local cachedCount = cached and cached.count
	local ownsItem
	if cachedCount ~= nil then
		ownsItem = cachedCount > 0 or (Api.IsEquippedItem and Api.IsEquippedItem(resolvedItemId))
	else
		ownsItem = hasItem(resolvedItemId)
	end
	local emptyItem = showWhenEmpty and not ownsItem
	local cooldownStart, cooldownDuration, cooldownEnabled
	local cooldownGCD = false
	local newVisible = false
	if (ownsItem or showWhenEmpty) and itemHasUseSpell(resolvedItemId) then
		if (showCooldown or entry.staticTextShowOnCooldown == true) and ownsItem then
			cooldownStart, cooldownDuration, cooldownEnabled = getItemCooldownInfo(resolvedItemId)
			if CooldownPanels:IsItemCooldownOnGCD(resolvedItemId, cooldownStart, cooldownDuration) then
				cooldownStart, cooldownDuration, cooldownEnabled = 0, 0, true
				cooldownGCD = true
			end
		end
		local cooldownEnabledOk = cooldownEnabled ~= false and cooldownEnabled ~= 0
		newVisible = alwaysShow or showWhenEmpty
		if not newVisible and showCooldown and cooldownEnabledOk and isCooldownActive(cooldownStart, cooldownDuration) then newVisible = true end
	end
	local customCooldownState = CooldownPanels:GetActiveEntryCustomCooldownDuration(panelId, entryId, entry, "ITEM")
	if not customCooldownState then customCooldownState = CooldownPanels:GetActiveEntryProcTriggerDuration(panelId, entryId, entry, "ITEM") end
	if customCooldownState then
		cooldownStart = customCooldownState.startTime
		cooldownDuration = customCooldownState.duration
		cooldownEnabled = true
		cooldownGCD = false
		if showCooldown then newVisible = true end
	end
	if CooldownPanels:ResolveEntryActivationOverlayOnly(panel.layout, entry) and CooldownPanels:EntryUsesActivationOverlay(entry, "ITEM") then newVisible = customCooldownState ~= nil end
	if not icon then return newVisible ~= true end
	if not (data and data.entryId == entryId and data.resolvedType == "ITEM") then return false end
	if not newVisible then return false end

	local itemCount = nil
	if showItemCount then
		if cachedCount == nil then
			updateItemCountCacheForItem(resolvedItemId, showItemUses)
			itemCache = CooldownPanels.runtime and CooldownPanels.runtime.itemCountCache or nil
			cached = itemCache and itemCache[resolvedItemId] or nil
			cachedCount = cached and cached.count or 0
		end
		if isSafeGreaterThan(cachedCount, 0) then
			itemCount = cachedCount
		elseif showWhenEmpty then
			itemCount = 0
		end
	end

	local itemUses = nil
	if showItemUses then
		local uses = cached and cached.uses
		if uses == nil then
			updateItemCountCacheForItem(resolvedItemId, true)
			itemCache = CooldownPanels.runtime and CooldownPanels.runtime.itemCountCache or nil
			cached = itemCache and itemCache[resolvedItemId] or nil
			uses = cached and cached.uses or 0
		end
		if isSafeGreaterThan(uses, 0) then
			itemUses = uses
		elseif showWhenEmpty then
			itemUses = 0
		end
	end

	data.itemCount = itemCount
	data.itemUses = itemUses
	data.emptyItem = emptyItem
	data.stackCount = nil
	data.showStacks = false
	data.cooldownStart = cooldownStart or 0
	data.cooldownDuration = cooldownDuration or 0
	data.cooldownEnabled = cooldownEnabled
	data.cooldownIsActive = nil
	data.cooldownRate = 1
	data.cooldownGCD = cooldownGCD == true
	data.cooldownDurationObject = nil
	data.chargeDurationObject = nil
	data.chargesInfo = nil
	data.canTriggerReadyGlow = ownsItem == true
	data.resolvedItemId = resolvedItemId
	data.customCooldownDurationActive = customCooldownState ~= nil
	data.customCooldownDurationKey = customCooldownState and customCooldownState.key or nil
	data.customCooldownDurationObject = customCooldownState and customCooldownState.durationObject or nil
	data.customCooldownStart = customCooldownState and customCooldownState.startTime or nil
	data.customCooldownDuration = customCooldownState and customCooldownState.duration or nil
	CooldownPanels:ApplyCustomCooldownDurationState(data, customCooldownState)
	CooldownPanels:ApplyActivationOverlayVisualState(data, entry)
	if customCooldownState then data.canTriggerReadyGlow = true end

	local resolvedLayout = CooldownPanels.ResolveRuntimeLayout(runtime, runtime.frame, panel.layout)
	return cdp.ENTRY.ApplyVisibleItemRuntime(panelId, runtime, icon, data, resolvedLayout)
end

function cdp.ENTRY.TryRefreshVisibleSlotEntry(panelId, entryId)
	local panel = CooldownPanels:GetPanel(panelId)
	local runtime = panel and getRuntime(panelId) or nil
	if not (panel and runtime and runtime.frame) then return false end
	if CooldownPanels:IsPanelLayoutEditActive(panelId) then return false end

	local icon = runtime.entryToIcon and runtime.entryToIcon[entryId] or nil
	local data = icon and icon._eqolRuntimeData or nil
	local entry = panel.entries and panel.entries[entryId] or nil
	if not (entry and entry.type == "SLOT") then return false end
	if entry.displayMode == "BAR" then return false end

	local slotId = tonumber(entry.slotID)
	if not slotId then return false end
	local showCooldown = entry.showCooldown ~= false
	local alwaysShow = entry.alwaysShow ~= false
	local showWhenNoCooldown = entry.showWhenNoCooldown == true
	local itemId = Api.GetInventoryItemID and Api.GetInventoryItemID("player", slotId) or nil
	local hasUsableItem = itemId and itemHasUseSpell(itemId) or false
	local cooldownStart, cooldownDuration, cooldownEnabled
	local cooldownGCD = false
	local newVisible = false
	if hasUsableItem then
		if showCooldown or entry.staticTextShowOnCooldown == true then
			cooldownStart, cooldownDuration, cooldownEnabled = getItemCooldownInfo(itemId, slotId)
			if CooldownPanels:IsItemCooldownOnGCD(itemId, cooldownStart, cooldownDuration) then
				cooldownStart, cooldownDuration, cooldownEnabled = 0, 0, true
				cooldownGCD = true
			end
		end
		local cooldownEnabledOk = cooldownEnabled ~= false and cooldownEnabled ~= 0
		newVisible = alwaysShow or showWhenNoCooldown
		if not newVisible and showCooldown and cooldownEnabledOk and isCooldownActive(cooldownStart, cooldownDuration) then newVisible = true end
	elseif showWhenNoCooldown then
		newVisible = true
	end
	local customCooldownState = CooldownPanels:GetActiveEntryCustomCooldownDuration(panelId, entryId, entry, "SLOT")
	if not customCooldownState then customCooldownState = CooldownPanels:GetActiveEntryProcTriggerDuration(panelId, entryId, entry, "SLOT") end
	if customCooldownState then
		cooldownStart = customCooldownState.startTime
		cooldownDuration = customCooldownState.duration
		cooldownEnabled = true
		cooldownGCD = false
		if showCooldown then newVisible = true end
	end
	if CooldownPanels:ResolveEntryActivationOverlayOnly(panel.layout, entry) and CooldownPanels:EntryUsesActivationOverlay(entry, "SLOT") then newVisible = customCooldownState ~= nil end
	if not icon then return newVisible ~= true end
	if not (data and data.entryId == entryId and data.resolvedType == "SLOT") then return false end
	if data.nativeAuraHostBaseVisible ~= nil then data.nativeAuraHostBaseVisible = newVisible == true end
	if not newVisible then return false end

	data.cooldownStart = cooldownStart or 0
	data.cooldownDuration = cooldownDuration or 0
	data.stackCount = customCooldownState and CooldownPanels.NormalizePositiveDisplayCount(customCooldownState.stackCount) or nil
	data.showStacks = data.stackCount ~= nil and shouldShowEntryStacks(data.layout, entry, "SLOT") or false
	data.cooldownEnabled = cooldownEnabled
	data.cooldownIsActive = nil
	data.cooldownRate = 1
	data.cooldownGCD = cooldownGCD == true
	data.cooldownDurationObject = nil
	data.chargeDurationObject = nil
	data.chargesInfo = nil
	data.canTriggerReadyGlow = hasUsableItem == true
	data.customCooldownDurationActive = customCooldownState ~= nil
	data.customCooldownDurationKey = customCooldownState and customCooldownState.key or nil
	data.customCooldownDurationObject = customCooldownState and customCooldownState.durationObject or nil
	data.customCooldownStart = customCooldownState and customCooldownState.startTime or nil
	data.customCooldownDuration = customCooldownState and customCooldownState.duration or nil
	CooldownPanels:ApplyCustomCooldownDurationState(data, customCooldownState)
	CooldownPanels:ApplyActivationOverlayVisualState(data, entry)
	if customCooldownState then data.canTriggerReadyGlow = true end

	local resolvedLayout = CooldownPanels.ResolveRuntimeLayout(runtime, runtime.frame, panel.layout)
	return cdp.ENTRY.ApplyVisibleItemRuntime(panelId, runtime, icon, data, resolvedLayout)
end

function cdp.ENTRY.RefreshSpellEntries(spellId, baseSpellId, mode, panelsToRefresh)
	local runtime = CooldownPanels.runtime
	local targets = cdp.ENTRY.GetSpellTargets(runtime, spellId, baseSpellId)
	if not targets then return false end
	local startedBatch = false
	if CooldownPanels.BeginRuntimeQueryBatch and CooldownPanels.IsRuntimeQueryBatchActive and not CooldownPanels:IsRuntimeQueryBatchActive() then
		CooldownPanels:BeginRuntimeQueryBatch()
		startedBatch = true
	end

	local refreshed = false
	for panelId, entries in pairs(targets) do
		local panelNeedsRefresh = false
		for entryId, meta in pairs(entries) do
			local shouldProcess = false
			if mode == "event" then
				shouldProcess = true
			elseif mode == "charges" then
				shouldProcess = meta.trackCharges == true
			elseif mode == "power" then
				shouldProcess = meta.trackPower == true
			else
				shouldProcess = meta.trackCooldown == true
			end
			if shouldProcess then
				if cdp.ENTRY.TryRefreshVisibleSpellEntry(panelId, entryId, mode) then
					refreshed = true
				else
					panelNeedsRefresh = true
					refreshed = true
					break
				end
			end
		end
		if panelNeedsRefresh then cdp.ENTRY.QueuePanelRefresh(panelsToRefresh, panelId) end
	end

	if startedBatch and CooldownPanels.EndRuntimeQueryBatch then CooldownPanels:EndRuntimeQueryBatch() end
	return refreshed
end

function cdp.ENTRY.RefreshAllTrackedSpellCooldownEntries()
	local runtime = CooldownPanels.runtime
	local metaByPanel = runtime and runtime.spellEntryMeta
	if not metaByPanel then return false end
	local panelsToRefresh = cdp.ENTRY.GetPanelRefreshScratch(runtime, "_eqolSpellCooldownEntryRefreshScratch")
	local startedBatch = false
	if CooldownPanels.BeginRuntimeQueryBatch and CooldownPanels.IsRuntimeQueryBatchActive and not CooldownPanels:IsRuntimeQueryBatchActive() then
		CooldownPanels:BeginRuntimeQueryBatch()
		startedBatch = true
	end

	local refreshed = false
	for panelId, entries in pairs(metaByPanel) do
		local panelNeedsRefresh = false
		for entryId, meta in pairs(entries) do
			if meta.trackCooldown == true then
				if cdp.ENTRY.TryRefreshVisibleSpellEntry(panelId, entryId, "cooldown") then
					refreshed = true
				else
					local reason = cdp.ENTRY.GetVisibleSpellEntryRefreshBlockReason(panelId, entryId, "cooldown")
					if reason ~= "unknownSpell" and reason ~= "passiveSpell" then
						panelNeedsRefresh = true
						refreshed = true
						break
					end
				end
			end
		end
		if panelNeedsRefresh then cdp.ENTRY.QueuePanelRefresh(panelsToRefresh, panelId) end
	end

	if startedBatch and CooldownPanels.EndRuntimeQueryBatch then CooldownPanels:EndRuntimeQueryBatch() end
	if cdp.ENTRY.FlushPanelRefreshes(panelsToRefresh) then refreshed = true end
	return refreshed
end

function cdp.ENTRY.RefreshTrackedSpellEntriesForGlobalGCD(spellId, baseSpellId)
	local runtime = CooldownPanels.runtime
	local metaByPanel = runtime and runtime.spellEntryMeta
	if not metaByPanel then return false end
	local directTargets = cdp.ENTRY.GetSpellTargets(runtime, spellId, baseSpellId)
	local panelsToRefresh = cdp.ENTRY.GetPanelRefreshScratch(runtime, "_eqolGlobalGCDEntryRefreshScratch")
	local startedBatch = false
	if CooldownPanels.BeginRuntimeQueryBatch and CooldownPanels.IsRuntimeQueryBatchActive and not CooldownPanels:IsRuntimeQueryBatchActive() then
		CooldownPanels:BeginRuntimeQueryBatch()
		startedBatch = true
	end

	local refreshed = false
	for panelId, entries in pairs(metaByPanel) do
		local panel = CooldownPanels:GetPanel(panelId)
		local panelEntries = panel and panel.entries
		local directEntries = directTargets and directTargets[panelId]
		local panelNeedsRefresh = false
		for entryId, meta in pairs(entries) do
			local entry = panelEntries and panelEntries[entryId]
			local isDirectTarget = directEntries and directEntries[entryId] ~= nil
			if
				meta.trackCooldown == true
				and entry
				and entry.displayMode ~= "BAR"
				and not isDirectTarget
				and not CooldownPanels:ShouldIgnoreEntryCooldownGCD(panel.layout, entry)
			then
				if cdp.ENTRY.TryRefreshVisibleSpellEntry(panelId, entryId, "cooldown") then
					refreshed = true
				else
					local reason = cdp.ENTRY.GetVisibleSpellEntryRefreshBlockReason(panelId, entryId, "cooldown")
					if reason ~= "unknownSpell" and reason ~= "passiveSpell" then
						panelNeedsRefresh = true
						refreshed = true
						break
					end
				end
			end
		end
		if panelNeedsRefresh then cdp.ENTRY.QueuePanelRefresh(panelsToRefresh, panelId) end
	end

	if startedBatch and CooldownPanels.EndRuntimeQueryBatch then CooldownPanels:EndRuntimeQueryBatch() end
	if cdp.ENTRY.FlushPanelRefreshes(panelsToRefresh) then refreshed = true end
	return refreshed
end

function cdp.ENTRY.RefreshItemEntries(itemId, panelsToRefresh)
	local runtime = CooldownPanels.runtime
	local targets = cdp.ENTRY.GetItemTargets(runtime, itemId)
	if not targets then return false end

	local refreshed = false
	for panelId, entries in pairs(targets) do
		local panelNeedsRefresh = false
		for entryId in pairs(entries) do
			if cdp.ENTRY.TryRefreshVisibleItemEntry(panelId, entryId) then
				refreshed = true
			else
				panelNeedsRefresh = true
				refreshed = true
				break
			end
		end
		if panelNeedsRefresh then cdp.ENTRY.QueuePanelRefresh(panelsToRefresh, panelId) end
	end

	return refreshed
end

function cdp.ENTRY.RefreshAllTrackedBagCooldownEntries()
	local runtime = CooldownPanels.runtime
	if not runtime then return false end
	local panelsToRefresh = cdp.ENTRY.GetPanelRefreshScratch(runtime, "_eqolBagCooldownEntryRefreshScratch")
	local refreshed = false

	local itemMeta = runtime.itemEntryMeta
	if itemMeta then
		for panelId, entries in pairs(itemMeta) do
			local panelNeedsRefresh = false
			for entryId in pairs(entries) do
				if cdp.ENTRY.TryRefreshVisibleItemEntry(panelId, entryId) then
					refreshed = true
				else
					panelNeedsRefresh = true
				end
			end
			if panelNeedsRefresh then
				cdp.ENTRY.QueuePanelRefresh(panelsToRefresh, panelId)
				refreshed = true
			end
		end
	end

	local slotMeta = runtime.slotEntryMeta
	if slotMeta then
		for panelId, entries in pairs(slotMeta) do
			local panelNeedsRefresh = false
			for entryId in pairs(entries) do
				if cdp.ENTRY.TryRefreshVisibleSlotEntry(panelId, entryId) then
					refreshed = true
				else
					panelNeedsRefresh = true
				end
			end
			if panelNeedsRefresh then
				cdp.ENTRY.QueuePanelRefresh(panelsToRefresh, panelId)
				refreshed = true
			end
		end
	end

	if cdp.ENTRY.FlushPanelRefreshes(panelsToRefresh) then refreshed = true end
	return refreshed
end

function cdp.ENTRY.RefreshChangedTrackedItemEntries()
	local runtime = CooldownPanels.runtime
	if not runtime then return false end
	runtime.itemCountCache = runtime.itemCountCache or {}
	local cache = runtime.itemCountCache
	local trackedIds = runtime.itemTrackedIds
	local trackedUsesIds = runtime.itemUsesTrackedIds
	if not trackedIds or not next(trackedIds) then return false end

	local changedItemIds = runtime._eqolChangedTrackedItemIds
	if not changedItemIds then
		changedItemIds = {}
		runtime._eqolChangedTrackedItemIds = changedItemIds
	else
		for itemId in pairs(changedItemIds) do
			changedItemIds[itemId] = nil
		end
	end

	for itemId in pairs(cache) do
		if not trackedIds[itemId] then cache[itemId] = nil end
	end
	for itemId in pairs(trackedIds) do
		local slot = cache[itemId] or {}
		local oldCount = slot.count
		local oldUses = slot.uses
		local newCount = Api.GetItemCount(itemId, false, false) or 0
		local newUses = trackedUsesIds and trackedUsesIds[itemId] and (Api.GetItemCount(itemId, false, true) or 0) or nil
		if oldCount ~= newCount or oldUses ~= newUses then changedItemIds[itemId] = true end
		slot.count = newCount
		slot.uses = newUses
		cache[itemId] = slot
	end
	if not next(changedItemIds) then return false end

	local panelsToRefresh = cdp.ENTRY.GetPanelRefreshScratch(runtime, "_eqolItemEntryRefreshScratch")
	local refreshed = false
	for itemId in pairs(changedItemIds) do
		if cdp.ENTRY.RefreshItemEntries(itemId, panelsToRefresh) then refreshed = true end
	end
	if cdp.ENTRY.FlushPanelRefreshes(panelsToRefresh) then refreshed = true end
	return refreshed
end

local function refreshTrackedSpellEntries(spellId, baseSpellId, mode, panelsToRefresh) return cdp.ENTRY.RefreshSpellEntries(spellId, baseSpellId, mode, panelsToRefresh) == true end

refreshPanelsForSpell = function(spellId)
	local id = tonumber(spellId)
	if not id then return false, false end
	local runtime = CooldownPanels.runtime
	local index = runtime and runtime.spellIndex
	if not runtime or not index or runtime.specRebuildPending == true then return false, false end
	runtime._eqolSpellRefreshScratch = runtime._eqolSpellRefreshScratch or {}
	local panelsToRefresh = runtime._eqolSpellRefreshScratch
	for panelId in pairs(panelsToRefresh) do
		panelsToRefresh[panelId] = nil
	end
	local refreshed = false
	local function collectPanels(lookupId)
		if not lookupId then return end
		local panels = index[lookupId]
		if not panels then return end
		for panelId in pairs(panels) do
			panelsToRefresh[panelId] = true
			refreshed = true
		end
	end
	local aliasIDs = CooldownPanels:GetSpellAliasIDs(id)
	for i = 1, #aliasIDs do
		collectPanels(aliasIDs[i])
	end
	if not refreshed then return false, true end
	for panelId in pairs(panelsToRefresh) do
		panelsToRefresh[panelId] = nil
		if CooldownPanels.RequestPanelRefresh then
			CooldownPanels:RequestPanelRefresh(panelId)
		elseif CooldownPanels:GetPanel(panelId) then
			CooldownPanels:RefreshPanel(panelId)
		end
	end
	return refreshed, true
end

function cdp.ENTRY.RefreshSpellEntriesForEvent(spellId, baseSpellId)
	local id = tonumber(spellId)
	local baseId = tonumber(baseSpellId)
	if not (id or baseId) then return false, false end
	local runtime = CooldownPanels.runtime
	local index = runtime and runtime.spellEntryIndex
	if not runtime or not index or runtime.specRebuildPending == true then return false, false end
	local panelsToRefresh = cdp.ENTRY.GetPanelRefreshScratch(runtime, "_eqolSpellEventEntryRefreshScratch")
	local refreshed = cdp.ENTRY.RefreshSpellEntries(id, baseId, "event", panelsToRefresh) == true
	if cdp.ENTRY.FlushPanelRefreshes(panelsToRefresh) then refreshed = true end
	return refreshed, true
end

function cdp.ENTRY.RefreshSpellEvent(spellId, baseSpellId)
	local refreshed, indexReady = cdp.ENTRY.RefreshSpellEntriesForEvent(spellId, baseSpellId)
	if indexReady then return refreshed, true end
	return refreshPanelsForSpell(spellId or baseSpellId)
end

local function invalidateSpellIconCacheForSpell(spellId)
	local numericSpellId = tonumber(spellId)
	local runtime = CooldownPanels.runtime
	local cache = runtime and runtime.iconCache
	if not (numericSpellId and cache) then return false end

	local changed = false
	local function clearForId(id)
		if not id then return end
		local cacheKey = "S:" .. tostring(id)
		if cache[cacheKey] ~= nil then
			cache[cacheKey] = nil
			changed = true
		end
	end

	clearForId(numericSpellId)

	local baseId = getBaseSpellId(numericSpellId)
	if baseId and baseId ~= numericSpellId then clearForId(baseId) end

	local effectiveId = getEffectiveSpellId(numericSpellId)
	if effectiveId and effectiveId ~= numericSpellId and effectiveId ~= baseId then clearForId(effectiveId) end

	local canonicalId, _, variantGroup = CooldownPanels:GetCanonicalSpellVariantID(numericSpellId)
	if canonicalId and canonicalId ~= numericSpellId and canonicalId ~= baseId and canonicalId ~= effectiveId then clearForId(canonicalId) end
	if type(variantGroup) == "table" then
		for i = 1, #variantGroup do
			clearForId(variantGroup[i])
		end
	end

	return changed
end

local setOverlayGlowForSpell

local function handleSpellUpdateIcon(spellId)
	if spellId ~= nil then
		invalidateSpellIconCacheForSpell(spellId)
		if setOverlayGlowForSpell(spellId, true) then return true end
		local _, indexReady = refreshPanelsForSpell(spellId)
		return indexReady == true
	end

	if CooldownPanels.runtime then CooldownPanels.runtime.iconCache = nil end
	if CooldownPanels.RefreshAllOverlayGlowStates then CooldownPanels:RefreshAllOverlayGlowStates(true) end
	CooldownPanels:RequestUpdate({
		cause = "Event:SPELL_UPDATE_ICON",
		fullRefresh = true,
	})
	return true
end

function CooldownPanels:GetReadySoundState(spellId, create)
	local runtime = self.runtime
	if not runtime then return nil end
	local stateKey = self:GetReadySoundStateKey(spellId)
	if not stateKey then return nil end
	runtime.readySoundStates = runtime.readySoundStates or {}
	local states = runtime.readySoundStates
	local state = states[stateKey]
	if not state and create ~= false then
		state = {}
		states[stateKey] = state
	end
	return state
end

function CooldownPanels:PrimeReadySoundStateForSpell(spellId)
	local runtime = self.runtime
	local stateKey = self:GetReadySoundStateKey(spellId)
	local queryByStateKey = runtime and runtime.readySoundQueryByStateKey
	local eventDrivenByStateKey = runtime and runtime.readySoundEventDrivenByStateKey
	local querySpellId = stateKey and queryByStateKey and queryByStateKey[stateKey] or nil
	if not (runtime and stateKey and querySpellId and eventDrivenByStateKey and eventDrivenByStateKey[stateKey] == true) then return end
	local state = self:GetReadySoundState(stateKey, true)
	if not state then return end
	state.initialized = true
	state.unavailable = self:GetTrustedReadyUnavailable(querySpellId) == true
end

function CooldownPanels:PrimeReadySoundStates()
	local runtime = self.runtime
	if not runtime then return end
	runtime.readySoundStates = {}
	local sweepIds = runtime.readySoundSweepIds
	if not sweepIds then return end
	for i = 1, #sweepIds do
		self:PrimeReadySoundStateForSpell(sweepIds[i])
	end
end

function CooldownPanels:EvaluateReadySoundTransitionForSpell(spellId)
	local runtime = self.runtime
	local stateKey = self:GetReadySoundStateKey(spellId)
	local queryByStateKey = runtime and runtime.readySoundQueryByStateKey
	local eventDrivenByStateKey = runtime and runtime.readySoundEventDrivenByStateKey
	local querySpellId = stateKey and queryByStateKey and queryByStateKey[stateKey] or nil
	if not (runtime and stateKey and querySpellId and eventDrivenByStateKey and eventDrivenByStateKey[stateKey] == true) then return false end
	local state = self:GetReadySoundState(stateKey, true)
	if not state then return false end
	local unavailable = self:GetTrustedReadyUnavailable(querySpellId) == true
	local shouldPlay = state.initialized == true and state.unavailable == true and unavailable ~= true
	state.initialized = true
	state.unavailable = unavailable
	return shouldPlay
end

function CooldownPanels:TriggerReadySoundForSpell(spellId)
	local id = tonumber(spellId)
	if not id then return end
	local runtime = self.runtime
	local stateKey = self:GetReadySoundStateKey(id)
	local soundByStateKey = runtime and runtime.readySoundSoundByStateKey
	local soundName = stateKey and soundByStateKey and soundByStateKey[stateKey] or nil
	if soundName and soundName ~= "None" then playSoundName(soundName) end
end

function CooldownPanels:SweepReadySoundTransitions()
	local runtime = self.runtime
	local sweepIds = runtime and runtime.readySoundSweepIds
	if not sweepIds then return false end
	local played = false
	for i = 1, #sweepIds do
		local spellId = sweepIds[i]
		if self:EvaluateReadySoundTransitionForSpell(spellId) then
			self:TriggerReadySoundForSpell(spellId)
			played = true
		end
	end
	return played
end

function CooldownPanels:HandleReadySoundSpellEvent(spellId, baseSpellId, fallbackSweep)
	local runtime = self.runtime
	local queryByStateKey = runtime and runtime.readySoundQueryByStateKey
	local eventDrivenByStateKey = runtime and runtime.readySoundEventDrivenByStateKey
	if not (queryByStateKey and next(queryByStateKey)) then return false end
	local seenKeys = {}
	local handled = false
	local played = false

	local function process(id)
		id = tonumber(id)
		if not id then return end
		local stateKey = self:GetReadySoundStateKey(id)
		local querySpellId = stateKey and queryByStateKey[stateKey] or nil
		if not (stateKey and querySpellId and eventDrivenByStateKey and eventDrivenByStateKey[stateKey] == true) then return end
		if seenKeys[stateKey] then return end
		seenKeys[stateKey] = true
		handled = true
		if self:EvaluateReadySoundTransitionForSpell(id) then
			self:TriggerReadySoundForSpell(id)
			played = true
		end
	end

	process(spellId)
	process(baseSpellId)

	if not handled and fallbackSweep == true then played = self:SweepReadySoundTransitions() or played end
	return played
end

CooldownPanels.InvalidateChargeCachesForSpell = function(spellId)
	return CooldownPanels:InvalidateSpellCooldownCachesForAliases(spellId)
end

refreshPanelsForCharges = function()
	local runtime = CooldownPanels.runtime
	local chargesIndex = runtime and runtime.chargesIndex
	if not chargesIndex or not Api.GetSpellChargesInfo then return false end
	runtime.chargesState = runtime.chargesState or {}
	local chargesState = runtime.chargesState
	local panelsToRefresh = cdp.ENTRY.GetPanelRefreshScratch(runtime, "_eqolChargeEntryRefreshScratch")
	local changedSpellIds = runtime._eqolChargeChangedSpellScratch
	if not changedSpellIds then
		changedSpellIds = {}
		runtime._eqolChargeChangedSpellScratch = changedSpellIds
	else
		for trackedSpellId in pairs(changedSpellIds) do
			changedSpellIds[trackedSpellId] = nil
		end
	end

	for spellId, panels in pairs(chargesIndex) do
		local info = Api.GetSpellChargesInfo(spellId)
		local function safeNumber(value)
			if Api.issecretvalue and Api.issecretvalue(value) then return nil, true end
			return type(value) == "number" and value or nil, false
		end
		local function safeBoolean(value)
			if Api.issecretvalue and Api.issecretvalue(value) then return nil, true end
			return type(value) == "boolean" and value or nil, false
		end
		local cur, curSecret = safeNumber(info and info.currentCharges)
		local max, maxSecret = safeNumber(info and info.maxCharges)
		local start, startSecret = safeNumber(info and info.cooldownStartTime)
		local duration, durationSecret = safeNumber(info and info.cooldownDuration)
		local rate, rateSecret = safeNumber(info and info.chargeModRate)
		local active, activeSecret = safeBoolean(info and info.isActive)

		local state = chargesState[spellId]
		local changed = false
		if not state then
			state = {}
			chargesState[spellId] = state
			changed = true
		end

		local function updateStateField(field, value, isSecret)
			local secretField = field .. "Secret"
			local normalizedSecret = isSecret or nil
			if state[field] ~= value or state[secretField] ~= normalizedSecret then changed = true end
			state[field] = value
			state[secretField] = normalizedSecret
		end
		updateStateField("cur", cur, curSecret)
		updateStateField("max", max, maxSecret)
		updateStateField("start", start, startSecret)
		updateStateField("duration", duration, durationSecret)
		updateStateField("rate", rate, rateSecret)
		updateStateField("active", active, activeSecret)
		if changed and panels then
			local refreshSpellId = getEffectiveSpellId(spellId) or tonumber(spellId)
			if refreshSpellId then
				changedSpellIds[refreshSpellId] = true
			else
				for panelId in pairs(panels) do
					panelsToRefresh[panelId] = true
				end
			end
		end
	end

	local refreshed = false
	for trackedSpellId in pairs(changedSpellIds) do
		local trackedBaseSpellId = getBaseSpellId(trackedSpellId)
		if refreshTrackedSpellEntries(trackedSpellId, trackedBaseSpellId, "charges", panelsToRefresh) then
			refreshed = true
		else
			local panels = chargesIndex[trackedSpellId]
			if not panels and trackedBaseSpellId and trackedBaseSpellId ~= trackedSpellId then panels = chargesIndex[trackedBaseSpellId] end
			if panels then
				for panelId in pairs(panels) do
					panelsToRefresh[panelId] = true
				end
				refreshed = true
			end
		end
	end
	if cdp.ENTRY.FlushPanelRefreshes(panelsToRefresh) then refreshed = true end
	return refreshed
end

local function updatePowerStatesVisible(powerTokens)
	if not Api.IsSpellUsableFn then return false end
	local runtime = CooldownPanels.runtime
	local powerIndex = runtime and runtime.powerIndex
	local powerCheckSpells = runtime and runtime.powerCheckSpells
	local powerPanelsBySpell = runtime and runtime.powerPanelsBySpell
	if not powerCheckSpells or not runtime.powerCheckActive then return false end
	runtime.powerInsufficient = runtime.powerInsufficient or {}
	runtime.spellUnusable = runtime.spellUnusable or {}
	runtime._eqolPowerCheckSpellsScratch = runtime._eqolPowerCheckSpellsScratch or {}
	runtime._eqolPowerChangedScratch = runtime._eqolPowerChangedScratch or {}
	local spellsToCheck = runtime._eqolPowerCheckSpellsScratch
	local changedBySpell = runtime._eqolPowerChangedScratch
	for spellId in pairs(spellsToCheck) do
		spellsToCheck[spellId] = nil
	end
	for spellId in pairs(changedBySpell) do
		changedBySpell[spellId] = nil
	end
	local panelsToRefresh = cdp.ENTRY.GetPanelRefreshScratch(runtime, "_eqolPowerEntryRefreshScratch")
	local checkAll = true
	if powerTokens and next(powerTokens) and powerIndex and next(powerIndex) then
		checkAll = false
		for token in pairs(powerTokens) do
			local bucket = token and powerIndex[token] or nil
			if bucket then
				for spellId in pairs(bucket) do
					spellsToCheck[spellId] = true
				end
			else
				checkAll = true
				break
			end
		end
		if not checkAll and not next(spellsToCheck) then checkAll = true end
	end
	local spellMap = checkAll and powerCheckSpells or spellsToCheck
	for effectiveId in pairs(spellMap) do
		if powerCheckSpells[effectiveId] then
			local isUsable, insufficientPower = Api.IsSpellUsableFn(effectiveId)
			changedBySpell[effectiveId] = setPowerInsufficient(runtime, effectiveId, isUsable, insufficientPower) == true
			if changedBySpell[effectiveId] then
				local baseSpellId = getBaseSpellId(effectiveId)
				if not refreshTrackedSpellEntries(effectiveId, baseSpellId, "power", panelsToRefresh) then
					local panels = powerPanelsBySpell and powerPanelsBySpell[effectiveId] or nil
					if panels then
						for panelId in pairs(panels) do
							panelsToRefresh[panelId] = true
						end
					end
				end
			end
		end
	end
	cdp.ENTRY.FlushPanelRefreshes(panelsToRefresh)
	return true
end

local function schedulePowerUsableRefresh(powerToken)
	local runtime = CooldownPanels.runtime
	if not runtime or not runtime.powerCheckActive then return end
	runtime._eqolPendingPowerTokens = runtime._eqolPendingPowerTokens or {}
	local pendingTokens = runtime._eqolPendingPowerTokens
	if type(powerToken) == "string" and powerToken ~= "" then
		pendingTokens[string.upper(powerToken)] = true
	else
		runtime._eqolPendingPowerFull = true
	end
	if runtime.powerRefreshPending then return end
	runtime.powerRefreshPending = true
	C_Timer.After(CooldownPanels.POWER_USABLE_REFRESH_DELAY, function()
		local rt = CooldownPanels.runtime
		if not rt then return end
		local pending = rt._eqolPendingPowerTokens
		local pendingFull = rt._eqolPendingPowerFull == true
		rt.powerRefreshPending = nil
		rt._eqolPendingPowerFull = nil
		updatePowerStatesVisible(pendingFull and nil or pending)
		rt._eqolPendingPowerTokens = rt._eqolPendingPowerTokens or {}
		if pending and next(pending) then
			for token in pairs(pending) do
				rt._eqolPendingPowerTokens[token] = nil
			end
		end
	end)
end

updatePowerEventRegistration = function()
	local runtime = CooldownPanels.runtime
	local frame = runtime and runtime.updateFrame
	if not frame or not frame.RegisterUnitEvent then return end
	local enable = runtime and runtime.powerCheckActive
	if enable and not runtime.powerEventRegistered then
		frame:RegisterUnitEvent("UNIT_POWER_UPDATE", "player")
		frame:RegisterEvent("SPELL_UPDATE_USABLE")
		runtime.powerEventRegistered = true
	elseif not enable and runtime.powerEventRegistered then
		frame:UnregisterEvent("UNIT_POWER_UPDATE")
		frame:UnregisterEvent("SPELL_UPDATE_USABLE")
		runtime.powerEventRegistered = nil
	end
end

updateRangeCheckSpells = function(rangeCheckSpells)
	if not Api.EnableSpellRangeCheck then return end
	local wanted = rangeCheckSpells
	if not wanted then
		wanted = {}
		local root = ensureRoot()
		if root and root.panels then
			for _, panel in pairs(root.panels) do
				if panel and panel.enabled ~= false and panelAllowsSpec(panel) then
					local layout = panel.layout
					if layout and layout.rangeOverlayEnabled == true then
						for _, entry in pairs(panel.entries or {}) do
							local spellId
							if entry and entry.type == "SPELL" and entry.spellID then
								spellId = tonumber(entry.spellID)
							elseif entry and entry.type == "MACRO" then
								local macro = CooldownPanels.ResolveMacroEntry(entry)
								if macro and macro.kind == "SPELL" and macro.spellID then spellId = tonumber(macro.spellID) end
							end
							if spellId then
								local effectiveId, resolvedSpellId = CooldownPanels:ResolveEntryTrackedSpellID(entry, spellId)
								effectiveId = effectiveId or getEffectiveSpellId(spellId) or spellId
								resolvedSpellId = resolvedSpellId or spellId
								if effectiveId and (shouldTrackPassiveSpell(entry) or not isSpellPassiveSafe(resolvedSpellId, effectiveId)) then wanted[effectiveId] = true end
							end
						end
					end
				end
			end
		end
	end

	CooldownPanels.runtime = CooldownPanels.runtime or {}
	local runtime = CooldownPanels.runtime
	runtime.rangeCheckSpells = runtime.rangeCheckSpells or {}
	local active = runtime.rangeCheckSpells

	for spellId in pairs(active) do
		if not wanted[spellId] then
			Api.EnableSpellRangeCheck(spellId, false)
			active[spellId] = nil
			if runtime.rangeOverlaySpells then runtime.rangeOverlaySpells[spellId] = nil end
		end
	end
	for spellId in pairs(wanted) do
		if not active[spellId] then
			Api.EnableSpellRangeCheck(spellId, true)
			active[spellId] = true
		end
	end
end
local function clearReadyGlowForSpell(spellId)
	local id = tonumber(spellId)
	if not id then return false end
	local index = CooldownPanels.runtime and CooldownPanels.runtime.spellIndex
	if not index then return false end
	local panels
	local aliasIDs = CooldownPanels:GetSpellAliasIDs(id)
	for i = 1, #aliasIDs do
		local aliasPanels = index[aliasIDs[i]]
		if aliasPanels then
			panels = panels or {}
			for panelId in pairs(aliasPanels) do
				panels[panelId] = true
			end
		end
	end
	if not panels then return false end
	for panelId in pairs(panels) do
		local runtime = getRuntime(panelId)
		local panel = CooldownPanels:GetPanel(panelId)
		if runtime and panel and panel.entries then
			runtime.readyAt = runtime.readyAt or {}
			runtime.glowTimers = runtime.glowTimers or {}
			local primed = CooldownPanels.GetReadyGlowPrimedState(runtime)
			for entryId, entry in pairs(panel.entries) do
				if entry then
					local entrySpellId
					if entry.type == "SPELL" and entry.spellID then
						entrySpellId = tonumber(entry.spellID)
					elseif entry.type == "MACRO" then
						local macro = CooldownPanels.ResolveMacroEntry(entry)
						if macro and macro.kind == "SPELL" and macro.spellID then entrySpellId = tonumber(macro.spellID) end
					end
					if CooldownPanels:AreSpellVariantsEquivalent(entrySpellId, id) then
						runtime.readyAt[entryId] = nil
						local t = runtime.glowTimers[entryId]
						if t and t.Cancel then t:Cancel() end
						runtime.glowTimers[entryId] = nil
						if primed then primed[entryId] = nil end
					end
				end
			end
		end
	end
	return true
end

local function triggerProcSoundForSpell(spellId)
	local id = tonumber(spellId)
	if not id then return end

	local index = CooldownPanels.runtime and CooldownPanels.runtime.spellIndex
	if not index then return end

	local panels
	local function mergePanels(map)
		if not map then return end
		panels = panels or {}
		for panelId in pairs(map) do
			panels[panelId] = true
		end
	end

	local aliasIDs = CooldownPanels:GetSpellAliasIDs(id)
	for i = 1, #aliasIDs do
		mergePanels(index[aliasIDs[i]])
	end
	if not panels then return end

	-- EINMAL spielen, auch wenn der Spell in mehreren Panels vorkommt.
	local root = ensureRoot()
	local panelOrder = root and root.order

	local function scanPanel(panelId)
		local panel = CooldownPanels:GetPanel(panelId)
		if not (panel and panel.order and panel.entries) then return false end

		for _, entryId in ipairs(panel.order) do
			local entry = panel.entries[entryId]
			if entry then
				local entryBaseId
				if entry.type == "SPELL" and entry.spellID then
					entryBaseId = tonumber(entry.spellID)
				elseif entry.type == "MACRO" then
					local macro = CooldownPanels.ResolveMacroEntry(entry)
					if macro and macro.kind == "SPELL" and macro.spellID then entryBaseId = tonumber(macro.spellID) end
				end
				if entryBaseId and CooldownPanels:AreSpellVariantsEquivalent(entryBaseId, id) and entry.type ~= "MACRO" and entry.soundReady == true then
					local soundName = normalizeSoundName(entry.soundReadyFile)
					if soundName and soundName ~= "None" then
						playSoundName(soundName)
						return true
					end
				end
			end
		end

		return false
	end

	-- deterministisch: erst Root-Panel-Reihenfolge
	if panelOrder then
		for _, panelId in ipairs(panelOrder) do
			if panels[panelId] and scanPanel(panelId) then return end
		end
	end

	-- fallback: irgend eins
	for panelId in pairs(panels) do
		if scanPanel(panelId) then return end
	end
end

setOverlayGlowForSpell = function(spellId, enabled)
	local id = tonumber(spellId)
	if not id then return false end
	CooldownPanels.runtime = CooldownPanels.runtime or {}
	local runtime = CooldownPanels.runtime
	runtime.overlayGlowSpells = runtime.overlayGlowSpells or {}
	local overlayGlowSpells = runtime.overlayGlowSpells
	if Api.IsSpellOverlayed then
		local aliasIds = CooldownPanels:GetSpellAliasIDs(id)
		local wasEnabled = false
		for i = 1, #aliasIds do
			local aliasId = aliasIds[i]
			if aliasId and overlayGlowSpells[aliasId] == true then
				wasEnabled = true
				break
			end
		end
		local isEnabled = false
		local changed = false
		for i = 1, #aliasIds do
			local aliasId = aliasIds[i]
			local value = (aliasId and Api.IsSpellOverlayed(aliasId) == true) and true or nil
			if value then isEnabled = true end
			if aliasId and overlayGlowSpells[aliasId] ~= value then
				overlayGlowSpells[aliasId] = value
				changed = true
			end
		end
		if enabled and isEnabled and not wasEnabled then triggerProcSoundForSpell(id) end
		if not changed then return false end
	else
		local baseId = getBaseSpellId(id)
		local effectiveId = getEffectiveSpellId(id)
		local wasEnabled = overlayGlowSpells[id] == true
		if not wasEnabled and baseId then wasEnabled = overlayGlowSpells[baseId] == true end
		if not wasEnabled and effectiveId then wasEnabled = overlayGlowSpells[effectiveId] == true end
		local function setFlag(spellIdentifier, value)
			if spellIdentifier then overlayGlowSpells[spellIdentifier] = value end
		end
		if enabled then
			setFlag(id, true)
			if baseId and baseId ~= id then setFlag(baseId, true) end
			if effectiveId and effectiveId ~= id then setFlag(effectiveId, true) end
		else
			setFlag(id, nil)
			if baseId and baseId ~= id then setFlag(baseId, nil) end
			if effectiveId and effectiveId ~= id then setFlag(effectiveId, nil) end
		end
		-- Sound nur wenn es frisch "an" ging.
		if enabled and not wasEnabled then triggerProcSoundForSpell(id) end
	end
	local refreshed, indexReady = refreshPanelsForSpell(id)
	if refreshed == true then return true end
	if indexReady ~= true and CooldownPanels and CooldownPanels.RequestUpdate then CooldownPanels:RequestUpdate("OverlayGlow") end
	return true
end

function CooldownPanels:RefreshAllOverlayGlowStates(suppressRefresh)
	if not Api.IsSpellOverlayed then return false end
	local runtime = self.runtime
	if not runtime then return false end
	runtime.overlayGlowSpells = runtime.overlayGlowSpells or {}
	local overlayGlowSpells = runtime.overlayGlowSpells
	local candidateIds = runtime.overlayGlowCandidateIds
	if not candidateIds then
		candidateIds = {}
		runtime.overlayGlowCandidateIds = candidateIds
	else
		for i = 1, #candidateIds do
			candidateIds[i] = nil
		end
	end
	local candidateSeen = runtime.overlayGlowCandidateSeen
	if not candidateSeen then
		candidateSeen = {}
		runtime.overlayGlowCandidateSeen = candidateSeen
	else
		wipe(candidateSeen)
	end
	local spellIndex = runtime.spellIndex
	if spellIndex then
		for spellId in pairs(spellIndex) do
			self:GetSpellAliasIDs(spellId, candidateIds, candidateSeen)
		end
	end
	for spellId in pairs(overlayGlowSpells) do
		self:GetSpellAliasIDs(spellId, candidateIds, candidateSeen)
	end
	local changed = false
	for i = 1, #candidateIds do
		local candidateId = candidateIds[i]
		local value = (candidateId and Api.IsSpellOverlayed(candidateId) == true) and true or nil
		if candidateId and overlayGlowSpells[candidateId] ~= value then
			overlayGlowSpells[candidateId] = value
			changed = true
		end
	end
	if not changed then return false end
	if suppressRefresh then return true end
	if self.RequestEnabledPanelRefreshes and self:RequestEnabledPanelRefreshes() then return true end
	if self.RequestUpdate then self:RequestUpdate("OverlayGlowSync") end
	return true
end

local function setRangeOverlayForSpell(spellIdentifier, isInRange, checksRange)
	local id = tonumber(spellIdentifier)
	if not id and type(spellIdentifier) == "string" then id = C_Spell.GetSpellIDForSpellIdentifier(spellIdentifier) end
	if not id then return false end
	local index = CooldownPanels.runtime and CooldownPanels.runtime.spellIndex
	local panels = index and index[id]
	if not panels then return false end
	CooldownPanels.runtime = CooldownPanels.runtime or {}
	local runtime = CooldownPanels.runtime
	runtime.rangeOverlaySpells = runtime.rangeOverlaySpells or {}
	local shouldShow = checksRange and isInRange == false
	local wasShown = runtime.rangeOverlaySpells[id] == true
	if shouldShow == wasShown then return false end
	if shouldShow then
		runtime.rangeOverlaySpells[id] = true
	else
		runtime.rangeOverlaySpells[id] = nil
	end
	if refreshPanelsForSpell and refreshPanelsForSpell(id) then return true end
	if CooldownPanels and CooldownPanels.RequestUpdate then CooldownPanels:RequestUpdate("RangeOverlay") end
	return true
end

local function refreshPanelsDisabledBySpecChange(previousEnabledPanels)
	if type(previousEnabledPanels) ~= "table" then return false end
	local runtime = CooldownPanels.runtime
	local enabledPanels = runtime and runtime.enabledPanels
	local root = ensureRoot()
	if not root or not root.panels then return false end

	local refreshed = false
	CooldownPanels:BeginRuntimeQueryBatch()
	for panelId in pairs(previousEnabledPanels) do
		if panelId and root.panels[panelId] and not (enabledPanels and enabledPanels[panelId]) then
			CooldownPanels:RefreshPanel(panelId)
			refreshed = true
		end
	end
	CooldownPanels:EndRuntimeQueryBatch()

	local disabledPanelIds = runtime and runtime.disabledPanelIds
	if disabledPanelIds then
		for i = 1, #disabledPanelIds do
			disabledPanelIds[i] = nil
		end
	end
	return refreshed
end

function CooldownPanels:RequestSpecAwareScopedPanelRefresh(panelScope, cause)
	local runtime = self.runtime
	if not runtime then return false, "missingRuntime", 0 end
	if issecretvalue and issecretvalue(panelScope) then return false, "secretScope", 0 end
	if type(panelScope) ~= "table" then return false, "invalidScope", 0 end
	if runtime.updatePending or runtime.updateDispatching then return false, "updateBusy", 0 end
	if runtime._eqolPanelRefreshPending or runtime._eqolEntryRefreshPending then return false, "refreshBusy", 0 end

	local enabledPanels = runtime.enabledPanels
	if issecretvalue and issecretvalue(enabledPanels) then return false, "secretEnabledPanels", 0 end
	if type(enabledPanels) ~= "table" then return false, "missingEnabledPanels", 0 end

	local validatedPanels = {}
	local validatedCount = 0
	for panelId, membership in pairs(panelScope) do
		if issecretvalue and (issecretvalue(panelId) or issecretvalue(membership)) then return false, "secretPanel", 0 end
		local panelIdType = type(panelId)
		if (panelIdType ~= "number" and panelIdType ~= "string") or membership ~= true then return false, "invalidPanel", 0 end
		local enabled = enabledPanels[panelId]
		if issecretvalue and issecretvalue(enabled) then return false, "secretPanelState", 0 end
		if enabled ~= true or not self:GetPanel(panelId) then return false, "inactivePanel", 0 end
		validatedPanels[panelId] = true
		validatedCount = validatedCount + 1
	end
	if validatedCount == 0 then return false, "emptyScope", 0 end

	local activeSpecId = runtime.activeSpecId
	if issecretvalue and issecretvalue(activeSpecId) then return false, "secretSpec", 0 end
	if activeSpecId == nil then return false, "missingSpec", 0 end
	local queuedSpecId = runtime._eqolSpecScopedRefreshSpecId
	if issecretvalue and issecretvalue(queuedSpecId) then return false, "secretQueuedSpec", 0 end
	if runtime._eqolSpecScopedRefreshPending and queuedSpecId ~= activeSpecId then return false, "queuedSpecChanged", 0 end

	runtime._eqolSpecScopedRefreshQueue = runtime._eqolSpecScopedRefreshQueue or {}
	for panelId in pairs(validatedPanels) do
		runtime._eqolSpecScopedRefreshQueue[panelId] = true
	end
	runtime._eqolSpecScopedRefreshSpecId = activeSpecId
	runtime._eqolSpecScopedRefreshCause = cause
	if runtime._eqolSpecScopedRefreshPending then return true, nil, validatedCount end
	runtime._eqolSpecScopedRefreshPending = true

	RunNextFrame(function()
		local currentRuntime = CooldownPanels.runtime
		if not currentRuntime then return end
		currentRuntime._eqolSpecScopedRefreshPending = nil
		local queuedPanels = currentRuntime._eqolSpecScopedRefreshQueue
		local expectedSpecId = currentRuntime._eqolSpecScopedRefreshSpecId
		local refreshCause = currentRuntime._eqolSpecScopedRefreshCause
		currentRuntime._eqolSpecScopedRefreshQueue = nil
		currentRuntime._eqolSpecScopedRefreshSpecId = nil
		currentRuntime._eqolSpecScopedRefreshCause = nil

		local function fallback()
			if currentRuntime.updatePending or currentRuntime.updateDispatching then
				CooldownPanels:RequestUpdate({
					cause = refreshCause or "SpecScopedFallback",
					fullRefresh = true,
				})
			else
				CooldownPanels:RefreshAllPanels(true)
			end
		end

		if type(queuedPanels) ~= "table" or not next(queuedPanels) then
			fallback()
			return
		end
		if currentRuntime.updatePending or currentRuntime.updateDispatching then
			fallback()
			return
		end
		if currentRuntime._eqolPanelRefreshPending or currentRuntime._eqolEntryRefreshPending then
			fallback()
			return
		end
		if (CooldownPanels.IsAnyPanelLayoutEditActive and CooldownPanels:IsAnyPanelLayoutEditActive()) or (CooldownPanels.IsEditorOpen and CooldownPanels:IsEditorOpen()) then
			fallback()
			return
		end

		local currentSpecId = currentRuntime.activeSpecId
		if issecretvalue and (issecretvalue(expectedSpecId) or issecretvalue(currentSpecId)) then
			fallback()
			return
		end
		if expectedSpecId == nil or currentSpecId == nil or expectedSpecId ~= currentSpecId then
			fallback()
			return
		end

		local enabledPanelIds = currentRuntime.enabledPanelIds
		local currentEnabledPanels = currentRuntime.enabledPanels
		local disabledPanelIds = currentRuntime.disabledPanelIds
		if
			(issecretvalue and (issecretvalue(enabledPanelIds) or issecretvalue(currentEnabledPanels) or issecretvalue(disabledPanelIds)))
			or type(enabledPanelIds) ~= "table"
			or type(currentEnabledPanels) ~= "table"
			or (type(disabledPanelIds) == "table" and next(disabledPanelIds) ~= nil)
		then
			fallback()
			return
		end

		local panelIds = {}
		for i = 1, #enabledPanelIds do
			local panelId = enabledPanelIds[i]
			if issecretvalue and issecretvalue(panelId) then
				fallback()
				return
			end
			if queuedPanels[panelId] then
				local enabled = currentEnabledPanels[panelId]
				if issecretvalue and issecretvalue(enabled) then
					fallback()
					return
				end
				if enabled ~= true or not CooldownPanels:GetPanel(panelId) then
					fallback()
					return
				end
				queuedPanels[panelId] = nil
				panelIds[#panelIds + 1] = panelId
			end
		end
		if next(queuedPanels) ~= nil or #panelIds == 0 then
			fallback()
			return
		end

		CooldownPanels:RefreshAllPanels(false, panelIds)
	end)
	return true, nil, validatedCount
end

local function performSpecAwareRebuild(cause)
	local runtime = CooldownPanels.runtime
	local previousSpecId = runtime and runtime.activeSpecId
	local previousEnabledPanels = runtime and runtime.enabledPanels
	local previousIndexState, indexFields = cdp.ENTRY.CaptureSpecRefreshIndexState(runtime)
	local racialsChanged = CooldownPanels:NormalizeActivePanelPlayerRacials()
	if racialsChanged then Keybinds.MarkPanelsDirty() end
	CooldownPanels:RebuildSpellIndex()
	local currentSpecId = CooldownPanels.runtime and CooldownPanels.runtime.activeSpecId
	local specIdsSecret = issecretvalue and (issecretvalue(previousSpecId) or issecretvalue(currentSpecId))
	local panelScope, scopeUnknown, scopeUnmapped, scopeCount =
		cdp.ENTRY.BuildSpecAwareRefreshScope(previousIndexState, indexFields, CooldownPanels.runtime, racialsChanged)
	if not specIdsSecret and previousSpecId ~= nil and previousSpecId ~= currentSpecId then refreshPanelsDisabledBySpecChange(previousEnabledPanels) end
	Keybinds.InvalidateCache()

	local fallbackReason
	if issecretvalue and issecretvalue(cause) then
		fallbackReason = "secretCause"
	elseif cause ~= "Event:SPELLS_CHANGED" then
		fallbackReason = "ineligibleCause"
	elseif specIdsSecret then
		fallbackReason = "secretSpec"
	elseif previousSpecId == nil or currentSpecId == nil then
		fallbackReason = "missingSpec"
	elseif previousSpecId ~= currentSpecId then
		fallbackReason = "specChanged"
	elseif racialsChanged == true then
		fallbackReason = "racialsChanged"
	elseif (scopeUnknown or 0) > 0 then
		fallbackReason = "unknownScope"
	elseif (scopeUnmapped or 0) > 0 then
		fallbackReason = "unmappedScope"
	elseif (scopeCount or 0) == 0 then
		fallbackReason = "emptyScope"
	elseif (CooldownPanels.IsAnyPanelLayoutEditActive and CooldownPanels:IsAnyPanelLayoutEditActive()) or (CooldownPanels.IsEditorOpen and CooldownPanels:IsEditorOpen()) then
		fallbackReason = "editorActive"
	else
		local accepted, reason = CooldownPanels:RequestSpecAwareScopedPanelRefresh(panelScope, cause)
		if not accepted then fallbackReason = reason or "scopeRejected" end
	end
	if fallbackReason then
		CooldownPanels:RequestUpdate({
			cause = cause,
			fullRefresh = true,
		})
	end
	if CooldownPanels.IsEditorOpen and CooldownPanels:IsEditorOpen() then CooldownPanels:RefreshEditor() end
end

local function runDelayedSpecAwareRebuild()
	local rt = CooldownPanels.runtime
	if not rt then return end
	rt.specRebuildPending = nil
	rt.specRebuildImmediateDone = nil
	local cause = rt.specRebuildCause
	rt.specRebuildCause = nil
	performSpecAwareRebuild(cause)
end

local function scheduleSpecAwareRebuild(event, immediate)
	CooldownPanels.runtime = CooldownPanels.runtime or {}
	local runtime = CooldownPanels.runtime
	runtime.specRebuildCause = "Event:" .. tostring(event or "Unknown")

	if immediate == true and runtime.specRebuildImmediateDone ~= true then
		runtime.specRebuildImmediateDone = true
		performSpecAwareRebuild(runtime.specRebuildCause .. ":Immediate")
	end

	if runtime.specRebuildPending then return end
	runtime.specRebuildPending = true
	C_Timer.After(1, runDelayedSpecAwareRebuild)
end

